var JD_META = {"title": "课内文言文精读自测", "count": 56, "questions": 1093, "tags": ["七年级上册", "七年级下册", "三年级上册", "三年级下册", "九年级上册", "五年级上册", "五年级下册", "八年级上册", "八年级下册", "六年级上册", "六年级下册", "四年级上册", "四年级下册", "课外·入门", "课外·入门级", "课外·初级"]};
var JD = [{"no":1,"t":"狗父","src":"课外古文·入门·《笑林广记》","tag":"课外·入门","html":true,"p":["陆某，<u>善</u>说话，有邻妇<u>性</u>不<u>好</u>笑，其友<u>谓</u>之曰：“汝能说一字令<u>彼</u>妇笑，又说一字令彼妇骂，则吾<u>愿</u>以酒菜享<u>汝</u>。”一日，妇立门前，<u>适</u>门前卧一犬，陆向之<span class=\"jz\" title=\"长跪：直身而跪，表恭敬\">长跪曰：“爷！”妇见之<u>不觉</u>好笑，陆复<span class=\"jz\" title=\"仰首：抬头\">仰首向妇曰：“娘！”妇闻之大骂。<br>\n    💡 带下划线的词可点击查看注释；黄色高亮为考察的实词"],"common":"","q":[{"s":"“陆某，<em class='k'>善</em>说话”中“<em class='k'>善</em>”的意思是？","o":["擅长","善良","好事","和善"],"a":"A","e":"“善”意为擅长。“善说话”即擅长说笑。","tag":"字词释义"},{"s":"“有邻妇<em class='k'>性</em>不好笑”中“<em class='k'>性</em>”的意思是？","o":["性情","性别","性命","姓氏"],"a":"A","e":"“性”意为性情、性格。“性不好笑”即性情不爱笑。","tag":"字词释义"},{"s":"“性不<em class='k'>好</em>笑”中“<em class='k'>好</em>”的读音和意思是？","o":["读 hào，喜欢","读 hǎo，良好","读 hǎo，容易","读 hào，善于"],"a":"A","e":"“好”读 hào，意为喜欢。“不好笑”即不喜欢笑、不爱笑。","tag":"字词释义"},{"s":"“其友<em class='k'>谓</em>之曰”中“<em class='k'>谓</em>”的意思是？","o":["说","称呼","叫做","评论"],"a":"A","e":"“谓”意为说。“谓之曰”即对他说。","tag":"字词释义"},{"s":"“令<em class='k'>彼</em>妇笑”中“<em class='k'>彼</em>”的意思是？","o":["那","他","彼此","别人"],"a":"A","e":"“彼”是指示代词，那。“彼妇”即那个妇人。","tag":"字词释义"},{"s":"“则吾<em class='k'>愿</em>以酒菜享汝”中“<em class='k'>愿</em>”的意思是？","o":["愿意","愿望","心愿","请求"],"a":"A","e":"“愿”意为愿意。“吾愿以酒菜享汝”即我愿意用酒菜请你（吃）。","tag":"字词释义"},{"s":"“以酒菜享<em class='k'>汝</em>”中“<em class='k'>汝</em>”的意思是？","o":["你","我","他","你们"],"a":"A","e":"“汝”是第二人称代词，你。“享汝”即请你（吃）。","tag":"字词释义"},{"s":"“<em class='k'>适</em>门前卧一犬”中“<em class='k'>适</em>”的意思是？","o":["恰好","适合","舒适","刚才"],"a":"A","e":"“适”意为恰好、正好。“适门前卧一犬”即恰好门前卧着一条狗。","tag":"字词释义"},{"s":"“妇见之<em class='k'>不觉</em>好笑”中“<em class='k'>不觉</em>”的意思是？","o":["不由得","没有察觉","不知不觉","毫不理会"],"a":"A","e":"“不觉”意为不由得、忍不住。“不觉好笑”即忍不住觉得好笑。","tag":"字词释义"},{"s":"对“汝能说一字令彼妇笑，又说一字令彼妇骂”翻译正确的一项是？","o":["你能说一个字让那个妇人笑，再说一个字让那个妇人骂","你能说一个词让她笑，再说一个词让她骂","你能说一个字使她笑，再说一个字使她们骂","你说一个字让她高兴，再说一个字让她生气"],"a":"A","e":"“字”指单个字，“彼妇”即那个妇人。A 翻译准确。B 误译“字”为词；C 误译“彼妇”为她们；D 意译不准确。","tag":"翻译"},{"s":"对“适门前卧一犬”翻译正确的一项是？","o":["恰好门前卧着一条狗","刚好门前躺着一条大狗","刚才门前趴着一只狗","正巧门前拴着一条狗"],"a":"A","e":"“适”意为恰好，“卧”意为趴着、卧着。A 翻译准确。B 误加“大”；C 误译“适”为刚才；D 误译“卧”为拴着。","tag":"翻译"},{"s":"陆某喊狗“爷”、又喊妇人“娘”，妇人为什么大怒？","o":["陆某把狗称为“爷”，又喊她“娘”，等于把她和狗配成“爹娘”，占了她的便宜","陆某不该跪在地上喊狗，有失体统","妇人觉得陆某不该叫她娘，她没那么老","妇人觉得陆某说话声音太大，吓到了她"],"a":"A","e":"A 正确。陆某先认狗为“爷”，再喊妇人“娘”，等于说妇人是狗的配偶，妇人回过味来自然大怒。B、C、D 均不是发怒的真正原因。","tag":"内容理解"}],"jd":[{"o":"陆某，善说话，有邻妇性不好笑，其友谓之曰。","t":"有个姓陆的人，擅长说笑，有个邻居妇人性情不爱笑，他的朋友对他说。","notes":[["善","擅长"],["性","性情"],["好","喜欢"],["谓","说"]]},{"o":"汝能说一字令彼妇笑，又说一字令彼妇骂，则吾愿以酒菜享汝。","t":"你能说一个字让那个妇人笑，再说一个字让那个妇人骂，那么我愿意用酒菜请你（吃）。","notes":[["彼","那"],["愿","愿意"],["享","请，款待"],["汝","你"]]},{"o":"一日，妇立门前，适门前卧一犬，陆向之长跪曰：“爷！”","t":"一天，妇人站在门前，恰好门前卧着一条狗，陆某对着狗直身跪下说：“爷！”","notes":[["适","恰好"],["犬","狗"],["长跪","直身而跪，表恭敬"]]},{"o":"妇见之不觉好笑，陆复仰首向妇曰：“娘！”妇闻之大骂。","t":"妇人见了不由得觉得好笑，陆某又抬头对妇人说：“娘！”妇人听了大骂。","notes":[["不觉","不由得"],["复","又"],["仰首","抬头"]]},{"o":"","t":"","notes":[]}]},{"no":2,"t":"书低","src":"课外古文·入门级·《笑林广记》","tag":"课外·入门级","html":true,"p":["一生<u>赁</u>僧房读书，每日游玩，午后归房。呼童取书来，童持《文选》，视之<u>曰</u>低；持《汉书》，视之曰低；又持《史记》，视之曰低。僧大<u>诧</u>曰：“此三书<u>熟</u>其一，<u>足</u>称<span class=\"jz\" title=\"饱学：学问渊博\">饱学，<u>俱</u>云低何也？”生曰：“我要睡，取书作枕头<u>耳</u>。”<br>\n    💡 带下划线的词可点击查看注释；黄色高亮为考察的实词"],"common":"","q":[{"s":"“一生<em class='k'>赁</em>僧房读书”中“<em class='k'>赁</em>”的意思是？","o":["租借","租金","典当","居住"],"a":"A","e":"“赁”意为租借。“赁僧房”即租借僧人的房子。","tag":"字词释义"},{"s":"“视之<em class='k'>曰</em>低”中“<em class='k'>曰</em>”的意思是？","o":["说","日","写道","告诉"],"a":"A","e":"“曰”意为说。“视之曰低”即看了看说（书）低。","tag":"字词释义"},{"s":"“僧大<em class='k'>诧</em>曰”中“<em class='k'>诧</em>”的意思是？","o":["惊讶","责骂","叹息","生气"],"a":"A","e":"“诧”意为惊讶。“僧大诧曰”即僧人十分惊讶地说。","tag":"字词释义"},{"s":"“此三书<em class='k'>熟</em>其一”中“<em class='k'>熟</em>”的意思是？","o":["熟悉","哪一个","成熟","仔细"],"a":"A","e":"“熟”意为熟悉、精通。“熟其一”即（你）熟悉其中一本。","tag":"字词释义"},{"s":"“<em class='k'>足</em>称饱学”中“<em class='k'>足</em>”的意思是？","o":["足以","脚","值得","充足"],"a":"A","e":"“足”意为足以、够得上。“足称饱学”即足以称得上学问渊博。","tag":"字词释义"},{"s":"“<em class='k'>俱</em>云低何也”中“<em class='k'>俱</em>”的意思是？","o":["都","仅","一起","总共"],"a":"A","e":"“俱”意为都。“俱云低”即（你）都说（书）低。","tag":"字词释义"},{"s":"“取书作枕头<em class='k'>耳</em>”中“<em class='k'>耳</em>”的意思是？","o":["罢了","耳朵","而是","如此"],"a":"A","e":"“耳”是句末语气词，罢了。“作枕头耳”即只是拿来当枕头罢了。","tag":"字词释义"},{"s":"对“此三书熟其一，足称饱学，俱云低何也？”翻译正确的一项是？","o":["这三本书（你）熟悉其中一本，就足以称得上学问渊博，（你）却都说低，是为什么呢？","这三本书（你）都熟悉，全都称得上饱学，为什么说低呢？","这三本书有一本熟悉，就可以称饱学，低是什么？","这三本书你都会背诵，怎么还说低呢？"],"a":"A","e":"“熟其一”即熟悉其中一本；“足称”即足以称得上。A 翻译准确。B 误把“熟其一”当作“都熟悉”；C 语序不畅、漏译“其一”的强调；D 误把“熟”当作“背诵”。","tag":"翻译"},{"s":"下列对文章内容理解有误的一项是？","o":["书生租僧房说是读书，实际每天游玩","书生说三本书“低”，是说书里的学问低","书生把书当枕头，嫌书不够高","故事讽刺不学无术、附庸风雅的人"],"a":"B","e":"B 有误。书生说书“低”是因为书太薄、枕着不够高，并非说书里的学问低——这正是笑话的“包袱”所在。","tag":"内容理解"}],"jd":[{"o":"一生赁僧房读书，每日游玩，午后归房。呼童取书来，童持《文选》，视之曰低；持《汉书》，视之曰低；又持《史记》，视之曰低。","t":"一个书生租借僧人的房子读书，却每天游玩，午后才回房。（他）叫书童取书来，书童拿来《文选》，（他）看了看说低；拿来《汉书》，看了看说低；又拿来《史记》，看了看说低。","notes":[["赁","租借"],["曰","说"]]},{"o":"僧大诧曰：“此三书熟其一，足称饱学，俱云低何也？”","t":"僧人十分惊讶地说：“这三本书（你）熟悉其中一本，就足以称得上学问渊博，（你）却都说低，是为什么呢？”","notes":[["诧","惊讶"],["熟","熟悉，精通"],["足","足以"],["饱学","学问渊博"],["俱","都"]]},{"o":"生曰：“我要睡，取书作枕头耳。”","t":"书生说：“我要睡觉，拿书来当枕头罢了。”","notes":[["耳","罢了"]]},{"o":"","t":"","notes":[]}]},{"no":3,"t":"借牛","src":"课外古文·入门级·《笑林广记》","tag":"课外·入门级","html":true,"p":["有<span class=\"jz\" title=\"走柬：送信（的人）\">走柬借牛<u>于</u>富翁者，翁<u>方</u>对客，<u>讳</u>不识字，<u>伪</u><u>启</u><span class=\"jz\" title=\"缄：书信\">缄视之，对来使曰：“知道了，<u>少刻</u>我自来也。”<br>\n    💡 带下划线的词可点击查看注释；黄色高亮为考察的实词"],"common":"","q":[{"s":"“借牛<em class='k'>于</em>富翁者”中“<em class='k'>于</em>”的意思是？","o":["向","在","被","从"],"a":"A","e":"“于”是介词，向。“借牛于富翁”即向富翁借牛。","tag":"字词释义"},{"s":"“翁<em class='k'>方</em>对客”中“<em class='k'>方</em>”的意思是？","o":["正，正在","方向","方法","方才"],"a":"A","e":"“方”意为正、正在。“翁方对客”即富翁正对着客人。","tag":"字词释义"},{"s":"“<em class='k'>讳</em>不识字”中“<em class='k'>讳</em>”的意思是？","o":["隐瞒","避讳","名讳","躲闪"],"a":"A","e":"“讳”意为隐瞒（不愿让人知道）。“讳不识字”即隐瞒自己不识字。","tag":"字词释义"},{"s":"“<em class='k'>伪</em>启缄视之”中“<em class='k'>伪</em>”的意思是？","o":["假装","虚伪","伪造","奸诈"],"a":"A","e":"“伪”意为假装。“伪启缄视之”即假装打开信看。","tag":"字词释义"},{"s":"“<em class='k'>启</em>缄视之”中“<em class='k'>启</em>”的意思是？","o":["打开","启动","启发","告诉"],"a":"A","e":"“启”意为打开。“启缄”即打开书信。","tag":"字词释义"},{"s":"“<em class='k'>少刻</em>我自来也”中“<em class='k'>少刻</em>”的意思是？","o":["一会儿","小时候","很少","一刻钟"],"a":"A","e":"“少刻”意为片刻、一会儿。“少刻我自来也”即一会儿我自己来。","tag":"字词释义"},{"s":"对“知道了，少刻我自来也”翻译正确的一项是？","o":["知道了，一会儿我自己来","知道了，少刻钟我自己来","知道了，一会儿我亲自去送信","知道了，我马上派人来取"],"a":"A","e":"“少刻”即一会儿，“自来”即自己来。A 翻译准确。B 误拆“少刻”；C 误以为他是送信人；D 误“派人来”（应是“自己来”）。","tag":"翻译"},{"s":"下列对文章内容理解有误的一项是？","o":["富翁正在会客，不想让人知道自己不识字","富翁假装看信，其实根本不认识字","富翁说“我自来也”，是要亲自去还牛","故事讽刺不懂装懂、死要面子的人"],"a":"C","e":"C 有误。富翁说“我自来也”是他误以为信里请自己去，并非“去还牛”——他连信里借牛的内容都没看懂。","tag":"内容理解"}],"jd":[{"o":"有走柬借牛于富翁者，翁方对客，讳不识字，伪启缄视之。","t":"有个送信的人向富翁借牛，富翁正对着客人，（他）隐瞒自己不识字，假装打开信看了看。","notes":[["走柬","送信（的人）"],["于","向"],["方","正，正在"],["讳","隐瞒"],["伪","假装"],["启","打开"],["缄","书信"]]},{"o":"对来使曰：“知道了，少刻我自来也。”","t":"（富翁）对来送信的人说：“知道了，一会儿我自己来。”","notes":[["少刻","一会儿"],["自来","自己来"]]},{"o":"","t":"","notes":[]}]},{"no":4,"t":"属牛","src":"课外古文·入门级·《笑林广记》","tag":"课外·入门级","html":true,"p":["一官遇<u>生辰</u>，吏典<u>闻</u>其属鼠，乃<span class=\"jz\" title=\"醵(jù)：凑集（钱财），众人凑钱\">醵(jù)黄金铸一鼠为寿。官<u>甚</u>喜，曰：“<u>汝等</u>可知<u>奶奶</u>生辰<u>亦</u>在<u>目下</u>乎？”众吏曰：“不知，请问其属？”官曰：“小我一岁，丑年生的。”<br>\n    💡 带下划线的词可点击查看注释；黄色高亮为考察的实词"],"common":"","q":[{"s":"“一官遇<em class='k'>生辰</em>”中“<em class='k'>生辰</em>”的意思是？","o":["生日","时辰","出生地","八字"],"a":"A","e":"“生辰”即生日。“遇生辰”即过生日。","tag":"字词释义"},{"s":"“吏典<em class='k'>闻</em>其属鼠”中“闻”的意思是？","o":["听说","听到","闻到","新闻"],"a":"A","e":"“闻”意为听说。“吏典闻其属鼠”即下属听说官员属鼠。","tag":"字词释义"},{"s":"“官<em class='k'>甚</em>喜”中“甚”的意思是？","o":["很，非常","甚至","过分","什么"],"a":"A","e":"“甚”意为很、非常。“官甚喜”即官员非常高兴。","tag":"字词释义"},{"s":"“<em class='k'>汝等</em>可知”中“<em class='k'>汝等</em>”的意思是？","o":["你们","你的","我等","此人"],"a":"A","e":"“汝”是你，“等”表复数，“汝等”即你们。","tag":"字词释义"},{"s":"“<em class='k'>奶奶</em>生辰亦在目下乎”中“奶奶”在文中的意思是？","o":["官员的夫人","祖母","老年妇女","奶妈"],"a":"A","e":"“奶奶”在文中指官员的夫人（古时对官员妻子的称呼），是古今异义词，今义为祖母或老年妇女。","tag":"古今异义"},{"s":"“生辰<em class='k'>亦</em>在目下乎”中“<em class='k'>亦</em>”的意思是？","o":["也","又","却","才"],"a":"A","e":"“亦”意为也。“生辰亦在目下”即夫人的生日也就在眼前。","tag":"字词释义"},{"s":"“生辰亦在<em class='k'>目下</em>乎”中“<em class='k'>目下</em>”的意思是？","o":["眼前","名下","目光下","脚下"],"a":"A","e":"“目下”意为眼前、近日。“在目下”即就在眼前（指日子临近）。","tag":"字词释义"},{"s":"对“小我一岁，丑年生的”翻译正确的一项是？","o":["（她）比我小一岁，是丑年（牛年）生的","（她）比我小一岁，是丑时（凌晨）生的","我比（她）小一岁，是丑年生的","（她）比我小一岁，长得丑陋不堪"],"a":"A","e":"“小我一岁”即比我小一岁；“丑年”指牛年（地支丑对应牛），官员借此暗示夫人属牛，希望属下照送金牛。A 翻译准确。B 误把“丑年”当作“丑时”；C 弄错主宾关系；D 望文生义。","tag":"翻译"},{"s":"下列对文章内容理解有误的一项是？","o":["吏典听说官员属鼠，凑钱铸金鼠祝寿","官员对金鼠很满意，又提起夫人的生辰","官员想让属下认识夫人，是出于关心","故事讽刺官员借生辰之名索取财物"],"a":"C","e":"C 有误。官员提起夫人“小我一岁，丑年生”（属牛），是暗示属下也照送金牛，并非关心夫人。","tag":"内容理解"}],"jd":[{"o":"一官遇生辰，吏典闻其属鼠，乃醵黄金铸一鼠为寿。","t":"一个官员遇到生日，下属吏典听说他属鼠，就凑钱用黄金铸了一只老鼠祝寿。","notes":[["生辰","生日"],["闻","听说"],["醵","凑集（钱财）"]]},{"o":"官甚喜，曰：“汝等可知奶奶生辰亦在目下乎？”","t":"官员非常高兴，说：“你们可知道我夫人的生日也就在眼前吗？”","notes":[["甚","很，非常"],["汝等","你们"],["奶奶","官员的夫人"],["亦","也"],["目下","眼前，近日"]]},{"o":"众吏曰：“不知，请问其属？”官曰：“小我一岁，丑年生的。”","t":"众吏说：“不知道，请问夫人属什么？”官员说：“（她）比我小一岁，是丑年（牛年）生的。”","notes":[["其","她的"],["丑年","牛年（地支丑对应牛）"]]},{"o":"","t":"","notes":[]}]},{"no":5,"t":"床头捉刀人","src":"课外古文·入门级·刘义庆《世说新语》","tag":"课外·入门级","html":true,"p":["魏武将见匈奴使，自以形陋，不足<u>雄</u>远国，<u>使</u>崔季圭代，帝自<u>捉</u>刀立<span class=\"jz\" title=\"床：胡床、榻等坐具，非现代床铺\">床头。<u>既</u><u>毕</u>，令<span class=\"jz\" title=\"间谍：此处指侦察消息的探子，非现代秘密情报人员\">间谍问曰：“魏王何如？”匈奴使答曰：“魏王<u>雅望</u><u>非常</u><u>然</u>床头捉刀人<u>乃</u>英雄也”魏武闻之，追杀此使。<br>\n    💡 带下划线的词可点击查看注释；黄色高亮为考察的实词"],"common":"","q":[{"s":"“不足<em class='k'>雄</em>远国”中“<em class='k'>雄</em>”的意思是？","o":["称雄","英雄","雄壮","首领"],"a":"A","e":"“雄”名词作动词，称雄、显扬威名。“不足雄远国”即不足以在远国（使者面前）称雄。","tag":"字词释义"},{"s":"“<em class='k'>使</em>崔季圭代”中“<em class='k'>使</em>”的意思是？","o":["使者","致使","使用","派遣"],"a":"D","e":"“使”意为“派遣、让”。“使崔季圭代”即让崔季圭代替自己。","tag":"字词释义"},{"s":"“帝自<em class='k'>捉</em>刀立床头”中“<em class='k'>捉</em>”的意思是？","o":["捕捉","握着","携带","放置"],"a":"B","e":"“捉”意为“握”。“捉刀”即握着刀（古义为握持，非抓捕）。","tag":"字词释义"},{"s":"“<em class='k'>既</em>毕”中“<em class='k'>既</em>”的意思是？","o":["既然","即使","已经","不久"],"a":"C","e":"“既”意为“已经”。“既毕”即（接见）完毕之后。","tag":"字词释义"},{"s":"“既<em class='k'>毕</em>”中“<em class='k'>毕</em>”的意思是？","o":["结束","全部","毕竟","穷尽"],"a":"A","e":"“毕”意为“完毕、结束”。“既毕”即（接见）结束后。","tag":"字词释义"},{"s":"“魏王<em class='k'>雅望</em>非常”中“<em class='k'>雅望</em>”的意思是？","o":["高雅的期望","崇高的声望","深远的谋划","傲慢的态度"],"a":"B","e":"“雅望”意为“崇高的声望”（雅，美好；望，声望），不是“期望”。","tag":"字词释义"},{"s":"“魏王雅望<em class='k'>非常</em>”中“<em class='k'>非常</em>”的意思是？","o":["不同寻常","十分","经常","平凡"],"a":"A","e":"“非常”是古今异义，古义为“不同寻常”，今义为“十分”。“雅望非常”即声望不同寻常。","tag":"字词释义"},{"s":"“<em class='k'>然</em>床头捉刀人乃英雄也”中“<em class='k'>然</em>”的意思是？","o":["然而","这样","于是","果然"],"a":"A","e":"“然”表转折，然而。“然床头捉刀人乃英雄也”即然而床边握着刀的那个人才是英雄。","tag":"字词释义"},{"s":"“床头捉刀人<em class='k'>乃</em>英雄也”中“<em class='k'>乃</em>”的意思是？","o":["于是","竟然","你的","就是"],"a":"D","e":"“乃”是副词，表判断，就是。“乃英雄也”即才是英雄。","tag":"字词释义"},{"s":"给下面的句子断句（原句去掉标点）：魏王雅望非常然床头捉刀人乃英雄也，停顿正确的一项是？","o":["魏王雅望非常 / 然床头捉刀人 / 乃英雄也","魏王雅望 / 非常然床头捉刀人 / 乃英雄也","魏王 / 雅望非常然 / 床头捉刀人乃英雄也","魏王雅望非常然 / 床头捉刀人 / 乃英雄也"],"a":"A","e":"“魏王雅望非常”是完整分句（魏王声望不同寻常）；“然”表转折，领起后句；“床头捉刀人乃英雄也”中“乃”表判断。A 正确。","tag":"断句"},{"s":"下列对“魏王雅望非常，然床头捉刀人乃英雄也”翻译最准确的一项是？","o":["魏王声望不同寻常，然而床边握着刀的那个人才是英雄。","魏王的期望很不一般，但床边捉刀的人才是英雄。","魏王非常儒雅有风度，他身边拿刀的侍卫是英雄。","魏王看人眼光独到，他身旁握刀之人必有大勇。"],"a":"A","e":"A 直译准确。B 误译“雅望”为“期望”；C“儒雅有风度”“侍卫”是原文没有的过度意译；D“看人眼光独到”“大勇”是原文没有的内容。","tag":"内容理解"},{"s":"下列对“自以形陋，不足雄远国，使崔季圭代，帝自捉刀立床头”翻译最准确的一项是？","o":["魏武帝认为自己形貌丑陋，不足以在远国（使者面前）称雄，就让崔季圭代替自己，自己握着刀站在床头。","魏武帝觉得自己长得丑，不好意思接见外国使者，就让崔季圭去，自己拿刀站在床边。","魏武帝因相貌难看而不配与远方国家的人相见，于是派崔季圭充当使者，自己持刀立于床侧。","魏武帝自觉相貌丑陋，便让崔季圭代替接见使者，自己握刀站在床边。"],"a":"A","e":"A 直译准确，各词均有落实。B“不好意思”是过度意译且漏译“不足雄远国”；C“不配……相见”过度意译；D 漏译“不足雄远国”。","tag":"内容理解"}],"jd":[{"o":"魏武将见匈奴使，自以形陋，不足雄远国，使崔季圭代，帝自捉刀立床头。","t":"魏武帝将要接见匈奴使者，（他）认为自己形貌丑陋，不足以在远国（使者面前）称雄，就让崔季圭代替自己，（魏武帝）自己握着刀站在床头。","notes":[["雄","名词作动词，称雄"],["使","派遣，让"],["捉","握"]]},{"o":"既毕，令间谍问曰：“魏王何如？”","t":"（接见）完毕后，（他）派间谍问（使者）说：“魏王怎么样？”","notes":[["既","已经"],["毕","完毕，结束"],["间谍","此处指侦察消息的探子"]]},{"o":"匈奴使答曰：“魏王雅望非常，然床头捉刀人乃英雄也。”","t":"匈奴使者回答说：“魏王声望不同寻常，然而床边握着刀的那个人才是英雄。”","notes":[["雅望","崇高的声望"],["非常","不同寻常"],["然","然而"],["乃","就是，表判断"]]},{"o":"魏武闻之，追杀此使。","t":"魏武帝听说了这件事，就派人追杀这个使者。","notes":[["闻","听说"],["追","追赶"]]}]},{"no":6,"t":"偶遇知音","src":"课外古文·初级·《笑林广记》","tag":"课外·初级","html":true,"p":["某生<u>素</u>善琴，<u>尝</u><u>谓</u>世无知音，<span class=\"jz\" title=\"抑抑：郁郁不乐的样子\">抑抑不乐。一日无事，抚琴消遣，忽闻隔邻，有叹息声，大喜，以为知音在<u>是</u>，<u>款</u>扉<u>叩</u>之，邻媪曰：“无他，亡儿存日，以<span class=\"jz\" title=\"弹絮：弹棉花。絮，棉絮\">弹絮为业，今客<u>鼓</u>此，<u>酷</u>类其音，闻之，不觉悲从中<u>耳</u>。”<br>\n    💡 带下划线的词可点击查看注释；黄色高亮为考察的实词"],"common":"","q":[{"s":"“某生<em class='k'>素</em>善琴”中“<em class='k'>素</em>”的意思是？","o":["一向","白色","朴素","平时"],"a":"A","e":"“素”意为向来、一向。“素善琴”即向来擅长弹琴。","tag":"字词释义"},{"s":"“<em class='k'>尝</em>谓世无知音”中“<em class='k'>尝</em>”的意思是？","o":["曾经","品尝","尝试","常常"],"a":"A","e":"“尝”意为曾经。“尝谓”即曾经说。","tag":"字词释义"},{"s":"“尝<em class='k'>谓</em>世无知音”中“<em class='k'>谓</em>”的意思是？","o":["说","称呼","叫做","告诉"],"a":"A","e":"“谓”意为说。“尝谓世无知音”即曾经说世上没有知音。","tag":"字词释义"},{"s":"“以为知音在<em class='k'>是</em>”中“<em class='k'>是</em>”的意思是？","o":["这里","正确","判断词","这样"],"a":"A","e":"“是”意为这里（代词，表处所）。“知音在是”即知音在这里。","tag":"字词释义"},{"s":"“<em class='k'>款</em>扉叩之”中“<em class='k'>款</em>”的意思是？","o":["敲","款待","缓慢","款式"],"a":"A","e":"“款”意为敲。“款扉”即敲门。","tag":"字词释义"},{"s":"“款扉<em class='k'>叩</em>之”中“<em class='k'>叩</em>”的意思是？","o":["询问","叩头","敲打","跪拜"],"a":"A","e":"“叩”意为敲（门）并询问。“叩之”即敲门问他。","tag":"字词释义"},{"s":"“今客<em class='k'>鼓</em>此”中“<em class='k'>鼓</em>”的意思是？","o":["弹奏","敲鼓","鼓起","鼓动"],"a":"A","e":"“鼓”名词作动词，弹奏。“鼓此”即弹这个（琴）。","tag":"字词释义"},{"s":"“<em class='k'>酷</em>类其音”中“<em class='k'>酷</em>”的意思是？","o":["很，非常","残酷","酷热","酷刑"],"a":"A","e":"“酷”意为很、非常。“酷类其音”即非常像他的（弹棉花）声音。","tag":"字词释义"},{"s":"“不觉悲从中<em class='k'>耳</em>”中“<em class='k'>耳</em>”的意思是？","o":["罢了","耳朵","听闻","然而"],"a":"A","e":"“耳”是句末语气词，罢了。“悲从中耳”即悲从中来罢了。","tag":"字词释义"},{"s":"对“亡儿存日，以弹絮为业”翻译正确的一项是？","o":["死去的儿子在世时，以弹棉花为职业","死去的儿子存在时，用弹棉花作为产业","死去的儿子每天用弹棉花来打发日子","死去的儿子生前靠卖棉花维持生计"],"a":"A","e":"“亡儿”即死去的儿子，“存日”即在世时，“弹絮”即弹棉花。A 翻译准确。B 误译“存日”；C 误译“为业”；D 误译“弹絮”为卖棉花。","tag":"翻译"},{"s":"对“今客鼓此，酷类其音”翻译正确的一项是？","o":["如今客人弹这个（琴），声音非常像他的（弹棉花声）","如今客人敲这个鼓，声音很像他的声音","如今客人弹奏这个，酷似他的音乐","今天客人弹这琴，像他唱歌的声音"],"a":"A","e":"“鼓”意为弹奏，“酷”意为非常，“类”意为像。A 翻译准确。B 误译“鼓”为敲鼓；C“其音”指代不明；D 误以为“弹絮”是唱歌。","tag":"翻译"},{"s":"下列对文章内容理解正确的一项是？","o":["老妇人叹息是因为书生弹琴的声音像她死去的儿子弹棉花的声音","老妇人认为书生琴艺高超，是难得的知音","书生弹琴声音太差，老妇人听了感到心烦","老妇人的儿子生前也喜欢弹琴，所以听到琴声伤感"],"a":"A","e":"A 正确。老妇人说“今客鼓此，酷类其音”，她叹息是触景伤情，想起弹棉花的亡儿，并非把书生当作知音。B、C、D 均与文意不符。","tag":"内容理解"}],"jd":[{"o":"某生素善琴，尝谓世无知音，抑抑不乐。","t":"有个书生向来擅长弹琴，曾经说世上没有知音，郁郁不乐。","notes":[["素","一向"],["尝","曾经"],["谓","说"],["抑抑","郁郁不乐的样子"]]},{"o":"一日无事，抚琴消遣，忽闻隔邻，有叹息声，大喜，以为知音在是，款扉叩之。","t":"一天没事，弹琴消遣，忽然听到隔壁有叹息声，（他）非常高兴，以为知音就在这里，（便）敲门询问。","notes":[["是","这里"],["款","敲"],["叩","询问"]]},{"o":"邻媪曰：“无他，亡儿存日，以弹絮为业，今客鼓此，酷类其音，闻之，不觉悲从中耳。”","t":"邻居老妇人说：“没有别的（原因），我死去的儿子在世时，以弹棉花为职业，如今客人弹这个（琴），（声音）非常像他的（弹棉花声），听了，不由得悲伤从心中涌起罢了。”","notes":[["媪","老妇人"],["存日","在世时"],["弹絮","弹棉花"],["鼓","弹奏"],["酷","很，非常"],["耳","罢了"]]},{"o":"","t":"","notes":[]}]},{"no":7,"t":"先后","src":"课外古文·初级·《笑林广记》","tag":"课外·初级","html":true,"p":["有人剃头<u>于</u>铺，其人剃发极<span class=\"jz\" title=\"草率：马虎，不认真\">草率，既<u>毕</u>，特倍<u>与</u>之钱而行。<u>异日</u>复往，其人<u>竭力</u>为主剃发，加倍工夫，事事周到，<u>既</u>已，<u>乃</u>少给其资。其人不服曰：“前次剃头草率，<u>尚</u>蒙厚赐，此番格外用心，何可如此？”此人<u>谓</u>曰：“今之资，前已给过。今日所给<u>乃</u>前次之资也。”<br>\n    💡 带下划线的词可点击查看注释；黄色高亮为考察的实词"],"common":"","q":[{"s":"“有人剃头<em class='k'>于</em>铺”中“<em class='k'>于</em>”的意思是？","o":["在","从","向","被"],"a":"A","e":"“于”是介词，在。“剃头于铺”即在理发铺里剃头。","tag":"字词释义"},{"s":"“既<em class='k'>毕</em>”中“<em class='k'>毕</em>”的意思是？","o":["完，结束","毕竟","毕业","全，都"],"a":"A","e":"“毕”意为完毕、结束。“既毕”即剃完以后。","tag":"字词释义"},{"s":"“特倍<em class='k'>与</em>之钱而行”中“<em class='k'>与</em>”的意思是？","o":["给","和","参与","结交"],"a":"A","e":"“与”是动词，给。“与之钱”即给他钱。","tag":"字词释义"},{"s":"“<em class='k'>异日</em>复往”中“<em class='k'>异日</em>”的意思是？","o":["改天","平时","当日","往日"],"a":"A","e":"“异日”意为他日、改天。“异日复往”即改天又去。","tag":"字词释义"},{"s":"“其人<em class='k'>竭力</em>为主剃发”中“<em class='k'>竭力</em>”的意思是？","o":["尽力","敷衍","随意","马虎"],"a":"A","e":"“竭力”意为用尽全力。“竭力为主剃发”即尽力为（顾客）剃发。","tag":"字词释义"},{"s":"“<em class='k'>既</em>已”中“<em class='k'>既</em>”的意思是？","o":["已经","既然","即使","完成"],"a":"A","e":"“既”意为已经。“既已”即已经（剃完）。","tag":"字词释义"},{"s":"“<em class='k'>乃</em>少给其资”中“<em class='k'>乃</em>”的意思是？","o":["却","于是","才","就"],"a":"A","e":"“乃”表转折，却。“既已，乃少给其资”即剃完以后，却少给他钱。","tag":"字词释义"},{"s":"“<em class='k'>尚</em>蒙厚赐”中“<em class='k'>尚</em>”的意思是？","o":["还，尚且","高尚","崇尚","骄傲"],"a":"A","e":"“尚”意为还、尚且。“尚蒙厚赐”即还承蒙丰厚的赏赐。","tag":"字词释义"},{"s":"“此人<em class='k'>谓</em>曰”中“<em class='k'>谓</em>”的意思是？","o":["说","称呼","以为","叫做"],"a":"A","e":"“谓”意为说、告诉。“谓曰”即说道。","tag":"字词释义"},{"s":"“今日所给<em class='k'>乃</em>前次之资也”中“<em class='k'>乃</em>”的意思是？","o":["是","却","才","于是"],"a":"A","e":"“乃”表判断，是。“今日所给乃前次之资也”即今天所给（的钱）是前次的工钱。与第 7 题“乃”（却）用法不同。","tag":"字词释义"},{"s":"对“特倍与之钱而行”翻译正确的一项是？","o":["特意加倍给他钱就走了","特意给他双倍的钱让他走","特地和他平分了钱就走了","特意多给他钱后行走起来"],"a":"A","e":"“倍”意为加倍，“与”意为给，“行”意为走、离开。A 翻译准确。B 误译“而”为“让他”；C 误译“倍”为平分；D 误译“行”为行走。","tag":"翻译"},{"s":"对“今之资，前已给过”翻译正确的一项是？","o":["今天的钱，之前已经给过了","现在的工资，之前已经发过了","今天来的人，之前已经见过了","这次的账，以前已经结过了"],"a":"A","e":"“资”意为钱，“前”意为先前。A 翻译准确。B 误译“资”为工资；C 误译“资”为人；D 误译“资”为账。","tag":"翻译"},{"s":"对顾客“今日所给乃前次之资也”这句话的理解，正确的一项是？","o":["第一次多给的钱已预付第二次的工钱，所以第二次给得少","顾客记性不好，忘记给过第二次的钱","顾客认为剃头匠手艺差，不想付工钱","顾客的钱被偷了，只能少给一些"],"a":"A","e":"A 正确。顾客的意思是第一次“特倍与之钱”时，多给的部分已算作第二次的工钱，所以第二次少给也“有理”，借此占剃头匠的便宜。","tag":"内容理解"}],"jd":[{"o":"有人剃头于铺，其人剃发极草率，既毕，特倍与之钱而行。","t":"有个人在理发铺里剃头，那个剃头匠剃发非常草率马虎，剃完以后，（这个人）特意加倍给他钱就走了。","notes":[["于","在"],["毕","完，结束"],["与","给"],["行","走，离开"]]},{"o":"异日复往，其人竭力为主剃发，加倍工夫，事事周到，既已，乃少给其资。","t":"改天（这个人）又去（那家铺子），那个剃头匠尽力为（他）剃发，加倍下功夫，每件事都周到，剃完以后，（顾客）却少给他钱。","notes":[["异日","改天"],["竭力","尽力"],["既","已经"],["乃","却"],["资","钱"]]},{"o":"其人不服曰：“前次剃头草率，尚蒙厚赐，此番格外用心，何可如此？”","t":"剃头匠不服气地说：“前次剃头草率，还承蒙厚赏，这次格外用心，怎么可以这样（少给钱）？”","notes":[["尚","还，尚且"],["厚赐","丰厚的赏赐"],["何","怎么"]]},{"o":"此人谓曰：“今之资，前已给过。今日所给乃前次之资也。”","t":"这个顾客说道：“今天的钱，之前已经给过了。今天所给的（钱），是前次的工钱啊。”","notes":[["谓","说"],["资","钱"],["乃","是"]]},{"o":"","t":"","notes":[]}]},{"no":8,"t":"前倨后恭","src":"课外古文·初级·唐代笔记","tag":"课外·初级","html":true,"p":["裴佶少时，姑夫为<span class=\"jz\" title=\"朝官：在朝廷任职的官员\">朝官，有<u>雅望</u>。佶至宅看其姑，<u>会</u>其朝退，深叹曰：“崔昭何人？众口称美，此必行贿者也。如此<u>安得</u>不乱？”言未<u>竟</u>，<u>阍者</u>报崔使君候<u>谒</u>。姑夫怒呵阍者，将鞭之。<u>良</u>久，<span class=\"jz\" title=\"束带：整理衣带，指穿戴整齐\">束带<u>强</u>出。<span class=\"jz\" title=\"须臾：一会儿，片刻\">须臾，命茶甚急，又命酒馔，又令秣马、<u>饭</u>仆。姑曰：“前何<u>倨</u>而后何恭也！”<u>及</u>入门，有得色，揖佶曰：“且憩<u>学院</u>中。”佶未下阶，出怀中一纸，<u>乃</u>昭赠<span class=\"jz\" title=\"官缣(jiān)：官府的细绢\">官缣千匹。<br>\n    💡 带下划线的词可点击查看注释；黄色高亮为考察的实词"],"common":"","q":[{"s":"“有<em class='k'>雅望</em>”中“<em class='k'>雅望</em>”的意思是？","o":["美好的声望","高雅的期望","公正的评价","远大的志向"],"a":"A","e":"“雅”意为美好，“望”意为声望。“雅望”即美好的声望，指高尚的名声。其余三项均为字面拆解。","tag":"字词释义"},{"s":"“<em class='k'>会</em>其朝退”中“<em class='k'>会</em>”的意思是？","o":["恰逢","聚会","领会","必然"],"a":"A","e":"“会”意为恰逢、正赶上。“会其朝退”即正赶上他退朝回来。","tag":"字词释义"},{"s":"“如此<em class='k'>安得</em>不乱”中“<em class='k'>安得</em>”的意思是？","o":["怎么能","如何获得","从何而来","怎么不会"],"a":"A","e":"“安得”意为怎么能够，表反问。“如此安得不乱”即这样怎么能够不乱呢。","tag":"字词释义"},{"s":"“言未<em class='k'>竟</em>”中“<em class='k'>竟</em>”的意思是？","o":["结束","竟然","毕竟","最终"],"a":"A","e":"“竟”意为完毕、结束。“言未竟”即话没说完。","tag":"字词释义"},{"s":"“<em class='k'>阍者</em>报崔使君候谒”中“<em class='k'>阍者</em>”的意思是？","o":["守门人","使者","仆人","官员"],"a":"A","e":"“阍”指守门，“阍者”即守门人。“阍者报”即守门人禀报。","tag":"字词释义"},{"s":"“崔使君候<em class='k'>谒</em>”中“<em class='k'>谒</em>”的意思是？","o":["拜见","报告","邀请","命令"],"a":"A","e":"“谒”意为拜见（进见尊长）。“候谒”即等候拜见。","tag":"字词释义"},{"s":"“<em class='k'>良</em>久”中“<em class='k'>良</em>”的意思是？","o":["很，甚","良好","确实","善良"],"a":"A","e":"“良久”意为很久，“良”表程度，很、甚。","tag":"字词释义"},{"s":"“束带<em class='k'>强</em>出”中“<em class='k'>强</em>”的意思是？","o":["勉强","强硬","强大","强迫"],"a":"A","e":"“强”意为勉强。“强出”即勉强出来（接见）。","tag":"字词释义"},{"s":"“又令秣马、<em class='k'>饭</em>仆”中“<em class='k'>饭</em>”的意思是？","o":["给……吃饭","吃饭","饭菜","休息"],"a":"A","e":"“饭”名词作动词，给……吃饭（使动）。“饭仆”即给仆人吃饭。","tag":"字词释义"},{"s":"“前何<em class='k'>倨</em>而后何恭也”中“<em class='k'>倨</em>”的意思是？","o":["傲慢","谨慎","急切","慌张"],"a":"A","e":"“倨”意为傲慢。“前何倨而后何恭”即先前为何傲慢、后来为何恭敬。","tag":"字词释义"},{"s":"“<em class='k'>及</em>入门”中“<em class='k'>及</em>”的意思是？","o":["等到","及时","涉及","趁着"],"a":"A","e":"“及”意为等到。“及入门”即等到（他）进门。","tag":"字词释义"},{"s":"“且憩<em class='k'>学院</em>中”中“<em class='k'>学院</em>”的意思是？","o":["书房","学校","官署","客厅"],"a":"A","e":"“学院”在文中指书房（私人读书处）。“憩学院中”即在书房里休息。","tag":"字词释义"},{"s":"“<em class='k'>乃</em>昭赠官缣千匹”中“<em class='k'>乃</em>”的意思是？","o":["是","竟然","于是","才"],"a":"A","e":"“乃”表判断，是。“乃昭赠官缣千匹”即（纸上写的）是崔昭赠送官缣千匹（的凭证）。","tag":"字词释义"}],"jd":[{"o":"裴佶少时，姑夫为朝官，有雅望。","t":"裴佶年少时，姑夫是朝廷官员，有美好的声望。","notes":[["朝官","在朝廷任职的官员"],["雅望","美好的声望"]]},{"o":"佶至宅看其姑，会其朝退，深叹曰：“崔昭何人？众口称美，此必行贿者也。如此安得不乱？”","t":"裴佶到宅子看望姑母，正赶上姑夫退朝回来，（姑夫）深深地叹息说：“崔昭是什么人？众口称赞他好，这一定是行贿得来的。这样怎么能够不乱呢？”","notes":[["会","恰逢"],["行贿","行贿，以财物买通"],["安得","怎么能"]]},{"o":"言未竟，阍者报崔使君候谒。","t":"话没说完，守门人禀报崔使君等候拜见。","notes":[["竟","结束"],["阍者","守门人"],["谒","拜见"]]},{"o":"姑夫怒呵阍者，将鞭之。良久，束带强出。","t":"姑夫生气地呵斥守门人，要用鞭子打他。过了很久，（姑夫）整理好衣带勉强出来（见客）。","notes":[["鞭","用鞭子打"],["良","很，甚"],["束带","整理衣带，指穿戴整齐"],["强","勉强"]]},{"o":"须臾，命茶甚急，又命酒馔，又令秣马、饭仆。","t":"一会儿，（姑夫）急着命人上茶，又命人备酒食，又让人喂马、给仆人吃饭。","notes":[["须臾","一会儿"],["馔","食物"],["秣马","喂马"],["饭","给……吃饭"]]},{"o":"姑曰：“前何倨而后何恭也！”及入门，有得色，揖佶曰：“且憩学院中。”","t":"姑母说：“先前为何傲慢，后来为何恭敬啊！”等到（姑夫）进门，一脸得意的神色，向裴佶作揖说：“暂且到书房里休息吧。”","notes":[["倨","傲慢"],["及","等到"],["得色","得意的神色"],["学院","书房"]]},{"o":"佶未下阶，出怀中一纸，乃昭赠官缣千匹。","t":"裴佶还没走下台阶，（姑夫）从怀中掏出一张纸，（上面写的）是崔昭赠送官缣千匹（的凭证）。","notes":[["乃","是"],["昭","崔昭"],["官缣","官府的细绢"]]}]},{"no":9,"t":"原不识字","src":"课外古文·初级·《笑林广记》","tag":"课外·初级","html":true,"p":["有<u>延</u>师教其子者，师至，主人曰：“家贫，多失礼<u>于</u>先生，<u>奈何</u>！”师曰：“何言之谦，仆<u>固</u>无不可者。”主人曰：“<span class=\"jz\" title=\"蔬食：粗茶淡饭，简单的饭菜\">蔬食，可乎？”曰：“可。”主人曰：“家无<u>臧获</u>，<u>凡</u>洒扫<span class=\"jz\" title=\"庭除：庭院和台阶，除即台阶\">庭除，启闭门户，劳先生<u>为</u>之，可乎？”曰：“可。”主人曰：“<u>或</u>家人妇子欲买零星杂物，屈先生一行，可乎？”曰：“可。”主人曰：“如此，<span class=\"jz\" title=\"幸甚：非常荣幸\">幸甚！”师曰：“<u>仆</u>亦有一言，<u>愿</u>主人勿讶焉。”主人问何言？师曰：“自愧幼时不学耳！”主人曰：“何言之谦。”师曰：“不敢欺，仆实不识一字。”<br>\n    💡 带下划线的词可点击查看注释；黄色高亮为考察的实词"],"common":"","q":[{"s":"“有<em class='k'>延</em>师教其子者”中“<em class='k'>延</em>”的意思是？","o":["聘请","延长","迎接","拖延"],"a":"A","e":"“延”意为聘请、邀请。“延师”即聘请老师。","tag":"字词释义"},{"s":"“多失礼<em class='k'>于</em>先生”中“<em class='k'>于</em>”的意思是？","o":["对，向","在","从","被"],"a":"A","e":"“于”是介词，对、向。“失礼于先生”即对先生多有失礼。","tag":"字词释义"},{"s":"“多失礼于先生，<em class='k'>奈何</em>！”中“<em class='k'>奈何</em>”的意思是？","o":["怎么办","为什么","多么","怎么"],"a":"A","e":"“奈何”是固定结构，怎么办。“多失礼于先生，奈何”即对先生多有失礼，怎么办呢。","tag":"字词释义"},{"s":"“仆<em class='k'>固</em>无不可者”中“<em class='k'>固</em>”的意思是？","o":["本来","坚固","固然","一定"],"a":"A","e":"“固”是副词，本来。“仆固无不可者”即我本来没有什么不可以的。","tag":"字词释义"},{"s":"“家无<em class='k'>臧获</em>”中“<em class='k'>臧获</em>”的意思是？","o":["奴婢","钱财","粮食","藏品"],"a":"A","e":"“臧获”是古代对奴婢的贱称。“家无臧获”即家里没有奴婢。","tag":"字词释义"},{"s":"“<em class='k'>凡</em>洒扫庭除”中“<em class='k'>凡</em>”的意思是？","o":["凡是","平常","总共","平凡"],"a":"A","e":"“凡”是副词，凡是、所有的。“凡洒扫庭除”即凡是洒扫庭院台阶（的杂活）。","tag":"字词释义"},{"s":"“劳先生<em class='k'>为</em>之”中“<em class='k'>为</em>”的意思是？","o":["做","是","因为","被"],"a":"A","e":"“为”是动词，做。“为之”即做这些事。","tag":"字词释义"},{"s":"“<em class='k'>或</em>家人妇子欲买零星杂物”中“<em class='k'>或</em>”的意思是？","o":["有时","或者","有人","或许"],"a":"A","e":"“或”是副词，有时。“或家人妇子欲买零星杂物”即有时家里女眷孩子想买零碎杂物。","tag":"字词释义"},{"s":"“<em class='k'>仆</em>固无不可者”中“<em class='k'>仆</em>”的意思是？","o":["我","仆人","跌倒","侍奉"],"a":"A","e":"“仆”是谦称，我。“仆固无不可者”即我本来没有什么不可以的。","tag":"字词释义"},{"s":"“<em class='k'>愿</em>主人勿讶焉”中“<em class='k'>愿</em>”的意思是？","o":["希望","情愿","心愿","甘心"],"a":"A","e":"“愿”是动词，希望。“愿主人勿讶焉”即希望您不要惊讶。","tag":"字词释义"},{"s":"对“仆实不识一字”翻译正确的一项是？","o":["我确实一个字也不认识","仆人确实不认识一个字","我确实一个字也写不出","我实在不认识一个文字"],"a":"A","e":"“仆”是谦称“我”，“实”是确实，“一字”是一个字。A 翻译准确。B 误把“仆”译成“仆人”。","tag":"翻译"},{"s":"下列对文章内容理解有误的一项是？","o":["主人因家贫，请先生原谅自己多有失礼","先生对主人提出的各种要求都答应了","先生说自己“不识一字”是谦虚之词","故事讽刺了不学无术、不懂装懂的人"],"a":"C","e":"C 有误。先生说自己“不识一字”是实话，不是谦虚之词——正是这种“实话”与开头谦辞的反差构成了笑话的幽默。","tag":"内容理解"}],"jd":[{"o":"有延师教其子者，师至，主人曰：“家贫，多失礼于先生，奈何！”师曰：“何言之谦，仆固无不可者。”","t":"有个人聘请老师教自己的儿子，老师到了，主人说：“家里贫穷，对先生多有失礼，怎么办呢！”老师说：“您说话何必如此谦虚，我本来没有什么不可以的。”","notes":[["延","聘请"],["于","对，向"],["奈何","怎么办"],["固","本来"]]},{"o":"主人曰：“蔬食，可乎？”曰：“可。”主人曰：“家无臧获，凡洒扫庭除，启闭门户，劳先生为之，可乎？”曰：“可。”","t":"主人说：“吃粗茶淡饭，可以吗？”（老师）说：“可以。”主人说：“家里没有奴婢，凡是打扫庭院台阶、开关门户这类杂活，劳累先生来做，可以吗？”（老师）说：“可以。”","notes":[["蔬食","粗茶淡饭"],["臧获","奴婢"],["凡","凡是"],["为","做"]]},{"o":"主人曰：“或家人妇子欲买零星杂物，屈先生一行，可乎？”曰：“可。”主人曰：“如此，幸甚！”师曰：“仆亦有一言，愿主人勿讶焉。”","t":"主人说：“有时家里女眷孩子想买零碎杂物，委屈先生跑一趟，可以吗？”（老师）说：“可以。”主人说：“如果这样，真是太荣幸了！”老师说：“我也有句话，希望您不要惊讶。”","notes":[["或","有时"],["幸甚","非常荣幸"],["仆","我，谦称"],["愿","希望"]]},{"o":"主人问何言？师曰：“自愧幼时不学耳！”主人曰：“何言之谦。”师曰：“不敢欺，仆实不识一字。”","t":"主人问（是）什么话？老师说：“（我）惭愧自己小时候没有学习罢了！”主人说：“您说话何必如此谦虚。”老师说：“不敢欺骗您，我实在一个字也不认识。”","notes":[["耳","罢了"],["实","确实"]]},{"o":"","t":"","notes":[]}]},{"no":10,"t":"吕蒙正为相","src":"课外古文·初级·北宋名臣轶事","tag":"课外·初级","html":true,"p":["<span class=\"jz\" title=\"吕文穆公：即吕蒙正，北宋政治家，官至宰相，谥号文穆\">吕文穆公以宽厚为宰相，太宗<u>尤</u>所<u>眷遇</u>。有一<u>朝士</u>，家藏古镜，自言能照二百里，欲<u>因</u><span class=\"jz\" title=\"公弟：吕蒙正的弟弟\">公弟献以<u>求知</u>。其弟<u>伺</u>间<span class=\"jz\" title=\"从容：舒缓、不慌不忙\">从容言之，公笑曰：“吾面不过碟子大，<u>安</u>用照二百里？”其弟<u>遂</u>不复敢言。闻者叹服，以为贤于<span class=\"jz\" title=\"李卫公：指李德裕，唐代宰相，封卫国公，以廉洁寡欲著称\">李卫公远矣。<u>盖</u><u>寡</u>好而不为物<u>累</u>者，<u>昔</u><span class=\"jz\" title=\"贤：古代贤能之人\">贤之所<u>难</u>也。<br>\n    💡 带下划线的词可点击查看注释；黄色高亮为考察的实词"],"common":"","q":[{"s":"“太宗<em class='k'>尤</em>所眷遇”中“<em class='k'>尤</em>”的意思是？","o":["更加","尤其","怨恨","错误"],"a":"B","e":"“尤”是副词，尤其、特别。“太宗尤所眷遇”即太宗尤其器重（他）。","tag":"字词释义"},{"s":"“太宗尤所<em class='k'>眷遇</em>”中“<em class='k'>眷遇</em>”的意思是？","o":["照顾","遇见","恩遇","眷恋"],"a":"C","e":"“眷遇”是名词，宠爱优待（眷，宠爱；遇，待遇），不是“遇见”。","tag":"字词释义"},{"s":"“有一<em class='k'>朝士</em>”中“<em class='k'>朝士</em>”的意思是？","o":["朝堂武士","朝廷官员","早晨读书人","朝见士人"],"a":"B","e":"“朝士”是名词，朝中大臣（朝，朝廷；士，官员）。","tag":"字词释义"},{"s":"“欲<em class='k'>因</em>公弟献”中“<em class='k'>因</em>”的意思是？","o":["通过","因为","于是","趁机"],"a":"A","e":"“因”是介词，通过、经由。“欲因公弟献”即想通过（吕蒙正的）弟弟献上。","tag":"字词释义"},{"s":"“献以<em class='k'>求知</em>”中“<em class='k'>求知</em>”的意思是？","o":["寻求了解","求得智慧","求被赏识","追求知识"],"a":"C","e":"“求知”意为求被赏识，即求得名声或官职（知，赏识）。","tag":"字词释义"},{"s":"“其弟<em class='k'>伺</em>间从容言之”中“<em class='k'>伺</em>”的意思是？","o":["等待","观察","伺候","窥探"],"a":"A","e":"“伺”意为等待。“伺间”即等待时机。","tag":"字词释义"},{"s":"“<em class='k'>安</em>用照二百里”中“<em class='k'>安</em>”的意思是？","o":["安全","安置","哪里","怎么"],"a":"D","e":"“安”是疑问副词，怎么（表反问）。“安用照二百里”即哪里用得着照二百里。","tag":"字词释义"},{"s":"“其弟<em class='k'>遂</em>不复敢言”中“<em class='k'>遂</em>”的意思是？","o":["最终","竟然","于是","违背"],"a":"C","e":"“遂”是副词，于是、就。“遂不复敢言”即于是不敢再说。","tag":"字词释义"},{"s":"“<em class='k'>盖</em>寡好而不为物累者”中“<em class='k'>盖</em>”的意思是？","o":["覆盖","因为","大概","原来"],"a":"C","e":"“盖”是句首语气词，表推测，大概、因为。“盖寡好而不为物累者”即大概（是因为）嗜好少而不被外物拖累的人。","tag":"字词释义"},{"s":"“<em class='k'>寡</em>好而不为物累者”中“<em class='k'>寡</em>”的意思是？","o":["孤独","少","寡妇","薄弱"],"a":"B","e":"“寡”是形容词，少。“寡好”即嗜好少。","tag":"字词释义"},{"s":"“不为物<em class='k'>累</em>”中“<em class='k'>累</em>”的意思是？","o":["拖累","积累","劳累","累赘"],"a":"A","e":"“累”意为使受牵累、拖累。“不为物累”即不被外物拖累。","tag":"字词释义"},{"s":"“<em class='k'>昔</em>贤之所难也”中“<em class='k'>昔</em>”的意思是？","o":["通“夕”","昔日","同“惜”","从前"],"a":"D","e":"“昔”是名词，从前、过去。“昔贤”即从前的贤人。","tag":"字词释义"},{"s":"“昔贤之所<em class='k'>难</em>也”中“<em class='k'>难</em>”的意思是？","o":["困难","灾难","责难","难以做到"],"a":"D","e":"“难”形容词作动词，以为难、难以做到。“昔贤之所难也”即这是古代贤人也难以做到的事。","tag":"字词释义"}],"jd":[{"o":"吕文穆公以宽厚为宰相，太宗尤所眷遇。","t":"吕文穆公凭宽厚（的品性）担任宰相，太宗尤其器重（他）。","notes":[["宽厚","宽厚（的品性）"],["尤","尤其"],["眷遇","宠爱优待"]]},{"o":"有一朝士，家藏古镜，自言能照二百里，欲因公弟献以求知。","t":"有一位朝廷官员，家里珍藏一面古镜，（他）自己说（这面镜子）能照二百里，想通过吕蒙正的弟弟献上（古镜）以求被赏识。","notes":[["朝士","朝中大臣"],["因","通过，经由"],["求知","求被赏识"]]},{"o":"其弟伺间从容言之，公笑曰：“吾面不过碟子大，安用照二百里？”","t":"他的弟弟等到时机，不慌不忙地提起这件事，吕蒙正笑着说：“我的脸不过碟子那么大，哪里用得着照二百里的镜子？”","notes":[["伺","等待"],["间","时机"],["安","怎么"]]},{"o":"其弟遂不复敢言。","t":"他的弟弟于是不敢再说。","notes":[["遂","于是"]]},{"o":"闻者叹服，以为贤于李卫公远矣。","t":"听说这件事的人都赞叹佩服，认为（吕蒙正）比李卫公贤德多了。","notes":[["闻","听说"],["贤","贤德"],["于","比"]]},{"o":"盖寡好而不为物累者，昔贤之所难也。","t":"大概（因为）嗜好少而不被外物拖累，（这）是古代贤人也难以做到的啊。","notes":[["盖","大概，表推测"],["寡","少"],["累","拖累，使受牵累"],["昔","从前"],["难","难以做到"]]}]},{"no":11,"t":"司马光","src":"部编版三年级上册·《宋史·司马光传》","tag":"三年级上册","html":true,"p":["群儿<u>戏</u><u>于</u><u>庭</u>，一儿<u>登</u><u>瓮</u>，足<u>跌</u><u>没</u>水中。<u>众</u><u>皆</u><u>弃</u><u>去</u>，光<u>持</u>石<u>击破</u><u>之</u>，水<u>迸</u>，儿<u>得活</u>。"],"common":"","q":[{"s":"“群儿<em class='k'>戏</em>于庭”中“<em class='k'>戏</em>”的意思是？","o":["演戏","玩耍","看戏","马戏"],"a":"B","e":"“戏”在此处意为“玩耍”。一群小孩在庭院里玩耍。","tag":"字词释义"},{"s":"“群儿戏<em class='k'>于</em>庭”中“<em class='k'>于</em>”的意思是？","o":["对于","在","于是","关于"],"a":"B","e":"“于”是介词，意为“在”。","tag":"字词释义"},{"s":"“群儿戏于<em class='k'>庭</em>”中“<em class='k'>庭</em>”的意思是？","o":["家庭","朝廷","庭院","大厅"],"a":"C","e":"“庭”指“庭院”，即房子前的院子。","tag":"字词释义"},{"s":"“一儿<em class='k'>登</em>瓮”中“<em class='k'>登</em>”的意思是？","o":["登记","攀登，爬上","蹬腿","刊登"],"a":"B","e":"“登”意为“攀登、爬上”。一个小孩爬上了瓮缸。","tag":"字词释义"},{"s":"“一儿登<em class='k'>瓮</em>”中“<em class='k'>瓮</em>”是什么？","o":["水缸（口小腹大的陶器）","水桶","大锅","瓶子"],"a":"A","e":"“瓮”是口小腹大的陶制容器，用来盛水或酒。这里指庭院里的大水缸。","tag":"字词释义"},{"s":"“足跌<em class='k'>没</em>水中”中“<em class='k'>没</em>”的读音和意思是？","o":["méi，没有","mò，淹没","méi，没事儿","mò，出没"],"a":"B","e":"“没”读mò，意为“淹没”。小孩失足落入水中，被水淹没。","tag":"字词释义"},{"s":"“<em class='k'>众</em>皆弃去”中“<em class='k'>众</em>”的意思是？","o":["众多","观众","众人","群众"],"a":"C","e":"“众”指“大家、其他人”，即其他小孩。","tag":"字词释义"},{"s":"“众<em class='k'>皆</em>弃去”中“<em class='k'>皆</em>”的意思是？","o":["都","一起","普通","皆是"],"a":"A","e":"“皆”意为“都”。其他小孩都吓跑了。","tag":"字词释义"},{"s":"“众皆<em class='k'>去</em>”中“<em class='k'>去</em>”的意思是？","o":["离开","去…","去除","跑了"],"a":"A","e":"“去”在古文中意为“离开”。其他小孩都抛下（落水的小孩）离开了。","tag":"字词释义"},{"s":"“光<em class='k'>持</em>石击瓮破之”中“<em class='k'>持</em>”的意思是？","o":["保持","坚持","拿","支持"],"a":"C","e":"“持”意为“拿”。司马光拿起石头砸瓮。","tag":"字词释义"},{"s":"“水<em class='k'>迸</em>”中“<em class='k'>迸</em>”的意思是？","o":["迸发","喷涌而出","迸裂","四溅"],"a":"B","e":"“迸”意为“喷涌而出”。瓮被砸破后，水一下子喷涌出来。","tag":"字词释义"},{"s":"这个故事主要表现了司马光的什么品质？","o":["胆小怕事","聪明勇敢、临危不乱","力气很大","喜欢玩石头"],"a":"B","e":"面对突发危险，其他孩子都吓跑了，司马光却沉着冷静地砸瓮救人，表现了聪明勇敢、临危不乱的品质。","tag":"内容理解"}],"jd":[{"o":"群儿戏于庭，","t":"一群小孩在庭院里玩耍，","notes":[["戏","玩耍"],["于","在"],["庭","庭院"]]},{"o":"一儿登瓮，足跌没水中。","t":"一个小孩爬上瓮缸，失足落入水中。","notes":[["登","爬上"],["瓮","水缸"],["没","淹没"]]},{"o":"众皆弃去，","t":"众人都丢下（他）跑了，","notes":[["众","大家"],["皆","都"],["弃去","抛下离开"]]},{"o":"光持石击瓮破之，","t":"司马光拿石头击打瓮缸，打破了它，","notes":[["持","拿"]]},{"o":"水迸，儿得活。","t":"水喷涌而出，小孩得以活命。","notes":[["迸","喷涌而出"],["得活","得以活命"]]}]},{"no":12,"t":"守株待兔","src":"部编版三年级下册·《韩非子·五蠹》","tag":"三年级下册","html":true,"p":["宋人有<u>耕</u>者。田中有株。兔<u>走</u><u>触</u>株，折<u>颈</u>而死。<u>因</u><u>释</u>其<u>耒</u>而守株，<u>冀</u><u>复</u><u>得</u>兔。兔不可复<u>得</u>，而身<u>为</u>宋国<u>笑</u>。"],"common":"","q":[{"s":"“宋人有<em class='k'>耕</em>者”中“<em class='k'>耕</em>”的意思是？","o":["打猎","耕种","砍柴","钓鱼"],"a":"B","e":"“耕”意为“耕种”。宋国有个耕种的人（农民）。","tag":"字词释义"},{"s":"“兔<em class='k'>走</em>触株”中“<em class='k'>走</em>”的意思是？","o":["走路","跑","散步","逃走"],"a":"B","e":"“走”在古文中意为“跑”，是古今异义词。现代汉语的“走”古代说“行”。","tag":"字词释义"},{"s":"“兔走<em class='k'>触</em>株”中“<em class='k'>触</em>”的意思是？","o":["接触","碰撞","触摸","触发"],"a":"B","e":"“触”意为“碰撞”。兔子跑得太快，撞到了树桩上。","tag":"字词释义"},{"s":"“折<em class='k'>颈</em>而死”中“<em class='k'>颈</em>”的意思是？","o":["头","脖子","翅膀","脚"],"a":"B","e":"“颈”指“脖子”。兔子撞断脖子而死。","tag":"字词释义"},{"s":"“<em class='k'>因</em>释其耒”中“<em class='k'>因</em>”的意思是？","o":["因为","于是","原因","因此"],"a":"B","e":"“因”在此处意为“于是”，表示顺承关系。","tag":"字词释义"},{"s":"“因<em class='k'>释</em>其耒”中“<em class='k'>释</em>”的意思是？","o":["解释","释放","放下","消失"],"a":"C","e":"“释”意为“放下”。农民放下农具不再干活。","tag":"字词释义"},{"s":"“因释其<em class='k'>耒</em>”中“<em class='k'>耒</em>”是什么？","o":["一种农具","一棵树","一把伞","一个笼子"],"a":"A","e":"“耒”是古代用来耕田的农具，类似今天的犁。","tag":"字词释义"},{"s":"“<em class='k'>冀</em>复得兔”中“<em class='k'>冀</em>”的意思是？","o":["希望","继续","既然","奇怪"],"a":"A","e":"“冀”意为“希望”。农夫希望再得到一只兔子。","tag":"字词释义"},{"s":"“冀<em class='k'>复</em>得兔”中“<em class='k'>复</em>”的意思是？","o":["复习","恢复","再，又","答复"],"a":"C","e":"“复”意为“再、又”。希望能再得到一只兔子。","tag":"字词释义"},{"s":"“兔不可复<em class='k'>得</em>”中“<em class='k'>得</em>”的意思是？","o":["得到","得意","得体","来得及"],"a":"A","e":"“得”意为“得到”。兔子不可能再得到了。","tag":"字词释义"},{"s":"“而身<em class='k'>为</em>宋国笑”中“<em class='k'>为</em>”的意思是？","o":["为了","因为","被","成为"],"a":"C","e":"“为”表示被动，意为“被”。农夫被宋国人耻笑。","tag":"字词释义"},{"s":"这则寓言告诉我们什么道理？","o":["兔子跑得快容易撞树","不要心存侥幸，要靠劳动获得成果","种地很辛苦","树桩可以用来抓兔子"],"a":"B","e":"守株待兔讽刺了那些把偶然当作必然、妄想不劳而获的人。告诉我们不要心存侥幸，要靠诚实的劳动获得成果。","tag":"内容理解"}],"jd":[{"o":"宋人有耕者。田中有株。","t":"宋国有个种地的农民。田地里有一截树桩。","notes":[["耕","耕种"]]},{"o":"兔走触株，折颈而死。","t":"一只兔子跑过来撞到树桩上，折断脖子死了。","notes":[["走","跑"],["触","碰撞"],["颈","脖子"]]},{"o":"因释其耒而守株，冀复得兔。","t":"于是农夫放下农具守在树桩旁，希望能再得到兔子。","notes":[["因","于是"],["释","放下"],["耒","农具"],["冀","希望"],["复","再"]]},{"o":"兔不可复得，而身为宋国笑。","t":"兔子不可能再得到了，而农夫自己被宋国人耻笑。","notes":[["为","被"],["笑","耻笑"]]}]},{"no":13,"t":"囊萤夜读","src":"部编版四年级上册·《晋书·车胤传》","tag":"四年级上册","html":true,"p":["胤<u>恭勤</u>不<u>倦</u>，博学多<u>通</u>。家贫不<u>常</u>得油，夏月则<u>练囊</u><u>盛</u>数十<u>萤火</u>以照书，<u>以夜继日</u>焉。<br>"],"common":"本文选自《晋书·车胤传》。“囊”用袋子装，“萤”萤火虫。","q":[{"s":"“胤<em class='k'>恭勤</em>不倦”中“<em class='k'>恭勤</em>”的意思是？","o":["恭谨","庭勤","肃敬勤勉","恭敬"],"a":"C","e":"“恭勤”意为“肃敬勤勉”。车胤肃敬勤勉而不知疲倦。","tag":"字词释义"},{"s":"“恭勤不<em class='k'>倦</em>”中“<em class='k'>倦</em>”的意思是？","o":["疲倦","反倦","懈怠","厌倦"],"a":"A","e":"“倦”意为“疲倦”。肃敬勤勉而不知疲倦。","tag":"字词释义"},{"s":"“博学多<em class='k'>通</em>”中“<em class='k'>通</em>”的意思是？","o":["通过","流通","通晓，明白","串通"],"a":"C","e":"“通”意为“通晓，明白”。博学多通即知识广博，学问精通。","tag":"字词释义"},{"s":"“家贫不<em class='k'>常</em>得油”中“<em class='k'>常</em>”的意思是？","o":["经常","平常","常识","常见"],"a":"A","e":"“常”意为“经常”。家境贫寒，不能经常得到灯油。","tag":"字词释义"},{"s":"“夏月则<em class='k'>练囊</em>”中“<em class='k'>练囊</em>”是什么？","o":["练习用的袋子","白色薄绢做的口袋","棉布袋","练过的袋子"],"a":"B","e":"“练囊”指“白色薄绢做的口袋”。“练”是白色薄绢，“囊”是袋子。","tag":"字词释义"},{"s":"“练囊<em class='k'>盛</em>数十萤火”中“<em class='k'>盛</em>”的意思是？","o":["盛大","装着","孟","充满"],"a":"B","e":"“盛”读shèng，意为“装”。用白绢袋子装数十只萤火虫。","tag":"字词释义"},{"s":"“盛数十<em class='k'>萤火</em>”中“<em class='k'>萤火</em>”指的是？","o":["火光","萤火虫","火把","荧幕"],"a":"B","e":"“萤火”指的是“萤火虫”。古人称萤火虫为“萤”。","tag":"字词释义"},{"s":"“<em class='k'>以夜继日</em>”中“<em class='k'>以夜继日</em>”的意思是？","o":["夜晚接着白天","白天接着夜晚","以夜替日","夜和日一样"],"a":"A","e":"“以夜继日”即“用夜晚接着白天”，形容夜以继日地学习。","tag":"字词释义"},{"s":"车胤用什么照亮书籍？","o":["灯油","月光","萤火虫","火把"],"a":"C","e":"车胤用白绢袋子装萤火虫照亮书籍，即“囊萤夜读”故事。","tag":"内容理解"},{"s":"这则故事表现了车胤什么样的品质？","o":["聪明过人","苦学勤奋、刻苦读书","喜欢萤火虫","有钱买油"],"a":"B","e":"囊萤夜读表现了车胤刻苦勤奋、刻苦读书的品质。这也是后世“囊萤夜读”典故的来历。","tag":"内容理解"}],"jd":[{"o":"胤恭勤不倦，博学多通。","t":"车胤肃敬勤勉而不知疲倦，知识广博，学问精通。","notes":[["恭勤","肃敬勤勉"],["倦","疲倦"],["通","通晓"]]},{"o":"家贫不常得油，","t":"他家境贫寒，不能经常得到灯油。","notes":[["常","经常"]]},{"o":"夏月则练囊盛数十萤火以照书，","t":"夏天的夜晚，就用白绢做成透光的袋子，装几十只萤火虫照着书本，","notes":[["练囊","白色薄绢做的口袋"],["盛","装"],["萤火","萤火虫"],["照","照亮"]]},{"o":"以夜继日焉。","t":"夜以继日地学习着。","notes":[["以夜继日","夜以继日"]]}]},{"no":14,"t":"王戎不取道旁李","src":"部编版四年级上册·《世说新语》","tag":"四年级上册","html":true,"p":["王戎七岁，<u>尝</u><u>与</u><u>诸</u>小儿<u>游</u>。看道边李树多<u>子</u><u>折</u>枝，<u>诸</u>儿<u>竞</u><u>走</u><u>取</u><u>之</u>，<u>唯</u>戎不动。人问<u>之</u>，答<u>曰</u>：“树在道边而多子，<u>此</u><u>必</u><u>苦</u>李。”取之，<u>信</u><u>然</u>。"],"common":"","q":[{"s":"“王戎七岁，<em class='k'>尝</em>与诸小儿游”中“<em class='k'>尝</em>”的意思是？","o":["品尝","曾经","尝试","常常"],"a":"B","e":"“尝”意为“曾经”。王戎七岁的时候，曾经和一群小孩一起玩。","tag":"字词释义"},{"s":"“尝<em class='k'>与</em>诸小儿游”中“<em class='k'>与</em>”的意思是？","o":["给予","和","参与","与其"],"a":"B","e":"“与”是介词，意为“和、跟”。","tag":"字词释义"},{"s":"“尝与<em class='k'>诸</em>小儿游”中“<em class='k'>诸</em>”的意思是？","o":["各个（众位）","全部","几位","各位（尊称）"],"a":"A","e":"“诸”意为“众、各”。“诸小儿”即“各位小孩、一群小孩”。“诸位”是现代敬称，与本义不同。","tag":"字词释义"},{"s":"“看道边李树多<em class='k'>子</em>折枝”中“<em class='k'>子</em>”的意思是？","o":["儿子","果实","种子","子女"],"a":"B","e":"“子”在此处指“果实”，即李子。李树上结满了果子。","tag":"字词释义"},{"s":"“诸儿<em class='k'>竞</em>走取之”中“<em class='k'>竞</em>”的意思是？","o":["竞争","争相","竞赛","究竟"],"a":"B","e":"“竞”意为“争相”。其他小孩都争相跑过去摘李子。","tag":"字词释义"},{"s":"“诸儿竞<em class='k'>走</em>取之”中“<em class='k'>走</em>”的意思是？","o":["走路","跑","散步","逃走"],"a":"B","e":"“走”在古文中意为“跑”，是古今异义词。小孩们跑着去摘李子。","tag":"字词释义"},{"s":"“诸儿竞走取<em class='k'>之</em>”中“<em class='k'>之</em>”指的是什么？","o":["王戎","李子","树枝","小孩"],"a":"B","e":"“之”是代词，指代“李子”。小孩们争相跑过去摘李子。","tag":"字词释义"},{"s":"“<em class='k'>唯</em>戎不动”中“<em class='k'>唯</em>”的意思是？","o":["唯一","只有","但是","思维"],"a":"B","e":"“唯”意为“只有”。只有王戎站在原地不动。","tag":"字词释义"},{"s":"“答<em class='k'>曰</em>”中“<em class='k'>曰</em>”的意思是？","o":["说","日","是","因为"],"a":"A","e":"“曰”意为“说”。王戎回答说。","tag":"字词释义"},{"s":"“<em class='k'>此</em>必苦李”中“<em class='k'>此</em>”的意思是？","o":["此时","这","因此","彼此"],"a":"B","e":"“此”意为“这”。这一定是苦李子。","tag":"字词释义"},{"s":"“此<em class='k'>必</em>苦李”中“<em class='k'>必</em>”的意思是？","o":["必须","一定","必要","毕竟"],"a":"B","e":"“必”意为“一定”。这一定是苦李子。","tag":"字词释义"},{"s":"“取之，<em class='k'>信然</em>”中“<em class='k'>信然</em>”的意思是？","o":["相信别人","确实这样","信以为真","自然相信"],"a":"B","e":"“信然”意为“确实这样”。“信”是“确实”，“然”是“这样”。摘下李子一尝，果然像王戎说的那样是苦的。王戎小小年纪就能通过观察推理得出结论，表现了善于观察思考的品质。","tag":"内容理解"}],"jd":[{"o":"王戎七岁，尝与诸小儿游。","t":"王戎七岁的时候，曾经和一群小孩子一起游玩。","notes":[["尝","曾经"],["与","和"],["诸","众、各"]]},{"o":"看道边李树多子折枝，","t":"看见路边李树上结满果实，压弯了树枝，","notes":[["子","果实"]]},{"o":"诸儿竞走取之，唯戎不动。","t":"其他小孩都争相跑去摘李子，只有王戎没有动。","notes":[["竞","争相"],["走","跑"],["之","李子"],["唯","只有"]]},{"o":"人问之，答曰：u201c树在道边而多子，此必苦李。u201d","t":"有人问他，王戎回答说：u201c李树长在路边却结满果实，这一定是苦李子。u201d","notes":[["曰","说"],["此","这"],["必","一定"]]},{"o":"取之，信然。","t":"摘取李子，确实这样。","notes":[["信然","确实这样"]]}]},{"no":15,"t":"精卫填海","src":"部编版四年级上册·《山海经·北山经》","tag":"四年级上册","html":true,"p":["炎帝<u>之</u><u>少女</u>，名<u>曰</u>女娃。女娃<u>游</u><u>于</u>东海，<u>溺</u><u>而</u>不<u>返</u>，<u>故</u><u>为</u>精卫，常<u>衔</u>西山<u>之</u>木石，<u>以</u><u>堙(yīn)</u>于东海。<br>"],"common":"本文选自《山海经·北山经》。精卫是神话中的鸟，形状像乌鸦，头上有花纹，白嘴红脚，传说是炎帝小女儿溺水后的化身。","q":[{"s":"“炎帝<em class='k'>之</em>少女”中“<em class='k'>之</em>”的意思是？","o":["的","到","去","这"],"a":"A","e":"“之”是结构助词，意为“的”。炎帝的小女儿。","tag":"字词释义"},{"s":"“炎帝之<em class='k'>少女</em>”中“少女”在文中的意思是？","o":["年轻女子","小女儿","少女","小女孩"],"a":"B","e":"“少女”在此处是古今异义词，意为“小女儿”，不是现代汉语中的“少女”。","tag":"字词释义"},{"s":"“名<em class='k'>曰</em>女娃”中“<em class='k'>曰</em>”的意思是？","o":["说","叫","是","认为"],"a":"B","e":"“曰”意为“叫、称为”。名字叫女娃。","tag":"字词释义"},{"s":"“女娃<em class='k'>游</em>于东海”中“<em class='k'>游</em>”的意思是？","o":["游泳","游玩","旅游","游戏"],"a":"B","e":"“游”意为“游玩”。女娃去东海游玩。","tag":"字词释义"},{"s":"“女娃游<em class='k'>于</em>东海”中“<em class='k'>于</em>”的意思是？","o":["对于","到","在","于是"],"a":"C","e":"“于”是介词，意为“在”。女娃在东海游玩。","tag":"字词释义"},{"s":"“<em class='k'>溺</em>而不返”中“<em class='k'>溺</em>”的意思是？","o":["溺爱","溺水","沉溺","沉迷"],"a":"B","e":"“溺”意为“溺水、淹没”。女娃溺水而死。","tag":"字词释义"},{"s":"“溺<em class='k'>而</em>不返”中“而”表示什么关系？","o":["转折（却）","顺承（然后）","并列（并且）","因果（因而）"],"a":"B","e":"“而”表顺承，意为“然后”。溺水了然后没能返回（死去）。","tag":"字词释义"},{"s":"“<em class='k'>故</em>为精卫”中“<em class='k'>故</em>”的意思是？","o":["故事","旧的","因此","故乡"],"a":"C","e":"“故”意为“因此、所以”。因此化成了精卫鸟。","tag":"字词释义"},{"s":"“故<em class='k'>为</em>精卫”中“<em class='k'>为</em>”的意思是？","o":["为了","因为","成为","被"],"a":"C","e":"“为”意为“成为”。因此成为精卫鸟。","tag":"字词释义"},{"s":"“常<em class='k'>衔</em>西山之木石”中“<em class='k'>衔</em>”的意思是？","o":["包含","叼","衔接","头衔"],"a":"B","e":"“衔”意为“叼”。精卫鸟经常用嘴叼着西山的树枝和石块。","tag":"字词释义"},{"s":"“<em class='k'>以</em>堙于东海”中“<em class='k'>以</em>”的意思是？","o":["因为","用来","认为","可以"],"a":"B","e":"“以”意为“用来”，表示目的。用来填塞东海。","tag":"字词释义"},{"s":"“以<em class='k'>堙(yīn)</em>于东海”中“<em class='k'>堙(yīn)</em>”的意思是？","o":["淹没","填塞","烟囱","阻拦"],"a":"B","e":"“堙(yīn)”意为“填塞”。精卫鸟叼来木石是为了填平东海。","tag":"字词释义"}],"jd":[{"o":"炎帝之少女，名曰女娃。","t":"炎帝的小女儿，名叫女娃。","notes":[["之","的"],["少女","小女儿"],["曰","叫"]]},{"o":"女娃游于东海，溺而不返，","t":"女娃在东海游玩，溺水身亡没能回来，","notes":[["游","游玩"],["于","在"],["溺","溺水"],["而","却"],["返","返回"]]},{"o":"故为精卫，常衔西山之木石，","t":"因此化为精卫鸟，常常叼着西山的树枝和石块，","notes":[["故","因此"],["为","成为"],["衔","叼"]]},{"o":"以堙于东海。","t":"用来填塞东海。","notes":[["以","用来"],["堙(yīn)","填塞"]]}]},{"no":16,"t":"铁杵成针","src":"部编版四年级下册·《方舆胜览·眉州》","tag":"四年级下册","html":true,"p":["磨针溪，在象耳山下。世传李太白读书山中，未成，弃去。过<u>是</u>溪，逢老媪<u>方</u>磨铁杵。问之，曰：“欲作针。”太白<u>感其意</u>，<u>还卒业</u>。<br>"],"common":"本文选自宋代祝穆的《方舆胜览·眉州》。铁杵，用来舂米或捣衣的铁棒。","q":[{"s":"“过<em class='k'>是</em>溪”中“<em class='k'>是</em>”的意思是？","o":["这","正确","判断","因为"],"a":"A","e":"“是”意为“这”。路过这条小溪。","tag":"字词释义"},{"s":"“逢老媪<em class='k'>方</em>磨铁杵”中“<em class='k'>方</em>”的意思是？","o":["方向","正在","方法","方才"],"a":"B","e":"“方”意为“正在”。遇见一位老妇人正在磨铁棒。","tag":"字词释义"},{"s":"“逢<em class='k'>老媪</em>方磨铁杵”中“<em class='k'>老媪</em>”指的是？","o":["老爷爷","老妇人","老婆婆的丈夫","年轻姑娘"],"a":"B","e":"“老媪”指老妇人。“媪”是古代对老年妇女的称呼。","tag":"字词释义"},{"s":"“逢老媪方磨<em class='k'>铁杵</em>”中“<em class='k'>铁杵</em>”是什么？","o":["铁针","用来舂米或捣衣的铁棒","铁锅","铁锤"],"a":"B","e":"“铁杵”是用来舂米或捣衣的铁棒。“杵”读chǔ，是捣物的棒槌。","tag":"字词释义"},{"s":"“未成，<em class='k'>弃去</em>”中“<em class='k'>去</em>”的意思是？","o":["去掉","离开","过去","前往"],"a":"B","e":"“去”意为“离开”。放弃学习离开了。","tag":"字词释义"},{"s":"“太白<em class='k'>感其意</em>”中“<em class='k'>感其意</em>”的意思是？","o":["感到她的意思","被她的意志感动","感谢她的心意","感受她的想法"],"a":"B","e":"“感其意”意为“被她的意志感动”。李白被老妇人的意志所感动。","tag":"字词释义"},{"s":"“还<em class='k'>卒</em>业”中“<em class='k'>卒</em>”的意思是？","o":["士兵","完成","突然","终归"],"a":"B","e":"“卒”意为“完成”。“卒业”即完成学业。","tag":"字词释义"},{"s":"“<em class='k'>还</em>卒业”中“<em class='k'>还</em>”的意思是？","o":["还是","回去","还给","还有"],"a":"B","e":"“还”读huán，意为“回去”。回去完成了学业。","tag":"字词释义"},{"s":"李白听了老妇人的话后怎么做？","o":["继续放弃学习","回去完成了学业","去别处游玩","帮老妇人磨针"],"a":"B","e":"李白被老妇人的意志感动，“还卒业”——回去完成了学业。","tag":"内容理解"},{"s":"这则故事告诉我们什么道理？","o":["做事要半途而废","只要有恒心毅力，再难的事也能成功","铁杵可以磨成针","李白小时候不爱学习"],"a":"B","e":"“铁杵成针”比喻只要有恒心、肯下功夫，再难的事也能做成。这也是成语“只要功夫深，铁杵磨成针”的来历。","tag":"内容理解"}],"jd":[{"o":"磨针溪，在象耳山下。","t":"磨针溪，坐落在象耳山下。","notes":[]},{"o":"世传李太白读书山中，未成，弃去。","t":"世间传说李白在山中读书的时候，没有完成自己的学业，就放弃学习离开了。","notes":[]},{"o":"过是溪，逢老媪方磨铁杵。","t":"他路过这条小溪，遇见一位老妇人正在磨铁棒。","notes":[["是","这"],["方","正在"]]},{"o":"问之，曰：u201c欲作针。u201d","t":"李白问她在做什么，老妇人回答说：u201c我想把它磨成针。u201d","notes":[]},{"o":"太白感其意，还卒业。","t":"李白被她的意志感动，就回去完成了学业。","notes":[["感其意","被她的意志感动"],["还卒业","回去完成了学业"]]}]},{"no":17,"t":"古人谈读书之论语","src":"部编版五年级上册·《论语》","tag":"五年级上册","html":true,"p":["①知之为知之，不知为不知，是<u>知</u>也。｜②<u>敏</u>而<u>好</u>学，不<u>耻</u><u>下问</u>。｜③默而<u>识</u>之，学而不<u>厌</u>，<u>诲</u>人不倦。｜④我非生而知之者，好古，<u>敏</u>以求之者也。｜⑤学如不<u>及</u>，<u>犹</u>恐失之。｜⑥吾<u>尝</u><u>终日</u>不食，终夜不寝，以思，无<u>益</u>，不如学也。<br>"],"common":"本文选自《论语》，是孔子及其弟子关于读书学习态度的语录。","q":[{"s":"“是<em class='k'>知</em>也”中“<em class='k'>知</em>”的读音和意思是？","o":["zhī，知道","zhì，同“智”，智慧","zhī，知识","zhì，知觉"],"a":"B","e":"“知”是通假字，同“智”，读zhì，意为“智慧”。知道就是知道，不知道就是不知道，这就是智慧。","tag":"字词释义"},{"s":"“<em class='k'>敏</em>而好学”中“<em class='k'>敏</em>”的意思是？","o":["聪敏","敏捷","敏感","勤奋"],"a":"A","e":"“敏”此处指聪敏。聪明而又喜好学习。","tag":"字词释义"},{"s":"“敏而<em class='k'>好</em>学”中“<em class='k'>好</em>”的意思是？","o":["良好","爱好，喜好","好处","友好"],"a":"B","e":"“好”读hào，意为“喜好、爱好”。聪明而又喜好学习。","tag":"字词释义"},{"s":"“不<em class='k'>耻</em>下问”中“<em class='k'>耻</em>”的意思是？","o":["羞耻","耻辱","以……为耻","可耻"],"a":"C","e":"“耻”是意动用法，意为“以……为耻”。不以向别人请教为耻。","tag":"字词释义"},{"s":"“不耻<em class='k'>下问</em>”中“<em class='k'>下问</em>”的意思是？","o":["向下问","向地位、学问不如自己的人请教","低声地问","谦虚地问"],"a":"B","e":"“下问”指向地位、学问不如自己的人请教。","tag":"字词释义"},{"s":"“默而<em class='k'>识</em>之”中“<em class='k'>识</em>”的读音和意思是？","o":["shí，认识","shí，知识","zhì，记住","zhì，识别"],"a":"C","e":"“识”读zhì，意为“记住”。默默地记住所学的知识。","tag":"字词释义"},{"s":"“学而不<em class='k'>厌</em>”中“<em class='k'>厌</em>”的意思是？","o":["讨厌","厌烦","满足","厌倦"],"a":"C","e":"“厌”意为“满足”。学习不知道满足。","tag":"字词释义"},{"s":"“<em class='k'>诲</em>人不倦”中“<em class='k'>诲</em>”的意思是？","o":["悔恨","教诲","学习","商量"],"a":"B","e":"“诲”意为“教诲”。教导别人不知疲倦。","tag":"字词释义"},{"s":"“<em class='k'>敏</em>以求之者也”中“<em class='k'>敏</em>”的意思是？","o":["聪敏","勤勉","敏捷","敏感"],"a":"B","e":"“敏”此处指勤勉。勤奋敏捷地去求得知识。","tag":"字词释义"},{"s":"“学如不<em class='k'>及</em>”中“<em class='k'>及</em>”的意思是？","o":["以及","到达","赶得上","及时"],"a":"C","e":"“及”意为“赶得上”。学习就像追赶什么似的，唯恐赶不上。","tag":"字词释义"},{"s":"“<em class='k'>犹</em>恐失之”中“<em class='k'>犹</em>”的意思是？","o":["还，尚且","犹如","犹豫","尤其"],"a":"A","e":"“犹”意为“还，尚且”。学到了，还唯恐丢失了。","tag":"字词释义"},{"s":"“吾<em class='k'>尝</em>终日不食”中“<em class='k'>尝</em>”的意思是？","o":["品尝","曾经","尝试","偿还"],"a":"B","e":"“尝”意为“曾经”。我曾经整天不吃饭。","tag":"字词释义"},{"s":"“吾尝<em class='k'>终日</em>不食”中“<em class='k'>终日</em>”的意思是？","o":["整天","太阳","终于","一天"],"a":"A","e":"“终日”意为“整天”。我曾经整天不吃饭。","tag":"字词释义"},{"s":"“以思，无<em class='k'>益</em>”中“<em class='k'>益</em>”的意思是？","o":["益处，好处","增加","有益","溢出"],"a":"A","e":"“益”意为“益处、好处”。用来思考没有益处，不如去学习。","tag":"字词释义"},{"s":"“知之为知之，不知为不知，是知也”告诉我们什么道理？","o":["做人要谦虚","要诚实，知道就是知道，不知道就是不知道","要多向别人请教","做人要聪明"],"a":"B","e":"这则语录告诉我们：对待知识要诚实，不不懂装懂，这才是真正的智慧。","tag":"内容理解"},{"s":"“学如不及，犹恐失之”表达了怎样的学习态度？","o":["学习要慢慢来","学习要争分夺秒，唯恐落后","学习不重要","学习要劳逸结合"],"a":"B","e":"这句话形容学习时唯恐赶不上、唯恐丢失的紧迫感，表达了勤勉努力、分秒必争的学习态度。","tag":"内容理解"}],"jd":[{"o":"①知之为知之，不知为不知，是知也。","t":"知道就是知道，不知道就是不知道，这就是智慧。","notes":[["知","同“智”，智慧"]]},{"o":"②敏而好学，不耻下问。","t":"聪敏而又喜好学习，不以向地位、学问不如自己的人请教为耻。","notes":[["敏","聪敏"],["好","喜好"],["耻","以……为耻"],["下问","向地位、学问不如自己的人请教"]]},{"o":"③默而识之，学而不厌，诲人不倦。","t":"默默地记住所学的知识，学习不知道满足，教诲别人不知疲倦。","notes":[["识","记住"],["厌","满足"],["诲","教诲"]]},{"o":"④我非生而知之者，好古，敏以求之者也。","t":"我不是生来就懂得知识的人，而是喜好古代文化，勤奋敏捷地去求得知识的人。","notes":[["敏","勤勉"]]},{"o":"⑤学如不及，犹恐失之。","t":"学习就像追赶什么似的，唯恐赶不上；学到了，还唯恐丢失了。","notes":[["及","赶得上"],["犹","还，尚且"]]},{"o":"⑥吾尝终日不食，终夜不寝，以思，无益，不如学也。","t":"我曾经整天不吃饭，整夜不睡觉，用来思考，但没有益处，不如去学习。","notes":[["尝","曾经"],["终日","整天"],["益","益处"]]}]},{"no":18,"t":"古人谈读书之读书有三到","src":"部编版五年级上册·[宋]朱熹","tag":"五年级上册","html":true,"p":["余<u>尝</u><u>谓</u>读书有三到，谓心到、眼到、口到。心不在此，<u>则</u>眼不看仔细，心<u>既</u>不专一，却只<u>漫浪</u>诵读，<u>决</u>不能记，记<u>亦</u>不能久也。三到之中，心到最<u>急</u>。心既到矣，眼口<u>岂</u>不到乎？<br>"],"common":"本文选自[宋]朱熹《训学斋规》，是《古人谈读书》第二则，讲读书要做到心到、眼到、口到。","q":[{"s":"“余<em class='k'>尝</em>谓读书有三到”中“<em class='k'>尝</em>”的意思是？","o":["曾经","品尝","尝试","偿还"],"a":"A","e":"“尝”意为“曾经”。我曾经说读书有三到。","tag":"字词释义"},{"s":"“余尝<em class='k'>谓</em>读书有三到”中“<em class='k'>谓</em>”的意思是？","o":["说","叫做","认为","称谓"],"a":"A","e":"“谓”意为“说”。我曾经说读书有三到。","tag":"字词释义"},{"s":"“心不在此，<em class='k'>则</em>眼不看仔细”中“<em class='k'>则</em>”的意思是？","o":["原则","就，便","但是","那么"],"a":"B","e":"“则”意为“就，便”。心思不在这里，那么眼睛就不看仔细。","tag":"字词释义"},{"s":"“心<em class='k'>既</em>不专一”中“<em class='k'>既</em>”的意思是？","o":["既然","即使","已经","既而"],"a":"C","e":"“既”意为“已经”。心思已经不专一了。","tag":"字词释义"},{"s":"“却只<em class='k'>漫浪</em>诵读”中“<em class='k'>漫浪</em>”的意思是？","o":["浪漫","随意","漫步","散漫"],"a":"B","e":"“漫浪”意为“随意”。却只是随意地诵读。","tag":"字词释义"},{"s":"“<em class='k'>决</em>不能记”中“<em class='k'>决</em>”的意思是？","o":["决定","坚决","一定，必定","决断"],"a":"C","e":"“决”意为“一定，必定”。一定不能记住。","tag":"字词释义"},{"s":"“记<em class='k'>亦</em>不能久也”中“<em class='k'>亦</em>”的意思是？","o":["也","又如","并且","既然"],"a":"A","e":"“亦”意为“也”。记住了也不能长久。","tag":"字词释义"},{"s":"“心到最<em class='k'>急</em>”中“<em class='k'>急</em>”的意思是？","o":["着急","紧急","要紧，重要","急促"],"a":"C","e":"“急”意为“要紧，重要”。三到之中，心到最要紧。","tag":"字词释义"},{"s":"“眼口<em class='k'>岂</em>不到乎”中“<em class='k'>岂</em>”的意思是？","o":["哪里","难道，怎么","岂止","可以"],"a":"B","e":"“岂”意为“难道，怎么”，表反问。心思到了，眼睛和嘴巴难道会不到吗？","tag":"字词释义"},{"s":"朱熹认为读书三到中，哪一最为重要？","o":["眼到","口到","心到","手到"],"a":"C","e":"朱熹说“心到最急”，认为三到之中心到最要紧。","tag":"内容理解"},{"s":"这则短文告诉我们读书时应该怎样？","o":["三心二意","专心致志，用心读书","只读不记","大声朗读就够了"],"a":"B","e":"短文强调读书要心到，心思专一才能真正记住，告诉我们读书要专心致志。","tag":"内容理解"}],"jd":[{"o":"余尝谓读书有三到，谓心到、眼到、口到。","t":"我曾经说读书有三到，就是心到、眼到、口到。","notes":[["尝","曾经"],["谓","说"]]},{"o":"心不在此，则眼不看仔细，心既不专一，却只漫浪诵读，决不能记，记亦不能久也。","t":"心思不在这里，那么眼睛就不看仔细，心思已经不专一，却只是随意地诵读，一定不能记住，记住了也不能长久。","notes":[["则","就，便"],["既","已经"],["漫浪","随意"],["决","一定，必定"],["亦","也"]]},{"o":"三到之中，心到最急。","t":"三到之中，心到最要紧。","notes":[["急","要紧，重要"]]},{"o":"心既到矣，眼口岂不到乎？","t":"心思已经到了，眼睛和嘴巴难道会不到吗？","notes":[["岂","难道，怎么"]]}]},{"no":19,"t":"杨氏之子","src":"部编版五年级下册·《世说新语·言语》","tag":"五年级下册","html":true,"p":["梁国杨氏子九岁，<u>甚</u>聪惠。孔君平<u>诣</u><u>其</u>父，父不在，<u>乃</u>呼儿出。为<u>设</u>果，果有杨梅。孔<u>指</u>以<u>示</u>儿曰：“此是君家果。”儿<u>应声</u>答曰：“未闻孔雀是夫子家禽。”<br>"],"common":"本文选自《世说新语·言语》，讲九岁的杨氏之子机智应答孔君平的故事。","q":[{"s":"“<em class='k'>甚</em>聪惠”中“<em class='k'>甚</em>”的意思是？","o":["很，非常","甚至","擅长","过分"],"a":"A","e":"“甚”意为“很，非常”。这个孩子非常聪明。","tag":"字词释义"},{"s":"“孔君平<em class='k'>诣</em>其父”中“<em class='k'>诣</em>”的读音和意思是？","o":["zhǐ，拜访","yì，拜访","zhǐ，造诣","yì，造诣"],"a":"B","e":"“诣”读yì，意为“拜访”。孔君平来拜访他的父亲。","tag":"字词释义"},{"s":"“孔君平诣<em class='k'>其</em>父”中“<em class='k'>其</em>”的意思是？","o":["代词，他的","其中","其他","尤其"],"a":"A","e":"“其”是代词，指代杨氏之子，意为“他的”。来拜访他的父亲。","tag":"字词释义"},{"s":"“<em class='k'>乃</em>呼儿出”中“<em class='k'>乃</em>”的意思是？","o":["竟然","就，于是","才","你的"],"a":"B","e":"“乃”意为“就，于是”。父亲不在家，于是就把孩子叫了出来。","tag":"字词释义"},{"s":"“为<em class='k'>设</em>果”中“<em class='k'>设</em>”的意思是？","o":["设计","假设","摆放，摆设","设立"],"a":"C","e":"“设”意为“摆放，摆设”。孩子给孔君平端来了水果。","tag":"字词释义"},{"s":"“孔<em class='k'>指</em>以示儿曰”中“<em class='k'>指</em>”的意思是？","o":["手指","指出","指导","指着"],"a":"D","e":"“指”意为“指着”。孔君平指着杨梅给孩子看。","tag":"字词释义"},{"s":"“孔指以<em class='k'>示</em>儿曰”中“<em class='k'>示</em>”的意思是？","o":["给……看","表示","示意","出示"],"a":"A","e":"“示”意为“给……看”。孔君平指着杨梅给孩子看。","tag":"字词释义"},{"s":"“儿<em class='k'>应声</em>答曰”中“<em class='k'>应声</em>”的意思是？","o":["随声而动","立刻回应","回应声音","大声说"],"a":"A","e":"“应声”意为“随声而动”，指随着声音（立刻）回答。孩子随声回答“未闻孔雀是夫子家禽”。","tag":"字词释义"},{"s":"孔君平说“此是君家果”是什么意思？","o":["杨梅确实是杨家的果子","因为“杨梅”的“杨”和孩子姓杨相同，故意开玩笑","杨梅很珍贵","杨梅只能杨家吃"],"a":"B","e":"孔君平利用“杨梅”的“杨”字和孩子姓“杨”相同，开玩笑说杨梅是杨家的果子。","tag":"内容理解"},{"s":"孩子回答“未闻孔雀是夫子家禽”妙在哪里？","o":["孔雀很好看","孔君平姓“孔”，孩子用“孔雀”来反击，既礼貌又机智","孩子不喜欢孔雀","孔雀是孔家的"],"a":"B","e":"孩子模仿孔君平的方法，用“孔雀”的“孔”字反击：既然杨梅是杨家的，那孔雀就是孔家的。以其人之道还治其人之身，既不失礼又十分机智。","tag":"内容理解"},{"s":"这个故事表现了杨氏之子的什么特点？","o":["调皮捣蛋","机智聪慧，反应敏捷","骄傲自大","贪吃嘴馋"],"a":"B","e":"九岁的孩子应声作答，用“孔雀是夫子家禽”巧妙反击，表现了机智聪慧、反应敏捷的特点。","tag":"内容理解"}],"jd":[{"o":"梁国杨氏子九岁，甚聪惠。","t":"梁国姓杨人家的儿子九岁，非常聪明。","notes":[["甚","很，非常"]]},{"o":"孔君平诣其父，父不在，乃呼儿出。","t":"孔君平来拜访他的父亲，父亲不在家，于是就把这个孩子叫了出来。","notes":[["诣","拜访"],["其","代词，他的"],["乃","就，于是"]]},{"o":"为设果，果有杨梅。","t":"孩子给孔君平端来了水果，水果中有杨梅。","notes":[["设","摆放，摆设"]]},{"o":"孔指以示儿曰：u201c此是君家果。u201d","t":"孔君平指着杨梅给孩子看，对他说：u201c这是你家的水果。u201d","notes":[["指","指着"],["示","给……看"]]},{"o":"儿应声答曰：u201c未闻孔雀是夫子家禽。u201d","t":"孩子马上回答道：u201c我可没有听说孔雀是先生您家的鸟。u201d","notes":[["应声","随声而动"]]}]},{"no":20,"t":"自相矛盾","src":"部编版五年级下册·《韩非子·难一》","tag":"五年级下册","html":true,"p":["楚人有<u>鬻(yù)</u>盾与矛者，<u>誉</u>之曰：“吾盾<u>之</u>坚，物<u>莫</u>能<u>陷</u>也。”又誉其矛曰：“吾矛之利，于物无不陷也。”<u>或</u>曰：“以子之矛陷子之盾，何如？”其人<u>弗</u>能应也。<u>夫</u>不可陷之盾与无不陷之矛，不可同世而立。<br>"],"common":"本文选自《韩非子·难一》，是成语“自相矛盾”的出处。","q":[{"s":"“楚人有<em class='k'>鬻</em>盾与矛者”中“<em class='k'>鬻</em>”的意思是？","o":["买","卖","煮","经营"],"a":"B","e":"“鬻”读yù，意为“卖”。有一个楚国人，既卖盾又卖矛。","tag":"字词释义"},{"s":"“<em class='k'>誉</em>之曰”中“<em class='k'>誉</em>”的意思是？","o":["荣誉","夸耀","信誉","名声"],"a":"B","e":"“誉”意为“夸耀”。他夸耀自己的盾。","tag":"字词释义"},{"s":"“吾盾<em class='k'>之</em>坚”中“<em class='k'>之</em>”的意思是？","o":["到","助词，的","去","它"],"a":"B","e":"“之”是助词，相当于“的”。“吾盾之坚”即“我的盾的坚固”。","tag":"字词释义"},{"s":"“物<em class='k'>莫</em>能陷也”中“<em class='k'>莫</em>”的意思是？","o":["没有，表示否定","不要","莫非","或许"],"a":"A","e":"“莫”意为“没有，表示否定”。没有什么东西能够穿透它。","tag":"字词释义"},{"s":"“物莫能<em class='k'>陷</em>也”中“<em class='k'>陷</em>”的意思是？","o":["陷阱","陷入","刺破","陷害"],"a":"C","e":"“陷”意为“刺破”。没有什么东西能够刺破它。","tag":"字词释义"},{"s":"“<em class='k'>或</em>曰”中“<em class='k'>或</em>”的意思是？","o":["或者","有的人","有时","或许"],"a":"B","e":"“或”意为“有的人”。有的人说。","tag":"字词释义"},{"s":"“其人<em class='k'>弗</em>能应也”中“<em class='k'>弗</em>”的意思是？","o":["不","通假字，通“拂”","不用","弗如"],"a":"A","e":"“弗”意为“不”。那人不能回答。","tag":"字词释义"},{"s":"“<em class='k'>夫</em>不可陷之盾”中“<em class='k'>夫</em>”的意思是？","o":["丈夫","句首发语词，表示要发议论","夫子","况且"],"a":"B","e":"“夫”放在句首，是发语词，表示将要发议论，不翻译。","tag":"字词释义"},{"s":"这个卖矛和盾的人为什么回答不上来？","o":["他忘了怎么说","矛和盾都太贵","他的话前后矛盾，无法自圆其说","他不想回答"],"a":"C","e":"他说盾“物莫能陷”、矛“于物无不陷”，两者互相抵触，所以被问“以子之矛陷子之盾”时无法回答。","tag":"内容理解"},{"s":"这则寓言告诉我们什么道理？","o":["矛和盾不能一起卖","说话做事要前后一致，不能自相矛盾","要同时夸耀矛和盾","买东西时要小心"],"a":"B","e":"“自相矛盾”比喻说话做事前后抵触，告诉我们说话做事要前后一致，实事求是。","tag":"内容理解"}],"jd":[{"o":"楚人有鬻盾与矛者。","t":"有一个楚国人，既卖盾又卖矛。","notes":[["鬻","卖"]]},{"o":"誉之曰：u201c吾盾之坚，物莫能陷也。u201d","t":"他夸耀自己的盾，说：u201c我的盾坚固无比，没有什么东西能够穿透它。u201d","notes":[["誉","夸耀"],["之","助词，的"],["莫","没有什么"],["陷","刺破"]]},{"o":"又誉其矛曰：u201c吾矛之利，于物无不陷也。u201d","t":"又夸耀自己的矛，说：u201c我的矛锋利极了，任何坚固的东西都穿得透。u201d","notes":[]},{"o":"或曰：u201c以子之矛陷子之盾，何如？u201d","t":"有人问他：u201c如果用您的矛刺您的盾，结果会怎么样呢？u201d","notes":[["或","有的人"]]},{"o":"其人弗能应也。","t":"那人不能回答。","notes":[["弗","不"]]},{"o":"夫不可陷之盾与无不陷之矛，不可同世而立。","t":"什么都不能刺穿的盾与什么都能刺穿的矛，不可能同时存在于这个世界上。","notes":[["夫","句首发语词"]]}]},{"no":21,"t":"书戴嵩画牛","src":"部编版六年级上册·宋·苏轼","tag":"六年级上册","html":true,"p":["蜀中有杜处士，<u>好</u>书画，所<u>宝</u><u>以</u>百<u>数</u>。有戴嵩《牛》一轴，<u>尤</u>所爱，<u>锦囊玉轴</u>，常以自随。一日曝书画，有一牧童见之，<u>拊(fǔ)</u>掌大笑，曰：“此画斗牛也。牛斗，力在角，尾<u>搐</u>入两<u>股</u>间，今<u>乃</u><u>掉</u>尾而斗，<u>谬(miù)</u>矣。”处士笑<u>而</u><u>然</u>之。古语有云：“耕当问奴，织当问婢。”不可改也。<br>"],"common":"本文作者是宋代的苏轼。戴嵩，唐代画家。处士，本指有德才而不愿去做官的人，后来也指未做官的士人。","q":[{"s":"“<em class='k'>好</em>书画”中“<em class='k'>好</em>”的意思是？","o":["喜爱","良好","好事","友好"],"a":"A","e":"“好”读hào，意为“喜爱”。喜爱书画。","tag":"字词释义"},{"s":"“所<em class='k'>宝</em>以百数”中“<em class='k'>宝</em>”的意思是？","o":["珍宝","名词作动词，珍藏","宝贝","宝贵"],"a":"B","e":"“宝”名词作动词，活用为“珍藏”。所珍藏的（书画）用百来计算。","tag":"字词释义"},{"s":"“所宝<em class='k'>以</em>百数”中“<em class='k'>以</em>”的意思是？","o":["用，凭","因为","所以","以为"],"a":"A","e":"“以”意为“用，凭”。所珍藏的书画用百来计算。","tag":"字词释义"},{"s":"“所宝以百<em class='k'>数</em>”中“<em class='k'>数</em>”的意思是？","o":["数字","计算","数量","数次"],"a":"B","e":"“数”意为“计算”。所珍藏的书画用百来计算，即成百件。","tag":"字词释义"},{"s":"“<em class='k'>尤</em>所爱”中“<em class='k'>尤</em>”的意思是？","o":["尤其","仍然","优秀","犹豫"],"a":"A","e":"“尤”意为“尤其”。其中他尤其珍爱《牛》这幅画。","tag":"字词释义"},{"s":"“<em class='k'>锦囊玉轴</em>”中“<em class='k'>锦囊玉轴</em>”的意思是？","o":["用锦缎作画囊，用玉作画轴（名词作动词）","锦缎做的囊、玉做的轴（名词）","锦缎和玉做的盒子","用锦缎包着的玉轴"],"a":"A","e":"“锦囊玉轴”是名词作动词，意为“用锦缎作画囊，用玉作画轴”。","tag":"字词释义"},{"s":"“<em class='k'>拊</em>掌大笑”中“<em class='k'>拊</em>”的意思是？","o":["拍","抚摸","扶持","拍打，击打"],"a":"A","e":"“拊”读fǔ，意为“拍”。“拊掌”即拍手。","tag":"字词释义"},{"s":"“尾<em class='k'>搐</em>入两股间”中“<em class='k'>搐</em>”的意思是？","o":["抽缩","抽搐","抽打","压缩"],"a":"A","e":"“搐”意为“抽缩”。尾巴收缩夹在两腿之间。","tag":"字词释义"},{"s":"“尾搐入两<em class='k'>股</em>间”中“<em class='k'>股</em>”的意思是？","o":["大腿","屁股","股份","一股"],"a":"A","e":"“股”意为“大腿”。“两股”即两条大腿。","tag":"字词释义"},{"s":"“今<em class='k'>乃</em>掉尾而斗”中“<em class='k'>乃</em>”的意思是？","o":["却","于是","才","竟然"],"a":"A","e":"“乃”意为“却”，表转折。如今这幅画却画成牛摇着尾巴相斗。","tag":"字词释义"},{"s":"“今乃<em class='k'>掉</em>尾而斗”中“<em class='k'>掉</em>”的意思是？","o":["摆动，摇","掉下","丢失","旋转"],"a":"A","e":"“掉”意为“摆动，摇”。“掉尾”即摇着尾巴。","tag":"字词释义"},{"s":"“<em class='k'>谬</em>矣”中“<em class='k'>谬</em>”的意思是？","o":["错误","荒谬","差错","巧妙"],"a":"A","e":"“谬”读miù，意为“错误”。这是错误的啊！","tag":"字词释义"},{"s":"“处士笑<em class='k'>而</em>然之”中“<em class='k'>而</em>”的意思是？","o":["表修饰，笑着","表转折，却","表顺承，然后","表并列，并且"],"a":"A","e":"“而”表修饰关系，连接“笑”和“然之”，意为“笑着”。处士笑着认为他说得对。","tag":"字词释义"},{"s":"“处士笑而<em class='k'>然</em>之”中“<em class='k'>然</em>”的意思是？","o":["认为……对","然而","这样","燃烧"],"a":"A","e":"“然”是意动用法，意为“认为……对”。“然之”即认为他说得对。","tag":"字词释义"},{"s":"牧童为什么说这幅《斗牛图》画错了？","o":["牛不应该画尾巴","牛相斗时尾巴夹在两腿间，画里却是摇着尾巴","牛角画得不对","牛的颜色不对"],"a":"B","e":"牧童说牛相斗时“力在角，尾搐入两股间”，而画里却是“掉尾而斗”，与实情不符，所以说画错了。","tag":"内容理解"},{"s":"“耕当问奴，织当问婢”告诉我们什么道理？","o":["要听奴仆的话","遇到事情要向有实践经验的人请教","农夫和织女最聪明","不要相信别人"],"a":"B","e":"“奴”“婢”是常年耕田、织布的人，最有实践经验。这句话告诉我们：遇事要向有实践经验的人请教，不可凭空臆断。","tag":"内容理解"}],"jd":[{"o":"蜀中有杜处士，好书画，所宝以百数。","t":"蜀地有一位杜处士，喜爱书法、绘画，他所珍藏的书画用上百来计算。","notes":[["好","喜爱"],["宝","珍藏"],["以","用，凭"],["数","计算"]]},{"o":"有戴嵩《牛》一轴，尤所爱，锦囊玉轴，常以自随。","t":"（他）有一幅戴嵩画的《牛》，格外喜爱，用锦缎做画囊、玉石做画轴，常常随身携带。","notes":[["尤","格外"],["锦囊玉轴","用锦缎做画囊、玉石做画轴"]]},{"o":"一日曝书画，有一牧童见之，拊掌大笑，曰：u201c此画斗牛也。","t":"一天，（杜处士）晾晒书画，有一个牧童看见了这幅画，拍手大笑，说：u201c这幅画画的是牛相斗。","notes":[["拊","拍"]]},{"o":"牛斗，力在角，尾搐入两股间，今乃掉尾而斗，谬矣。u201d","t":"牛争斗的时候，力量在牛角上，尾巴抽缩在两条大腿中间；现在（画里的牛）却摇着尾巴相斗，错了。u201d","notes":[["搐","抽缩"],["股","大腿"],["乃","却"],["掉","摆动，摇"],["谬","错误"]]},{"o":"处士笑而然之。","t":"杜处士笑着，认为牧童说得对。","notes":[["而","表修饰，笑着"],["然","认为……对"]]},{"o":"古语有云：u201c耕当问奴，织当问婢。u201d不可改也。","t":"古话说：u201c耕种应当询问农夫，织布应当询问婢女。u201d（这个道理）不可以更改。","notes":[]}]},{"no":22,"t":"伯牙鼓琴","src":"部编版六年级上册·《吕氏春秋·本味》","tag":"六年级上册","html":true,"p":["伯牙<u>鼓</u>琴，锺子期听之。<u>方</u>鼓琴而<u>志</u>在太山，锺子期曰：“<u>善</u>哉乎鼓琴，巍巍乎<u>若</u>太山。”<u>少选</u>之间而志在流水，锺子期又曰：“善哉乎鼓琴，<u>汤汤</u>乎若流水。”锺子期死，伯牙破琴<u>绝</u>弦，终身不复鼓琴，<u>以为</u>世无<u>足</u>复为鼓琴者。<br>"],"common":"本文选自《吕氏春秋·本味》，讲伯牙与锺子期知音相惜的故事。“高山流水”的典故即源于此。","q":[{"s":"“伯牙<em class='k'>鼓</em>琴”中“<em class='k'>鼓</em>”的意思是？","o":["弹奏","击鼓","鼓动","鼓励"],"a":"A","e":"“鼓”意为“弹奏”。“鼓琴”即弹琴。","tag":"字词释义"},{"s":"“<em class='k'>方</em>鼓琴而志在太山”中“<em class='k'>方</em>”的意思是？","o":["正，正在","方向","方法","方才"],"a":"A","e":"“方”意为“正，正在”。正当伯牙弹琴时，心中想着泰山。","tag":"字词释义"},{"s":"“方鼓琴而<em class='k'>志</em>在太山”中“<em class='k'>志</em>”的意思是？","o":["心志，情志","志向","标志","记录"],"a":"A","e":"“志”意为“心志，情志”，指心中所想的。伯牙弹琴时心中想着泰山。","tag":"字词释义"},{"s":"“<em class='k'>善</em>哉乎鼓琴”中“<em class='k'>善</em>”的意思是？","o":["善良","好","擅长","善于"],"a":"B","e":"“善哉”意为“好啊”，“善”意为“好”。这是锺子期的赞叹。","tag":"字词释义"},{"s":"“巍巍乎<em class='k'>若</em>太山”中“<em class='k'>若</em>”的意思是？","o":["如果","像","假若","若干"],"a":"B","e":"“若”意为“像”。琴音像大山一样高峻。","tag":"字词释义"},{"s":"“<em class='k'>少选</em>之间而志在流水”中“<em class='k'>少选</em>”的意思是？","o":["一会儿，不久","少数","选择","很久"],"a":"A","e":"“少选”意为“一会儿，不久”。过了一会儿，伯牙心意转向流水。","tag":"字词释义"},{"s":"“<em class='k'>汤汤</em>乎若流水”中“<em class='k'>汤汤</em>”的读音和意思是？","o":["shāng shāng，水流大而急的样子","tāng tāng，水很多","shāng shāng，热水","tāng tāng，浩浩荡荡"],"a":"A","e":"“汤汤”读shāng shāng，形容水流大而急的样子。琴音像流水一样浩荡。","tag":"字词释义"},{"s":"“伯牙破琴<em class='k'>绝</em>弦”中“<em class='k'>绝</em>”的意思是？","o":["断绝","绝对","绝妙","尽头"],"a":"A","e":"“绝”意为“断绝”。伯牙摔破琴身、扯断琴弦。","tag":"字词释义"},{"s":"“<em class='k'>以为</em>世无足复为鼓琴者”中“<em class='k'>以为</em>”的意思是？","o":["认为","因为","所以","把…当作"],"a":"A","e":"“以为”意为“认为”。认为世上再没有值得为之弹琴的人。","tag":"字词释义"},{"s":"“以为世无<em class='k'>足</em>复为鼓琴者”中“<em class='k'>足</em>”的意思是？","o":["脚","值得","足够","满足"],"a":"B","e":"“足”意为“值得”。认为世上再没有值得为之弹琴的人了。","tag":"字词释义"},{"s":"锺子期死后，伯牙“破琴绝弦，终身不复鼓琴”是因为什么？","o":["琴坏了","失去了知音，认为世上再没有值得为之弹琴的人","不喜欢弹琴了","琴弦断了"],"a":"B","e":"锺子期是伯牙的知音，能听懂他的琴声。知音已逝，伯牙认为世上再没有值得为之弹琴的人，所以破琴绝弦。","tag":"内容理解"},{"s":"“伯牙鼓琴”这个故事表达了什么？","o":["要爱护乐器","知音难觅，朋友间深厚的情谊","弹琴要专心","伯牙琴艺高超"],"a":"B","e":"故事表达了知音难觅、朋友间深厚情谊的主题。“高山流水”也因此成为知音的代称。","tag":"内容理解"}],"jd":[{"o":"伯牙鼓琴，锺子期听之。","t":"伯牙弹琴，锺子期聆听。","notes":[["鼓","弹奏"]]},{"o":"方鼓琴而志在太山，锺子期曰：u201c善哉乎鼓琴，巍巍乎若太山。u201d","t":"当伯牙弹琴时心中想着泰山，锺子期赞叹：u201c弹得真好啊！琴音巍峨如同泰山耸立。u201d","notes":[["方","正，正在"],["志","心志，情志"],["善","好"],["若","像"]]},{"o":"少选之间而志在流水，锺子期又曰：u201c善哉乎鼓琴，汤汤乎若流水。u201d","t":"过了一会儿，伯牙心意转向流水，锺子期又说：u201c弹得真好啊！琴音浩荡如同江河奔流。u201d","notes":[["少选","一会儿，不久"],["汤汤","水流大而急的样子"]]},{"o":"锺子期死，伯牙破琴绝弦，终身不复鼓琴，","t":"锺子期死后，伯牙摔破琴身、扯断琴弦，终身不再弹琴，","notes":[["绝","断绝"]]},{"o":"以为世无足复为鼓琴者。","t":"认为世上再没有值得为之弹琴的人了。","notes":[["以为","认为"],["足","值得"]]}]},{"no":23,"t":"两小儿辩日","src":"部编版六年级下册·《列子·汤问》","tag":"六年级下册","html":true,"p":["孔子<u>东</u>游，见两小儿<u>辩斗</u>，问其<u>故</u>。一儿曰：“我<u>以</u>日始出时<u>去</u>人近，而日中时远也。”一儿曰：“我以日初出远，而日中时近也。”一儿曰：“日初出大如车盖，<u>及</u>日中则如盘盂，此不为远者小而近者大乎？”一儿曰：“日初出沧沧凉凉，及其日中如探<u>汤</u>，此不为近者热而远者凉乎？”孔子不能<u>决</u>也。两小儿笑曰：“<u>孰(shú)</u><u>为</u><u>汝</u>多<u>知</u>乎？”<br>\n  <strong>注释</strong> 〔日中〕正午。　〔车盖〕古时车上的圆形篷盖，像雨伞一样。　〔盘盂〕盛物的器皿，圆的为盘，方的为盂。　〔沧沧凉凉〕寒凉。<br>"],"common":"本文选自《列子·汤问》，题目为后人所加。","q":[{"s":"“孔子<em class='k'>东</em>游”中“<em class='k'>东</em>”的意思是？","o":["向东（名词作状语）","东方","东家（主人）","东边"],"a":"A","e":"“东”名词作状语，意为“向东、往东”。孔子向东游历。","tag":"字词释义"},{"s":"“见两小儿<em class='k'>辩斗</em>”中“<em class='k'>辩斗</em>”的意思是？","o":["辩论，争论","打斗","辩解","比赛"],"a":"A","e":"“辩斗”意为“辩论、争论”。见到两个小孩在争辩。","tag":"字词释义"},{"s":"“问其<em class='k'>故</em>”中“<em class='k'>故</em>”的意思是？","o":["原因","故事","所以","旧"],"a":"A","e":"“故”意为“原因”。问他们争辩的原因。","tag":"字词释义"},{"s":"“我<em class='k'>以</em>日始出时去人近”中“<em class='k'>以</em>”的意思是？","o":["认为","用来","因为","可以"],"a":"A","e":"“以”意为“认为”。我认为太阳刚升起时距离人近。","tag":"字词释义"},{"s":"“日始出时<em class='k'>去</em>人近”中“<em class='k'>去</em>”的意思是？","o":["距离","离开","去除","过去"],"a":"A","e":"“去”意为“距离”。太阳刚升起时距离人近。","tag":"字词释义"},{"s":"“<em class='k'>及</em>日中则如盘盂”中“<em class='k'>及</em>”的意思是？","o":["到，到了","以及","及时","来得及"],"a":"A","e":"“及”意为“到、到了”。等到正午就像盘子一样小。","tag":"字词释义"},{"s":"“如探<em class='k'>汤</em>”中“<em class='k'>汤</em>”的意思是？","o":["热水","菜汤","茶水","汤药"],"a":"A","e":"“汤”是古今异义词，意为“热水”。像把手伸进热水里一样热。","tag":"字词释义"},{"s":"“孔子不能<em class='k'>决</em>也”中“<em class='k'>决</em>”的意思是？","o":["判断，决断","决定","决战","决心"],"a":"A","e":"“决”意为“判断、决断”。孔子不能判断谁对谁错。","tag":"字词释义"},{"s":"“<em class='k'>孰(shú)</em>为汝多知乎”中“<em class='k'>孰(shú)</em>”的意思是？","o":["谁","什么","为什么","怎么"],"a":"A","e":"“孰”读shú，意为“谁”。谁说你智慧多呢？","tag":"字词释义"},{"s":"“孰<em class='k'>为</em>汝多知乎”中“<em class='k'>为</em>”的读音和意思是？","o":["wèi，同“谓”，说","wéi，为了","wèi，因为","wéi，成为"],"a":"A","e":"“为”读wèi，同“谓”，意为“说”。谁说你知道得多呢？","tag":"字词释义"},{"s":"“孰为<em class='k'>汝</em>多知乎”中“<em class='k'>汝</em>”的意思是？","o":["你","我","他","大家"],"a":"A","e":"“汝”意为“你”。谁说你智慧多呢？","tag":"字词释义"},{"s":"“孰为汝多<em class='k'>知</em>乎”中“<em class='k'>知</em>”的读音和意思是？","o":["zhì，同“智”，智慧","zhī，知道","zhī，知识","zhì，知觉"],"a":"A","e":"“知”读zhì，同“智”，意为“智慧”。谁说你智慧多呢？","tag":"字词释义"}],"jd":[{"o":"孔子东游，见两小儿辩斗，问其故。","t":"孔子向东游历，见到两个小孩在争辩，便问他们争辩的原因。","notes":[["东","向东，名词作状语"],["辩斗","辩论，争论"],["故","原因"]]},{"o":"一儿曰：“我以日始出时去人近，而日中时远也。”","t":"一个小孩说：“我认为太阳刚升起的时候距离人近，而到中午的时候距离人远。”","notes":[["以","认为"],["去","距离"],["日中","正午"]]},{"o":"一儿曰：“我以日初出远，而日中时近也。”","t":"另一个小孩说：“我认为太阳刚升起的时候距离人远，而到中午的时候距离人近。”","notes":[["日中","正午"]]},{"o":"一儿曰：“日初出大如车盖，及日中则如盘盂，此不为远者小而近者大乎？”","t":"一个小孩说：“太阳刚出来的时候像车盖一样大，等到正午就小得像一个盘子，这不是远处的看着小而近处的看着大吗？”","notes":[["及","到，到了"],["盘盂","盛物的器皿"]]},{"o":"一儿曰：“日初出沧沧凉凉，及其日中如探汤，此不为近者热而远者凉乎？”","t":"另一个小孩说：“太阳刚出来的时候有清凉的感觉，等到中午的时候像把手伸进热水里一样热，这不是近的时候感觉热而远的时候感觉凉吗？”","notes":[["沧沧凉凉","寒凉"],["汤","热水"]]},{"o":"孔子不能决也。","t":"孔子不能判决（谁对谁错）。","notes":[["决","判断，决断"]]},{"o":"两小儿笑曰：“孰为汝多知乎？”","t":"两个小孩笑着说：“谁说你智慧多呢？”","notes":[["孰(shú)","谁"],["为","同“谓”，说"],["汝","你"],["知","同“智”，智慧"]]}]},{"no":24,"t":"学弈","src":"部编版六年级下册·《孟子·告子上》","tag":"六年级下册","html":true,"p":["弈秋，<u>通国</u>之<u>善</u>弈者也。<u>使</u>弈秋<u>诲</u>二人<u>弈</u>，其一人专心致志，<u>惟</u>弈秋之为听；一人虽听之，一心<u>以为</u>有鸿鹄将至，思<u>援</u>弓缴(zhuó)而射之。虽与之<u>俱</u>学，<u>弗若</u>矣。<u>为</u>是其智<u>弗</u>若<u>与(yú)</u>？曰：非<u>然</u>也。<br>\n  <strong>注释</strong> 〔鸿鹄〕指天鹅、大雁一类的鸟。<br>"],"common":"本文选自《孟子·告子上》，题目为后人所加。弈秋，“秋”是人名，因善于下棋，所以称为弈秋。","q":[{"s":"“<em class='k'>通国</em>之善弈者也”中“<em class='k'>通国</em>”的意思是？","o":["全国","各国","通行全国","全国统一"],"a":"A","e":"“通国”意为“全国”。弈秋是全国最擅长下棋的人。","tag":"字词释义"},{"s":"“通国之<em class='k'>善</em>弈者也”中“<em class='k'>善</em>”的意思是？","o":["善良","善于，擅长","好事","喜爱"],"a":"B","e":"“善”意为“善于、擅长”。善于下棋的人。","tag":"字词释义"},{"s":"“<em class='k'>使</em>弈秋诲二人弈”中“<em class='k'>使</em>”的意思是？","o":["使者","让，叫","使用","如果"],"a":"B","e":"“使”意为“让、叫”。让弈秋教导两个人下棋。","tag":"字词释义"},{"s":"“使弈秋<em class='k'>诲</em>二人弈”中“<em class='k'>诲</em>”的意思是？","o":["后悔","教导","劝告","训斥"],"a":"B","e":"“诲”意为“教导”。教导两个人下棋。","tag":"字词释义"},{"s":"“使弈秋诲二人<em class='k'>弈</em>”中“<em class='k'>弈</em>”的意思是？","o":["下棋","游戏","比赛","弹琴"],"a":"A","e":"“弈”意为“下棋”。教导两个人下棋。","tag":"字词释义"},{"s":"“<em class='k'>惟</em>弈秋之为听”中“<em class='k'>惟</em>”的意思是？","o":["只","虽然","但是","因为"],"a":"A","e":"“惟”意为“只”。“惟弈秋之为听”即“只听弈秋的教导”。","tag":"字词释义"},{"s":"“一心<em class='k'>以为</em>有鸿鹄将至”中“<em class='k'>以为</em>”的意思是？","o":["认为","作为","因为","可以"],"a":"A","e":"“以为”意为“认为”。心里一直认为（想着）有天鹅要飞来。","tag":"字词释义"},{"s":"“思<em class='k'>援</em>弓缴而射之”中“<em class='k'>援</em>”的意思是？","o":["引，拉","援助","放弃","举起"],"a":"A","e":"“援”意为“引、拉”。想拉弓搭箭去射它。","tag":"字词释义"},{"s":"“思援弓<em class='k'>缴(zhuó)</em>而射之”中“缴(zhuó)”的意思是？","o":["系在箭上的丝绳，指带丝绳的箭","缴纳","缴获","弓箭"],"a":"A","e":"“缴(zhuó)”指系在箭上的丝绳，这里指带有丝绳的箭，射出后可以收回。","tag":"字词释义"},{"s":"“虽与之<em class='k'>俱</em>学”中“<em class='k'>俱</em>”的意思是？","o":["一起，一同","害怕","聚集","各自"],"a":"A","e":"“俱”意为“一起、一同”。虽然他和前一个人一起学习。","tag":"字词释义"},{"s":"“弗<em class='k'>若</em>之矣”中“<em class='k'>若</em>”的意思是？","o":["比得上","好像","仿佛","如果"],"a":"A","e":"“若”意为“比得上”。“弗若”即“比不上”（不如）。","tag":"字词释义"},{"s":"“<em class='k'>为</em>是其智弗若与”中“<em class='k'>为</em>”的意思是？","o":["因为","为了","成为","作为"],"a":"A","e":"“为”意为“因为”。这是因为他的智力不如前一个人吗？","tag":"字词释义"},{"s":"“是其智<em class='k'>弗</em>若与”中“<em class='k'>弗</em>”的意思是？","o":["不","非常","难道","没有"],"a":"A","e":"“弗”意为“不”。智力不如（前一个人）。","tag":"字词释义"},{"s":"“弗若<em class='k'>与(yú)</em>”中“<em class='k'>与(yú)</em>”的意思是？","o":["同“欤”，句末语气词，表疑问","和，跟","给","参与"],"a":"A","e":"“与”同“欤”，读yú，是句末语气词，表示疑问。是智力不如吗？","tag":"字词释义"},{"s":"“曰：非<em class='k'>然</em>也”中“<em class='k'>然</em>”的意思是？","o":["这样","然而","然后","燃烧"],"a":"A","e":"“然”意为“这样”。回答说：不是这样的。","tag":"字词释义"}],"jd":[{"o":"弈秋，通国之善弈者也。","t":"弈秋，（是）通国（中）善于下棋的人。","notes":[["通国","全国"],["善","善于，擅长"],["弈","下棋"]]},{"o":"使弈秋诲二人弈，其一人专心致志，惟弈秋之为听；","t":"让弈秋教导两个人下棋，其中一个人专心致志，（只）听弈秋的教导；","notes":[["使","让，叫"],["诲","教导"],["惟","只"]]},{"o":"一人虽听之，一心以为有鸿鹄将至，思援弓缴而射之。","t":"另一个人虽然也在听（弈秋讲课），（心里）一心认为有天鹅将要飞来，想拉弓取箭去射它。","notes":[["以为","认为"],["鸿鹄","天鹅、大雁一类的鸟"],["援","引，拉"],["缴(zhuó)","带丝绳的箭"]]},{"o":"虽与之俱学，弗若之矣。","t":"虽然（他）和前一个人一起学习，（棋艺却）比不上（那个人）。","notes":[["俱","一起，一同"],["若","比得上"]]},{"o":"为是其智弗若与？曰：非然也。","t":"（这）是因为他的智力比不上（前一个人）吗？（有人）回答说：不是这样的。","notes":[["为","因为"],["弗","不"],["与(yú)","同“欤”，语气词"],["然","这样"]]}]},{"no":25,"t":"咏雪","src":"部编版七年级上册·《世说新语》二则","tag":"七年级上册","html":true,"p":["谢太傅寒雪日<u>内集</u>，与<u>儿女</u>讲论文义。<u>俄而</u>雪<u>骤</u>，公<u>欣然</u>曰：“白雪纷纷<u>何所似</u>？”兄子胡儿曰：“撒盐空中<u>差可拟</u>。”兄女曰：“<u>未若</u>柳絮<u>因</u>风起。”公大笑乐。<u>即</u>公大兄无奕女，左将军王凝之妻也。<br>"],"common":"本文选自《世说新语·言语》，编者刘义庆（南朝宋）。谢太傅即谢安，东晋名相。","q":[{"s":"“寒雪日<em class='k'>内集</em>”中“<em class='k'>内集</em>”的意思是？","o":["内部集会","把家人聚集在一起","在室内集中","内部收集"],"a":"B","e":"“内集”意为“把家人聚集在一起”，“内”指家人。","tag":"字词释义"},{"s":"“与<em class='k'>儿女</em>讲论文义”中“<em class='k'>儿女</em>”的意思是？","o":["儿子和女儿","子侄辈（泛指家中晚辈）","儿子","女儿"],"a":"B","e":"课下注释：“儿女”指“子侄辈”，即家中晚辈。","tag":"字词释义"},{"s":"“<em class='k'>俄而</em>雪骤”中“<em class='k'>俄而</em>”的意思是？","o":["突然","不久，一会儿","渐渐地","慢慢地"],"a":"B","e":"“俄而”表示时间短暂，意为“不久，一会儿”。","tag":"字词释义"},{"s":"“俄而雪<em class='k'>骤</em>”中“<em class='k'>骤</em>”的意思是？","o":["快速","急，紧（雪下得大而急）","突然","奔跑"],"a":"B","e":"“骤”此处意为“急”，指雪下得又大又急。","tag":"字词释义"},{"s":"“公<em class='k'>欣然</em>曰”中“<em class='k'>欣然</em>”的意思是？","o":["高兴的样子","生气地","平静地","严肃地"],"a":"A","e":"“欣然”意为“高兴的样子”。“然”是词尾，表示“……的样子”。","tag":"字词释义"},{"s":"“白雪纷纷<em class='k'>何所似</em>”中“<em class='k'>何所似</em>”的意思是？","o":["像什么","为什么相似","多么相似","怎样相似"],"a":"A","e":"“何所似”即“像什么”，“何”为疑问代词“什么”。","tag":"字词释义"},{"s":"“撒盐空中<em class='k'>差可拟</em>”中“<em class='k'>差可拟</em>”的意思是？","o":["大体上可以比拟","差别很大","差一点就能比","差别可以忽略"],"a":"A","e":"课下注释：“差可拟”意为“大体上可以比拟”。","tag":"字词释义"},{"s":"“<em class='k'>未若</em>柳絮因风起”中“<em class='k'>未若</em>”的意思是？","o":["比不上","不像","没有像","未能"],"a":"A","e":"“未若”意为“比不上”（未=不，若=比得上）。谢道韫说：比不上比作柳絮乘风飞起。","tag":"字词释义"},{"s":"“未若柳絮<em class='k'>因</em>风起”中“<em class='k'>因</em>”的意思是？","o":["因为","乘，趁","原因","顺着"],"a":"B","e":"“因”在此处意为“乘、趁”，即“柳絮趁着风势飞起”。","tag":"字词释义"},{"s":"“<em class='k'>即</em>公大兄无奕女”中“<em class='k'>即</em>”的意思是？","o":["立即","就是","既然","即使"],"a":"B","e":"“即”意为“就是”。","tag":"字词释义"},{"s":"谢太傅对两个比喻的反应是——","o":["未明确表态","「大笑乐」，非常高兴","比较后认为柳絮更好","两个都否定了"],"a":"B","e":"文中写道“公大笑乐”，含蓄地表现了他对谢道韫的回答更为欣赏。","tag":"内容理解"},{"s":"文章最后一句交代谢道韫的<em class='k'>身份</em>，作者的用意是？","o":["补充说明家庭关系","暗示对谢道韫才气的赞赏","介绍王凝之的背景","交待故事结局"],"a":"B","e":"末句含蓄表达了作者对谢道韫咏絮之才的赞赏。","tag":"内容理解"},{"s":"谢太傅对于两个比喻，只是“大笑乐”而未明确评判优劣，这样写的好处是？","o":["说明谢太傅也不知道哪个更好","含蓄地让读者自行品味高下，使文章余味无穷","说明谢太傅两种比喻都不满意","为了增加故事的悬念"],"a":"B","e":"谢安“大笑乐”而未直接评判，让读者在对比中自己体会谢道韫的妙处，含蓄隽永。","tag":"内容理解"},{"s":"“撒盐空中”作比喻，主要抓住了雪的什么特点？","o":["轻盈飘逸","颜色洁白和颗粒感","冰冷刺骨","纷纷扬扬"],"a":"B","e":"“撒盐空中”抓住了雪的颜色洁白和如盐粒般的质感。","tag":"句子理解"},{"s":"“柳絮因风起”作比喻，主要抓住了雪的什么特点？","o":["颜色洁白","轻盈飘逸、随风飞扬","寒冷","晶莹剔透"],"a":"B","e":"“柳絮因风起”写出了雪花轻盈飘逸的姿态，意境更胜一筹。","tag":"句子理解"},{"s":"以下对两个比喻的赏析，不正确的是？","o":["“撒盐空中”更贴近雪的色泽和下落形态","“柳絮因风起”比“撒盐空中”更有诗意和韵味","“柳絮因风起”是春天的事物，用来比喻雪不合适","两个比喻各有特色，但历来更推崇谢道韫的比喻"],"a":"C","e":"“柳絮因风起”以春景喻冬景，正因其巧妙而备受推崇。","tag":"句子理解"},{"s":"后人常用“<em class='k'>咏絮之才</em>”来赞美什么？","o":["擅长写诗的人","有文才的女子","擅长画画的人","善于辩论的人"],"a":"B","e":"“咏絮之才”典出谢道韫咏雪之事，后世用来赞誉有文学才华的女子。","tag":"综合"}],"jd":[{"o":"谢太傅寒雪日内集，与儿女讲论文义。","t":"谢安在寒冷的雪天把家人聚集在一起，和子侄辈讲解谈论文章义理。","notes":[["内集","把家人聚集在一起"],["儿女","子侄辈"]]},{"o":"俄而雪骤，公欣然曰：u201c白雪纷纷何所似？u201d","t":"不久雪下得紧了，谢太傅高兴地说：u201c白雪纷纷扬扬像什么？u201d","notes":[["俄而","不久"],["骤","急"],["欣然","高兴的样子"],["何所似","像什么"]]},{"o":"兄子胡儿曰：u201c撒盐空中差可拟。u201d","t":"他哥哥的儿子胡儿说：u201c在空中撒盐大体可以比拟。u201d","notes":[["差可拟","大体上可以比拟"]]},{"o":"兄女曰：u201c未若柳絮因风起。u201d","t":"他哥哥的女儿说：u201c不如比作柳絮乘风飞起。u201d","notes":[["未若","比不上"],["因","乘，趁"]]},{"o":"公大笑乐。","t":"谢太傅大笑，非常高兴。","notes":[]},{"o":"即公大兄无奕女，左将军王凝之妻也。","t":"（她）就是谢安的大哥谢无奕的女儿，左将军王凝之的妻子。","notes":[["即","就是"]]}]},{"no":26,"t":"杞人忧天","src":"部编版七年级上册·《列子》","tag":"七年级上册","html":true,"p":["杞国有人忧天地崩坠，<u>身</u>亡所寄，废寝食者。又有<u>忧</u>彼之所忧者，<u>因</u>往<u>晓</u>之，曰：“天，积气耳，<u>亡</u>处亡气。<u>若</u>屈伸呼吸，终日在天中行止，<u>奈何</u>忧崩坠乎？”其人曰：“天<u>果</u>积气，日月星宿，不<u>当</u>坠耶？”晓之者曰：“日月星宿，亦积气中之有光耀者，<u>只使</u>坠，亦不能有所<u>中伤</u>。”其人曰：“奈地坏何？”晓之者曰：“地，积块耳，充塞四虚，亡处亡块。若躇步跐蹈，终日在地上行止，奈何忧其坏？”其人<u>舍然</u>大喜，晓之者亦舍然大喜。<br>\n  <strong>注释</strong> 〔积气〕聚积的气体。　〔积块〕聚积的土块。　〔四虚〕四方。　〔躇(chú)步跐(cǐ)蹈〕都是踩、踏的意思。<br>"],"common":"本文节选自《列子·天瑞》（《列子集释》，中华书局2007年版），题目为编者所加。杞，周代诸侯国。《列子》旧题为列御寇著，据后人考证可能是晋代人的作品，今本八篇，内容多为民间故事、寓言和神话传说。列御寇，相传是战国时的道家人物，郑国人。","q":[{"s":"“<em class='k'>身</em>亡所寄”中“<em class='k'>身</em>”的意思是？","o":["自己","身体","身份","一生"],"a":"A","e":"“身”意为“自己”。（觉得）自己无处安身。","tag":"字词释义"},{"s":"“又有<em class='k'>忧</em>彼之所忧者”中“<em class='k'>忧</em>”的意思是？","o":["担忧","忧愁","忧伤","忧患"],"a":"A","e":"“忧”意为“担忧”。又有为那（杞人）所担忧的事而担忧的人。","tag":"字词释义"},{"s":"“<em class='k'>因</em>往晓之”中“<em class='k'>因</em>”的意思是？","o":["于是","因为","原因","因此"],"a":"A","e":"“因”意为“于是、就”。于是前去开导他。","tag":"字词释义"},{"s":"“因往<em class='k'>晓</em>之”中“<em class='k'>晓</em>”的意思是？","o":["开导","知道","拂晓","天亮"],"a":"A","e":"“晓”意为“告知、开导”（使……明白）。于是前去开导他。","tag":"字词释义"},{"s":"“<em class='k'>亡</em>处亡气”中“<em class='k'>亡</em>”的读音和意思是？","o":["wú，同“无”，没有","wáng，死亡","wáng，逃亡","wú，忘记"],"a":"A","e":"“亡”读wú，同“无”，意为“没有”。没有一处没有气。","tag":"字词释义"},{"s":"“<em class='k'>若</em>屈伸呼吸”中“<em class='k'>若</em>”的意思是？","o":["你","像","比得上","如果"],"a":"A","e":"“若”意为“你”（代词）。你屈伸四肢、呼吸。","tag":"字词释义"},{"s":"“<em class='k'>奈何</em>忧崩坠乎”中“<em class='k'>奈何</em>”的意思是？","o":["为什么","怎么办","无可奈何","竟然"],"a":"A","e":"“奈何”意为“为什么、怎么”。为什么担忧天会崩塌坠落呢？","tag":"字词释义"},{"s":"“天<em class='k'>果</em>积气”中“<em class='k'>果</em>”的意思是？","o":["果真","果实","结果","如果"],"a":"A","e":"“果”意为“果真、确实”。天果真是聚积的气体。","tag":"字词释义"},{"s":"“不<em class='k'>当</em>坠耶”中“<em class='k'>当</em>”的意思是？","o":["应当","会","担当","当时"],"a":"A","e":"“当”意为“应当”。天果真是聚积的气体，不应当掉下来吗？","tag":"字词释义"},{"s":"“<em class='k'>只使</em>坠”中“<em class='k'>只使</em>”的意思是？","o":["纵使","只让","只要","假如"],"a":"A","e":"“只使”意为“纵使、即使”。纵使坠落。","tag":"字词释义"},{"s":"“亦不能有所<em class='k'>中伤</em>”中“<em class='k'>中伤</em>”的意思是？","o":["伤害","诬陷","妨碍","破坏"],"a":"A","e":"“中伤”是古今异义词，这里意为“伤害”（被击中而受伤），不是现代汉语的“诬陷”。","tag":"字词释义"},{"s":"“其人<em class='k'>舍然</em>大喜”中“<em class='k'>舍然</em>”的意思是？","o":["消除疑虑的样子","舍弃的样子","忽然明白","安然无恙"],"a":"A","e":"“舍”同“释”，“舍然”即释然，意为“消除疑虑的样子”。那（杞）人消除疑虑，非常高兴。","tag":"字词释义"}],"jd":[{"o":"杞国有人忧天地崩坠，身亡所寄，废寝食者。","t":"杞国有个担忧天会崩塌、地会陷落的人，（觉得）自己无处安身，（以至于）睡不着觉、吃不下饭。","notes":[["身","自己"]]},{"o":"又有忧彼之所忧者，因往晓之，曰：“天，积气耳，亡处亡气。若屈伸呼吸，终日在天中行止，奈何忧崩坠乎？”","t":"又有（一个）为那（杞人）所担忧的事而担忧的人，于是前去开导他，说：“天，是聚积的气体罢了，没有（一处）没有气。你屈伸四肢、呼吸，整天在天中活动、休息，为什么担忧天会崩塌坠落呢？”","notes":[["忧","担忧"],["因","于是"],["晓","开导"],["亡","同“无”，没有"],["若","你"],["奈何","为什么"]]},{"o":"其人曰：“天果积气，日月星宿，不当坠耶？”","t":"那（杞）人说：“天果真是聚积的气体，那么日月星辰，不应当掉下来吗？”","notes":[["果","果真"],["当","应当"]]},{"o":"晓之者曰：“日月星宿，亦积气中之有光耀者，只使坠，亦不能有所中伤。”","t":"开导（他）的人说：“日月星辰，也是聚积的气体中那些有光亮的东西，纵使坠落，也不能对人有所伤害。”","notes":[["只使","纵使"],["中伤","伤害"]]},{"o":"其人曰：“奈地坏何？”","t":"那（杞）人说：“地陷落了（把地坏了）怎么办？”","notes":[["奈……何","把……怎么办"]]},{"o":"晓之者曰：“地，积块耳，充塞四虚，亡处亡块。若躇步跐蹈，终日在地上行止，奈何忧其坏？”","t":"开导（他）的人说：“地，是聚积的土块罢了，充满四方，没有（一处）没有土块。你踩踏行走，整天在地上活动、休息，为什么担忧它会陷落呢？”","notes":[["四虚","四方"],["躇步跐蹈","踩，踏"]]},{"o":"其人舍然大喜，晓之者亦舍然大喜。","t":"那（杞）人消除疑虑，非常高兴；开导（他）的人也消除疑虑，非常高兴。","notes":[["舍然","释然，消除疑虑的样子"]]}]},{"no":27,"t":"狼","src":"部编版七年级上册·《聊斋志异》","tag":"七年级上册","html":true,"p":["一屠晚归，担中肉尽，<u>止</u>有剩骨。途中两狼，<u>缀行</u>甚远。屠惧，<u>投以骨</u>。一狼得骨止，一狼仍从。复投之，后狼止而前狼又至。骨已尽矣，而两狼<u>之</u>并驱<u>如故</u>。屠大<u>窘</u>，恐前后受其<u>敌</u>。<u>顾</u>野有麦场，场主积<u>薪</u>其中，苫(shàn)蔽成丘。屠<u>乃</u>奔倚其下，<u>弛</u>担持刀。狼不敢<u>前</u>，眈眈相向。<u>少时</u>，一狼<u>径</u>去，其一<u>犬</u>坐于前。久之，目似<u>瞑</u>，意<u>暇</u>甚。屠<u>暴</u>起，以刀劈狼首，又数刀毙之。<u>方</u>欲行，转视积薪后，一狼<u>洞</u>其中，意将<u>隧</u>入以攻其后也。身已半入，止露尻(kāo)尾。屠自后断其<u>股</u>，亦毙之。<u>乃</u>悟前狼假寐，<u>盖</u>以诱敌。狼亦黠矣，而顷刻两毙，禽兽之变诈<u>几何</u>哉？止增笑<u>耳</u>。<br>\n  <strong>注释</strong> 〔苫(shàn)〕盖上。　〔尻(kāo)〕屁股。　〔眈眈〕凶狠注视的样子。<br>"],"common":"本文选自《聊斋志异》卷六（上海古籍出版社1986年版）。蒲松龄（1640—1715），字留仙，世称聊斋先生，淄川（今属山东淄博）人，清代文学家。著有文言小说集《聊斋志异》等。","q":[{"s":"“<em class='k'>止</em>有剩骨”中“<em class='k'>止</em>”的意思是？","o":["只，仅","停止","阻止","制止"],"a":"A","e":"“止”意为“只、仅”。担子里只剩下骨头。","tag":"字词释义"},{"s":"“<em class='k'>缀行</em>甚远”中“<em class='k'>缀行</em>”的意思是？","o":["紧跟着走","结伴行走","慢慢行走","绕道行走"],"a":"A","e":"“缀行”意为“紧跟着走”。“缀”是连接、紧跟的意思。","tag":"字词释义"},{"s":"“<em class='k'>投以骨</em>”是什么特殊句式？","o":["状语后置（以骨投之）","宾语前置","省略句","判断句"],"a":"A","e":"“投以骨”是状语后置句，正常语序为“以骨投之”，即把骨头投给（狼）。","tag":"字词释义"},{"s":"“而两狼<em class='k'>之</em>并驱如故”中“<em class='k'>之</em>”的作用是？","o":["取消句子独立性","结构助词，的","代词，它","动词，去"],"a":"A","e":"“之”用在主谓之间，取消句子独立性，无实义。","tag":"字词释义"},{"s":"“并驱<em class='k'>如故</em>”中“<em class='k'>如故</em>”的意思是？","o":["像原来一样","如同故人","按照旧例","装作没事"],"a":"A","e":"“如故”意为“像原来一样”。两只狼像原来一样一起追赶。","tag":"字词释义"},{"s":"“屠大<em class='k'>窘</em>”中“<em class='k'>窘</em>”的意思是？","o":["困迫","贫穷","害怕","着急"],"a":"A","e":"“窘”意为“处境困迫、为难”。屠户十分困迫。","tag":"字词释义"},{"s":"“恐前后受其<em class='k'>敌</em>”中“<em class='k'>敌</em>”的意思是？","o":["攻击","敌人","敌对","抵抗"],"a":"A","e":"“敌”名词作动词，意为“攻击”。担心前后受到狼的攻击。","tag":"字词释义"},{"s":"“<em class='k'>顾</em>野有麦场”中“<em class='k'>顾</em>”的意思是？","o":["看","照顾","回顾","探望"],"a":"A","e":"“顾”意为“看”。（屠户）看见田野里有麦场。","tag":"字词释义"},{"s":"“场主积<em class='k'>薪</em>其中”中“<em class='k'>薪</em>”的意思是？","o":["柴草","薪水","植被","木料"],"a":"A","e":"“薪”意为“柴草”。场主在麦场中堆了柴草。","tag":"字词释义"},{"s":"“屠<em class='k'>乃</em>奔倚其下”中“<em class='k'>乃</em>”的意思是？","o":["于是","才","竟然","你的"],"a":"A","e":"“乃”意为“于是、就”。屠户于是跑过去倚在柴堆下。","tag":"字词释义"},{"s":"“<em class='k'>弛</em>担持刀”中“<em class='k'>弛</em>”的意思是？","o":["放下","松弛","放松","奔驰"],"a":"A","e":"“弛”意为“解除、卸下”，这里指放下担子。放下担子拿起刀。","tag":"字词释义"},{"s":"“狼不敢<em class='k'>前</em>”中“<em class='k'>前</em>”的意思是？","o":["上前","前方","先前","前进"],"a":"A","e":"“前”名词作动词，意为“上前”。狼不敢上前。","tag":"字词释义"},{"s":"“<em class='k'>少时</em>”中“<em class='k'>少</em>”的读音是？","o":["shāo","sháo","shǎo","shào"],"a":"C","e":"“少时”的“少”读shǎo，意为“一会儿、时间短暂”。","tag":"字词释义"},{"s":"“一狼<em class='k'>径</em>去”中“<em class='k'>径</em>”的意思是？","o":["径直","直径","小路","路径"],"a":"A","e":"“径”意为“径直”。一只狼径直离开。","tag":"字词释义"},{"s":"“其一<em class='k'>犬</em>坐于前”中“<em class='k'>犬</em>”的意思是？","o":["像狗一样","狗","犬子","猎犬"],"a":"A","e":"“犬”名词作状语，意为“像狗一样”。另一只像狗一样坐在前面。","tag":"字词释义"},{"s":"“目似<em class='k'>瞑</em>”中“<em class='k'>瞑</em>”的意思是？","o":["闭上眼睛","昏暗","睡觉","困倦"],"a":"A","e":"“瞑”意为“闭上眼睛”。眼睛好像闭着。","tag":"字词释义"},{"s":"“意<em class='k'>暇</em>甚”中“<em class='k'>暇</em>”的意思是？","o":["从容","空闲","假日","休息"],"a":"A","e":"“暇”意为“悠闲、从容”。神情悠闲极了。","tag":"字词释义"},{"s":"“屠<em class='k'>暴</em>起”中“<em class='k'>暴</em>”的意思是？","o":["突然","暴躁","暴力","暴露"],"a":"A","e":"“暴”意为“突然”。屠户突然跳起。","tag":"字词释义"},{"s":"“<em class='k'>方</em>欲行”中“<em class='k'>方</em>”的意思是？","o":["正要","方向","方法","方才"],"a":"A","e":"“方”意为“正、正要”。正要走。","tag":"字词释义"},{"s":"“一狼<em class='k'>洞</em>其中”中“<em class='k'>洞</em>”的意思是？","o":["打洞","洞穴","洞口","洞察"],"a":"A","e":"“洞”名词作动词，意为“打洞”。一只狼正在其中打洞。","tag":"字词释义"},{"s":"“意将<em class='k'>隧</em>入”中“<em class='k'>隧</em>”的意思是？","o":["从隧道进入","隧道","地道","挖洞"],"a":"A","e":"“隧”名词作状语，意为“从隧道（通道）进入”。想钻洞从背后攻击。","tag":"字词释义"},{"s":"“屠自后断其<em class='k'>股</em>”中“<em class='k'>股</em>”的意思是？","o":["大腿","屁股","股票","股份"],"a":"A","e":"“股”是古今异义词，这里意为“大腿”。屠户从后面砍断它的大腿。","tag":"字词释义"},{"s":"“<em class='k'>乃</em>悟前狼假寐”中“<em class='k'>乃</em>”的意思是？","o":["才","于是","竟然","你的"],"a":"A","e":"“乃”意为“才”。（屠户）才明白前狼假装睡觉。","tag":"字词释义"},{"s":"“<em class='k'>盖</em>以诱敌”中“<em class='k'>盖</em>”的意思是？","o":["原来是","大概是","应该是","居然是"],"a":"A","e":"“盖”意为“原来是”，表示推断、说明原因。原来是用来诱惑敌人。","tag":"字词释义"},{"s":"“禽兽之变诈<em class='k'>几何</em>哉”中“<em class='k'>几何</em>”的意思是？","o":["多少","几何学","多久","几个"],"a":"A","e":"“几何”意为“多少”。禽兽的诡诈能有多少呢？","tag":"字词释义"},{"s":"“止增笑<em class='k'>耳</em>”中“<em class='k'>耳</em>”的意思是？","o":["罢了","耳朵","耳目","听闻"],"a":"A","e":"“耳”是语气词，意为“罢了”。只是增加笑料罢了。","tag":"字词释义"}],"jd":[{"o":"一屠晚归，担中肉尽，止有剩骨。途中两狼，缀行甚远。","t":"一个屠户傍晚回家，担子里的肉已经卖完，只剩下骨头。路上遇到两只狼，紧跟着（他）走了很远。","notes":[["止","只，仅"],["缀行","紧跟着走"]]},{"o":"屠惧，投以骨。一狼得骨止，一狼仍从。复投之，后狼止而前狼又至。骨已尽矣，而两狼之并驱如故。","t":"屠户害怕，（就）把骨头投给狼。一只狼得到骨头停下，另一只狼仍跟着。再投骨头，后狼停下而前狼又追上。骨头已投完，而两只狼像原来一样一起追赶。","notes":[["投以骨","状语后置，以骨投之"],["之","取消句子独立性"],["如故","像原来一样"]]},{"o":"屠大窘，恐前后受其敌。顾野有麦场，场主积薪其中，苫蔽成丘。屠乃奔倚其下，弛担持刀。狼不敢前，眈眈相向。","t":"屠户十分困迫，担心前后受到狼的攻击。看见田野里有麦场，场主在其中堆了柴草，覆盖成小山。屠户于是跑过去倚在柴堆下，放下担子拿起刀。狼不敢上前，瞪着眼朝着（他）。","notes":[["窘","困迫，为难"],["敌","攻击"],["顾","看"],["薪","柴草"],["乃","于是"],["弛","放下"],["前","上前"]]},{"o":"少时，一狼径去，其一犬坐于前。久之，目似瞑，意暇甚。屠暴起，以刀劈狼首，又数刀毙之。方欲行，转视积薪后，一狼洞其中，意将隧入以攻其后也。身已半入，止露尻尾。屠自后断其股，亦毙之。乃悟前狼假寐，盖以诱敌。","t":"一会儿，一只狼径直离开，另一只像狗一样坐在前面。很久，（它的）眼睛好像闭着，神情悠闲极了。屠户突然跳起，用刀劈狼头，又连砍几刀杀死了它。正要走，转身看见柴堆后面，一只狼正在其中打洞，想要钻洞从背后攻击（他）。（狼）身体已经钻入一半，只露出屁股和尾巴。屠户从后面砍断它的大腿，也杀死了它。（屠户）才明白前狼假装睡觉，原来是用（这种方式）来诱惑敌人。","notes":[["少时","一会儿"],["径","径直"],["犬","像狗一样"],["瞑","闭上眼睛"],["暇","从容"],["暴","突然"],["方","正要"],["洞","打洞"],["隧","从隧道进入"],["股","大腿"],["乃","才"],["盖","原来是"]]},{"o":"狼亦黠矣，而顷刻两毙，禽兽之变诈几何哉？止增笑耳。","t":"狼也狡猾啊，但片刻之间两只狼都被杀死，禽兽的诡诈能有多少呢？只是增加笑料罢了。","notes":[["几何","多少"],["耳","罢了"]]}]},{"no":28,"t":"穿井得一人","src":"部编版七年级上册·《吕氏春秋》","tag":"七年级上册","html":true,"p":["宋之丁氏，家无井<u>而</u>出溉汲，常一人居外。<u>及</u>其家穿井，告人曰：“吾穿井得一人。”有闻<u>而</u>传之者：“丁氏穿井得一人。”<u>国人</u>道之，<u>闻之于宋君</u>。宋君令人问之于丁氏，丁氏对曰：“得一人之<u>使</u>，非得一人于井中也。”求闻之<u>若</u>此，不<u>若</u>无闻也。<br>"],"common":"本文节选自《吕氏春秋·慎行论·察传》（中华书局2012年版），题目为编者所加。“穿”是挖掘、开凿的意思。《吕氏春秋》又称《吕览》，是先秦杂家代表著作，由战国末秦相吕不韦（？—前235）集合门客共同编写而成，全书共一百六十篇。","q":[{"s":"“家无井<em class='k'>而</em>出溉汲”中“<em class='k'>而</em>”表示什么关系？","o":["顺承（然后）","转折（却）","并列（并且）","修饰（地）"],"a":"A","e":"“而”表顺承，意为“然后”。家里没有井，要到外面打水浇田。","tag":"字词释义"},{"s":"“<em class='k'>及</em>其家穿井”中“<em class='k'>及</em>”的意思是？","o":["等到","以及","到达","来得及"],"a":"A","e":"“及”意为“等到”。等到他家里打了井。","tag":"字词释义"},{"s":"“有闻<em class='k'>而</em>传之者”中“<em class='k'>而</em>”表示什么关系？","o":["顺承（然后）","转折（却）","并列（并且）","修饰（地）"],"a":"A","e":"“而”表顺承，意为“然后”。有听到（传闻）然后传播（它）的人。","tag":"字词释义"},{"s":"“<em class='k'>国人</em>道之”中“<em class='k'>国人</em>”的意思是？","o":["国都的居民","宋国人","全国人民","国家的人"],"a":"A","e":"“国人”意为“国都的居民”。国都的居民都谈论这件事。","tag":"字词释义"},{"s":"“<em class='k'>闻之于宋君</em>”是什么特殊句式？","o":["状语后置","宾语前置","判断句","省略句"],"a":"A","e":"“闻之于宋君”是状语后置句，正常语序为“于宋君闻之”，即把这件事报告给宋国国君。","tag":"字词释义"},{"s":"“得一人之<em class='k'>使</em>”中“<em class='k'>使</em>”的意思是？","o":["使唤","使者","让","即使"],"a":"A","e":"“使”意为“使唤、使用（劳动力）”。得到一个人使唤（的劳动力）。","tag":"字词释义"},{"s":"“求闻之<em class='k'>若</em>此”中“<em class='k'>若</em>”的意思是？","o":["像","如果","假如","比得上"],"a":"A","e":"“若”意为“像”。寻求传闻像这样（处理）。","tag":"字词释义"},{"s":"“不<em class='k'>若</em>无闻也”中“<em class='k'>若</em>”的意思是？","o":["比得上","像","如果","假如"],"a":"A","e":"“若”意为“比得上”。“不若”即不如。不如没有听到（传闻）啊。","tag":"字词释义"},{"s":"这则寓言告诉我们的道理是？","o":["对待传闻要仔细辨别，不能轻信、以讹传讹","打井可以节省人力","宋国人都喜欢传闲话","丁家人口多才打井"],"a":"A","e":"“穿井得一人”的传闻以讹传讹，告诉我们：对待传闻要仔细辨别，不能轻信、更不能以讹传讹。","tag":"内容理解"},{"s":"下列句子中不是倒装句的是？","o":["吾穿井得一人","闻之于宋君","宋君令人问之于丁氏","非得一人于井中也"],"a":"A","e":"“闻之于宋君”（于宋君闻之）、“宋君令人问之于丁氏”（于丁氏问之）、“非得一人于井中也”（于井中得一人）都是状语后置；“吾穿井得一人”是正常语序。","tag":"内容理解"}],"jd":[{"o":"宋之丁氏，家无井而出溉汲，常一人居外。","t":"宋国有个姓丁的人家，家里没有井，要（到外面）打水浇田，常常有一个人住在外面。","notes":[["而","顺承"],["溉汲","打水浇田"]]},{"o":"及其家穿井，告人曰：“吾穿井得一人。”","t":"等到他家里打了井，（他）告诉别人说：“我打井得到一个人。”","notes":[["及","等到"]]},{"o":"有闻而传之者：“丁氏穿井得一人。”","t":"有听到（这话）然后传播（它）的人说：“丁家打井得到一个人。”","notes":[["而","顺承"]]},{"o":"国人道之，闻之于宋君。","t":"国都的居民谈论这件事，（有人）把（这件事）报告给宋国国君。","notes":[["国人","国都的居民"],["闻之于宋君","状语后置"]]},{"o":"宋君令人问之于丁氏，丁氏对曰：“得一人之使，非得一人于井中也。”","t":"宋国国君派人向丁家询问这件事，丁家的人回答说：“（我家打井）得到一个人使唤（的劳动力），不是从井中得到一个人。”","notes":[["使","使唤，使用"],["非得一人于井中也","状语后置"]]},{"o":"求闻之若此，不若无闻也。","t":"寻求传闻像这样（处理），不如没有听到（传闻）啊。","notes":[["若","像"],["若","比得上"]]}]},{"no":29,"t":"论语》十二章","src":"部编版七年级上册·《论语》","tag":"七年级上册","html":true,"p":["①子曰：“学而<u>时</u><u>习</u>之，不亦<u>说</u>乎？有朋自远方来，不亦乐乎？人不知而不<u>愠</u>，不亦君子乎？”｜②曾子曰：“吾<u>日</u><u>三</u>省吾<u>身</u>：为人谋而不<u>忠</u>乎？与朋友交而不信乎？<u>传</u>不习乎？”｜③子曰：“吾十<u>有</u>五而<u>志</u>于学，三十而<u>立</u>，四十而不惑，五十而知天命，六十而耳顺，七十而从心所欲，不<u>逾</u>矩。”｜④子曰：“温故<u>而</u>知新，可以为师矣。”｜⑤子曰：“学而不思则<u>罔</u>，思<u>而</u>不学则<u>殆</u>。”｜⑥子曰：“贤哉，回也！一箪食，一瓢饮，在陋巷，人不<u>堪</u>其忧，回也不改其乐。贤哉，回也！”｜⑦子曰：“知之者不如好之者，好之者不如<u>乐</u>之者。”｜⑧子曰：“<u>饭</u><u>疏食</u>，饮水，曲肱而枕之，乐亦在其中矣。不义而富且贵，<u>于</u>我如浮云。”｜⑨子曰：“<u>三</u>人行，必有我师<u>焉</u>。择其善者而从之，其不善者而改之。”｜⑩子在川上曰：“逝者如斯<u>夫</u>，不舍昼夜。”｜⑪子曰：“三军可<u>夺</u>帅也，<u>匹夫</u>不可夺志也。”｜⑫子夏曰：“博学而<u>笃志</u>，<u>切</u>问而近思，仁在其中矣。”<br>\n  <strong>注释</strong> 〔子〕古代对男子的尊称，这里指孔子。　〔天命〕上天的意旨。　〔耳顺〕指能听得进不同的意见。　〔箪〕古代盛饭用的圆形竹器。　〔肱〕胳膊。　〔川上〕河边。<br>"],"common":"本文选自《论语》，共十二章，题目为后人所加。《论语》是儒家经典，记录孔子及其弟子言行。孔子（前551—前479），名丘，字仲尼，春秋末期鲁国人，儒家学派创始人。曾子名参(shēn)，字子舆；颜回字子渊；子夏即卜商——都是孔子的弟子。","q":[{"s":"“学而<em class='k'>时</em>习之”中“<em class='k'>时</em>”的意思是？","o":["按时","时间","时常","时候"],"a":"A","e":"“时”名词作状语，意为“按时”。学习了（知识）然后按时温习。","tag":"字词释义"},{"s":"“学而时<em class='k'>习</em>之”中“<em class='k'>习</em>”的意思是？","o":["温习","学习","习惯","练习"],"a":"A","e":"“习”意为“温习、复习”。按时温习所学的知识。","tag":"字词释义"},{"s":"“不亦<em class='k'>说</em>乎”中“<em class='k'>说</em>”的读音和意思是？","o":["yuè，愉快","shuō，说话","shuì，劝说","yuè，说教"],"a":"A","e":"“说”读yuè，同“悦”，意为“愉快”。不也是令人愉快的吗？","tag":"字词释义"},{"s":"“人不知而不<em class='k'>愠</em>”中“<em class='k'>愠</em>”的意思是？","o":["恼怒","温暖","蕴含","怨恨"],"a":"A","e":"“愠”意为“恼怒”。别人不理解自己也不恼怒。","tag":"字词释义"},{"s":"“吾<em class='k'>日</em>三省吾身”中“<em class='k'>日</em>”的意思是？","o":["每天","太阳","日子","一日"],"a":"A","e":"“日”名词作状语，意为“每天”。我每天多次反省自己。","tag":"字词释义"},{"s":"“吾日<em class='k'>三</em>省吾身”中“<em class='k'>三</em>”的意思是？","o":["多次","三次","三件","第三"],"a":"A","e":"“三”在古汉语中常表“多次”，是虚指，不是确数。","tag":"字词释义"},{"s":"“吾日三省吾<em class='k'>身</em>”中“<em class='k'>身</em>”的意思是？","o":["自己","身体","身份","一生"],"a":"A","e":"“身”意为“自己”。我每天多次反省自己。","tag":"字词释义"},{"s":"“为人谋而不<em class='k'>忠</em>乎”中“<em class='k'>忠</em>”的意思是？","o":["尽心竭力","忠心","忠厚","忠告"],"a":"A","e":"“忠”意为“尽心竭力”。为别人谋划事情是否尽心竭力了？","tag":"字词释义"},{"s":"“<em class='k'>传</em>不习乎”中“<em class='k'>传</em>”的意思是？","o":["老师传授的知识","传授","传记","传达"],"a":"A","e":"“传”动词作名词，指“老师传授的知识”。老师传授的知识温习了吗？","tag":"字词释义"},{"s":"“吾十<em class='k'>有</em>五而志于学”中“<em class='k'>有</em>”的读音和意思是？","o":["yòu，同“又”","yǒu，有无","yòu，右边","yǒu，拥有"],"a":"A","e":"“有”读yòu，同“又”，用于整数和零数之间。“十有五”即十五岁。","tag":"字词释义"},{"s":"“吾十有五而<em class='k'>志</em>于学”中“<em class='k'>志</em>”的意思是？","o":["立志","志向","标志","志愿"],"a":"A","e":"“志”意为“立志”。我十五岁立志于学问。","tag":"字词释义"},{"s":"“三十而<em class='k'>立</em>”中“<em class='k'>立</em>”的意思是？","o":["立身","站立","建立","立刻"],"a":"A","e":"“立”意为“立身”，指能有所成就。三十岁能在社会上立足。","tag":"字词释义"},{"s":"“不<em class='k'>逾</em>矩”中“<em class='k'>逾</em>”的意思是？","o":["越过","逾期","更加","剩余"],"a":"A","e":"“逾”意为“越过”。却不越过规矩。","tag":"字词释义"},{"s":"“温故<em class='k'>而</em>知新”中“<em class='k'>而</em>”表示什么关系？","o":["顺承（然后）","转折（却）","并列（并且）","修饰（地）"],"a":"A","e":"“而”表顺承，意为“然后”。温习旧知识然后获得新理解。","tag":"字词释义"},{"s":"“学而不思则<em class='k'>罔</em>”中“<em class='k'>罔</em>”的意思是？","o":["迷惑","欺骗","枉费","冤枉"],"a":"A","e":"“罔”意为“迷惑”，感到迷茫而无所得。只学习却不思考就会迷惑。","tag":"字词释义"},{"s":"“思<em class='k'>而</em>不学则殆”中“<em class='k'>而</em>”表示什么关系？","o":["转折（却）","顺承（然后）","并列（并且）","修饰（地）"],"a":"A","e":"“而”表转折，意为“却”。只思考却不学习就会疑惑。","tag":"字词释义"},{"s":"“思而不学则<em class='k'>殆</em>”中“<em class='k'>殆</em>”的意思是？","o":["疑惑","危险","几乎","大概"],"a":"A","e":"“殆”意为“疑惑”。只思考却不学习就会疑惑而无所适从。","tag":"字词释义"},{"s":"“人不<em class='k'>堪</em>其忧”中“<em class='k'>堪</em>”的意思是？","o":["能忍受","难以","可以","胜任"],"a":"A","e":"“堪”意为“能忍受”。别人都无法忍受这种贫苦的忧愁。","tag":"字词释义"},{"s":"“好之者不如<em class='k'>乐</em>之者”中“<em class='k'>乐</em>”的意思是？","o":["以……为乐","快乐","音乐","乐趣"],"a":"A","e":"“乐”意动用法，意为“以……为乐”。喜爱道理的人不如以践行道理为乐的人。","tag":"字词释义"},{"s":"“<em class='k'>饭</em>疏食”中“<em class='k'>饭</em>”的意思是？","o":["吃","米饭","粮食","厨师"],"a":"A","e":"“饭”名词作动词，意为“吃”。吃粗劣的食物。","tag":"字词释义"},{"s":"“饭<em class='k'>疏食</em>”中“<em class='k'>疏食</em>”的意思是？","o":["粗粮","菜和饭","稀疏食物","剩饭"],"a":"A","e":"“疏食”意为“粗粮、粗劣的食物”。","tag":"字词释义"},{"s":"“<em class='k'>于</em>我如浮云”中“<em class='k'>于</em>”的意思是？","o":["对于","在","到","被"],"a":"A","e":"“于”意为“对于”。对我而言就像浮云一样。","tag":"字词释义"},{"s":"“<em class='k'>三</em>人行”中“<em class='k'>三</em>”的意思是？","o":["几个","三个","三次","第三"],"a":"A","e":"“三”在古汉语中常表“多”，是约数，不是确数。几个人同行。","tag":"字词释义"},{"s":"“必有我师<em class='k'>焉</em>”中“<em class='k'>焉</em>”的意思是？","o":["在其中","哪里","怎么","语气词"],"a":"A","e":"“焉”是兼词，相当于“于此”，意为“在其中”。其中必定有值得我学习的人。","tag":"字词释义"},{"s":"“逝者如斯<em class='k'>夫</em>”中“<em class='k'>夫</em>”的意思是？","o":["表感叹","丈夫","夫子","夫人"],"a":"A","e":"“夫”是句末语气词，表示感叹。消逝的事物就像这流水一样啊。","tag":"字词释义"},{"s":"“三军可<em class='k'>夺</em>帅也”中“<em class='k'>夺</em>”的意思是？","o":["改变","夺取","抢夺","剥夺"],"a":"A","e":"“夺”意为“改变”。军队可以被夺走主帅（改变主帅），但普通人的志向不可改变。","tag":"字词释义"},{"s":"“<em class='k'>匹夫</em>不可夺志也”中“<em class='k'>匹夫</em>”的意思是？","o":["平民","莽夫","武夫","一个人"],"a":"A","e":"“匹夫”意为“平民、普通人”。普通百姓的志向无法被强行改变。","tag":"字词释义"},{"s":"“博学而<em class='k'>笃志</em>”中“<em class='k'>笃志</em>”的意思是？","o":["志向坚定","诚实守信","专心学习","志向远大"],"a":"A","e":"“笃”意为“坚定”，“笃志”即志向坚定。广泛学习且志向坚定。","tag":"字词释义"},{"s":"“<em class='k'>切</em>问而近思”中“<em class='k'>切</em>”的意思是？","o":["恳切","急切","确切","密切"],"a":"A","e":"“切”意为“恳切”。恳切地发问且贴近现实思考。","tag":"字词释义"}],"jd":[{"o":"①子曰：“学而时习之，不亦说乎？有朋自远方来，不亦乐乎？人不知而不愠，不亦君子乎？”","t":"孔子说：“学习了（知识）然后按时温习实践，不也是令人愉悦的吗？有志同道合的朋友从远方来相聚，不也是令人快乐的吗？别人不理解自己也不恼怒，不正是君子的品格吗？”","notes":[["时","按时"],["习","温习，复习"],["说","同“悦”，愉快"],["愠","生气，恼怒"]]},{"o":"②曾子曰：“吾日三省吾身：为人谋而不忠乎？与朋友交而不信乎？传不习乎？”","t":"曾子说：“我每天多次反省（我）自己：为别人谋划事情是否尽心竭力了？与朋友交往是否诚实守信了？老师传授的知识是否温习了？”","notes":[["日","每天"],["三","多次，虚指"],["身","自己"],["忠","尽心竭力"],["传","老师传授的知识"]]},{"o":"③子曰：“吾十有五而志于学，三十而立，四十而不惑，五十而知天命，六十而耳顺，七十而从心所欲，不逾矩。”","t":"孔子说：“我十五岁立志于学问，三十岁（能）立身（于世），四十岁对世事不再困惑，五十岁知晓天命的深意，六十岁能听得进不同的意见，七十岁随心所欲做事，却不越过规矩。”","notes":[["有","同“又”"],["志","立志"],["立","立身"],["逾","越过，超过"]]},{"o":"④子曰：“温故而知新，可以为师矣。”","t":"孔子说：“温习学过的知识，从中获得新的理解与体会，这样的人就可以（凭这一点）当老师了。”","notes":[["而","顺承"]]},{"o":"⑤子曰：“学而不思则罔，思而不学则殆。”","t":"孔子说：“只学习却不思考，就会迷惑而无所得；只思考却不学习，就会疑惑而无所适从。”","notes":[["罔","迷惑"],["而","转折，却"],["殆","疑惑"]]},{"o":"⑥子曰：“贤哉，回也！一箪食，一瓢饮，在陋巷，人不堪其忧，回也不改其乐。贤哉，回也！”","t":"多么贤德啊，颜回！一竹筐饭食，一瓢清水，住在简陋的小巷里。别人都无法忍受这种贫苦的忧愁，颜回却不改变他内心的快乐。多么贤德啊，颜回！","notes":[["堪","能忍受"]]},{"o":"⑦子曰：“知之者不如好之者，好之者不如乐之者。”","t":"孔子说：“了解道理的人，不如喜爱道理的人；喜爱道理的人，不如以践行道理为乐的人。”","notes":[["乐","以……为乐"]]},{"o":"⑧子曰：“饭疏食，饮水，曲肱而枕之，乐亦在其中矣。不义而富且贵，于我如浮云。”","t":"孔子说：“吃粗劣的食物，喝冷水，弯起胳膊当作枕头，乐趣也在这其中。用不正当的手段得到的富贵，对我而言就像浮云一样。”","notes":[["饭","吃"],["疏食","粗粮"],["于","对于"]]},{"o":"⑨子曰：“三人行，必有我师焉。择其善者而从之，其不善者而改之。”","t":"孔子说：“几个人同行（“三”在古汉语中常表“多”，非确数），其中必定有值得我学习的人。选择他们的优点去效仿，看到他们的缺点就对照自身，反思并改正自己的不足。”","notes":[["三","几个，约数"],["焉","于此，在其中"]]},{"o":"⑩子在川上曰：“逝者如斯夫，不舍昼夜。”","t":"孔子在河边感叹道：“消逝的事物就像这流水一样啊，不分昼夜地向前奔流。”","notes":[["夫","语气词，表感叹"]]},{"o":"⑪子曰：“三军可夺帅也，匹夫不可夺志也。”","t":"孔子说：“即便庞大的军队能被夺走主帅，普通百姓的志向也无法被强行改变。”","notes":[["夺","改变"],["匹夫","普通人，平民"]]},{"o":"⑫子夏曰：“博学而笃志，切问而近思，仁在其中矣。”","t":"子夏说：“广泛学习且志向坚定，恳切发问且贴近现实思考，'仁'便在这过程中了。”","notes":[["笃志","志向坚定"],["切","恳切"]]}]},{"no":30,"t":"诫子书","src":"部编版七年级上册·《诸葛亮集》","tag":"七年级上册","html":true,"p":["<u>夫</u>君子之行，静<u>以</u>修身，俭以养德。非淡泊无以<u>明</u>志，非宁静无以<u>致远</u>。夫学须静也，才须学也，非学无以<u>广</u>才，非志无以成学。<u>淫慢</u>则不能<u>励精</u>，<u>险躁</u>则不能<u>治</u>性。年与时<u>驰</u>，意与日去，遂成<u>枯落</u>，多不<u>接世</u>，悲守穷庐，将复何<u>及</u>！<br>"],"common":"本文选自《诸葛亮集·文集》卷一（中华书局2012年版）。诸葛亮（181—234），字孔明，琅玡阳都（今山东沂南）人，三国时蜀汉政治家、军事家。“诫”是告诫、劝勉的意思；“子”一般指诸葛亮的儿子诸葛瞻；“书”即书信。","q":[{"s":"“<em class='k'>夫</em>君子之行”中“<em class='k'>夫</em>”的意思是？","o":["句首发语词，无实义","丈夫","夫子","夫人"],"a":"A","e":"“夫”是句首发语词，用在句首表示要发议论，无实义。","tag":"字词释义"},{"s":"“静<em class='k'>以</em>修身”中“<em class='k'>以</em>”的意思是？","o":["来，用来（表目的）","因为","认为","可以"],"a":"A","e":"“以”是连词，表目的，意为“来、用来”。屏除杂念来修养身心。","tag":"字词释义"},{"s":"“非淡泊无以<em class='k'>明</em>志”中“<em class='k'>明</em>”的意思是？","o":["明确","明亮","明白","明智"],"a":"A","e":"“明”形容词作动词，意为“明确、坚定”（使……明确）。不内心恬淡就无法明确志向。","tag":"字词释义"},{"s":"“非宁静无以<em class='k'>致远</em>”中“<em class='k'>致远</em>”的意思是？","o":["达到远大目标","到达远方","走向远方","远大志向"],"a":"A","e":"“致”是“达到”，“远”指远大目标（形容词作名词）。“致远”即达到远大目标。","tag":"字词释义"},{"s":"“非学无以<em class='k'>广</em>才”中“<em class='k'>广</em>”的意思是？","o":["增长","广大","广泛","宽广"],"a":"A","e":"“广”形容词作动词，意为“增长、扩充”（使……增长）。不学习就无法增长才干。","tag":"字词释义"},{"s":"“<em class='k'>淫慢</em>则不能励精”中“<em class='k'>淫慢</em>”的意思是？","o":["放纵懈怠","过于懈怠","懒惰懈怠","放松傲慢"],"a":"A","e":"“淫慢”意为“放纵懈怠”。“淫”是放纵，“慢”是懈怠。","tag":"字词释义"},{"s":"“淫慢则不能<em class='k'>励精</em>”中“<em class='k'>励精</em>”的意思是？","o":["振奋精神","鼓励精神","勉励精神","勤奋努力"],"a":"A","e":"“励精”意为“振奋精神”。“励”是振奋，“精”指精神。","tag":"字词释义"},{"s":"“<em class='k'>险躁</em>则不能治性”中“<em class='k'>险躁</em>”的意思是？","o":["轻薄浮躁","危险急躁","谨慎小心","缓慢迟钝"],"a":"A","e":"“险躁”意为“轻薄浮躁”。“险”是轻薄，“躁”是浮躁。","tag":"字词释义"},{"s":"“险躁则不能<em class='k'>治</em>性”中“<em class='k'>治</em>”的意思是？","o":["修养","治理","治疗","整治"],"a":"A","e":"“治”意为“修养”。“治性”即修养性情。","tag":"字词释义"},{"s":"“年与时<em class='k'>驰</em>”中“<em class='k'>驰</em>”的意思是？","o":["疾速逝去","奔驰","驰骋","松弛"],"a":"A","e":"“驰”本义是奔驰，这里意为“疾速逝去”。年纪随同时光疾速逝去。","tag":"字词释义"},{"s":"“遂成<em class='k'>枯落</em>”中“<em class='k'>枯落</em>”的意思是？","o":["枯枝落叶，比喻年老志衰","枯萎凋落","落叶","干枯"],"a":"A","e":"“枯落”指枯枝落叶，这里比喻人年老志衰、没有用处。","tag":"字词释义"},{"s":"“多不<em class='k'>接世</em>”中“<em class='k'>接世</em>”的意思是？","o":["接触社会，为社会所用","接受现实","连接世界","继承传统"],"a":"A","e":"“接世”意为“接触社会，为社会所用”。大多对社会没有贡献。","tag":"字词释义"},{"s":"“将复何<em class='k'>及</em>”中“<em class='k'>及</em>”的意思是？","o":["来得及","以及","到达","及格"],"a":"A","e":"“及”意为“来得及”。到那时悔恨又怎么来得及！","tag":"字词释义"}],"jd":[{"o":"夫君子之行，静以修身，俭以养德。非淡泊无以明志，非宁静无以致远。","t":"君子的行为操守，（依靠）宁静来修养身心，（依靠）节俭培养品德。不内心恬淡就无法明确志向，不宁静专一就无法实现远大目标。","notes":[["夫","句首发语词"],["以","来，用来"],["明","使……明确"],["致远","达到远大目标"]]},{"o":"夫学须静也，才须学也，非学无以广才，非志无以成学。","t":"学习必须静心专一，才干来源于学习；不学习就无法增长才干，没有志向就不能使学习有所成就。","notes":[["广","增长，扩充"]]},{"o":"淫慢则不能励精，险躁则不能治性。","t":"放纵懈怠，就不能振奋精神；轻薄浮躁，就不能修养性情。","notes":[["淫慢","放纵懈怠"],["励精","振奋精神"],["险躁","轻薄浮躁"],["治","修养"]]},{"o":"年与时驰，意与日去，遂成枯落，多不接世，悲守穷庐，将复何及！","t":"年纪随同时光疾速逝去，意志随同岁月慢慢丧失，最终人年老志衰，大多对社会没有贡献，悲伤地困守在简陋的屋舍中，到那时悔恨又怎么来得及！","notes":[["驰","疾速逝去"],["枯落","比喻年老志衰"],["接世","接触社会，为社会所用"],["及","来得及"]]}]},{"no":31,"t":"陈太丘与友期行","src":"部编版七年级上册·《世说新语·方正》","tag":"七年级上册","html":true,"p":["陈太丘与友<u>期</u>行，期日中。过中不至，太丘<u>舍</u><u>去</u>，去后<u>乃</u>至。元方时年七岁，门外<u>戏</u>。客问元方：“<u>尊君</u>在<u>不</u>？”答曰：“待君久不至，已去。”友人便怒曰：“非人哉！与人期行，相<u>委</u>而去。”元方曰：“君与家君期日中。日中不至，则是无信；对子骂父，则是无礼。”友人惭，下车<u>引</u>之。元方入门不<u>顾</u>。<br>\n  <strong>注释</strong> 〔家君〕对人谦称自己的父亲。<br>"],"common":"本文选自《世说新语·方正》。刘义庆（南朝宋）组织编写。陈太丘即陈寔(shí)，字仲弓，东汉颍川人，曾任太丘长。元方即陈纪，陈寔的长子。","q":[{"s":"“陈太丘与友<em class='k'>期</em>行”中“<em class='k'>期</em>”的意思是？","o":["约定","期限","期望","日期"],"a":"A","e":"“期”意为“约定”。陈太丘和友人约定同行。","tag":"字词释义"},{"s":"“太丘<em class='k'>舍</em>去”中“<em class='k'>舍</em>”的意思是？","o":["舍弃，丢下","房舍","施舍","舍不得"],"a":"A","e":"“舍”意为“舍弃、丢下”。陈太丘丢下（友人）离开了。","tag":"字词释义"},{"s":"“太丘舍<em class='k'>去</em>”中“<em class='k'>去</em>”的意思是？","o":["离开","距离","去除","过去"],"a":"A","e":"“去”意为“离开”。陈太丘丢下（友人）离开了。（注意：《两小儿辩日》中“去”是“距离”义，此处是“离开”义。）","tag":"字词释义"},{"s":"“去后<em class='k'>乃</em>至”中“<em class='k'>乃</em>”的意思是？","o":["才","于是","竟然","你的"],"a":"A","e":"“乃”意为“才”。太丘走后友人才到。","tag":"字词释义"},{"s":"“门外<em class='k'>戏</em>”中“<em class='k'>戏</em>”的意思是？","o":["玩耍，游戏","戏曲","戏弄","演戏"],"a":"A","e":"“戏”意为“玩耍、游戏”。元方在门外玩耍。","tag":"字词释义"},{"s":"“<em class='k'>尊君</em>在不”中“<em class='k'>尊君</em>”的意思是？","o":["对别人父亲的尊称","对人谦称自己的父亲","尊敬的君主","年长的君子"],"a":"A","e":"“尊君”是对别人父亲的尊称（您父亲）。“家君”才是对人谦称自己的父亲。","tag":"字词释义"},{"s":"“尊君在<em class='k'>不</em>”中“<em class='k'>不</em>”的读音和意思是？","o":["fǒu，同“否”，表示疑问","bù，不，否定","fǒu，否定","bù，没有"],"a":"A","e":"“不”读fǒu，同“否”，用在句末表示疑问。你父亲在吗？","tag":"字词释义"},{"s":"“相<em class='k'>委</em>而去”中“<em class='k'>委</em>”的意思是？","o":["丢下，舍弃","委托","委屈","委员"],"a":"A","e":"“委”意为“丢下、舍弃”。却丢下我离开了。","tag":"字词释义"},{"s":"“下车<em class='k'>引</em>之”中“<em class='k'>引</em>”的意思是？","o":["拉，牵","引导","引用","吸引"],"a":"A","e":"“引”意为“拉、牵”。友人下车想拉元方（表示歉意）。","tag":"字词释义"},{"s":"“元方入门不<em class='k'>顾</em>”中“<em class='k'>顾</em>”的意思是？","o":["回头看","照顾","探望","理睬"],"a":"A","e":"“顾”意为“回头看”。元方头也不回地走进门去。","tag":"字词释义"}],"jd":[{"o":"陈太丘与友期行，期日中。","t":"陈太丘和友人约定同行，约定（在）正午。","notes":[["期","约定"]]},{"o":"过中不至，太丘舍去，去后乃至。","t":"（友人）过了正午还没到，陈太丘便舍弃（友人）离开了，（太丘）走后（友人）才到。","notes":[["舍","舍弃，丢下"],["去","离开"],["乃","才"]]},{"o":"元方时年七岁，门外戏。","t":"元方当时七岁，（在）门外玩耍。","notes":[["戏","玩耍"]]},{"o":"客问元方：“尊君在不？”答曰：“待君久不至，已去。”","t":"（友人）问元方：“你父亲在吗？”（元方）回答说：“（父亲）等您很久（您）都没来，（他）已经离开了。”","notes":[["尊君","对别人父亲的尊称"],["不","同“否”，表疑问"]]},{"o":"友人便怒曰：“非人哉！与人期行，相委而去。”","t":"友人便发怒说：“真不是人啊！（他）和别人约定同行，却丢下（我）离开了。”","notes":[["委","丢下，舍弃"]]},{"o":"元方曰：“君与家君期日中。日中不至，则是无信；对子骂父，则是无礼。”","t":"元方说：“您与我父亲约定（在）正午。（您）正午不到，就是不讲信用；对着儿子骂他的父亲，就是没有礼貌。”","notes":[["家君","对人谦称自己的父亲"]]},{"o":"友人惭，下车引之。元方入门不顾。","t":"友人感到惭愧，下车拉（元方）。元方（走）进门去，不回头看。","notes":[["引","拉，牵"],["顾","回头看"]]}]},{"no":32,"t":"卖油翁","src":"部编版七年级下册·《归田录》","tag":"七年级下册","html":true,"p":["陈康肃公<u>善</u>射当世无双公亦<u>以</u>此<u>自矜(jīn)</u>。<u>尝</u>射于家圃，有卖油翁<u>释</u>担<u>而</u>立，<u>睨(nì)</u>之久<u>而</u>不<u>去</u>。见其发矢十中八九，<u>但</u>微<u>颔(hàn)</u>之。康肃问曰：“汝亦知射乎？吾射不亦精乎？”翁曰：“<u>无他</u>，但手熟<u>尔</u>。”康肃忿<u>然</u>曰：“<u>尔</u><u>安</u>敢轻吾射！”翁曰：“<u>以</u>我酌(zhuó)油知之。”<u>乃</u>取一葫芦置于地，<u>以</u>钱覆其口，<u>徐</u>以<u>杓(sháo)</u>酌油沥之，自钱孔入，而钱不湿。因曰：“我亦无他，惟手熟尔。”康肃笑而<u>遣</u>之。<br>\n  <strong>注释</strong> 〔酌(zhuó)〕舀取。<br>"],"common":"本文选自《归田录》卷一（中华书局1981年版），有删节，题目是编者加的。欧阳修（1007—1072），字永叔，号醉翁，晚号六一居士，谥号文忠，吉州永丰（今属江西）人，北宋政治家、文学家，唐宋八大家之一。陈康肃公即陈尧咨，谥号康肃，北宋官员，公是对男子的尊称。","q":[{"s":"“陈康肃公<em class='k'>善</em>射”中“<em class='k'>善</em>”的意思是？","o":["擅长","善良","良好","喜爱"],"a":"A","e":"“善”意为“擅长”。陈康肃公擅长射箭。","tag":"字词释义"},{"s":"“公亦<em class='k'>以</em>此自矜”中“<em class='k'>以</em>”的意思是？","o":["凭借","用来","因为","认为"],"a":"A","e":"“以”意为“凭、凭借”。康肃公也凭这种本领自夸。","tag":"字词释义"},{"s":"“公亦以此<em class='k'>自矜(jīn)</em>”中“自矜”的意思是？","o":["自夸","自尊","自豪","自卑"],"a":"A","e":"“矜”读jīn，“自矜”意为“自夸”。康肃公也凭这种本领自夸。","tag":"字词释义"},{"s":"“<em class='k'>尝</em>射于家圃”中“<em class='k'>尝</em>”的意思是？","o":["曾经","尝试","品尝","常常"],"a":"A","e":"“尝”意为“曾经”。他曾经在自家的园子里射箭。","tag":"字词释义"},{"s":"“有卖油翁<em class='k'>释</em>担而立”中“<em class='k'>释</em>”的意思是？","o":["放下","解释","释放","消除"],"a":"A","e":"“释”意为“放下”。放下担子站在那里。","tag":"字词释义"},{"s":"“释担<em class='k'>而</em>立”中“<em class='k'>而</em>”表示什么关系？","o":["顺承（然后）","转折（却）","并列（并且）","修饰（地）"],"a":"A","e":"“而”表顺承，意为“然后”。放下担子然后站着。","tag":"字词释义"},{"s":"“<em class='k'>睨(nì)</em>之久而不去”中“睨”的意思是？","o":["斜着眼看","正眼看","闭着眼","偷偷看"],"a":"A","e":"“睨”读nì，意为“斜着眼看”。斜着眼睛看他射箭。","tag":"字词释义"},{"s":"“睨之久<em class='k'>而</em>不去”中“<em class='k'>而</em>”表示什么关系？","o":["顺承（然后）","转折（却）","并列（并且）","修饰（地）"],"a":"A","e":"“而”表顺承。斜着眼睛看了很久，没有离开。","tag":"字词释义"},{"s":"“睨之久而不<em class='k'>去</em>”中“<em class='k'>去</em>”的意思是？","o":["离开","去除","过去","距离"],"a":"A","e":"“去”意为“离开”。很久都没有离开。","tag":"字词释义"},{"s":"“<em class='k'>但</em>微颔之”中“<em class='k'>但</em>”的意思是？","o":["只","但是","竟然","况且"],"a":"A","e":"“但”意为“只、只是”。只是对此微微点头。","tag":"字词释义"},{"s":"“但微<em class='k'>颔(hàn)</em>之”中“颔”的意思是？","o":["点头","下巴","摇头","低垂"],"a":"A","e":"“颔”读hàn，意为“点头”。只是对此微微点头。","tag":"字词释义"},{"s":"“<em class='k'>无他</em>”中“无他”的意思是？","o":["没有别的奥妙","没有别人","没有其他办法","没有别的意思"],"a":"A","e":"“无他”意为“没有别的（奥妙）”。没有别的奥妙，只是手法熟练罢了。","tag":"字词释义"},{"s":"“但手熟<em class='k'>尔</em>”中“<em class='k'>尔</em>”的意思是？","o":["罢了","你","这样","仍然"],"a":"A","e":"“尔”同“耳”，是句末语气词，意为“罢了”。只是手法熟练罢了。","tag":"字词释义"},{"s":"“康肃忿<em class='k'>然</em>”中“<em class='k'>然</em>”的意思是？","o":["……的样子","然而","然后","这样"],"a":"A","e":"“然”是形容词词尾，意为“……的样子”。康肃公气愤的样子。","tag":"字词释义"},{"s":"“<em class='k'>尔</em>安敢轻吾射”中“<em class='k'>尔</em>”的意思是？","o":["你","罢了","这样","我"],"a":"A","e":"“尔”意为“你”。你怎么敢轻视我射箭的本领！","tag":"字词释义"},{"s":"“尔<em class='k'>安</em>敢轻吾射”中“<em class='k'>安</em>”的意思是？","o":["怎么","安全","安定","安心"],"a":"A","e":"“安”意为“怎么”。你怎么敢轻视我射箭的本领！","tag":"字词释义"},{"s":"“<em class='k'>以</em>我酌油知之”中“<em class='k'>以</em>”的意思是？","o":["凭借","用来","因为","认为"],"a":"A","e":"“以”意为“凭、凭借”。凭我倒油的经验懂得这个道理。","tag":"字词释义"},{"s":"“<em class='k'>乃</em>取一葫芦置于地”中“<em class='k'>乃</em>”的意思是？","o":["于是","才","竟然","你的"],"a":"A","e":"“乃”意为“于是、就”。于是拿出一个葫芦放在地上。","tag":"字词释义"},{"s":"“<em class='k'>以</em>钱覆其口”中“<em class='k'>以</em>”的意思是？","o":["用","凭借","用来","认为"],"a":"A","e":"“以”意为“用”。用一枚铜钱盖住葫芦的口。","tag":"字词释义"},{"s":"“<em class='k'>徐</em>以杓酌油沥之”中“<em class='k'>徐</em>”的意思是？","o":["慢慢地","匆匆地","轻轻地","重重地"],"a":"A","e":"“徐”意为“慢慢地”。慢慢地用勺子舀油滴入葫芦。","tag":"字词释义"},{"s":"“徐以<em class='k'>杓(sháo)</em>酌油沥之”中“杓”的意思是？","o":["同“勺”，勺子","木桶","器皿","竹竿"],"a":"A","e":"“杓”读sháo，同“勺”，意为“勺子”。慢慢地用勺子舀油。","tag":"字词释义"},{"s":"“康肃笑而<em class='k'>遣</em>之”中“<em class='k'>遣</em>”的意思是？","o":["打发","派遣","谴责","惩罚"],"a":"A","e":"“遣”意为“打发、让……走”。康肃公笑着让他走了。","tag":"字词释义"},{"s":"“<em class='k'>尝射于家圃</em>”是什么特殊句式？","o":["状语后置","宾语前置","定语后置","主谓倒装"],"a":"A","e":"“尝射于家圃”是状语后置句，正常语序为“尝于家圃射”，即曾经在自家的园子里射箭。","tag":"字词释义"},{"s":"下列句子中没有省略成分的是？","o":["汝亦知射乎","但微颔之","自钱孔入，而钱不湿","尝射于家圃"],"a":"A","e":"“但微颔之”省略主语“翁”，“自钱孔入”省略主语“油”，“尝射于家圃”省略主语“公”；“汝亦知射乎”主谓宾完整，没有省略。","tag":"内容理解"},{"s":"“陈康肃公善射当世无双公亦以此自矜”断句正确的一项是？","o":["陈康肃公善射，当世无双，公亦以此自矜。","陈康肃公善射当世，无双公亦，以此自矜。","陈康肃公善，射当世无双，公亦以此自矜。","陈康肃公善射当世无双公，亦以此自矜。"],"a":"A","e":"正确断句为“陈康肃公善射，当世无双，公亦以此自矜。”即陈康肃公擅长射箭，当世没有第二个人能比，他也凭此自夸。","tag":"内容理解"},{"s":"把“我亦无他，惟手熟尔。”翻译为“我也没有别的本事，手法熟练罢了。”是否正确？","o":["正确","错误","空","空"],"a":"B","e":"译文错误。“惟”意为“只、只是”，漏译了；“无他”应译“没有别的奥妙”。正确翻译为“我也没有别的奥妙，只是手法熟练罢了”。","tag":"内容理解"},{"s":"这则故事告诉我们的道理是？","o":["熟能生巧，本领再高也不应自夸","射箭不如倒油","卖油翁技艺更高超","做事要抢先一步"],"a":"A","e":"卖油翁以“酌油”技艺折服陈尧咨，告诉我们熟能生巧，即使本领再高也不应自夸。","tag":"内容理解"},{"s":"陈尧咨对卖油翁的态度前后有什么变化？","o":["从自矜、忿然到心服（笑而遣之）","始终谦虚","始终愤怒","从佩服到轻视"],"a":"A","e":"陈尧咨起初“自矜”，被质疑后“忿然”，见到酌油绝技后“笑而遣之”，态度从自夸、生气转为心服。","tag":"内容理解"}],"jd":[{"o":"陈康肃公善射当世无双公亦以此自矜。尝射于家圃，有卖油翁释担而立，睨之久而不去。见其发矢十中八九，但微颔之。","t":"陈康肃公陈尧咨擅长射箭，当世没有第二个人能同他相比，康肃公也凭这种本领自夸。（他）曾经在自家的园子里射箭，有个卖油的老翁放下担子，站在那里，斜着眼睛看他射箭，很久都没有离开。（老翁）看他射出十支箭能射中八九支，只是对此微微点头。","notes":[["善","擅长"],["以","凭借"],["自矜","自夸"],["尝","曾经"],["释","放下"],["睨","斜着眼看"],["去","离开"],["但","只"],["颔","点头"]]},{"o":"康肃问曰：“汝亦知射乎？吾射不亦精乎？”翁曰：“无他，但手熟尔。”","t":"康肃公问道：“你也懂得射箭吗？我射箭的技艺难道不精湛吗？”老翁说：“没有别的奥妙，只是手法技艺熟练罢了。”","notes":[["无他","没有别的奥妙"],["尔","罢了"]]},{"o":"康肃忿然曰：“尔安敢轻吾射！”翁曰：“以我酌油知之。”","t":"康肃公气愤地说：“你怎么敢轻视我射箭的本领！”老翁说：“凭我倒油的经验就可以懂得这个道理。”","notes":[["然","……的样子"],["尔","你"],["安","怎么"],["以","凭借"]]},{"o":"乃取一葫芦置于地，以钱覆其口，徐以杓酌油沥之，自钱孔入，而钱不湿。","t":"（老翁）于是拿出一个葫芦放在地上，用一枚铜钱盖住葫芦的口，慢慢地用勺子舀油滴入葫芦，（油）从铜钱的方孔注入，而铜钱没有被沾湿。","notes":[["乃","于是"],["以","用"],["徐","慢慢地"],["杓","同“勺”，勺子"]]},{"o":"因曰：“我亦无他，惟手熟尔。”康肃笑而遣之。","t":"于是（老翁）说：“我也没有别的奥妙，只是手法技艺熟练罢了。”康肃公笑着让他走了。","notes":[["遣","打发，让……走"]]}]},{"no":33,"t":"孙权劝学","src":"部编版七年级下册·《资治通鉴》","tag":"七年级下册","html":true,"p":["初，权<u>谓</u>吕蒙曰：“<u>卿(qīng)</u>今当涂掌事，不可不学！”蒙<u>辞</u>以军中多务。权曰：“<u>孤</u>岂欲卿<u>治经</u>为<u>博士</u>邪(yé)！<u>但</u>当<u>涉猎</u>，见往事耳。卿言多务<u>孰</u><u>若</u>孤孤常读书自<u>以为</u>大有所益。”蒙<u>乃</u>始就学。<u>及</u>鲁肃过寻阳，与蒙论议，大惊曰：“卿今者<u>才略</u>，非复吴下阿蒙！”蒙曰：“士别三日，即<u>更(gēng)</u>刮目相待，大兄何见事之晚乎！”肃<u>遂</u>拜蒙母，结友而别。<br>\n  <strong>注释</strong> 〔当涂〕当道，当权。　〔阿蒙〕吕蒙的小名。<br>"],"common":"本文节选自《资治通鉴》卷六十六（中华书局1956年版），题目是编者加的。《资治通鉴》是北宋司马光主持编纂的一部编年体通史，记载了从战国到五代共1362年间的史事。司马光（1019—1086），字君实，北宋政治家、史学家。孙权（182—252），字仲谋，三国时吴国的创建者。","q":[{"s":"“权<em class='k'>谓</em>吕蒙曰”中“<em class='k'>谓</em>”的意思是？","o":["对……说","认为","叫做","称谓"],"a":"A","e":"“谓”意为“对……说”。孙权对吕蒙说。","tag":"字词释义"},{"s":"“<em class='k'>卿(qīng)</em>今当涂掌事”中“卿(qīng)”的意思是？","o":["君对臣的爱称（你）","臣对君的敬称","宰相","夫妻互称"],"a":"A","e":"“卿”是古代君对臣的爱称，这里相当于“你”。","tag":"字词释义"},{"s":"“蒙<em class='k'>辞</em>以军中多务”中“<em class='k'>辞</em>”的意思是？","o":["推辞","言辞","告别","口才"],"a":"A","e":"“辞”意为“推辞、推托”。吕蒙用军中事务多来推辞。","tag":"字词释义"},{"s":"“<em class='k'>孤</em>岂欲卿治经为博士邪”中“<em class='k'>孤</em>”的意思是？","o":["古代王侯的自称","孤独","孤儿","孤单"],"a":"A","e":"“孤”是古代王侯的自称，相当于“我”。","tag":"字词释义"},{"s":"“岂欲卿<em class='k'>治经</em>为博士邪”中“<em class='k'>治经</em>”的意思是？","o":["研究儒家经典","管理经书","整理经典","诵读经文"],"a":"A","e":"“治经”意为“研究儒家经典”。难道想要你研究儒家经典吗？","tag":"字词释义"},{"s":"“为<em class='k'>博士</em>邪”中“<em class='k'>博士</em>”的意思是？","o":["专掌经学传授的学官","学位称号","博学的人","博士研究生"],"a":"A","e":"“博士”是古今异义词，这里指专掌经学传授的学官。","tag":"字词释义"},{"s":"“<em class='k'>但</em>当涉猎”中“<em class='k'>但</em>”的意思是？","o":["只","但是","竟然","况且"],"a":"A","e":"“但”意为“只、只是”（古今异义，今义“但是”）。只是应当粗略地阅读。","tag":"字词释义"},{"s":"“但当<em class='k'>涉猎</em>”中“<em class='k'>涉猎</em>”的意思是？","o":["粗略地阅读","深入研读","涉水打猎","广泛猎取"],"a":"A","e":"“涉猎”意为“粗略地阅读”。只是应当粗略地阅读。","tag":"字词释义"},{"s":"“卿言多务<em class='k'>孰</em>若孤”中“<em class='k'>孰</em>”的意思是？","o":["谁","什么","为什么","怎么"],"a":"A","e":"“孰”意为“谁”。你说事务多，谁比得上我呢？","tag":"字词释义"},{"s":"“孰<em class='k'>若</em>孤”中“<em class='k'>若</em>”的意思是？","o":["比得上","像","如果","你"],"a":"A","e":"“若”意为“比得上”。“孰若”即哪里比得上。","tag":"字词释义"},{"s":"“自<em class='k'>以为</em>大有所益”中“<em class='k'>以为</em>”的意思是？","o":["认为","作为","因为","可以"],"a":"A","e":"“以为”意为“认为”。自己认为大有好处。","tag":"字词释义"},{"s":"“蒙<em class='k'>乃</em>始就学”中“<em class='k'>乃</em>”的意思是？","o":["于是","才","竟然","你的"],"a":"A","e":"“乃”意为“于是、就”。吕蒙于是开始学习。","tag":"字词释义"},{"s":"“<em class='k'>及</em>鲁肃过寻阳”中“<em class='k'>及</em>”的意思是？","o":["等到","以及","到达","及时"],"a":"A","e":"“及”意为“到了……的时候”（等到）。等到鲁肃经过寻阳。","tag":"字词释义"},{"s":"“卿今者<em class='k'>才略</em>”中“<em class='k'>才略</em>”的意思是？","o":["才干谋略","聪明才智","远大志向","文学才华"],"a":"A","e":"“才略”意为“才干和谋略”。以你现在的才干谋略来看。","tag":"字词释义"},{"s":"“即<em class='k'>更(gēng)</em>刮目相待”中“更(gēng)”的意思是？","o":["另外","更加","更换","反而"],"a":"A","e":"“更”读gēng，意为“另、另外”（重新）。就要另外用新的眼光看待。","tag":"字词释义"},{"s":"“肃<em class='k'>遂</em>拜蒙母”中“<em class='k'>遂</em>”的意思是？","o":["于是","终于","顺遂","满足"],"a":"A","e":"“遂”意为“于是、就”。鲁肃于是拜见吕蒙的母亲。","tag":"字词释义"},{"s":"“<em class='k'>蒙辞以军中多务</em>”是什么特殊句式？","o":["状语后置","宾语前置","省略句","判断句"],"a":"A","e":"“蒙辞以军中多务”是状语后置句，正常语序为“蒙以军中多务辞”，即吕蒙用军中事务多来推辞。","tag":"字词释义"},{"s":"“卿言多务孰若孤孤常读书自以为大有所益”断句正确的一项是？","o":["卿言多务，孰若孤？孤常读书，自以为大有所益。","卿言多务孰，若孤孤常读书，自以为大有所益。","卿言多务孰若孤孤，常读书自以为，大有所益。","卿言多务，孰若孤孤，常读书自，以为大有所益。"],"a":"A","e":"正确断句为“卿言多务，孰若孤？孤常读书，自以为大有所益。”意思是：你说事务多，谁比得上我呢？我经常读书，自己认为大有好处。","tag":"内容理解"}],"jd":[{"o":"初，权谓吕蒙曰：“卿今当涂掌事，不可不学！”","t":"当初，孙权对吕蒙说：“你现在当权管事了，不可不学习！”","notes":[["谓","对……说"],["卿","君对臣的爱称"],["当涂","当权"]]},{"o":"蒙辞以军中多务。","t":"吕蒙用军中事务多（来）推辞。","notes":[["辞","推辞"],["以军中多务","状语后置"]]},{"o":"权曰：“孤岂欲卿治经为博士邪！但当涉猎，见往事耳。卿言多务孰若孤孤常读书自以为大有所益。”","t":"孙权说：“我难道想要你研究儒家经典，成为专掌经学传授的学官吗！只是应当粗略地阅读，了解历史罢了。你说事务多，谁比得上我（事务多）呢？我经常读书，自己认为大有好处。”","notes":[["孤","王侯自称"],["治经","研究儒家经典"],["博士","学官"],["但","只"],["涉猎","粗略地阅读"],["孰","谁"],["若","比得上"],["以为","认为"]]},{"o":"蒙乃始就学。","t":"吕蒙于是开始学习。","notes":[["乃","于是"]]},{"o":"及鲁肃过寻阳，与蒙论议，大惊曰：“卿今者才略，非复吴下阿蒙！”","t":"等到鲁肃经过寻阳，和吕蒙谈论议事，（鲁肃）十分惊奇地说：“以你现在的才干、谋略来看，你不再是原来那个吴地的阿蒙了！”","notes":[["及","等到"],["才略","才干谋略"],["阿蒙","吕蒙的小名"]]},{"o":"蒙曰：“士别三日，即更刮目相待，大兄何见事之晚乎！”","t":"吕蒙说：“读书人分别多日，就要另外用新的眼光看待，长兄你认清事物怎么这么晚呢！”","notes":[["更","另外"]]},{"o":"肃遂拜蒙母，结友而别。","t":"鲁肃于是拜见吕蒙的母亲，与吕蒙结为朋友后就分别了。","notes":[["遂","于是"]]}]},{"no":34,"t":"木兰诗","src":"部编版七年级下册·《乐府诗集》","tag":"七年级下册","html":true,"p":["唧唧复唧唧，木兰<u>当户</u>织。不闻<u>机杼</u>声，<u>唯</u>闻女叹息。问女<u>何所思</u><small>〔何所思〕宾语前置，想什么</small>，问女何所忆。女亦无所思，女亦无所忆。昨夜见<u>军帖</u>，<u>可汗(kè hán)</u>大点兵，军书<u>十二</u>卷，卷卷有爷名。阿爷无大儿，木兰无长兄，愿为<u>市</u>鞍马，从此替爷征。","东<u>市</u>买骏马，西市买鞍鞯<small>〔鞍鞯〕jiān，马鞍下的垫子</small>，南市买辔头<small>〔辔(pèi)头〕驾驭牲口的嚼子和缰绳</small>，北市买长鞭。<u>旦</u>辞爷娘去，暮宿黄河边，不闻爷娘唤女声，但闻黄河流水鸣溅溅<small>〔溅溅〕jiān，水流声</small>。<u>旦</u>辞黄河去，暮至黑山头，不闻爷娘唤女声，但闻燕山<small>〔燕(yān)山〕北方山名</small>胡骑鸣啾啾<small>〔啾啾〕jiū，马叫的声音</small>。","万里赴<u>戎机</u>，关山<u>度</u>若飞。<u>朔气</u>传金柝<small>〔金柝(tuò)〕古时军中守夜打更用的器具</small>，寒光照<u>铁衣</u>。将军百战死，壮士十年归。归来见天子，天子坐明堂。<u>策勋</u>十二转<small>〔十二转〕勋级每升一级叫一转，“十二”表多数</small>，赏赐百千<u>强</u>。可汗问所欲，木兰<u>不用</u>尚书郎，愿驰<u>千里足</u>，送儿还故乡。","爷娘闻女来，出<u>郭</u>相扶将；阿姊闻妹来，当户理<u>红妆</u>；小弟闻姊来，磨刀<u>霍霍</u>向猪羊。开我东阁门，坐我西阁床，脱我战时袍，<u>著(zhuó)</u>我旧时裳。当窗理云鬓，<u>帖(tiē)</u>花黄。出门看<u>火伴</u>，火伴皆惊忙：同行十二年，不知木兰是女郎。雄兔脚<u>扑朔</u>，雌兔眼<u>迷离</u>；双兔傍地走，安能辨我是雄雌？"],"common":"","q":[{"s":"“<em class='k'>唧唧</em>复唧唧”中“<em class='k'>唧唧</em>”的意思是？","o":["叹息声","织布声","哭泣声","鸟叫声"],"a":"A","e":"“唧唧”是叹息声。木兰对着门织布，听不到织布声，只听到她的叹息声。","tag":"字词释义"},{"s":"“木兰<em class='k'>当户</em>织”中“<em class='k'>当户</em>”的意思是？","o":["对着门","在户外","抵挡门户","在屋内"],"a":"A","e":"“当”意为“对着”，“户”是“门”。“当户织”即对着门织布。","tag":"字词释义"},{"s":"“不闻<em class='k'>机杼</em>声”中“<em class='k'>机杼</em>”的意思是？","o":["织布机","纺锤","机敏","机关"],"a":"A","e":"“机杼”指织布机。“杼”是织布机的梭子。","tag":"字词释义"},{"s":"“<em class='k'>问女何所思</em>”是什么特殊句式？","o":["宾语前置","状语后置","判断句","省略句"],"a":"A","e":"“何所思”即“所思何”（想的是什么），疑问代词“何”作宾语前置。","tag":"内容理解"},{"s":"“<em class='k'>唯</em>闻女叹息”中“<em class='k'>唯</em>”的意思是？","o":["只","唯一","因为","虽然"],"a":"A","e":"“唯（同’惟‘）”意为“只”。只听到木兰在叹息。","tag":"字词释义"},{"s":"“愿为<em class='k'>市</em>鞍马”中“<em class='k'>市</em>”的意思是？","o":["买","市场","出售","集市"],"a":"A","e":"“市”名词作动词，意为“买”。木兰愿意去买鞍马，替父出征。","tag":"字词释义"},{"s":"“军书<em class='k'>十二</em>卷”中“<em class='k'>十二</em>”的意思是？","o":["虚指，表多数","确指十二","十加二","十二次"],"a":"A","e":"“十二”是虚指，表示多数（与下文“壮士十年归”“同行十二年”中的“十、十二”均为虚数）。","tag":"字词释义"},{"s":"“<em class='k'>旦</em>辞爷娘去”中“<em class='k'>旦</em>”的意思是？","o":["早晨","白天","天亮","明日"],"a":"A","e":"“旦”意为“早晨”。早晨告别爹娘出发。","tag":"字词释义"},{"s":"“东市买骏马……北市买长鞭”四句使用了什么修辞？","o":["排比和互文","比喻","拟人","夸张"],"a":"A","e":"“互文”指上下文各举一端，合起来表达完整意思——去各处市场置办出征装备。“排比”指结构相似的四句并列。","tag":"内容理解"},{"s":"“<em class='k'>但</em>闻黄河流水鸣溅溅”中“<em class='k'>但</em>”的意思是？","o":["只","但是","然而","不过"],"a":"A","e":"“但”意为“只、只是”，与“不闻”形成对比——听不到爹娘唤女声，只听到黄河水声。","tag":"字词释义"},{"s":"“鸣<em class='k'>溅溅</em>”中“<em class='k'>溅溅</em>”的读音是？","o":["jiān jiān","jiàn jiàn","jiǎn jiǎn","jiān jiàn"],"a":"A","e":"“溅溅”读 jiān jiān，形容水流声。（纯读音题，四声调辨析）","tag":"字词释义"},{"s":"“<em class='k'>燕</em>山胡骑鸣啾啾”中“<em class='k'>燕</em>”的读音是？","o":["yān","yàn","yǎn","yán"],"a":"A","e":"“燕山”的“燕”读 yān（地名专用读法）。","tag":"字词释义"},{"s":"“万里赴<em class='k'>戎机</em>”中“<em class='k'>戎机</em>”的意思是？","o":["战事","军机","军事","战争"],"a":"A","e":"课本注释：“戎机”即“战事”。不远万里奔赴战场参加战事。","tag":"字词释义"},{"s":"“关山<em class='k'>度</em>若飞”中“<em class='k'>度</em>”的意思是？","o":["越过","度过","衡量","速度"],"a":"A","e":"“度”意为“越过”。像飞一样越过关隘和山岭。","tag":"字词释义"},{"s":"“<em class='k'>朔气</em>传金柝”中“<em class='k'>朔气</em>”的意思是？","o":["北方的寒气","寒气","天气","初春的气息"],"a":"A","e":"“朔”常指北方，“朔气”即北方的寒气。北方的寒气传来打更的声音。","tag":"字词释义"},{"s":"“寒光照<em class='k'>铁衣</em>”中“<em class='k'>铁衣</em>”的意思是？","o":["铠甲","铁匠的衣服","战袍","金属衣服"],"a":"A","e":"“铁衣”指铠甲（将士的护身服装）。冷冷的月光照在将士的铠甲上。","tag":"字词释义"},{"s":"“<em class='k'>策勋</em>十二转”中“<em class='k'>策勋</em>”的意思是？","o":["记功","策略","鞭策","功劳"],"a":"A","e":"“策”意为“记”（写在简策上），“勋”意为“功勋”。“策勋”即在功劳簿上记功。","tag":"字词释义"},{"s":"“赏赐百千<em class='k'>强</em>”中“<em class='k'>强</em>”的含义是？","o":["有余","强大","勉强","强盛"],"a":"A","e":"“强”意为“有余、不止”。赏赐的财物成百上千还有余。","tag":"字词释义"},{"s":"“木兰<em class='k'>不用</em>尚书郎”中“<em class='k'>不用</em>”的意思是？","o":["不愿做","不使用","用不着","不可以"],"a":"A","e":"“不用”是古今异义词，意为“不愿做、不做”。木兰不愿做尚书郎的官职。","tag":"字词释义"},{"s":"“愿驰<em class='k'>千里足</em>”中“<em class='k'>千里足</em>”的意思是？","o":["千里马","远行","走一千里路","日行千里的脚"],"a":"A","e":"“千里足”指千里马（日行千里的良马）。希望骑上千里马回家乡。","tag":"字词释义"},{"s":"“将军百战死，壮士十年归”使用了什么修辞？","o":["互文","比喻","夸张","排比"],"a":"A","e":"“互文”——将军和壮士有的战死沙场，有的经历十年征战凯旋。不可拆开理解为“将军都战死、壮士都归来”。","tag":"内容理解"},{"s":"诗歌为什么略写十年征战、详写战前准备与还乡场景？","o":["突出木兰女儿本色、重亲情不热衷功名","缺少战争素材","战争场面不好描写","为了节省诗歌篇幅"],"a":"A","e":"详略安排服务于主题——诗歌重在塑造木兰勤劳孝顺、不慕荣利的形象。详写战前（替父从军体现孝）和战后（辞官还乡体现淡泊），略写战争（一笔带过），突出木兰的女儿本色。","tag":"内容理解"},{"s":"“出<em class='k'>郭</em>相扶将”中“<em class='k'>郭</em>”的意思是？","o":["外城","城门","城墙","城郭姓"],"a":"A","e":"“郭”指外城（古代城有内外两重，内城为“城”，外城为“郭”）。","tag":"字词释义"},{"s":"“当户理<em class='k'>红妆</em>”中“<em class='k'>红妆</em>”的意思是？","o":["古代女子的艳丽装束","红色的衣裳","红花","红粉"],"a":"A","e":"“红妆”指古代女子艳丽的装束和打扮。对着门整理打扮。","tag":"字词释义"},{"s":"“磨刀<em class='k'>霍霍</em>向猪羊”中“<em class='k'>霍霍</em>”的意思是？","o":["磨刀的声音","快速的样子","光亮闪闪","众多"],"a":"A","e":"“霍霍”是拟声词，形容磨刀的声音。","tag":"字词释义"},{"s":"“<em class='k'>著</em>我旧时裳”中“<em class='k'>著</em>”的读音和意思是？","o":["zhuó，穿","zhù，著作","zhù，穿着","zhe，助词"],"a":"A","e":"“著”读 zhuó，意为“穿”。穿上我旧时的衣裳。","tag":"字词释义"},{"s":"“对镜<em class='k'>帖</em>花黄”中“<em class='k'>帖</em>”的意思是？","o":["通“贴”，粘贴","帖子","涂贴","帖附"],"a":"A","e":"“帖”通“贴”，意为“粘贴”。对着镜子贴上花黄（面部装饰）。","tag":"字词释义"},{"s":"“出门看<em class='k'>火伴</em>”中“<em class='k'>火伴</em>”的意思是？","o":["同伍的士兵","火把","伙伴的火","伙夫"],"a":"A","e":"“火”是古代兵制单位，十人为一“火”。“火伴”即同伍的士兵，后写作“伙伴”。","tag":"字词释义"},{"s":"“雄兔脚<em class='k'>扑朔</em>”中“<em class='k'>扑朔</em>”的意思是？","o":["动弹","扑腾","迷失","迅速"],"a":"A","e":"“扑朔”指兔子前脚不停动弹的样子。雄兔前脚总在动弹。","tag":"字词释义"},{"s":"木兰形象的核心特点是？","o":["勤劳孝顺、勇敢坚毅、不慕荣利","武艺高强、争强好胜","温柔贤淑、不爱武装","机智狡黠、善于伪装"],"a":"A","e":"全文刻画了木兰勤劳（当户织）、孝顺（替父征）、勇敢（万里赴戎机）、不慕荣利（不用尚书郎）、机智（安能辨我是雄雌）的多元形象。","tag":"内容理解"}],"jd":[{"o":"唧唧复唧唧，木兰当户织。不闻机杼声，唯闻女叹息。","t":"叹息声一声接着一声，木兰对着门在织布。听不到织布机的响声，只听到木兰在叹息。","notes":[["唧唧","叹息声"],["当户","对着门"],["机杼","织布机"],["唯","只"]]},{"o":"问女何所思，问女何所忆。女亦无所思，女亦无所忆。昨夜见军帖，可汗大点兵，军书十二卷，卷卷有爷名。","t":"问木兰在想什么，问木兰在思念什么。木兰也没有想什么，也没有思念什么。昨夜看到军中的文告，可汗大规模征兵，征兵的名册有很多卷，每卷都有父亲的名字。","notes":[["何所思","宾语前置，想什么"],["军帖","军中文告"],["十二","虚指，表多数"]]},{"o":"阿爷无大儿，木兰无长兄，愿为市鞍马，从此替爷征。","t":"父亲没有大儿子，木兰没有哥哥，（她）愿意去买鞍马，从此代替父亲出征。","notes":[["市","买（名作动）"]]},{"o":"东市买骏马，西市买鞍鞯，南市买辔头，北市买长鞭。","t":"（到）各处市场购置骏马、马鞍垫、嚼子缰绳和长鞭。（互文排比）","notes":[["互文排比",""]]},{"o":"旦辞爷娘去，暮宿黄河边，不闻爷娘唤女声，但闻黄河流水鸣溅溅。旦辞黄河去，暮至黑山头，不闻爷娘唤女声，但闻燕山胡骑鸣啾啾。","t":"早晨告别爹娘出发，傍晚宿营在黄河边，听不到爹娘呼唤女儿的声音，只听到黄河水哗哗作响。早晨辞别黄河，傍晚到达黑山脚下，听不到爹娘唤女声，只听到燕山胡人的战马嘶鸣。","notes":[["旦","早晨"],["但","只"],["溅溅","水流声"],["啾啾","马叫声"]]},{"o":"万里赴戎机，关山度若飞。朔气传金柝，寒光照铁衣。将军百战死，壮士十年归。","t":"不远万里奔赴战事，像飞一样越过关隘山岭。北方的寒气传来打更声，冷冷的月光照在铠甲上。（有的）将军和壮士战死沙场，（有的）经历多年征战胜利归来。（互文）","notes":[["戎机","战事"],["度","越过"],["朔气","北方的寒气"],["铁衣","铠甲"]]},{"o":"归来见天子，天子坐明堂。策勋十二转，赏赐百千强。可汗问所欲，木兰不用尚书郎，愿驰千里足，送儿还故乡。","t":"归来拜见天子，天子坐在明堂上。（天子）给木兰记了很高的功勋，赏赐的财物成百上千还有余。可汗问（木兰）想要什么，木兰不愿做尚书郎，希望骑上千里马回家乡。","notes":[["策勋","记功"],["强","有余"],["不用","不愿做"],["千里足","千里马"]]},{"o":"爷娘闻女来，出郭相扶将；阿姊闻妹来，当户理红妆；小弟闻姊来，磨刀霍霍向猪羊。","t":"爹娘听说女儿回来，互相扶持着到外城迎接；姐姐听说妹妹回来，对着门整理艳丽的装束；小弟听说姐姐回来，霍霍地磨刀向着猪羊。","notes":[["郭","外城"],["红妆","女子艳丽装束"],["霍霍","磨刀声"]]},{"o":"开我东阁门，坐我西阁床，脱我战时袍，著我旧时裳。当窗理云鬓，对镜帖花黄。","t":"打开我东阁的门，坐我西阁的床，脱下打仗时的战袍，穿上旧时的衣裳。对着窗户梳理如云般美丽的鬓发，对着镜子贴上花黄。","notes":[["著(zhuó)","穿"],["帖","通“贴”"]]},{"o":"出门看火伴，火伴皆惊忙：同行十二年，不知木兰是女郎。雄兔脚扑朔，雌兔眼迷离；双兔傍地走，安能辨我是雄雌？","t":"出门去见同伍的士兵，伙伴们都非常惊讶：同行多年，竟不知木兰是女郎。雄兔前脚不停动弹，雌兔两眼总是眯着；两只兔子贴着地面跑，怎能辨别哪只是雄兔、哪只是雌兔呢？（比喻木兰女扮男装难以辨别）","notes":[["火伴","同伍的士兵"],["扑朔","动弹"],["迷离","眯着眼"]]}]},{"no":35,"t":"活板","src":"部编版七年级下册·《梦溪笔谈》","tag":"七年级下册","html":true,"p":["板印书籍，唐人尚未<u>盛</u>为之。<u>已</u>后典籍皆为板本。庆历中，有<u>布衣</u>毕昇，又<u>为</u>活板。","其法：用胶泥刻字，薄如钱<u>唇</u>，每字为一<u>印</u>，<u>火</u>烧令坚。先设一铁板，其上以松脂、蜡和纸灰之类<u>冒</u>之。欲印，则以一铁范置铁板上，乃密布字印，满铁范为一板，持<u>就</u>火炀(yáng)之，药稍熔，则以一平板按其面，则字平如<u>砥</u>。","若<u>止</u>印三二本，未为简易；若印数十百千本，则极为神速。常作二铁板，一板印刷，一板已自<u>布字</u>，此印者才毕，则第二板已<u>具</u>，<u>更互</u>用之，瞬息可<u>就</u>。","每一字皆有数印，如“之”“也”等字，每字有二十余印，以备一板内有重复者。不用，则以纸<u>帖</u>之，每韵为一帖，木格贮之。有奇字<small>〔奇字〕生僻字</small>素无备者，<u>旋</u>刻之，以草火烧，瞬息可成。不以木为之者，文<u>理</u>有疏密，沾水则高下不平，兼与药相粘，不可取；不若燔土，用讫再火令药熔，以手拂之，其印自落，<u>殊</u>不沾污。"],"common":"","q":[{"s":"“<em class='k'>板</em>印书籍”中“<em class='k'>板</em>”的意思是？","o":["用雕版（同“版”，名作状）","木板","印刷","版面"],"a":"A","e":"“板”同“版”，名词作状语，意为“用雕版”。用雕版印刷书籍。","tag":"字词释义"},{"s":"“尚未<em class='k'>盛</em>为之”中“<em class='k'>盛</em>”的意思是？","o":["大规模地","茂盛","丰富","隆重"],"a":"A","e":"“盛”意为“大规模地”。唐朝人还没有大规模地这样做。","tag":"字词释义"},{"s":"“<em class='k'>已</em>后典籍”中“<em class='k'>已</em>”的读音和意思是？","o":["yǐ，同“以”","yǐ，已经","jǐ，自己","yì，已经"],"a":"A","e":"“已”读yǐ，同“以”，“已后”即“以后”。","tag":"字词释义"},{"s":"“有<em class='k'>布衣</em>毕昇”中“<em class='k'>布衣</em>”的意思是？","o":["平民","布做的衣服","布衣人家","粗布衣裳"],"a":"A","e":"“布衣”借代指平民（穿布衣的人）。有个平民叫毕昇。","tag":"字词释义"},{"s":"“又<em class='k'>为</em>活板”中“<em class='k'>为</em>”的意思是？","o":["制作","为了","被","作为"],"a":"A","e":"“为”意为“制作”。又发明（制作）了活字印刷。","tag":"字词释义"},{"s":"“薄如钱<em class='k'>唇</em>”中“<em class='k'>唇</em>”的意思是？","o":["边缘","嘴唇","钱孔","中心"],"a":"A","e":"“唇”意为“边缘”。字模薄得像铜钱的边缘。","tag":"字词释义"},{"s":"“每字为一<em class='k'>印</em>”中“<em class='k'>印</em>”的意思是？","o":["字印","印刷","印刻","印象"],"a":"A","e":"“印”指字印（印章）。每个字做一个字印。","tag":"字词释义"},{"s":"“<em class='k'>火</em>烧令坚”中“<em class='k'>火</em>”的意思是？","o":["用火（名词作状语）","火焰","火烧","火烤"],"a":"A","e":"“火”名词作状语，意为“用火”。用火烧使它坚硬。","tag":"字词释义"},{"s":"“以松脂、蜡和纸灰之类<em class='k'>冒</em>之”中“<em class='k'>冒</em>”的意思是？","o":["覆盖","冒犯","冒出","冒充"],"a":"A","e":"“冒”意为“覆盖”。用松脂、蜡混合纸灰这类东西覆盖（铁板）。","tag":"字词释义"},{"s":"“持<em class='k'>就</em>火炀之”中“<em class='k'>就</em>”的意思是？","o":["靠近","完成","立即","于是"],"a":"A","e":"“就”意为“靠近”。拿着（铁板）靠近火烘烤。","tag":"字词释义"},{"s":"“持就火<em class='k'>炀(yáng)</em>之”中“<em class='k'>炀(yáng)</em>”的意思是？","o":["烤","加热","烧灼","点火"],"a":"A","e":"“炀”读yáng，意为“烤”。拿着（铁板）靠近火烘烤。","tag":"字词释义"},{"s":"“则字平如<em class='k'>砥</em>”中“<em class='k'>砥</em>”的意思是？","o":["磨刀石","地面","平地","基础"],"a":"A","e":"“砥”意为“磨刀石”。字模平整得像磨刀石一样。","tag":"字词释义"},{"s":"“若<em class='k'>止</em>印三二本”中“<em class='k'>止</em>”的意思是？","o":["只","停止","阻止","还是"],"a":"A","e":"“止”意为“只、仅”。如果只印两三本。","tag":"字词释义"},{"s":"“一板已自<em class='k'>布字</em>”中“<em class='k'>布字</em>”的意思是？","o":["排字","布置","分布","写字"],"a":"A","e":"“布字”意为“排字”。另一块板已经在自行排字。","tag":"字词释义"},{"s":"“则第二板已<em class='k'>具</em>”中“<em class='k'>具</em>”的意思是？","o":["准备好","工具","具备","具体"],"a":"A","e":"“具”意为“准备好”。第二块板已经准备好了。","tag":"字词释义"},{"s":"“<em class='k'>更互</em>用之”中“<em class='k'>更互</em>”的意思是？","o":["交替","更加","更换","互相"],"a":"A","e":"“更互”意为“交替、轮流”。交替使用两块板。","tag":"字词释义"},{"s":"“瞬息可<em class='k'>就</em>”中“<em class='k'>就</em>”的意思是？","o":["完成","靠近","立即","靠近"],"a":"A","e":"“就”意为“完成”。转眼之间就能完成。（与“持就火炀之”的“就=靠近”对比）","tag":"字词释义"},{"s":"“则以纸<em class='k'>帖</em>之”中“<em class='k'>帖</em>”的意思是？","o":["标注（动词）","粘贴","帖子","字帖"],"a":"A","e":"“帖”作动词，意为“标注”。就用纸标签标注它们。","tag":"字词释义"},{"s":"“<em class='k'>旋</em>刻之”中“<em class='k'>旋</em>”的意思是？","o":["随即","旋转","盘旋","周转"],"a":"A","e":"“旋”意为“随即、立刻”。随即刻制它。","tag":"字词释义"},{"s":"“文<em class='k'>理</em>有疏密”中“<em class='k'>文</em>”的意思是？","o":["同“纹”，纹理","文章","文字","文化"],"a":"A","e":"“文”同“纹”，意为“纹理”。木头的纹理有疏有密。","tag":"字词释义"},{"s":"“<em class='k'>殊</em>不沾污”中“<em class='k'>殊</em>”的意思是？","o":["根本","特殊","不同","非常"],"a":"A","e":"“殊”意为“根本、绝对”。根本不会被弄脏。","tag":"字词释义"},{"s":"“常作二铁板一板印刷一板已自布字此印者才毕则第二板已具更互用之瞬息可就”断句正确的一项是？","o":["常作二铁板，一板印刷，一板已自布字，此印者才毕，则第二板已具，更互用之，瞬息可就。","常作二铁板一板，印刷一板，已自布字此印者，才毕则第二板，已具更互用之，瞬息可就。","常作二铁板，一板印刷一板已，自布字此印者才毕，则第二板已具更互，用之瞬息可就。","常作二铁板一板印刷，一板已自布字此印者，才毕则第二板已具，更互用之瞬息可就。"],"a":"A","e":"正确断句为“常作二铁板，一板印刷，一板已自布字，此印者才毕，则第二板已具，更互用之，瞬息可就。”意为常常做两块铁板，一块印刷，一块排字，交替使用，转眼完成。","tag":"内容理解"},{"s":"下列句子中是被动句的是？","o":["昇死，其印为余群从所得","板印书籍，唐人尚未盛为之","火烧令坚","不以木为之者"],"a":"A","e":"“其印为余群从所得”中“为……所”表被动，是被动句，意为“字印被我的堂兄弟和子侄辈得到”。","tag":"内容理解"}],"jd":[{"o":"板印书籍，唐人尚未盛为之。自冯瀛王始印五经，已后典籍皆为板本。","t":"用雕版印刷书籍，唐朝人还没有大规模地这样做。从冯瀛王开始用雕版印刷五经，以后的书籍都是用雕版印刷的本子了。","notes":[["板","用雕版（名作状）"],["盛","大规模地"],["已","同“以”"]]},{"o":"庆历中，有布衣毕昇，又为活板。","t":"庆历年间，有个平民叫毕昇，又发明（制作）了活字印刷。","notes":[["布衣","平民（借代）"],["为","制作"]]},{"o":"其法：用胶泥刻字，薄如钱唇，每字为一印，火烧令坚。","t":"他的方法是：用黏土刻字，字模薄得像铜钱的边缘，每个字做一个字印，用火烧使它坚硬。","notes":[["唇","边缘"],["印","字印"],["火","用火（名作状）"]]},{"o":"先设一铁板，其上以松脂、蜡和纸灰之类冒之。","t":"先设置一块铁板，在它上面用松脂、蜡混合纸灰这类东西覆盖。","notes":[["冒","覆盖"]]},{"o":"欲印，则以一铁范置铁板上，乃密布字印，满铁范为一板，持就火炀之，药稍熔，则以一平板按其面，则字平如砥。","t":"想要印刷时，就把一个铁框放在铁板上，于是密密地排布字印，排满铁框算作一板，拿着（铁板）靠近火烘烤它，药物稍微熔化，就用一块平板按压它的表面，于是字模就平整得像磨刀石一样。","notes":[["就","靠近"],["炀(yáng)","烤"],["砥","磨刀石"]]},{"o":"若止印三二本，未为简易；若印数十百千本，则极为神速。","t":"如果只印两三本，还不算是简便省事；如果印几十、几百、上千本，那就非常快速了。","notes":[["止","只"]]},{"o":"常作二铁板，一板印刷，一板已自布字，此印者才毕，则第二板已具，更互用之，瞬息可就。","t":"常常做两块铁板，一块板在印刷，另一块板已经在自行排字，这块板刚印完，第二块板已经准备好了，交替使用它们，转眼之间就能完成。","notes":[["布字","排字"],["具","准备好"],["更互","交替"],["就","完成"]]},{"o":"每一字皆有数印，如“之”“也”等字，每字有二十余印，以备一板内有重复者。","t":"每个字都有好几个字印，像“之”“也”等字，每个字有二十多个字印，用来防备一块板内有重复出现（的字）。","notes":[["备","防备"]]},{"o":"不用，则以纸帖之，每韵为一帖，木格贮之。","t":"（字印）不用的时候，就用纸标签标注它们，每个韵部做一个标签，用木格存放它们。","notes":[["帖","标注（动词）"],["韵","韵部"]]},{"o":"有奇字素无备者，旋刻之，以草火烧，瞬息可成。","t":"有平时没有准备的生僻字，随即刻制它，用草火烘烤，转眼之间就能做成。","notes":[["奇字","生僻字"],["素","平时"],["旋","随即"]]},{"o":"不以木为之者，文理有疏密，沾水则高下不平，兼与药相粘，不可取；不若燔土，用讫再火令药熔，以手拂之，其印自落，殊不沾污。","t":"不用木头刻字印的原因，是（木头的）纹理有疏有密，沾水后就高低不平，并且和药物互相粘连，不能取下来；不如用火烧黏土（制印），用完后再用火烤使药物熔化，用手掸它，那些字印自然掉落，根本不会被弄脏。","notes":[["文","同“纹”，纹理"],["燔","烧"],["讫","完毕"],["殊","根本"]]},{"o":"昇死，其印为余群从所得，至今保藏。","t":"毕昇死后，他的字印被我的堂兄弟和子侄辈得到，至今还保存收藏着。","notes":[["为……所","被动句式"],["群从","堂兄弟及侄子辈"]]}]},{"no":36,"t":"爱莲说","src":"部编版七年级下册·《周敦颐集》","tag":"七年级下册","html":true,"p":["水陆草木之花，<u>可爱</u>者甚<u>蕃(fán)</u>。晋陶渊明<u>独</u>爱菊。自李唐来，世人甚爱牡丹。<u>予</u>独爱莲<u>之</u>出淤泥<u>而</u>不染，<u>濯</u>清涟而不<u>妖</u>，中通外直，不<u>蔓</u>不<u>枝</u>，香远<u>益</u>清，亭亭净植，可远观而不可<u>亵</u>玩焉。予<u>谓</u>菊花之隐逸者也牡丹花之富贵者也莲花之君子者也。噫！菊之爱，陶后<u>鲜</u>有闻。莲之爱，同予者何人？牡丹之爱，<u>宜</u>乎众矣。<br>"],"common":"本文选自《周敦颐集》卷三（中华书局2009年版）。周敦颐（1017—1073），字茂叔，道州营道（今湖南道县）人，北宋哲学家，著有《太极图说》《通书》等。“说”是古代的一种议论性文体，多借事物阐述道理。","q":[{"s":"“<em class='k'>可爱</em>者甚蕃”中“可爱”的意思是？","o":["值得喜爱","讨人喜欢","可爱的人","喜爱"],"a":"A","e":"“可爱”是古今异义词，意为“值得喜爱”。值得喜爱的非常多。","tag":"字词释义"},{"s":"“可爱者甚<em class='k'>蕃(fán)</em>”中“蕃”的意思是？","o":["多","茂盛","繁殖","稀少"],"a":"A","e":"“蕃”读fán，意为“多”。值得喜爱的非常多。","tag":"字词释义"},{"s":"“晋陶渊明<em class='k'>独</em>爱菊”中“<em class='k'>独</em>”的意思是？","o":["只","独自","孤独","独特"],"a":"A","e":"“独”意为“只、唯独”。晋代的陶渊明只喜爱菊花。","tag":"字词释义"},{"s":"“<em class='k'>予</em>独爱莲”中“<em class='k'>予</em>”的读音和意思是？","o":["yú，我","yǔ，给予","yú，语气词","yǔ，参与"],"a":"A","e":"“予”读yú，意为“我”。我唯独喜爱莲花。","tag":"字词释义"},{"s":"“莲<em class='k'>之</em>出淤泥而不染”中“<em class='k'>之</em>”的作用是？","o":["取消句子独立性，不译","结构助词，的","代词，它","动词，去"],"a":"A","e":"“之”用在主谓之间，取消句子独立性，不译。莲花从淤泥中长出却不被污染。","tag":"字词释义"},{"s":"“出淤泥<em class='k'>而</em>不染”中“<em class='k'>而</em>”表示什么关系？","o":["转折（却）","顺承（然后）","并列（并且）","修饰（地）"],"a":"A","e":"“而”表转折，意为“却”。从淤泥中长出却不被污染。","tag":"字词释义"},{"s":"“<em class='k'>濯</em>清涟而不妖”中“<em class='k'>濯</em>”的意思是？","o":["洗","沐浴","浇灌","沾染"],"a":"A","e":"“濯”意为“洗”。经过清水的洗涤却不显得妖艳。","tag":"字词释义"},{"s":"“濯清涟而不<em class='k'>妖</em>”中“<em class='k'>妖</em>”的意思是？","o":["妖艳","妖怪","妖气","端庄"],"a":"A","e":"“妖”意为“妖艳、艳丽”（美丽而不端庄）。经过清水洗涤却不显得妖艳。","tag":"字词释义"},{"s":"“不<em class='k'>蔓</em>不枝”中“<em class='k'>蔓</em>”的意思是？","o":["生枝蔓","藤蔓","蔓延","缠绕"],"a":"A","e":"“蔓”名词作动词，意为“生枝蔓”。不生枝蔓，不长枝节。","tag":"字词释义"},{"s":"“不蔓不<em class='k'>枝</em>”中“<em class='k'>枝</em>”的意思是？","o":["长枝节","树枝","蔓延","缠绕"],"a":"A","e":"“枝”名词作动词，意为“长枝节”。不生枝蔓，不长枝节。","tag":"字词释义"},{"s":"“香远<em class='k'>益</em>清”中“<em class='k'>益</em>”的意思是？","o":["更加","益处","增加","有益"],"a":"A","e":"“益”意为“更加”。香气远播更加清香。","tag":"字词释义"},{"s":"“可远观而不可<em class='k'>亵</em>玩焉”中“<em class='k'>亵</em>”的意思是？","o":["亲近而不庄重","轻浮","亵渎","玩耍"],"a":"A","e":"“亵”意为“亲近而不庄重”。只能远远地观赏而不能靠近赏玩它。","tag":"字词释义"},{"s":"“予<em class='k'>谓</em>菊”中“<em class='k'>谓</em>”的意思是？","o":["认为","对……说","叫做","称谓"],"a":"A","e":"“谓”意为“认为”。我认为菊花是花中的隐士。","tag":"字词释义"},{"s":"“陶后<em class='k'>鲜</em>有闻”中“<em class='k'>鲜</em>”的意思是？","o":["少","新鲜","鲜艳","鲜美"],"a":"A","e":"“鲜”读xiǎn，意为“少”。在陶渊明以后很少听到了。","tag":"字词释义"},{"s":"“<em class='k'>宜</em>乎众矣”中“<em class='k'>宜</em>”的意思是？","o":["应当","适宜","便宜","适合"],"a":"A","e":"“宜”意为“应当”。应当（喜爱牡丹的人）很多了。","tag":"字词释义"},{"s":"“予谓菊花之隐逸者也牡丹花之富贵者也莲花之君子者也”断句正确的一项是？","o":["予谓菊，花之隐逸者也；牡丹，花之富贵者也；莲，花之君子者也。","予谓菊花，之隐逸者也；牡丹花，之富贵者也；莲花，之君子者也。","予谓菊，花之隐逸者，也牡丹花之富贵者，也莲花之君子者也。","予谓菊花之，隐逸者也；牡丹花之，富贵者也；莲花之，君子者也。"],"a":"A","e":"正确断句为“予谓菊，花之隐逸者也；牡丹，花之富贵者也；莲，花之君子者也。”即我认为菊花是花中的隐士，牡丹是花中的富贵者，莲花是花中品德高尚的君子。","tag":"内容理解"},{"s":"下列对莲花特点与君子品行的搭配中，错误的是？","o":["出淤泥而不染——不与世俗同流合污","濯清涟而不妖——孤高自傲、哗众取宠","中通外直——内心通达，行为正直","不蔓不枝——不结党营私"],"a":"B","e":"B项搭配不当。“濯清涟而不妖”比喻君子不孤高自傲、不哗众取宠，B项“孤高自傲、哗众取宠”恰好说反了。","tag":"内容理解"},{"s":"文中写菊、牡丹有什么作用？","o":["衬托莲，突出莲的高洁（菊正衬、牡丹反衬）","说明菊和牡丹也很美","介绍三种花的习性","表达对菊和牡丹的喜爱"],"a":"A","e":"写菊、牡丹是为了衬托莲：用菊（隐逸）正衬莲，用牡丹（富贵）反衬莲，突出莲高洁、不慕名利的特点。","tag":"内容理解"},{"s":"“莲之爱，同予者何人？”表达了作者怎样的情感？","o":["感叹知音稀少，表达洁身自好、不慕名利的情操","抱怨没人陪自己赏莲","疑问是否有人爱莲","表达对牡丹的厌恶"],"a":"A","e":"“同予者何人”感叹世上像自己一样爱莲（洁身自好）的人很少，知音难觅，表达作者不慕名利、洁身自好的高洁情操。","tag":"内容理解"},{"s":"如何理解“出淤泥而不染”？","o":["比喻君子身处污浊环境却能洁身自好、不同流合污","说明莲花长在淤泥里","表达对淤泥的厌恶","指莲花出淤泥但很干净"],"a":"A","e":"“出淤泥而不染”比喻君子虽身处污浊的环境，却能洁身自好、不与世俗同流合污。","tag":"内容理解"}],"jd":[{"o":"水陆草木之花，可爱者甚蕃。","t":"水上、陆地上各种草本木本的花，值得喜爱的非常多。","notes":[["可爱","值得喜爱"],["蕃(fán)","多"]]},{"o":"晋陶渊明独爱菊。自李唐来，世人甚爱牡丹。","t":"晋代的陶渊明只喜爱菊花。从李氏唐朝以来，世上的人十分喜爱牡丹。","notes":[["独","只"]]},{"o":"予独爱莲之出淤泥而不染，濯清涟而不妖，中通外直，不蔓不枝，香远益清，亭亭净植，可远观而不可亵玩焉。","t":"我唯独喜爱莲花从淤泥中长出却不被污染，经过清水的洗涤却不显得妖艳；它的茎内空外直，不生蔓不长枝，香气远播更加清香，笔直洁净地立在水中，人们只能远远地观赏而不能靠近赏玩它。","notes":[["予","我"],["之","取消句子独立性"],["而","转折，却"],["濯","洗"],["妖","妖艳"],["蔓","生枝蔓"],["枝","长枝节"],["益","更加"],["亵","亲近而不庄重"]]},{"o":"予谓菊，花之隐逸者也；牡丹，花之富贵者也；莲，花之君子者也。","t":"我认为菊花，是花中的隐士；牡丹，是花中的富贵者；莲花，是花中品德高尚的君子。","notes":[["谓","认为"]]},{"o":"噫！菊之爱，陶后鲜有闻。莲之爱，同予者何人？牡丹之爱，宜乎众矣。","t":"唉！对于菊花的喜爱，在陶渊明以后很少听到了。对于莲花的喜爱，像我一样的还有什么人呢？对于牡丹的喜爱，应当（喜爱的人）很多了！","notes":[["鲜","少"],["宜","应当"]]}]},{"no":37,"t":"陋室铭","src":"部编版七年级下册·《刘禹锡集》","tag":"七年级下册","html":true,"p":["山不在高，有仙则<u>名</u>。水不在深，有龙则灵。<u>斯</u>是陋室，<u>惟</u>吾德馨。苔痕上阶绿，草色入帘青。谈笑有鸿儒，往来无<u>白丁</u>。可以<u>调</u><u>素</u>琴，阅<u>金经</u>。无<u>丝竹</u>之<u>乱</u>耳，无案牍之<u>劳</u>形。南阳诸葛庐，西蜀子云亭。孔子云：<u>何陋之有</u>？<br>"],"common":"本文选自《刘禹锡集》（中华书局1990年版）。刘禹锡（772—842），字梦得，唐代文学家。“铭”是古代刻在器物上用来警诫自己或者称述功德的文字，后来成为一种文体。“陋室”即简陋的屋子。","q":[{"s":"“有仙则<em class='k'>名</em>”中“<em class='k'>名</em>”的意思是？","o":["出名","名字","名声","命名"],"a":"A","e":"“名”名词作动词，意为“出名、有名”。有了神仙就会出名。","tag":"字词释义"},{"s":"“<em class='k'>斯</em>是陋室”中“<em class='k'>斯</em>”的意思是？","o":["这","那","这样","于是"],"a":"A","e":"“斯”意为“这”。这是简陋的屋子。","tag":"字词释义"},{"s":"“<em class='k'>惟</em>吾德馨”中“<em class='k'>惟</em>”的意思是？","o":["加强肯定语气","只","因为","虽然"],"a":"A","e":"“惟”在最新课本中解释为“加强肯定语气”。“惟吾德馨”即正是因为我品德高尚（才不觉得简陋）。","tag":"字词释义"},{"s":"“往来无<em class='k'>白丁</em>”中“<em class='k'>白丁</em>”的意思是？","o":["没有功名的平民","目不识丁的人","穿白衣服的人","有名望的人"],"a":"A","e":"“白丁”指没有功名的平民。交往的没有无功名的平民。","tag":"字词释义"},{"s":"“可以<em class='k'>调</em>素琴”中“<em class='k'>调</em>”的意思是？","o":["弹奏","调节","调动","调试"],"a":"A","e":"“调”意为“弹奏”。可以弹奏不加装饰的琴。","tag":"字词释义"},{"s":"“调<em class='k'>素</em>琴”中“<em class='k'>素</em>”的意思是？","o":["不加装饰的","白色的","原本的","素雅的"],"a":"A","e":"“素”意为“不加装饰的”。“素琴”即不加装饰的琴。","tag":"字词释义"},{"s":"“阅<em class='k'>金经</em>”中“<em class='k'>金经</em>”的意思是？","o":["佛经","用金粉书写的经书","最珍贵的经书","道德经"],"a":"A","e":"“金经”指佛经。阅读佛经。","tag":"字词释义"},{"s":"“无<em class='k'>丝竹</em>之乱耳”中“<em class='k'>丝竹</em>”的意思是？","o":["奏乐的声音","丝绸和竹子","乐器本身","悠扬的歌声"],"a":"A","e":"“丝竹”原指弦乐器和管乐器，这里借代指奏乐的声音。","tag":"字词释义"},{"s":"“无丝竹之<em class='k'>乱</em>耳”中“<em class='k'>乱</em>”的意思是？","o":["使……扰乱","混乱","作乱","杂乱"],"a":"A","e":"“乱”使动用法，意为“使……扰乱”。没有奏乐的声音使（我的）耳朵被扰乱。","tag":"字词释义"},{"s":"“无案牍之<em class='k'>劳</em>形”中“<em class='k'>劳</em>”的意思是？","o":["使……劳累","劳累","劳动","功劳"],"a":"A","e":"“劳”使动用法，意为“使……劳累”。没有官府的公文使（我的）身体劳累。","tag":"字词释义"},{"s":"“<em class='k'>何陋之有</em>”是什么特殊句式？","o":["宾语前置","状语后置","判断句","省略句"],"a":"A","e":"“何陋之有”是宾语前置句，正常语序为“有何陋”，即有什么简陋的呢？","tag":"字词释义"},{"s":"本文表达了作者怎样的思想感情？","o":["安贫乐道、高洁傲岸的情操","对诸葛亮的仰慕","对自然景色的喜爱","对官场生活的向往"],"a":"A","e":"作者身居陋室却不以为陋，因为“惟吾德馨”，表达了安贫乐道、高洁傲岸的情操。","tag":"内容理解"},{"s":"文中提到“南阳诸葛庐，西蜀子云亭”的作用是？","o":["类比自比，表明自己品德高尚、安贫乐道","说明这些房子都很简陋","表达对古代贤人的怀念","表明自己想去南阳西蜀居住"],"a":"A","e":"以诸葛亮的草庐、扬子云的亭子自比（类比），表明自己同古代贤人一样，虽居陋室但品德高尚、不慕荣利。","tag":"内容理解"}],"jd":[{"o":"山不在高，有仙则名。水不在深，有龙则灵。","t":"山不在于高，有了神仙就会出名；水不在于深，有了龙就会有灵气。","notes":[["名","出名，名词作动词"]]},{"o":"斯是陋室，惟吾德馨。","t":"这是简陋的屋子，正是因为我的品德高尚（而不觉得简陋）。","notes":[["斯","这"],["惟","加强肯定语气"]]},{"o":"苔痕上阶绿，草色入帘青。","t":"苔痕碧绿，长到台阶上；草色青葱，映入帘子里。","notes":[]},{"o":"谈笑有鸿儒，往来无白丁。","t":"（在这里）谈笑的都是博学之人，往来的没有无功名的平民。","notes":[["白丁","没有功名的平民"]]},{"o":"可以调素琴，阅金经。","t":"可以弹奏不加装饰的琴，阅读佛经。","notes":[["调","弹奏"],["素","不加装饰的"],["金经","佛经"]]},{"o":"无丝竹之乱耳，无案牍之劳形。","t":"没有奏乐的声音使（我的）耳朵被扰乱，没有官府的公文使（我的）身体劳累。","notes":[["丝竹","奏乐的声音"],["乱","使……扰乱"],["劳","使……劳累"]]},{"o":"南阳诸葛庐，西蜀子云亭。","t":"南阳有诸葛亮的草庐，西蜀有扬子云的亭子。","notes":[]},{"o":"孔子云：何陋之有？","t":"孔子说：（这）有什么简陋的呢？","notes":[["何陋之有","宾语前置"]]}]},{"no":38,"t":"三峡","src":"部编版八年级上册·《水经注》","tag":"八年级上册","html":true,"p":["自三峡七百里中，两岸连山，略无<u>阙</u>处。重岩叠嶂<small>〔嶂〕直立像屏障的山峰</small>，隐天蔽日，自非<u>亭午</u>夜分，不见曦<small>〔曦〕日光，这里指太阳</small>月。","至于夏水<u>襄</u>陵，沿<u>溯</u>阻绝。或王命急<u>宣</u>，有时朝发白帝，暮到江陵，其间千二百里，<u>虽</u>乘<u>奔</u><u>御</u>风，不以<u>疾</u>也。","春冬之时，则<u>素</u><u>湍</u>绿潭，回清倒影，<u>绝巘(yǎn)</u>多生怪柏，悬泉瀑布，<u>飞漱</u>其间，清荣峻茂，<u>良</u>多趣味。","每至晴初霜旦林寒涧肃常有高猿长啸属引凄异空谷传响哀转久绝。故渔者歌曰：“巴东三峡巫峡长，猿鸣三声泪沾裳。”"],"common":"","q":[{"s":"“略无<em class='k'>阙</em>处”中“<em class='k'>阙</em>”的读音和意思是？","o":["quē，同“缺”，空隙缺口","què，宫阙","quē，缺少","jué，掘"],"a":"A","e":"“阙”读quē，同“缺”，意为“空隙、缺口”。完全没有中断的地方。","tag":"字词释义"},{"s":"“<em class='k'>自非</em>亭午夜分”中“<em class='k'>自非</em>”的意思是？","o":["如果不是","自然不是","自从不是","只要不是"],"a":"A","e":"“自非”意为“如果不是”。如果不是正午和半夜。","tag":"字词释义"},{"s":"“<em class='k'>亭午</em>夜分”中“<em class='k'>亭午</em>”的意思是？","o":["正午","亭子旁","中午","半夜"],"a":"A","e":"“亭午”意为“正午”。不是正午和半夜就看不见太阳和月亮。","tag":"字词释义"},{"s":"“夏水<em class='k'>襄</em>陵”中“<em class='k'>襄</em>”的意思是？","o":["冲上，漫上","襄阳","帮助","高起"],"a":"A","e":"“襄”意为“冲上、漫上”。夏天江水漫上山陵。","tag":"字词释义"},{"s":"“沿<em class='k'>溯</em>阻绝”中“<em class='k'>溯</em>”的意思是？","o":["逆流而上","顺流而下","追溯","溯流"],"a":"A","e":"“溯”意为“逆流而上”。上行和下行的航道都被阻断。","tag":"字词释义"},{"s":"“<em class='k'>或</em>王命急宣”中“<em class='k'>或</em>”的意思是？","o":["有时","或者","或许","某人"],"a":"A","e":"“或”意为“有时”。有时遇到皇帝的命令要急速传达。","tag":"字词释义"},{"s":"“<em class='k'>虽</em>乘奔御风”中“<em class='k'>虽</em>”的意思是？","o":["即使","虽然","虽然……但是","纵然"],"a":"A","e":"“虽”意为“即使”（古今异义，今义“虽然”）。即使骑着飞奔的马。","tag":"字词释义"},{"s":"“虽乘<em class='k'>奔</em>御风”中“<em class='k'>奔</em>”的意思是？","o":["飞奔的马（动词作名词）","奔跑","奔驰","奔跑的人"],"a":"A","e":"“奔”动词作名词，意为“飞奔的马”。骑着飞奔的马。","tag":"字词释义"},{"s":"“不<em class='k'>以</em>疾也”中“<em class='k'>以</em>”的意思是？","o":["认为","用来","因为","可以"],"a":"A","e":"“以”意为“认为”。也不认为（比这）快。","tag":"字词释义"},{"s":"“虽乘奔御风，不以疾也。”翻译正确的一项是？","o":["即使骑着飞奔的马，驾着疾风，也没有这么快。","虽然骑着飞奔的马，驾着疾风，也没有这么快。","即使骑着飞奔的马，驾着疾风，也不认为（比这）慢。","虽然骑着奔驰的快马，乘着疾风，也不觉得这么快。"],"a":"A","e":"A正确。“虽”应译“即使”，B、D误译“虽然”；“疾”是“快”，C误译“慢”。","tag":"内容理解"},{"s":"“<em class='k'>朝发白帝</em>”与下列哪句的特殊句式相同？","o":["蒙辞以军中多务（状语后置）","何陋之有（宾语前置）","莲，花之君子者也（判断句）","其印为余群从所得（被动句）"],"a":"A","e":"“朝发白帝”即“朝于白帝发”，状语后置句，与《孙权劝学》“蒙辞以军中多务”（以军中多务辞）句式相同，都是状语后置。","tag":"内容理解"},{"s":"“则素<em class='k'>湍</em>绿潭”中“<em class='k'>湍</em>”的意思是？","o":["急流","湍急","水流","瀑布"],"a":"A","e":"“湍”意为“急流”。白色的急流、碧绿的深潭。","tag":"字词释义"},{"s":"“<em class='k'>绝巘(yǎn)</em>多生怪柏”中“<em class='k'>绝巘</em>”的意思是？","o":["极高的山峰","山崖","山顶","山谷"],"a":"A","e":"“绝巘”读绝巘(yǎn)，意为“极高的山峰”。极高的山峰上多生长着怪柏。","tag":"字词释义"},{"s":"“<em class='k'>飞漱</em>其间”中“<em class='k'>飞漱</em>”的意思是？","o":["急流冲荡","飞速冲刷","飞流","洗涤"],"a":"A","e":"“飞漱”意为“急流冲荡”。悬泉瀑布在山峰之间飞速冲荡。","tag":"字词释义"},{"s":"“<em class='k'>良</em>多趣味”中“<em class='k'>良</em>”的意思是？","o":["确实，很","良好","善良","优良"],"a":"A","e":"“良”意为“确实、很”。确实有很多趣味。","tag":"字词释义"},{"s":"“<em class='k'>属</em>引凄异”中“<em class='k'>属</em>”的意思是？","o":["连接","属于","嘱咐","跟随"],"a":"A","e":"“属”意为“连接”。声音连续不断。","tag":"字词释义"},{"s":"“属<em class='k'>引</em>凄异”中“<em class='k'>引</em>”的意思是？","o":["延长","引导","牵引","引用"],"a":"A","e":"“引”意为“延长”。声音连续不断、延长。（属=连接，引=延长）","tag":"字词释义"},{"s":"“哀转久<em class='k'>绝</em>”中“<em class='k'>绝</em>”的意思是？","o":["消失","断绝","绝对","极高"],"a":"A","e":"“绝”意为“消失”。悲哀婉转，很久才消失。（与“沿溯阻绝”的“绝=断绝”对比）","tag":"字词释义"},{"s":"“<em class='k'>林寒涧肃</em>”使用了什么修辞？","o":["互文（树林和山涧都清寒寂静）","比喻","拟人","夸张"],"a":"A","e":"“林寒涧肃”是互文，意为“树林和山涧都清寒寂静”，不能拆开理解为“树林寒、山涧肃”。","tag":"内容理解"},{"s":"“每至晴初霜旦林寒涧肃常有高猿长啸属引凄异空谷传响哀转久绝”断句正确的一项是？","o":["每至晴初霜旦，林寒涧肃，常有高猿长啸，属引凄异，空谷传响，哀转久绝。","每至晴初，霜旦林寒，涧肃常有，高猿长啸属引，凄异空谷，传响哀转，久绝。","每至晴初霜旦林寒，涧肃常有高猿，长啸属引凄异，空谷传响哀转，久绝。","每至晴初霜旦，林寒涧肃常有，高猿长啸属，引凄异空谷，传响哀转久绝。"],"a":"A","e":"正确断句为“每至晴初霜旦，林寒涧肃，常有高猿长啸，属引凄异，空谷传响，哀转久绝。”","tag":"内容理解"},{"s":"文末引用渔歌“巴东三峡巫峡长，猿鸣三声泪沾裳”的作用是？","o":["烘托秋季三峡萧瑟凄清的氛围，侧面写出山高峡长，渲染猿鸣哀婉","说明当地百姓生活艰苦","表现渔者的劳动号子","赞美三峡秋天景色优美"],"a":"A","e":"引用渔歌有三层作用：①烘托秋季三峡萧瑟凄清的氛围；②侧面写出三峡山高、峡长；③渲染猿鸣哀婉，增强文学色彩。","tag":"内容理解"}],"jd":[{"o":"自三峡七百里中，两岸连山，略无阙处。","t":"在三峡七百里的（沿途）中，两岸都是相连的山，完全没有中断的地方。","notes":[["自","在"],["略无","完全没有"],["阙","同“缺”，空隙"]]},{"o":"重岩叠嶂，隐天蔽日，自非亭午夜分，不见曦月。","t":"重重的悬崖，层层的峭壁，遮蔽了天空，挡住了太阳，如果不是正午和半夜，就看不见太阳和月亮。","notes":[["自非","如果不是"],["亭午","正午"],["曦","日光，这里指太阳"]]},{"o":"至于夏水襄陵，沿溯阻绝。","t":"到了夏天江水漫上山陵的时候，上行和下行的航道都被阻断，不能通航。","notes":[["襄","冲上，漫上"],["溯","逆流而上"]]},{"o":"或王命急宣，有时朝发白帝，暮到江陵，其间千二百里，虽乘奔御风，不以疾也。","t":"有时遇到皇帝的命令要急速传达，这时候只要清早坐船从白帝城出发，傍晚就可到江陵，中间相距一千二百里，即使骑着飞奔的马、驾着疾风，也不认为（比这）快。","notes":[["或","有时"],["宣","传达"],["虽","即使"],["奔","飞奔的马（名作动）"],["御","驾"],["疾","快"]]},{"o":"春冬之时，则素湍绿潭，回清倒影，绝巘多生怪柏，悬泉瀑布，飞漱其间，清荣峻茂，良多趣味。","t":"在春、冬两个季节，就有白色的急流、碧绿的深潭，回旋的清波，倒映着（各种景物的）影子，极高的山峰上多生长着奇形怪状的柏树，悬泉瀑布在山峰之间飞速冲荡，水清，树荣，山高，草盛，确实有很多趣味。","notes":[["素","白色"],["湍","急流"],["绝巘","极高的山峰"],["飞漱","急流冲荡"],["良","确实，很"]]},{"o":"每至晴初霜旦，林寒涧肃，常有高猿长啸，属引凄异，空谷传响，哀转久绝。","t":"（在秋天）每到天刚放晴或下霜的早晨，树林和山涧显出一片清寒和寂静，经常有高处的猿猴拉长声音鸣叫，声音连续不断，凄惨悲凉，空旷的山谷传来回声，悲哀婉转，很久才消失。","notes":[["肃","肃杀，寂静"],["属","连接"],["引","延长"],["响","回声"],["转","婉转"],["绝","消失"]]},{"o":"故渔者歌曰：“巴东三峡巫峡长，猿鸣三声泪沾裳。”","t":"所以打鱼的人唱道：“巴东三峡巫峡长，猿鸣三声泪沾裳。”","notes":[["故","所以"]]}]},{"no":39,"t":"与朱元思书","src":"部编版八年级上册·[南朝梁]吴均","tag":"八年级上册","html":true,"p":["风烟<u>俱</u><u>净</u>，天山共色。从流飘荡，任意<u>东西</u>。自富阳至桐庐一百<u>许</u>里，奇山异水，天下<u>独</u>绝。","水皆缥碧，千丈见底。游鱼细石，直视无碍。急湍甚箭，猛浪<u>若</u><u>奔</u>。","<u>夹岸</u>高山，皆生<u>寒树</u>，负势<u>竞</u>上，互相<u>轩邈</u>，争高<u>直指</u>，千百成峰<small>〔千百成峰〕形成千百座山峰</small>。","泉水激石，泠泠作响；好鸟相鸣，嘤嘤成韵。蝉则千<u>转</u>不<u>穷</u>，猿则百叫无绝。","鸢飞<u>戾</u>天者，望峰息心；<u>经纶</u>世务者，窥谷忘<u>反</u>。横<u>柯</u><u>上</u>蔽，在昼<u>犹</u>昏；疏条交映，有时见日。"],"common":"","q":[{"s":"“风烟<em class='k'>俱</em><em class='k'>净</em>”中“<em class='k'>俱</em>”的意思是？","o":["全，都","一起","工具","具备"],"a":"A","e":"“俱”意为“全、都”。“风烟俱净”即烟雾都消散尽净。","tag":"字词释义"},{"s":"“风烟俱<em class='k'>净</em>”中“<em class='k'>净</em>”的意思是？","o":["消散，散尽","干净","纯净","清净"],"a":"A","e":"“净”此处指烟雾消散尽净。","tag":"字词释义"},{"s":"“任意<em class='k'>东西</em>”中“<em class='k'>东西</em>”的活用和意思是？","o":["名词作动词，向东向西漂行","东边和西边","物品","方向"],"a":"A","e":"“东西”名词作动词，意为“向东向西漂行”。","tag":"字词释义"},{"s":"“一百<em class='k'>许</em>里”中“<em class='k'>许</em>”的意思是？","o":["左右，约","允许","也许","许多"],"a":"A","e":"“许”意为“左右、约”。“一百许里”即一百里左右。","tag":"字词释义"},{"s":"“天下<em class='k'>独</em>绝”中“<em class='k'>独</em>”的意思是？","o":["独一无二","独自","唯独","孤独"],"a":"A","e":"“独”意为“独一无二”。“天下独绝”即天下独一无二。","tag":"字词释义"},{"s":"“猛浪<em class='k'>若</em>奔”中“<em class='k'>若</em>”的意思是？","o":["像，如同","如果","比得上","假如"],"a":"A","e":"“若”意为“像、如同”。凶猛的巨浪像飞奔的骏马。","tag":"字词释义"},{"s":"“猛浪若<em class='k'>奔</em>”中“<em class='k'>奔</em>”的活用和意思是？","o":["动词作名词，飞奔的马","奔跑","奔腾","飞奔"],"a":"A","e":"“奔”动词作名词，指飞奔的骏马。","tag":"字词释义"},{"s":"“急湍甚箭，猛浪若奔”运用的修辞手法是？","o":["对偶+比喻","对偶+夸张","比喻+拟人","排比+比喻"],"a":"A","e":"把急流比作飞箭、巨浪比作奔马，是比喻；两句对仗工整，是对偶。生动写出江水流速迅猛、气势磅礴。","tag":"修辞手法"},{"s":"“<em class='k'>夹岸</em>高山”中“<em class='k'>夹岸</em>”的意思是？","o":["两岸","岸边","夹住江岸","对岸"],"a":"A","e":"“夹岸”即“两岸”。","tag":"字词释义"},{"s":"“皆生<em class='k'>寒树</em>”中“<em class='k'>寒树</em>”的意思是？","o":["耐寒常绿的树，这里指密而绿的树","寒冷的树","冬天的树","枯树"],"a":"A","e":"“寒树”指耐寒常绿的树，这里形容树木密而绿。","tag":"字词释义"},{"s":"“负势<em class='k'>竞</em>上”中“<em class='k'>竞</em>”的意思是？","o":["争相","竟然","竞争","比赛"],"a":"A","e":"“竞”意为“争相”。山峦凭借地势争相向上。","tag":"字词释义"},{"s":"“互相<em class='k'>轩邈</em>”中“<em class='k'>轩邈</em>”的活用和意思是？","o":["形容词作动词，向高处、远处伸展","高大","深远","轩敞"],"a":"A","e":"“轩”“邈”形容词作动词，意为“向高处、远处伸展”。","tag":"字词释义"},{"s":"“争高<em class='k'>直指</em>”中“<em class='k'>直指</em>”的意思是？","o":["笔直地向上，直插云天","直接指挥","径直指着","伸手指挥"],"a":"A","e":"“直指”意为笔直地向上，直插云天。","tag":"字词释义"},{"s":"“负势竞上，互相轩邈，争高直指”运用的修辞手法是？","o":["拟人","比喻","夸张","对偶"],"a":"A","e":"赋予山峦“竞上”“轩邈”“争高”的竞争情态，是拟人，生动写出群山高耸、连绵、生机勃勃的特点。","tag":"修辞手法"},{"s":"“蝉则千<em class='k'>转</em>不穷”中“<em class='k'>转</em>”的意思是？","o":["同“啭”，婉转鸣叫，这里指蝉鸣","转动","转变","转告"],"a":"A","e":"“转”同“啭”，婉转鸣叫，这里指蝉鸣。","tag":"字词释义"},{"s":"“蝉则千转不<em class='k'>穷</em>”中“<em class='k'>穷</em>”的意思是？","o":["穷尽","贫穷","穷困","尽头"],"a":"A","e":"“穷”意为“穷尽”。“千转不穷”即长久不停地鸣叫。","tag":"字词释义"},{"s":"“鸢飞<em class='k'>戾</em>天者”中“<em class='k'>戾</em>”的意思是？","o":["至，到达","暴戾","乖戾","弯曲"],"a":"A","e":"“戾”意为“至、到达”。“鸢飞戾天”即鸢鸟飞到天上。","tag":"字词释义"},{"s":"“<em class='k'>经纶</em>世务者”中“<em class='k'>经纶</em>”的意思是？","o":["筹划、治理","经营","丝线","纺织"],"a":"A","e":"“经纶”本义整理丝缕，引申为“筹划、治理”。","tag":"字词释义"},{"s":"“窥谷忘<em class='k'>反</em>”中“<em class='k'>反</em>”的意思是？","o":["同“返”，返回","反对","反而","反叛"],"a":"A","e":"“反”同“返”，返回。“忘反”即流连忘返。","tag":"字词释义"},{"s":"“横<em class='k'>柯</em>上蔽”中“<em class='k'>柯</em>”的意思是？","o":["树枝","斧柄","树干","树根"],"a":"A","e":"“柯”本义斧柄，这里指树枝。“横柯”即横斜的树枝。","tag":"字词释义"},{"s":"“横柯<em class='k'>上</em>蔽”中“<em class='k'>上</em>”的活用和意思是？","o":["名词作状语，在上方","向上（动词）","上面","上级"],"a":"A","e":"“上”名词作状语，意为“在上方”。","tag":"字词释义"},{"s":"“在昼<em class='k'>犹</em>昏”中“<em class='k'>犹</em>”的意思是？","o":["仍然，好像","犹豫","尤其","还要"],"a":"A","e":"“犹”意为“仍然、好像”。“在昼犹昏”即白天也如同黄昏。","tag":"字词释义"},{"s":"“鸢飞戾天者，望峰息心；经纶世务者，窥谷忘反”在文中的作用是？","o":["结构上承上启下，由写景转入抒情议论；内容上抒发热爱自然、淡泊名利、避世归隐的情怀，暗含对追逐名利之人的规劝","结构上总结全文，内容上点明时间地点","结构上照应开头，内容上描写景物细节","结构上引出下文，内容上交代写作缘由"],"a":"A","e":"结构上承上启下（由写景转入抒情议论）；内容上触景生情，抒发热爱自然、淡泊名利、避世归隐的情怀，也暗含对世俗官场追逐名利之人的规劝。","tag":"内容理解"},{"s":"下列加点词解释有误的一项是？","o":["一百许里——左右","猛浪若奔——奔跑","互相轩邈——向高处伸展","窥谷忘反——同“返”，返回"],"a":"B","e":"“奔”动词作名词，指“飞奔的马”，不是“奔跑”。","tag":"字词释义"},{"s":"下列最能概括“鸢飞戾天者，望峰息心；经纶世务者，窥谷忘反”所表达思想感情的一项是？","o":["热爱自然、避世退隐、鄙弃功名利禄","对山水美景的喜爱与留恋","对隐居生活的向往","赞美富春江山水之美"],"a":"A","e":"这两句由写景转入抒情议论，表达作者热爱自然、避世退隐、鄙弃功名利禄的思想感情。","tag":"内容理解"}],"jd":[{"o":"风烟俱净，天山共色。从流飘荡，任意东西。","t":"风停雾散，天空与山峦同呈青苍之色。（我乘船）随水流飘荡，任凭船儿向东或向西漂行。","notes":[["俱","全，都"],["净","消散，散尽"],["东西","名词作动词，向东向西漂行"]]},{"o":"自富阳至桐庐一百许里，奇山异水，天下独绝。","t":"从富阳到桐庐一百多里，奇山异水，是天下独一无二的景致。","notes":[["许","左右，约"],["独","独一无二"],["绝","绝妙"]]},{"o":"水皆缥碧，千丈见底。游鱼细石，直视无碍。","t":"江水都是浅青色，千丈之深也能见底。游动的鱼和细小的石子，径直看下去毫无障碍。","notes":[["缥碧","浅青色"],["直视","径直看下去"],["碍","障碍"]]},{"o":"急湍甚箭，猛浪若奔。","t":"湍急的水流比箭还快，凶猛的巨浪如飞奔的骏马。","notes":[["甚","超过，胜过"],["若","像，如同"],["奔","飞奔的马（动词作名词）"]]},{"o":"夹岸高山，皆生寒树，负势竞上，互相轩邈，争高直指，千百成峰。","t":"两岸高山都生长着密而绿的树，山峦凭借地势争着向上，仿佛都在争着往高处远处伸展，争相比高，直插云天，形成千百座山峰。","notes":[["夹岸","两岸"],["寒树","耐寒常绿的树"],["竞","争相"],["轩邈","向高处、远处伸展（形容词作动词）"],["直指","笔直地向上"]]},{"o":"泉水激石，泠泠作响；好鸟相鸣，嘤嘤成韵。","t":"泉水冲击石头，发出清越的声响；美丽的鸟儿相互和鸣，鸣声和谐动听。","notes":[["激","冲击"],["泠泠","清脆的水声"],["相鸣","互相和鸣"],["成韵","和谐动听"]]},{"o":"蝉则千转不穷，猿则百叫无绝。","t":"蝉长久不停地叫，猿猴的啼叫也持续不断。","notes":[["转","同“啭”，婉转鸣叫"],["穷","穷尽"],["绝","停止，断绝"]]},{"o":"鸢飞戾天者，望峰息心；经纶世务者，窥谷忘反。","t":"极力追求名利的人，望见山峰便平息野心；治理国家大事的人，看见山谷就流连忘返。","notes":[["戾","至，到达"],["息","平息"],["经纶","治理"],["反","同“返”，返回"]]},{"o":"横柯上蔽，在昼犹昏；疏条交映，有时见日。","t":"横斜的树枝在上遮蔽，白天犹如黄昏；稀疏的枝条交错掩映，有时能见到阳光。","notes":[["柯","树枝"],["上","名词作状语，在上方"],["犹","仍然，好像"],["交映","交错掩映"]]}]},{"no":40,"t":"周亚夫军细柳","src":"部编版八年级上册·[西汉]司马迁","tag":"八年级上册","html":true,"p":["文帝之后六年，匈奴大入边。<u>乃</u>以宗正<small>〔宗正〕掌管皇族事务的官员。</small>刘礼为将军，<u>军</u>霸上；祝兹侯<small>〔祝兹侯〕封号。</small>徐厉为将军，军棘门；以河内守亚夫为将军，军细柳：<u>以</u>备胡。","上自<u>劳</u>军。至霸上及棘门军，直驰入，将以<u>下骑</u>送迎。<u>已而</u><u>之</u>细柳军，军士吏<u>被</u>甲，<u>锐兵刃</u>，<u>彀(gòu)</u>弓弩，持满。天子<u>先驱</u>至，不得入。先驱曰：“天子<u>且</u>至！”军门都尉曰：“将军令曰‘军中闻将军令，不闻天子之诏’。”<u>居</u><u>无何</u>，上至，又不得入。","于是上乃<u>使</u><u>使</u>持节诏将军：“吾欲入劳军。”亚夫<u>乃</u>传言开壁门。壁门士吏<u>谓</u>从属车骑曰：“将军约，军中不得驱驰。”于是天子乃按辔徐行。至营，将军亚夫持兵曰：“<u>介</u>胄之士不拜，请以军礼见。”天子为<u>动</u>，改容<u>式车</u>。使人<u>称谢</u>：“皇帝敬劳将军。”成礼而<u>去</u>。","<u>既</u>出军门，群臣皆惊。文帝曰：“嗟乎，此真将军矣！<u>曩</u>者霸上、棘门军，<u>若</u>儿戏耳，其将<u>固</u>可袭而虏也。至于亚夫，可得而犯邪！”称善者久<u>之</u>。"],"common":"","q":[{"s":"“<em class='k'>乃</em>以宗正刘礼为将军”中“<em class='k'>乃</em>”的意思是？","o":["于是，就","才","竟然","却"],"a":"A","e":"“乃”意为“于是、就”。“乃以宗正刘礼为将军”即于是任命宗正刘礼为将军。","tag":"字词释义"},{"s":"“<em class='k'>军</em>霸上”中“<em class='k'>军</em>”的活用和意思是？","o":["名词作动词，驻军","军队","军营","军事"],"a":"A","e":"“军”名词作动词，意为“驻军”。“军霸上”即驻军霸上。","tag":"字词释义"},{"s":"“<em class='k'>以</em>备胡”中“<em class='k'>以</em>”的意思是？","o":["来，用来","凭借","因为","认为"],"a":"A","e":"“以”意为“来、用来”。“以备胡”即用来防备匈奴。","tag":"字词释义"},{"s":"“上自<em class='k'>劳</em>军”中“<em class='k'>劳</em>”的意思是？","o":["慰劳","劳动","劳累","功劳"],"a":"A","e":"“劳”意为“慰劳”。“上自劳军”即皇上亲自慰劳军队。","tag":"字词释义"},{"s":"“将以<em class='k'>下骑</em>送迎”中“<em class='k'>下骑</em>”的意思是？","o":["下马","骑马的人","骑兵","下车"],"a":"A","e":"“下骑”意为“下马”。“将以下骑送迎”即将军及其部下都下马迎送。","tag":"字词释义"},{"s":"“<em class='k'>已而</em>之细柳军”中“<em class='k'>已而</em>”的意思是？","o":["不久","已经","然后","很久"],"a":"A","e":"“已而”意为“不久”。","tag":"字词释义"},{"s":"“已而<em class='k'>之</em>细柳军”中“<em class='k'>之</em>”的意思是？","o":["到，往","的","代词","取消句子独立性"],"a":"A","e":"“之”是动词，意为“到、往”。“之细柳军”即到细柳军营。","tag":"字词释义"},{"s":"“军士吏<em class='k'>被</em>甲”中“<em class='k'>被</em>”的意思是？","o":["同“披”，穿着","被子","被动","背负"],"a":"A","e":"“被”同“披”，穿着。“军士吏被甲”即官兵都穿着铠甲。","tag":"字词释义"},{"s":"“<em class='k'>锐兵刃</em>”中“<em class='k'>锐</em>”的活用和意思是？","o":["形容词使动用法，使……锋利（刀出鞘）","锐利的兵器","精锐的部队","兵器锋利"],"a":"A","e":"“锐”形容词使动用法，“使……锋利”。“锐兵刃”即使刀刃锋利，即刀出鞘。","tag":"字词释义"},{"s":"“<em class='k'>彀(gòu)</em>弓弩”中“<em class='k'>彀</em>”的意思是？","o":["张开","弓箭","弓弦","拉满"],"a":"A","e":"“彀”意为“张开”。“彀弓弩”即张开弓弩。","tag":"字词释义"},{"s":"“天子<em class='k'>先驱</em>至”中“<em class='k'>先驱</em>”的意思是？","o":["先行引导的人员","先驱者","先头部队","前进"],"a":"A","e":"“先驱”指先行引导的人员。“天子先驱至”即天子的先行引导人员到了营前。","tag":"字词释义"},{"s":"“天子<em class='k'>且</em>至”中“<em class='k'>且</em>”的意思是？","o":["将要","并且","况且","尚且"],"a":"A","e":"“且”意为“将要”。“天子且至”即天子即将到来。","tag":"字词释义"},{"s":"“<em class='k'>居</em>无何”中“<em class='k'>居</em>”的意思是？","o":["经过，过了","居住","停留","占据"],"a":"A","e":"“居”意为“经过、过了”。“居无何”即过了不久。","tag":"字词释义"},{"s":"“居<em class='k'>无何</em>”中“<em class='k'>无何</em>”的意思是？","o":["不久","没有什么","没有原因","无论"],"a":"A","e":"“无何”意为“不久”。“居无何”即过了不久。","tag":"字词释义"},{"s":"“于是上乃<em class='k'>使</em>使持节诏将军”中第一个“<em class='k'>使</em>”的意思是？","o":["派遣","使者","使用","假如"],"a":"A","e":"第一个“使”是动词，意为“派遣”。","tag":"字词释义"},{"s":"“于是上乃使<em class='k'>使</em>持节诏将军”中第二个“<em class='k'>使</em>”的意思是？","o":["使者","派遣","使用","使命"],"a":"A","e":"第二个“使”是名词，意为“使者”。","tag":"字词释义"},{"s":"“亚夫<em class='k'>乃</em>传言开壁门”中“<em class='k'>乃</em>”的意思是？","o":["才","于是","竟然","却"],"a":"A","e":"“乃”意为“才”。“亚夫乃传言开壁门”即周亚夫这才传令打开营垒大门。","tag":"字词释义"},{"s":"“壁门士吏<em class='k'>谓</em>从属车骑曰”中“<em class='k'>谓</em>”的意思是？","o":["告诉，对……说","认为","叫做","称为"],"a":"A","e":"“谓”意为“告诉、对……说”。","tag":"字词释义"},{"s":"“<em class='k'>介</em>胄之士不拜”中“<em class='k'>介</em>”的活用和意思是？","o":["名词作动词，穿铠甲","介绍","间隔","铠甲（名词）"],"a":"A","e":"“介”名词作动词，意为“穿铠甲”。“介胄之士”即穿铠甲戴头盔的将士。","tag":"字词释义"},{"s":"“天子为<em class='k'>动</em>”中“<em class='k'>动</em>”的意思是？","o":["感动","行动","打动","变动"],"a":"A","e":"“动”意为“感动”。“天子为动”即天子被他感动（“为”表被动）。","tag":"字词释义"},{"s":"“改容<em class='k'>式车</em>”中“<em class='k'>式</em>”的意思是？","o":["同“轼”，车前横木，这里指扶轼致敬","乘车","车式","仪式"],"a":"A","e":"“式”同“轼”，车前横木，这里指扶轼致敬。“改容式车”即表情严肃，扶着车前横木表示敬意。","tag":"字词释义"},{"s":"“使人<em class='k'>称谢</em>”中“<em class='k'>称谢</em>”的意思是？","o":["致意，告知","感谢","称谢（今义）","谢罪"],"a":"A","e":"“称谢”意为“致意、告知”，是古今异义词。“使人称谢”即派人向周亚夫致意。","tag":"字词释义"},{"s":"“成礼而<em class='k'>去</em>”中“<em class='k'>去</em>”的意思是？","o":["离开","去除","过去","前往"],"a":"A","e":"“去”意为“离开”。“成礼而去”即完成礼仪后离去。","tag":"字词释义"},{"s":"“<em class='k'>既</em>出军门”中“<em class='k'>既</em>”的意思是？","o":["已经，……之后","既然","即使","立即"],"a":"A","e":"“既”意为“已经”。“既出军门”即出了军营大门之后。","tag":"字词释义"},{"s":"“<em class='k'>曩</em>者霸上、棘门军”中“<em class='k'>曩</em>”的意思是？","o":["先前，从前","囊","曾经","日后"],"a":"A","e":"“曩”意为“先前、从前”。“曩者”即先前。","tag":"字词释义"},{"s":"“<em class='k'>若</em>儿戏耳”中“<em class='k'>若</em>”的意思是？","o":["像，如同","如果","你","假如"],"a":"A","e":"“若”意为“像、如同”。“若儿戏耳”即就像儿戏一样。","tag":"字词释义"},{"s":"“其将<em class='k'>固</em>可袭而虏也”中“<em class='k'>固</em>”的意思是？","o":["一定，必","坚固","本来","顽固"],"a":"A","e":"“固”意为“一定、必”。“其将固可袭而虏也”即那里的将军必定会被袭击而俘获。","tag":"字词释义"},{"s":"“称善者久<em class='k'>之</em>”中“<em class='k'>之</em>”的意思是？","o":["音节助词，补足音节","的","代词","到"],"a":"A","e":"“之”是音节助词，用来补足音节。“称善者久之”即称赞了很久。","tag":"字词释义"},{"s":"下列加点字词类活用类型与“<em class='k'>军</em>细柳”相同的一项是？","o":["锐兵刃","介胄之士不拜","天子为动","按辔徐行"],"a":"B","e":"“军”名词作动词，驻军；“介胄”名词作动词，穿铠甲戴头盔，活用类型相同。A“锐”使动；C 被动句；D 无活用。","tag":"字词释义"},{"s":"下列对“军中闻将军令，不闻天子之诏”的翻译，准确的一项是？","o":["军营中听从将军的命令，不听从天子发布的诏令。","军营里听见将军下令，听不见天子的诏书。","在军队中只能听闻将军，不能听闻天子。","将军下令，天子的诏令不起作用。"],"a":"A","e":"“闻”为听从，“诏”为诏令。A 项翻译准确。","tag":"内容理解"},{"s":"下列翻译有误的一项是？","o":["居无何，上至，又不得入：过了不久，皇上驾到，也不能够进入军营。","将军约，军中不得驱驰：将军规定，军营中不可以策马疾驰。","介胄之士不拜，请以军礼见：穿戴盔甲的将士不行跪拜礼，请允许我用军礼参见。","天子为动：天子主动动身。"],"a":"D","e":"“天子为动”是被动句，意为“天子被他感动”，不是“主动动身”。","tag":"内容理解"},{"s":"下列朗读停顿划分正确的一项是？","o":["已而之细柳 / 军","军士吏 / 被甲，锐兵 / 刃","于是上 / 乃使使持节诏将军","称善者 / 久之"],"a":"D","e":"A“细柳军”不可拆；B“锐兵刃”不可拆；C 应在“于是”后停顿；D“称善者/久之”停顿正确。","tag":"断句"},{"s":"文章写霸上、棘门军营的作用是？","o":["体现三处军营防御力量各有特色","与细柳营形成对比，突出周亚夫治军严明","说明刘礼、徐厉两位将军毫无军事才能","交代匈奴入侵时汉朝全部边防部署"],"a":"B","e":"霸上、棘门营门大开、直驰而入，与细柳营军纪严明形成对比，突出周亚夫治军严明。","tag":"内容理解"},{"s":"下列说法不符合文意的一项是？","o":["细柳营士兵严守军令，即使天子到来也不随意放行","周亚夫面对汉文帝，坚持行军人礼仪，不卑不亢","群臣感到吃惊，是因为大家都认为周亚夫应当迎接皇帝","汉文帝内心不满周亚夫无礼，只是表面称赞他"],"a":"D","e":"汉文帝赞赏周亚夫（“此真将军矣”），并非“内心不满、表面称赞”。","tag":"内容理解"},{"s":"下列对周亚夫人物形象的概括，不准确的一项是？","o":["治军严格，军纪严明","坚守原则，刚正不阿","谄媚君主，讨好帝王","恪尽职守，不卑不亢"],"a":"C","e":"周亚夫治军严明、刚正不阿、不卑不亢，绝非“谄媚君主”。","tag":"内容理解"},{"s":"下列关于本文的理解，说法正确的一项是？","o":["周亚夫拒绝天子直接进军营，是以下犯上、目中无人","“被”“式”都是文中出现的通假字","霸上棘门军营守卫森严，外敌难以偷袭","本文主要通过大量心理描写塑造人物"],"a":"B","e":"“被”通“披”（穿着），“式”通“轼”（车前横木），都是通假字。B 项正确。","tag":"内容理解"}],"jd":[{"o":"文帝之后六年，匈奴大入边。乃以宗正刘礼为将军，军霸上；祝兹侯徐厉为将军，军棘门；以河内守亚夫为将军，军细柳：以备胡。","t":"汉文帝后元六年，匈奴大规模侵入汉朝边境。于是朝廷任命宗正刘礼为将军，驻军霸上；任命祝兹侯徐厉为将军，驻军棘门；任命河内郡郡守周亚夫为将军，驻军细柳：来防备匈奴侵扰。","notes":[["乃","于是，就"],["军","名词作动词，驻军"],["以","来，用来"]]},{"o":"上自劳军。至霸上及棘门军，直驰入，将以下骑送迎。","t":"文帝亲自去慰劳军队。到霸上和棘门的军营时，车马径直奔驰而入，将军及其部下都骑马迎送。","notes":[["劳","慰劳"],["下骑","下马"]]},{"o":"已而之细柳军，军士吏被甲，锐兵刃，彀弓弩，持满。","t":"不久来到细柳军营，只见官兵都穿着铠甲，刀剑出鞘，张开弓弩，拉满弓弦。","notes":[["已而","不久"],["之","到，往"],["被","同“披”，穿着"],["锐","使……锋利"],["彀","张开"]]},{"o":"天子先驱至，不得入。先驱曰：“天子且至！”军门都尉曰：“将军令曰‘军中闻将军令，不闻天子之诏’。”","t":"天子的先行引导人员到了营前，无法进入。先行官说：“天子即将到来！”军营的守卫军官说：“将军有令‘军中只听从将军的命令，不听从天子的诏令’。”","notes":[["先驱","先行引导的人员"],["且","将要"]]},{"o":"居无何，上至，又不得入。于是上乃使使持节诏将军：“吾欲入劳军。”亚夫乃传言开壁门。","t":"过了不久，文帝到了，也无法进入军营。于是文帝就派使者手持符节下诏令给周将军：“我想进入军营慰劳军队。”周亚夫这才传令打开营垒的大门。","notes":[["居","经过，过了"],["无何","不久"],["使（1）","派遣"],["使（2）","使者"],["乃","才"]]},{"o":"壁门士吏谓从属车骑曰：“将军约，军中不得驱驰。”于是天子乃按辔徐行。","t":"守卫营门的军官对随从车马队伍说：“将军规定，军营中不可以策马疾驰。”于是天子就控制着缰绳缓慢前行。","notes":[["谓","告诉，对……说"]]},{"o":"至营，将军亚夫持兵曰：“介胄之士不拜，请以军礼见。”天子为动，改容式车。","t":"到了军营中，将军周亚夫手持兵器拱手行礼说：“穿戴着盔甲的将领不行跪拜礼，请允许我用军礼参见陛下。”文帝被他感动，表情严肃起来，扶着车前横木俯下身子。","notes":[["介","名词作动词，穿铠甲"],["动","感动"],["式","同“轼”，扶轼致敬"]]},{"o":"使人称谢：“皇帝敬劳将军。”成礼而去。","t":"文帝派人向周亚夫致意：“皇帝敬重地慰劳将军。”完成劳军礼仪后离去。","notes":[["称谢","致意，告知"],["去","离开"]]},{"o":"既出军门，群臣皆惊。文帝曰：“嗟乎，此真将军矣！曩者霸上、棘门军，若儿戏耳，其将固可袭而虏也。至于亚夫，可得而犯邪！”称善者久之。","t":"出了细柳军营的大门后，群臣都很震惊。文帝感叹道：“啊！这才是真正的将军啊！先前霸上、棘门的军营，就像儿戏一样，那里的将军必定会被袭击而被俘获。至于周亚夫，怎么可能被侵犯呢！”文帝对他赞赏了很久。","notes":[["既","已经，……之后"],["曩","先前，从前"],["若","像，如同"],["固","一定，必"],["之","音节助词，补足音节"]]}]},{"no":41,"t":"富贵不能淫","src":"部编版八年级上册·[战国]孟子","tag":"八年级上册","html":true,"p":["景春<small>〔景春〕与孟子同时代的人，纵横家</small>曰：“公孙衍<small>〔公孙衍(yǎn)〕战国魏国人，纵横家</small>、张仪<small>〔张仪〕战国魏国人，纵横家</small>岂不<u>诚</u><u>大丈夫</u>哉？一怒<u>而</u>诸侯惧，安居而天下<u>熄</u>。”","孟子曰：“<u>是</u><u>焉</u><u>得</u>为大丈夫乎？子未学礼乎？丈夫之<u>冠</u>也，父<u>命</u>之；女子之嫁也，母命之，往送<u>之</u>门，<u>戒</u>之曰：‘往之<u>女</u>家，必敬必戒，无违<u>夫子</u>！’以顺为正者，妾妇之道也。”","居天下之<u>广居</u>，立天下之<u>正位</u>，行天下之<u>大道</u>。得志，与民<u>由</u>之；不得志，独行其道。富贵不能<u>淫</u>，贫贱不能<u>移</u>，威武不能<u>屈</u>。此之谓大丈夫。"],"common":"","q":[{"s":"“岂不<em class='k'>诚</em>大丈夫哉”中“<em class='k'>诚</em>”的意思是？","o":["真正，确实","诚心诚意","果真如此","忠厚老实"],"a":"A","e":"“诚”意为“真正、确实”。“岂不诚大丈夫哉”即难道不是真正的大丈夫吗？","tag":"字词释义"},{"s":"“岂不诚<em class='k'>大丈夫</em>哉”中“<em class='k'>大丈夫</em>”的意思是？","o":["有志气有节操的人","成年男子","大男人","丈夫"],"a":"A","e":"“大丈夫”指有志气、有节操、有作为的人。","tag":"字词释义"},{"s":"“一怒<em class='k'>而</em>诸侯惧”中“<em class='k'>而</em>”的意思是？","o":["表顺承，就，于是","表转折，却","表并列，并且","表修饰"],"a":"A","e":"“而”表顺承。“一怒而诸侯惧”即一发怒诸侯就害怕。","tag":"字词释义"},{"s":"“安居而天下<em class='k'>熄</em>”中“<em class='k'>熄</em>”的意思是？","o":["指战火停息，天下太平","熄灭","消灭","平息怒火"],"a":"A","e":"“熄”本义熄灭，这里指战火停息、天下太平。","tag":"字词释义"},{"s":"“<em class='k'>是</em>焉得为大丈夫乎”中“<em class='k'>是</em>”的意思是？","o":["这","是（判断词）","正确","于是"],"a":"A","e":"“是”是指示代词，意为“这”。","tag":"字词释义"},{"s":"“是<em class='k'>焉</em>得为大丈夫乎”中“<em class='k'>焉</em>”的意思是？","o":["怎么，哪里","于是，就","语气助词","在此，于此"],"a":"A","e":"“焉”是疑问代词，意为“怎么、哪里”。","tag":"字词释义"},{"s":"“是焉<em class='k'>得</em>为大丈夫乎”中“<em class='k'>得</em>”的意思是？","o":["能够","得到","得意","得以"],"a":"A","e":"“得”意为“能够”。","tag":"字词释义"},{"s":"“丈夫之<em class='k'>冠</em>也”中“<em class='k'>冠</em>”的读音和意思是？","o":["guàn，行冠礼（动词）","guān，帽子（名词）","guàn，冠军","guān，衣冠"],"a":"A","e":"“冠”读 guàn，动词，行冠礼。古代男子二十岁行冠礼表示成年。","tag":"字词释义"},{"s":"“父<em class='k'>命</em>之”中“<em class='k'>命</em>”的意思是？","o":["训导，教导","命令，使令","命运，运气","命名，取名"],"a":"A","e":"“命”此处意为“训导、教导”。“父命之”即父亲训导他。","tag":"字词释义"},{"s":"“往送<em class='k'>之</em>门”中“<em class='k'>之</em>”的意思是？","o":["到，往（动词）","的（助词）","代词，她","取消句子独立性"],"a":"A","e":"“往送之门”的“之”是动词，意为“到、往”。","tag":"字词释义"},{"s":"“<em class='k'>戒</em>之曰”中“<em class='k'>戒</em>”的意思是？","o":["告诫，叮嘱","警戒，防备","戒除，革除","戒备，提防"],"a":"A","e":"“戒”意为“告诫、叮嘱”。“戒之曰”即告诫她说。","tag":"字词释义"},{"s":"“往之<em class='k'>女</em>家”中“<em class='k'>女</em>”的意思是？","o":["同“汝”，你","女子","女儿","妇女"],"a":"A","e":"“女”同“汝”，你的。“往之女家”即到你的夫家去。","tag":"字词释义"},{"s":"“无违<em class='k'>夫子</em>”中“<em class='k'>夫子</em>”的意思是？","o":["丈夫","老师","对人的尊称","男子"],"a":"A","e":"“夫子”这里指丈夫。“无违夫子”即不要违背丈夫。","tag":"字词释义"},{"s":"“居天下之<em class='k'>广居</em>”中“<em class='k'>广居</em>”喻指？","o":["“仁”","宽广的住宅","广大的居所","天下"],"a":"A","e":"“广居”比喻“仁”，指仁的居所。","tag":"字词释义"},{"s":"“立天下之<em class='k'>正位</em>”中“<em class='k'>正位</em>”喻指？","o":["“礼”","端正的位置","正当地位","正确的座位"],"a":"A","e":"“正位”比喻“礼”。","tag":"字词释义"},{"s":"“行天下之<em class='k'>大道</em>”中“<em class='k'>大道</em>”喻指？","o":["“义”","宽阔的大路","大道理","正道"],"a":"A","e":"“大道”比喻“义”。","tag":"字词释义"},{"s":"“与民<em class='k'>由</em>之”中“<em class='k'>由</em>”的意思是？","o":["遵从，遵循","由于，因为","理由，缘故","自由自在"],"a":"A","e":"“由”意为“遵从、遵循”。“与民由之”即与百姓一同遵循大道。","tag":"字词释义"},{"s":"“贫贱不能<em class='k'>移</em>”中“<em class='k'>移</em>”的活用和意思是？","o":["使动，使……动摇","移动，挪动","迁移，转移","移交，转交"],"a":"A","e":"“移”使动用法，“使……改变、动摇”。贫贱不能使（他）改变操守。","tag":"字词释义"},{"s":"“威武不能<em class='k'>屈</em>”中“<em class='k'>屈</em>”的活用和意思是？","o":["使动，使……屈服","委屈，冤屈","弯曲，屈曲","理亏，理屈"],"a":"A","e":"“屈”使动用法，“使……屈服”。","tag":"字词释义"},{"s":"对“富贵不能淫”中“<em class='k'>淫</em>”的用法，解说得当的一项是？","o":["动词，放纵，古今词义一致，无活用","使动用法，使……惑乱、迷惑","名词，淫邪之事","形容词，荒淫的"],"a":"B","e":"“淫”是使动用法，“使……惑乱、迷惑”。富贵不能使（他）迷惑。B 项解说正确。","tag":"字词释义"},{"s":"下列对“一怒而诸侯惧，安居而天下熄”的翻译，正确的一项是？","o":["（他们）一发怒，诸侯就害怕；安定下来，天下的战火便停息。","一旦发怒，诸侯感到恐惧；安心居住，天下就熄灭了。","（他们）一发脾气，诸侯畏惧；居家过日子，天下太平消失。","一次发怒诸侯恐惧，安稳居住天下熄火。"],"a":"A","e":"“而”表顺承；“安居”指安定下来；“熄”指战火停息。A 项翻译准确。","tag":"内容理解"},{"s":"对“居天下之广居，立天下之正位，行天下之大道”的翻译，最准确的一项是？","o":["住进天下宽广的居所，站在天下端正的位置，走天下宽阔的大路。","住进宽敞房屋，坚守正当地位，行走宽阔道路。","（大丈夫应当）住进仁的居所，站在礼的位置，走义的道路。","居住在广阔之地，立身端正，行走在大道上。"],"a":"C","e":"“广居”“正位”“大道”分别喻指“仁”“礼”“义”，C 项译出比喻义，最准确。","tag":"内容理解"},{"s":"下列语句停顿划分正确的一项是？","o":["公孙衍、张仪岂不 / 诚大丈夫哉","是焉得 / 为大丈夫乎","居天下 / 之广居，立天下 / 之正位","富贵 / 不能淫，贫贱 / 不能移，威武 / 不能屈"],"a":"D","e":"“富贵”“贫贱”“威武”后停顿，主谓结构清晰：富贵不能淫，贫贱不能移，威武不能屈。","tag":"断句"},{"s":"景春认为公孙衍、张仪是大丈夫，理由是？","o":["他们坚守仁义，不被富贵迷惑","他们身居高位，坚守本心","他们一发怒，诸侯害怕；安静下来，天下太平","他们能够做到贫贱不能移，威武不能屈"],"a":"C","e":"景春认为他们能“一怒而诸侯惧，安居而天下熄”，凭威势左右天下，故称大丈夫。","tag":"内容理解"},{"s":"下列关于“大丈夫”标准的表述，不符合孟子观点的一项是？","o":["内心坚守仁、礼、义","得志时和百姓一同践行正道；不得志时独自坚守原则","富贵、贫贱、强权都无法改变内心操守","能够凭借自身威势左右诸侯，掌控天下局势"],"a":"D","e":"孟子恰恰否定“凭威势左右诸侯”，认为那只是“妾妇之道”，D 项与孟子观点相反。","tag":"内容理解"},{"s":"下列关于本文的说法，不正确的一项是？","o":["“广居”喻指“仁”，“正位”喻指“礼”，“大道”喻指“义”","文章先摆出景春观点，再反驳，提出自己的大丈夫标准","孟子认为公孙衍、张仪能够做到威武不能屈","文章运用类比论证，用女子出嫁遵从母命类比张仪等人顺从君主"],"a":"C","e":"孟子认为公孙衍、张仪只是“妾妇之道”，做不到“威武不能屈”，C 项说法错误。","tag":"内容理解"}],"jd":[{"o":"景春曰：“公孙衍、张仪岂不诚大丈夫哉？一怒而诸侯惧，安居而天下熄。”","t":"景春说：“公孙衍、张仪难道不是真正的大丈夫吗？他们一发怒，诸侯就恐惧；他们安静下来，天下战火就熄灭。”","notes":[["诚","真正，确实"],["大丈夫","有志气有节操的人"],["而","表顺承"],["熄","指战火停息，天下太平"]]},{"o":"孟子曰：“是焉得为大丈夫乎？子未学礼乎？","t":"孟子说：“这怎么能算大丈夫呢？你没学过礼吗？","notes":[["是","这"],["焉","怎么，哪里"],["得","能够"]]},{"o":"丈夫之冠也，父命之；女子之嫁也，母命之，往送之门，戒之曰：‘往之女家，必敬必戒，无违夫子！’","t":"男子行冠礼时，父亲训导他；女子出嫁时，母亲训导她，送到门口，告诫说：‘到了夫家，一定要恭敬谨慎，不要违背丈夫！’","notes":[["冠","行冠礼（guàn）"],["命","训导，教导"],["之","到，往"],["戒","告诫，叮嘱"],["女","同“汝”，你"],["夫子","丈夫"]]},{"o":"以顺为正者，妾妇之道也。","t":"把顺从当作正理，是妾妇的行为准则。","notes":[["以","把"],["正","正理"],["妾妇","泛指妇女"]]},{"o":"居天下之广居，立天下之正位，行天下之大道。","t":"居住在天下最宽广的住宅（仁）里，站立在天下最正确的位置（礼）上，行走在天下最光明的道路（义）上。","notes":[["广居","喻指“仁”"],["正位","喻指“礼”"],["大道","喻指“义”"]]},{"o":"得志，与民由之；不得志，独行其道。","t":"得志时，与百姓一同遵循大道；不得志时，独自坚守原则。","notes":[["由","遵从，遵循"],["独行","独自坚守"]]},{"o":"富贵不能淫，贫贱不能移，威武不能屈。此之谓大丈夫。","t":"富贵不能迷乱心性，贫贱不能改变操守，威武不能屈服意志。这才叫大丈夫。","notes":[["淫","使……惑乱"],["移","使……改变"],["屈","使……屈服"],["谓","叫做"]]}]},{"no":42,"t":"得道多助，失道寡助","src":"部编版八年级上册·[战国]孟子","tag":"八年级上册","html":true,"p":["天时不如地利，地利不如<u>人和</u>。三里之<u>城</u>，七里之<u>郭</u>，环<u>而</u>攻之<u>而</u>不胜。<u>夫</u>环而攻之，必有得天时者矣，<u>然而</u>不胜者，是天时不如地利也。","城非不高也，<u>池</u>非不深也，兵<u>革</u>非不坚利也，米粟非不多也，<u>委</u>而<u>去</u>之，是地利不如人和也。<u>故</u>曰：<u>域</u>民不以封疆之界，<u>固</u>国不<u>以</u>山溪之险，<u>威</u>天下不以兵革之利。","<u>得道</u>者多助，失道者寡助。寡助之<u>至</u>，<u>亲戚</u>畔之；多助之至，天下顺之。<u>以</u>天下之所顺，攻亲戚之所<u>畔</u>，故君子有不战，战必胜矣。"],"common":"","q":[{"s":"“地利不如<em class='k'>人和</em>”中“<em class='k'>人和</em>”的意思是？","o":["人心所向","人们和睦","友好相处","人心和顺"],"a":"A","e":"“人和”指人心所向、内部团结。","tag":"字词释义"},{"s":"“三里之<em class='k'>城</em>”中“<em class='k'>城</em>”的意思是？","o":["内城","城市","城墙","城外"],"a":"A","e":"“城”指内城。“三里之城”即方圆三里的内城。","tag":"字词释义"},{"s":"“七里之<em class='k'>郭</em>”中“<em class='k'>郭</em>”的意思是？","o":["外城","城郭","村庄","郊外"],"a":"A","e":"“郭”指外城。古时内城为“城”，外城为“郭”。","tag":"字词释义"},{"s":"“环<em class='k'>而</em>攻之”中“<em class='k'>而</em>”的意思是？","o":["表修饰，环绕着","表转折，却","表顺承，然后","表并列，并且"],"a":"A","e":"“而”表修饰，连接状语“环”和谓语“攻”，意为“环绕着进攻”。","tag":"字词释义"},{"s":"“<em class='k'>夫</em>环而攻之”中“<em class='k'>夫</em>”的意思是？","o":["发语词，无实义","丈夫，成年男子","指示代词，那","语气词，表感叹"],"a":"A","e":"“夫”是发语词，用于句首，表示将要发表议论，无实义。","tag":"字词释义"},{"s":"“<em class='k'>然而</em>不胜者”中“<em class='k'>然而</em>”的意思是？","o":["这样却","然而（今义）","然后","但是"],"a":"A","e":"“然而”是“然”和“而”连用，“然”指“这样”，“而”表转折，意为“这样却”。","tag":"字词释义"},{"s":"“三里之城，七里之郭，环而攻之而不胜”运用了什么论证方法？","o":["举例论证","道理论证","对比论证","比喻论证"],"a":"A","e":"举攻城不胜的事例来证明“天时不如地利”，是举例论证。","tag":"论证方法"},{"s":"“<em class='k'>池</em>非不深也”中“<em class='k'>池</em>”的意思是？","o":["护城河","池塘","水池","城池"],"a":"A","e":"“池”指护城河。“池非不深”即护城河并非不深。","tag":"字词释义"},{"s":"“兵<em class='k'>革</em>非不坚利也”中“<em class='k'>革</em>”的意思是？","o":["皮革制的甲","皮革","改革","革除"],"a":"A","e":"“革”指皮革制的甲。“兵革”泛指武器装备。","tag":"字词释义"},{"s":"“<em class='k'>委</em>而去之”中“<em class='k'>委</em>”的意思是？","o":["放弃","委托","委屈","推卸"],"a":"A","e":"“委”意为“放弃”。“委而去之”即弃城而逃。","tag":"字词释义"},{"s":"“<em class='k'>域</em>民不以封疆之界”中“<em class='k'>域</em>”的活用和意思是？","o":["限制（名作动）","划分疆域界限","划定区域范围","圈定领域范围"],"a":"A","e":"“域”名词作动词，意为“限制”。“域民”即限制人民（使人民定居）。","tag":"字词释义"},{"s":"“<em class='k'>固</em>国不以山溪之险”中“<em class='k'>固</em>”的活用和意思是？","o":["使……巩固","坚固，牢固","本来，原来","顽固，固执"],"a":"A","e":"“固”使动用法，“使……巩固”。“固国”即巩固国防。","tag":"字词释义"},{"s":"“固国不<em class='k'>以</em>山溪之险”中“<em class='k'>以</em>”的意思是？","o":["凭借，依靠","因为，由于","所以，因此","以为，认为"],"a":"A","e":"“以”意为“凭借、依靠”。巩固国防不靠山溪的险阻。","tag":"字词释义"},{"s":"“<em class='k'>威</em>天下不以兵革之利”中“<em class='k'>威</em>”的活用和意思是？","o":["威慑（形容词作动词）","威风凛凛的气势","强大威猛的力量","威严庄重的仪态"],"a":"A","e":"“威”形容词作动词，意为“威慑”。“威天下”即威慑天下。","tag":"字词释义"},{"s":"“<em class='k'>得道</em>者多助”中“<em class='k'>得道</em>”的意思是？","o":["施行仁政","得到方法","获得道理","走对路"],"a":"A","e":"“得道”指施行仁政。“得道者”即施行仁政的君主。","tag":"字词释义"},{"s":"“寡助之<em class='k'>至</em>”中“<em class='k'>至</em>”的意思是？","o":["极点","到达","至于","到来"],"a":"A","e":"“至”意为“极点”。“寡助之至”即少助到了极点。","tag":"字词释义"},{"s":"“<em class='k'>亲戚</em>畔之”中“<em class='k'>亲戚</em>”的意思是？","o":["内外亲属","亲戚朋友","有血缘的亲人","同宗族的族人"],"a":"A","e":"“亲戚”古义指内外亲属，今义指跟自己家庭有婚姻或血统关系的人，属古今异义。","tag":"字词释义"},{"s":"“亲戚<em class='k'>畔</em>之”中“<em class='k'>畔</em>”的意思是？","o":["同“叛”，背叛","田畔，田界","旁边，近旁","陪伴，伴随"],"a":"A","e":"“畔”同“叛”，背叛。“亲戚畔之”即内外亲属都背叛他。","tag":"字词释义"},{"s":"“<em class='k'>以</em>天下之所顺”中“<em class='k'>以</em>”的意思是？","o":["用（凭借）","被（表被动）","把（表处置）","于（表处所）"],"a":"A","e":"“以”意为“用、凭借”。“以天下之所顺”即用天下归顺的力量。","tag":"字词释义"},{"s":"下列对“寡助之至，亲戚畔之；多助之至，天下顺之”的翻译，正确的一项是？","o":["少助到极点，内外亲属都背叛他；多助到极点，天下百姓都归顺他。","少助的人到了，亲戚朋友背叛他；多助的人到了，天下人顺从他。","少助到了极点，亲戚都背叛；多助到了极点，天下人顺利。","缺少帮助的人来了，亲戚背叛他；帮助多的人来了，天下归顺。"],"a":"A","e":"“至”为极点，“亲戚”指内外亲属，“畔”同“叛”，“顺”为归顺。A 项翻译准确。","tag":"内容理解"},{"s":"下列加点词解释有误的一项是？","o":["池非不深也——护城河","委而去之——放弃","亲戚畔之——亲戚朋友","寡助之至——极点"],"a":"C","e":"“亲戚畔之”的“亲戚”应解释为古义“内外亲属”，不是今义“亲戚朋友”。","tag":"字词释义"},{"s":"下列关于本文论点的说法，正确的一项是？","o":["本文中心论点就是开篇提出的“得道者多助，失道寡助”","“天时不如地利，地利不如人和”是中心论点，推导出“得道多助”的结论","开篇即提出“得道者多助，失道寡助”，再用战争事例来证明","结尾“寡助之至，亲戚畔之；多助之至，天下顺之”两句是全文中心论点"],"a":"B","e":"本文开篇提出中心论点“天时不如地利，地利不如人和”，经论证后推导出核心结论“得道者多助，失道寡助”。","tag":"内容理解"},{"s":"“寡助之至，亲戚畔之；多助之至，天下顺之”运用了哪种论证方法？","o":["对比论证","举例论证","道理论证","比喻论证"],"a":"A","e":"将“寡助”“多助”两种后果相对照，是对比论证，突出“得道”的重要性。","tag":"论证方法"},{"s":"下列对文章内容的理解，有误的一项是？","o":["“得道”指君主施行仁政","“失道寡助”从反面论证人心的重要性","文章认为作战时地利的作用大于人和","“亲戚畔之”是内外亲属背叛君主，是寡助的极致表现"],"a":"C","e":"文章通过攻城、守城事例层层论证，最终推出“人和”最重要，认为人和的作用大于天时、地利，C 项说法与文意相反。","tag":"内容理解"},{"s":"下列对文章论证层次的梳理，正确的一项是？","o":["提出论点→举守城事例→举攻城事例→治国道理→得出结论","提出论点→举攻城事例→举守城事例→类推治国→得出结论","先提出“得道多助”→举战争例子→层层论证中心论点","由治国道理说起，再用战争事例佐证"],"a":"B","e":"文章先提出中心论点，再用攻城事例论证“天时不如地利”，用守城事例论证“地利不如人和”，进而类推治国之道，最后得出结论。","tag":"论证思路"},{"s":"本文的论证结构是？","o":["总分总：先总提论点，再分层论证，后归纳结论","并列式：各层平行论述，地位平等，不分主次","递进式：层层深入，环环相扣，逐层推进","总分式：先总说再分说，结尾不做归纳总结"],"a":"A","e":"开篇提出“天时不如地利，地利不如人和”的中心论点，中间分层论证，结尾归纳出“得道者多助”的结论，是总分总结构。","tag":"论证思路"}],"jd":[{"o":"天时不如地利，地利不如人和。","t":"有利于作战的天气时令，比不上有利于作战的地理形势；有利于作战的地理形势，比不上人心所向、内部团结。","notes":[["天时","有利于作战的天气时令"],["地利","有利于作战的地理形势"],["人和","人心所向，内部团结"]]},{"o":"三里之城，七里之郭，环而攻之而不胜。","t":"方圆三里的内城，方圆七里的外城，包围进攻却不能取胜。","notes":[["城","内城"],["郭","外城"],["环","包围"],["而","表修饰"]]},{"o":"夫环而攻之，必有得天时者矣，然而不胜者，是天时不如地利也。","t":"既然包围进攻，必定有得天时的条件，却不能取胜，这说明天时不如地利。","notes":[["夫","发语词"],["然而","这样却"]]},{"o":"城非不高也，池非不深也，兵革非不坚利也，米粟非不多也，委而去之，是地利不如人和也。","t":"城墙并非不高，护城河并非不深，武器装备并非不精良，粮食并非不多，但（守城者）弃城而逃，这说明地利不如人和。","notes":[["池","护城河"],["兵革","武器装备"],["委","放弃"],["去","离开"]]},{"o":"故曰：域民不以封疆之界，固国不以山溪之险，威天下不以兵革之利。","t":"所以说：使人民定居不应靠疆界限制，巩固国防不应靠山溪险阻，威慑天下不应靠武器锋利。","notes":[["域","名词作动词，限制"],["以","凭借，依靠"],["固","使……巩固"],["威","威慑"]]},{"o":"得道者多助，失道者寡助。寡助之至，亲戚畔之；多助之至，天下顺之。","t":"施行仁政者得众多支持，不行仁政者少人支持。少助到极点，内外亲属皆背叛；多助到极点，天下百姓都归顺。","notes":[["得道","施行仁政"],["至","极点"],["亲戚","内外亲属"],["畔","同“叛”，背叛"],["顺","归顺"]]},{"o":"以天下之所顺，攻亲戚之所畔，故君子有不战，战必胜矣。","t":"以天下归顺之力，攻亲属背叛之敌，所以君子不战则已，战则必胜。","notes":[["以","用，凭借"],["故","所以"]]}]},{"no":43,"t":"愚公移山","src":"部编版八年级上册·《列子》","tag":"八年级上册","html":true,"p":["太行、王屋二山，<u>方</u>七百里，高万<u>仞</u>，本在冀州之南，河阳之北。北山愚公者，年<u>且</u>九十，面山<u>而</u>居。<u>惩</u>山北之塞，出入之<u>迂</u>也，聚室而谋曰：“吾与汝<u>毕力</u>平险，<u>指</u>通豫南，达于汉<u>阴</u>，可乎？”<u>杂然</u>相许。其妻献疑曰：“以君之力，<u>曾</u>不能损魁父之丘，<u>如太行、王屋何</u>？且<u>焉</u>置土石？”杂曰：“投<u>诸</u>渤海之尾，隐土之北。”<u>遂</u>率子孙<u>荷</u>担者三夫，<u>叩</u>石垦壤，<u>箕畚</u>运于渤海之尾。邻人京城氏之<u>孀妻</u>有遗男，始<u>龀</u>，跳往助之。寒暑<u>易</u>节，<u>始</u>一<u>反</u>焉。","河曲智叟笑而止之曰：“甚矣，汝<u>之</u>不<u>惠</u>！以残年余力，曾不能毁山之一毛，<u>其</u>如土石何？”北山愚公长息曰：“汝心之<u>固</u>，固不可<u>彻</u>，曾<u>不若</u>孀妻弱子。<u>虽</u>我之死，有子存<u>焉</u>。子又生孙，孙又生子；子又有子，子又有孙；子子孙孙无穷匮也，而山不加增，何<u>苦</u>而不平？”河曲智叟<u>亡</u>以应。","操蛇之神<small>〔操蛇之神〕手里拿着蛇的神。操，持。</small>闻之，惧其不已也，告之于帝。帝感其诚，命夸娥氏<small>〔夸娥氏〕神话中的大力神。</small>二子负二山，一<u>厝</u>朔东<small>〔朔东〕朔方东部，今山西北部一带。朔，朔方，今内蒙古自治区南部一带。</small>，一厝雍南。自此，冀之南，汉之阴，无<u>陇</u>断焉。"],"common":"","q":[{"s":"“太行、王屋二山，<em class='k'>方</em>七百里”中“<em class='k'>方</em>”的意思是？","o":["方圆，纵横","方向","方法","正在"],"a":"A","e":"“方”意为“方圆、纵横”。“方七百里”指纵横七百里。","tag":"字词释义"},{"s":"“高万<em class='k'>仞</em>”中“<em class='k'>仞</em>”的意思是？","o":["古代长度单位，七尺或八尺为一仞","千仞","刀刃","认"],"a":"A","e":"“仞”是古代长度单位，七尺或八尺为一仞。“高万仞”极言其高。","tag":"字词释义"},{"s":"“年<em class='k'>且</em>九十”中“<em class='k'>且</em>”的意思是？","o":["将近","并且","况且","尚且"],"a":"A","e":"“且”意为“将近”。“年且九十”即年纪将近九十岁。","tag":"字词释义"},{"s":"“面山<em class='k'>而</em>居”中“<em class='k'>而</em>”的意思是？","o":["表修饰","表转折","表顺承","表并列"],"a":"A","e":"“而”表修饰，“面山而居”即面对着山居住。","tag":"字词释义"},{"s":"“<em class='k'>惩</em>山北之塞”中“<em class='k'>惩</em>”的意思是？","o":["苦于","惩罚","惩戒","戒备"],"a":"A","e":"“惩”意为“苦于”。“惩山北之塞”即苦于山北道路阻塞。","tag":"字词释义"},{"s":"“出入之<em class='k'>迂</em>也”中“<em class='k'>迂</em>”的意思是？","o":["曲折，绕远","迂腐","迂回","迟缓"],"a":"A","e":"“迂”意为“曲折、绕远”。“出入之迂”即进出都要绕远路。","tag":"字词释义"},{"s":"“吾与汝<em class='k'>毕力</em>平险”中“<em class='k'>毕力</em>”的意思是？","o":["用尽力气，竭尽全力","完毕","全部力量","最终"],"a":"A","e":"“毕力”意为“用尽力气”。“毕”是尽、竭尽。","tag":"字词释义"},{"s":"“<em class='k'>指</em>通豫南”中“<em class='k'>指</em>”的意思是？","o":["一直，直","手指","指向","指使"],"a":"A","e":"“指”意为“一直、直”。“指通豫南”即一直通向豫州南部。","tag":"字词释义"},{"s":"“达于汉<em class='k'>阴</em>”中“<em class='k'>阴</em>”的意思是？","o":["水的南岸","阴天","阴冷","阴影"],"a":"A","e":"“阴”指水的南岸。古代称山之北、水之南为阴。“汉阴”即汉水南岸。","tag":"字词释义"},{"s":"“<em class='k'>杂然</em>相许”中“<em class='k'>杂然</em>”的意思是？","o":["纷纷地","杂乱","混杂","纷杂"],"a":"A","e":"“杂然”意为“纷纷地”。“杂然相许”即大家纷纷表示赞同。","tag":"字词释义"},{"s":"“<em class='k'>曾</em>不能损魁父之丘”中“<em class='k'>曾</em>”的意思是？","o":["连……都（表强调）","曾经","不曾","竟然"],"a":"A","e":"“曾”意为“连……都”，表强调。“曾不能损魁父之丘”即连魁父这样的小山丘都不能削减。","tag":"字词释义"},{"s":"“<em class='k'>如太行、王屋何</em>”中“如……何”的意思是？","o":["把……怎么样","像……什么","如果……怎么办","如何"],"a":"A","e":"“如……何”意为“把……怎么样”。“如太行、王屋何”即能把太行、王屋两座大山怎么样呢？","tag":"字词释义"},{"s":"“且<em class='k'>焉</em>置土石”中“<em class='k'>焉</em>”的意思是？","o":["哪里","于此","语气词","怎么"],"a":"A","e":"“焉”意为“哪里”。“且焉置土石”即况且把土石放到哪里去呢？","tag":"字词释义"},{"s":"“投<em class='k'>诸</em>渤海之尾”中“<em class='k'>诸</em>”的意思是？","o":["兼词，“之于”","众多","诸位","各种"],"a":"A","e":"“诸”是兼词，为“之于”的合音。“投诸渤海之尾”即把它扔到渤海边上。","tag":"字词释义"},{"s":"“<em class='k'>遂</em>率子孙”中“<em class='k'>遂</em>”的意思是？","o":["于是，就","成功","顺利","完成"],"a":"A","e":"“遂”意为“于是、就”。","tag":"字词释义"},{"s":"“子孙<em class='k'>荷</em>担者三夫”中“<em class='k'>荷</em>”的意思是？","o":["肩负，挑","荷花","负荷","感谢"],"a":"A","e":"“荷”意为“肩负、挑”。“荷担者三夫”即能挑担子的三个人。","tag":"字词释义"},{"s":"“<em class='k'>叩</em>石垦壤”中“<em class='k'>叩</em>”的意思是？","o":["敲，打","叩头","扣留","询问"],"a":"A","e":"“叩”意为“敲、打”。“叩石垦壤”即敲石头挖泥土。","tag":"字词释义"},{"s":"“<em class='k'>箕畚</em>运于渤海之尾”中“<em class='k'>箕畚</em>”的活用和意思是？","o":["名词作状语，用箕畚","箕畚（名词）","扫帚","搬运"],"a":"A","e":"“箕畚”名词作状语，意为“用箕畚”。","tag":"字词释义"},{"s":"“邻人京城氏之<em class='k'>孀妻</em>”中“<em class='k'>孀妻</em>”的意思是？","o":["寡妇","双妻","独居女子","已婚女子"],"a":"A","e":"“孀妻”即寡妇。","tag":"字词释义"},{"s":"“始<em class='k'>龀</em>”中“<em class='k'>龀</em>”的意思是？","o":["换牙（指七八岁）","龋齿","牙齿","稚嫩"],"a":"A","e":"“龀”指换牙。“始龀”即刚换牙，指七八岁。","tag":"字词释义"},{"s":"“寒暑<em class='k'>易</em>节”中“<em class='k'>易</em>”的意思是？","o":["交换，变换","容易","改变","交易"],"a":"A","e":"“易”意为“交换、变换”。“寒暑易节”即冬夏换季。","tag":"字词释义"},{"s":"“<em class='k'>始</em>一反焉”中“<em class='k'>始</em>”的意思是？","o":["才","开始","起初","始终"],"a":"A","e":"“始”意为“才”。“始一反焉”即才往返一次。","tag":"字词释义"},{"s":"“始一<em class='k'>反</em>焉”中“<em class='k'>反</em>”的意思是？","o":["同“返”，往返","反对","反而","返回"],"a":"A","e":"“反”同“返”，往返。“始一反焉”即才往返一次。","tag":"字词释义"},{"s":"“汝<em class='k'>之</em>不惠”中“<em class='k'>之</em>”的意思是？","o":["取消句子独立性","的","代词","到"],"a":"A","e":"“汝之不惠”的“之”用于主谓之间，取消句子独立性。","tag":"字词释义"},{"s":"“汝之不<em class='k'>惠</em>”中“<em class='k'>惠</em>”的意思是？","o":["同“慧”，聪明","恩惠","贤惠","惠顾"],"a":"A","e":"“惠”同“慧”，聪明。“汝之不惠”即你太不聪明了。","tag":"字词释义"},{"s":"“<em class='k'>其</em>如土石何”中“<em class='k'>其</em>”的意思是？","o":["加强反问语气","他的","其中","大概"],"a":"A","e":"“其”用在“如……何”前，加强反问语气。“其如土石何”即又能把泥土石头怎么样呢？","tag":"字词释义"},{"s":"“汝心之<em class='k'>固</em>”中“<em class='k'>固</em>”的意思是？","o":["顽固","坚固","本来","巩固"],"a":"A","e":"“固”意为“顽固”。“汝心之固”即你的思想太顽固了。","tag":"字词释义"},{"s":"“固不可<em class='k'>彻</em>”中“<em class='k'>彻</em>”的意思是？","o":["通，变通","彻底","透彻","贯彻"],"a":"A","e":"“彻”意为“通、变通”。“固不可彻”即顽固到不可改变的地步。","tag":"字词释义"},{"s":"“曾<em class='k'>不若</em>孀妻弱子”中“<em class='k'>不若</em>”的意思是？","o":["不如，比不上","不像","若不是","不善"],"a":"A","e":"“不若”意为“不如、比不上”。“曾不若孀妻弱子”即连寡妇和小孩都比不上。","tag":"字词释义"},{"s":"“<em class='k'>虽</em>我之死”中“<em class='k'>虽</em>”的意思是？","o":["即使","虽然","虽然……但是","纵然"],"a":"A","e":"“虽”意为“即使”。“虽我之死，有子存焉”即即使我死了，还有儿子在。","tag":"字词释义"},{"s":"“有子存<em class='k'>焉</em>”中“<em class='k'>焉</em>”的意思是？","o":["语气词，了，啊","哪里","于此","怎么"],"a":"A","e":"“焉”是句末语气词，表陈述语气。“有子存焉”即还有儿子在啊。","tag":"字词释义"},{"s":"“何<em class='k'>苦</em>而不平”中“<em class='k'>苦</em>”的意思是？","o":["愁，担心","痛苦","辛苦","苦于"],"a":"A","e":"“苦”意为“愁、担心”。“何苦而不平”即还担心挖不平吗？","tag":"字词释义"},{"s":"“河曲智叟<em class='k'>亡</em>以应”中“<em class='k'>亡</em>”的意思是？","o":["同“无”，没有","死亡","灭亡","逃亡"],"a":"A","e":"“亡”同“无”，没有。“亡以应”即无话可答。","tag":"字词释义"},{"s":"“一<em class='k'>厝</em>朔东”中“<em class='k'>厝</em>”的意思是？","o":["放置，安放","处理","磨刀石","错过"],"a":"A","e":"“厝”意为“放置、安放”。“一厝朔东”即一座放在朔方东部。“厝”通“措”。","tag":"字词释义"},{"s":"“无<em class='k'>陇</em>断焉”中“<em class='k'>陇</em>”的意思是？","o":["同“垄”，山冈，高地","陇西","田地","丘陵"],"a":"A","e":"“陇”同“垄”，山冈、高地。“无陇断焉”即再也没有山冈阻隔了。","tag":"字词释义"},{"s":"对“毕力平险”中词语的用法，分析正确的一项是？","o":["险：动词，冒险","险：形容词作名词，险峻的大山","毕：名词，完毕","无词类活用现象"],"a":"B","e":"“险”形容词作名词，指险峻的大山；“毕”是“尽、用尽”。","tag":"字词释义"},{"s":"下列对“甚矣，汝之不惠”的翻译，准确的一项是？","o":["太过分了，你不懂得恩惠。","你太不聪明了！","严重啊，你不肯施舍。","你十分不贤惠。"],"a":"B","e":"“甚矣”表程度之深；“惠”同“慧”，聪明。“汝之不惠”即你太不聪明了。","tag":"内容理解"},{"s":"下列翻译有误的一项是？","o":["惩山北之塞，出入之迂也：苦于山北路途阻塞，出来进去都要绕远。","指通豫南，达于汉阴：一直通向豫州南部，到达汉水南岸。","子子孙孙无穷匮也，而山不加增，何苦而不平：子子孙孙无穷无尽，可是山不会增高加大，还担心挖不平吗？","帝感其诚：天帝感受到他的诚实。"],"a":"D","e":"“帝感其诚”是被动句，应为“天帝被他的诚心感动”，不是“感受到他的诚实”。","tag":"内容理解"},{"s":"下列朗读停顿划分正确的一项是？","o":["邻人京城氏之孀妻 / 有遗男","遂率子孙荷担 / 者三夫","河曲智叟笑 / 而止之曰","命夸娥氏 / 二子负二山"],"a":"A","e":"B 应为“遂率子孙荷担者/三夫”（荷担者定语后置）；C 应为“河曲智叟/笑而止之曰”；D 应为“命/夸娥氏二子负二山”。A 停顿正确。","tag":"断句"},{"s":"愚公妻子“献疑”与智叟“笑而止之”的态度，分析正确的一项是？","o":["两人都坚决反对移山，想法完全一致","妻子提出疑问，是出于关心；智叟嘲讽、阻止，目光短浅","妻子认为没有地方放置土石，坚决阻止愚公","智叟认可愚公志向，只是担忧他力量不足"],"a":"B","e":"妻子“献疑”是出于关心，提出实际困难；智叟“笑而止之”是嘲讽阻止、目光短浅。","tag":"内容理解"},{"s":"文中设置“操蛇之神”“天帝移山”的神话结尾，作用是？","o":["说明依靠人力无法移山，必须依靠神灵","增添神话色彩，寄托古人征服自然的愿望，突出愚公精神感动天地","证明古代山神可以随意移动大山","体现愚公自身能力不足以战胜大山"],"a":"B","e":"神话结尾寄托古人征服自然的愿望，突出愚公坚持不懈的精神感动天地，并非宣扬迷信。","tag":"内容理解"},{"s":"下列对文章内涵的理解，正确的一项是？","o":["本文告诉我们遇到困难，可以等待神灵帮助","只要持之以恒，持续奋斗，终能战胜艰难险阻","人力永远无法改变自然，只能被动顺从","做事不需要听取任何人的质疑与建议"],"a":"B","e":"本文赞颂持之以恒、艰苦奋斗的精神，说明只要坚持不懈就能战胜艰难险阻。","tag":"内容理解"}],"jd":[{"o":"太行、王屋二山，方七百里，高万仞，本在冀州之南，河阳之北。","t":"太行、王屋两座大山，纵横七百里，高数万仞，原本坐落在冀州的南部，河阳的北部。","notes":[["方","方圆，纵横"],["仞","古代长度单位"]]},{"o":"北山愚公者，年且九十，面山而居。惩山北之塞，出入之迂也，聚室而谋曰：“吾与汝毕力平险，指通豫南，达于汉阴，可乎？”","t":"北山有位名叫愚公的老人，年纪将近九十岁，面对着大山居住。他苦于山北道路阻塞，进出都要绕远路，于是召集全家商量说：“我和你们尽全力铲除这险峻的大山，直通向豫州南部，到达汉水南岸，好吗？”","notes":[["且","将近"],["而","表修饰"],["惩","苦于"],["迂","曲折，绕远"],["毕力","用尽力气"],["指","一直，直"],["阴","水的南岸"]]},{"o":"杂然相许。其妻献疑曰：“以君之力，曾不能损魁父之丘，如太行、王屋何？且焉置土石？”","t":"大家纷纷表示赞同。他的妻子提出疑问说：“凭您的力气，连魁父这样的小山丘都不能削减，又能把太行、王屋两座大山怎么样呢？况且把土石放到哪里去呢？”","notes":[["杂然","纷纷地"],["曾","连……都"],["如……何","把……怎么样"],["焉","哪里"]]},{"o":"杂曰：“投诸渤海之尾，隐土之北。”遂率子孙荷担者三夫，叩石垦壤，箕畚运于渤海之尾。","t":"众人纷纷说：“把它们扔到渤海的边上，隐土的北面。”于是愚公率领三个能挑担子的子孙，敲石头、挖泥土，用箕畚装着运到渤海的边上。","notes":[["诸","兼词，“之于”"],["遂","于是，就"],["荷","肩负，挑"],["叩","敲，打"],["箕畚","名词作状语，用箕畚"]]},{"o":"邻人京城氏之孀妻有遗男，始龀，跳往助之。寒暑易节，始一反焉。","t":"邻居姓京城的寡妇有个孤儿，刚七八岁，蹦蹦跳跳地去帮助他们。冬夏换季，才往返一次。","notes":[["孀妻","寡妇"],["龀","换牙（指七八岁）"],["易","交换，变换"],["始","才"],["反","同“返”，往返"]]},{"o":"河曲智叟笑而止之曰：“甚矣，汝之不惠！以残年余力，曾不能毁山之一毛，其如土石何？”","t":"河曲的智叟嘲笑并阻止他说：“你太不聪明了！凭你老迈的年纪和残余的气力，连山上的一根草木都毁不了，又能把泥土石头怎么样呢？”","notes":[["之","取消句子独立性"],["惠","同“慧”，聪明"],["其","加强反问语气"]]},{"o":"北山愚公长息曰：“汝心之固，固不可彻，曾不若孀妻弱子。虽我之死，有子存焉。子又生孙，孙又生子；子又有子，子又有孙；子子孙孙无穷匮也，而山不加增，何苦而不平？”","t":"北山愚公长叹一声说：“你的思想太顽固了，顽固到不可改变的地步，连寡妇和小孩都比不上。即使我死了，还有儿子在；儿子又生孙子，孙子又生儿子；儿子又有儿子，儿子又有孙子；子子孙孙无穷无尽，而山不会再增高，还担心挖不平吗？”","notes":[["固","顽固"],["彻","通，变通"],["不若","不如，比不上"],["虽","即使"],["焉","语气词"],["苦","愁，担心"]]},{"o":"河曲智叟亡以应。","t":"河曲的智叟无话可答。","notes":[["亡","同“无”，没有"]]},{"o":"操蛇之神闻之，惧其不已也，告之于帝。帝感其诚，命夸娥氏二子负二山，一厝朔东，一厝雍南。自此，冀之南，汉之阴，无陇断焉。","t":"手里拿着蛇的山神听说了这件事，害怕愚公不停地干下去，就把这件事报告给天帝。天帝被愚公的诚心感动，命令大力神夸娥氏的两个儿子背走两座大山，一座放在朔方东部，一座放在雍州南部。从此以后，冀州的南部直到汉水的南岸，再也没有山冈阻隔了。","notes":[["厝","放置，安放"],["陇","同“垄”，山冈，高地"]]}]},{"no":44,"t":"生于忧患，死于安乐","src":"部编版八年级上册·[战国]孟子","tag":"八年级上册","html":true,"p":["舜<u>发</u>于畎亩<small>〔畎(quǎn)亩〕田地</small>之中，傅说<u>举</u>于版筑<small>〔版筑〕筑墙</small>之间，胶鬲举于鱼盐<small>〔鱼盐〕贩卖鱼盐的人</small>之中，管夷吾举于士<small>〔士〕狱官</small>，孙叔敖举于海<small>〔海〕海滨</small>，百里奚举于市<small>〔市〕集市</small>。<u>故</u>天将降大任于<u>是人</u>也，必先<u>苦</u>其心志，<u>劳</u>其筋骨，<u>饿</u>其体肤，<u>空乏</u><small>〔空乏(kōng fá)〕</small>其身，行<u>拂</u>乱其所为，所以动心忍性，<u>曾益</u>其所不能。","人<u>恒</u>过，<u>然后</u>能改；困于心，<u>衡</u>于虑，而后<u>作</u>；<u>征</u>于色，发于声，而后<u>喻</u>。<u>入</u>则无<u>法家</u><u>拂士</u>，<u>出</u>则无<u>敌</u>国外患者，国恒亡。然后知生于忧患而死于安乐也。"],"common":"","q":[{"s":"“舜<em class='k'>发</em>于畎亩之中”中“<em class='k'>发</em>”的意思是？","o":["兴起，被任用","出发","散发","发现"],"a":"A","e":"“发”意为“兴起、被任用”。舜从田野之中兴起。","tag":"字词释义"},{"s":"“傅说<em class='k'>举</em>于版筑之间”中“<em class='k'>举</em>”的意思是？","o":["被举用，被选拔","举起","推举","全，都"],"a":"A","e":"“举”意为“被举用、被选拔”。","tag":"字词释义"},{"s":"“<em class='k'>故</em>天将降大任于是人也”中“<em class='k'>故</em>”的意思是？","o":["所以","缘故","旧的","故意"],"a":"A","e":"“故”意为“所以”。","tag":"字词释义"},{"s":"“天将降大任于<em class='k'>是人</em>也”中“<em class='k'>是人</em>”的意思是？","o":["这样的人","这个国家","人民","人类"],"a":"A","e":"“是人”意为“这样的人”，指承担大任的人。","tag":"字词释义"},{"s":"“必先<em class='k'>苦</em>其心志”中“<em class='k'>苦</em>”的活用和意思是？","o":["使动用法，使……痛苦","痛苦","辛苦","苦难"],"a":"A","e":"“苦”使动用法，“使……痛苦”。","tag":"字词释义"},{"s":"“<em class='k'>劳</em>其筋骨”中“<em class='k'>劳</em>”的活用和意思是？","o":["使动用法，使……劳累","劳累","劳动","功劳"],"a":"A","e":"“劳”使动用法，“使……劳累”。","tag":"字词释义"},{"s":"“<em class='k'>饿</em>其体肤”中“<em class='k'>饿</em>”的活用和意思是？","o":["使动用法，使……饥饿","饥饿","挨饿","饿死"],"a":"A","e":"“饿”使动用法，“使……饥饿”。","tag":"字词释义"},{"s":"“<em class='k'>空乏</em>其身”中“<em class='k'>空乏</em>”的意思是？","o":["使……穷困（困乏）","空缺","贫穷","空虚"],"a":"A","e":"“空乏”意为“使……穷困、资财缺乏”。使他的身体穷困。","tag":"字词释义"},{"s":"“行<em class='k'>拂</em>乱其所为”中“<em class='k'>拂</em>”的意思是？","o":["违背，不顺","擦拭","拂晓","拂过"],"a":"A","e":"“拂”意为“违背、不顺”。“拂乱”即扰乱。","tag":"字词释义"},{"s":"“<em class='k'>曾</em>益其所不能”中“<em class='k'>曾</em>”的意思是？","o":["同“增”，增加","曾经","竟然","尚且"],"a":"A","e":"“曾”同“增”，增加。“曾益”即增加。","tag":"字词释义"},{"s":"“人<em class='k'>恒</em>过”中“<em class='k'>恒</em>”的意思是？","o":["常常","恒心","长久","永久"],"a":"A","e":"“恒”意为“常常”。“人恒过”即人常常犯错误。","tag":"字词释义"},{"s":"“<em class='k'>然后</em>能改”中“<em class='k'>然后</em>”的意思是？","o":["这样以后","然后（今义）","然而","以后"],"a":"A","e":"“然后”意为“这样以后”。","tag":"字词释义"},{"s":"“困于心，<em class='k'>衡</em>于虑”中“<em class='k'>衡</em>”的意思是？","o":["同“横”，梗塞，不顺","平衡","衡量","秤"],"a":"A","e":"“衡”同“横”，梗塞、不顺。“衡于虑”即思虑阻塞。","tag":"字词释义"},{"s":"“而后<em class='k'>作</em>”中“<em class='k'>作</em>”的意思是？","o":["奋起，指有所作为","作业","制作","发作"],"a":"A","e":"“作”意为“奋起”，这里指有所作为。","tag":"字词释义"},{"s":"“<em class='k'>征</em>于色”中“<em class='k'>征</em>”的意思是？","o":["征验，表现","征讨","征求","特征"],"a":"A","e":"“征”意为“征验、表现”。“征于色”即表现在脸色上。","tag":"字词释义"},{"s":"“而后<em class='k'>喻</em>”中“<em class='k'>喻</em>”的意思是？","o":["了解，明白","比喻","告知","晓喻"],"a":"A","e":"“喻”意为“了解、明白”。“而后喻”即而后才能被人理解。","tag":"字词释义"},{"s":"“<em class='k'>入</em>则无法家拂士”中“<em class='k'>入</em>”的意思是？","o":["在国内","进入","收入","进来"],"a":"A","e":"“入”与“出”相对，指“在国内”。","tag":"字词释义"},{"s":"“入则无<em class='k'>法家</em>拂士”中“<em class='k'>法家</em>”的意思是？","o":["守法度的大臣","法家学派","执法的官吏","法律"],"a":"A","e":"“法家”指守法度的大臣。","tag":"字词释义"},{"s":"“入则无法家<em class='k'>拂士</em>”中“<em class='k'>拂士</em>”的意思是？","o":["辅佐君主的贤士","拂拭兵器的士兵","有志之士","文人士子"],"a":"A","e":"“拂士”指辅佐君主的贤士。“拂”同“弼”，辅佐。","tag":"字词释义"},{"s":"“<em class='k'>出</em>则无敌国外患者”中“<em class='k'>出</em>”的意思是？","o":["在国外","出去","外出","出来"],"a":"A","e":"“出”指“在国外”，与“入”（在国内）相对。","tag":"字词释义"},{"s":"“出则无<em class='k'>敌</em>国外患者”中“<em class='k'>敌</em>”的意思是？","o":["匹敌，相当","敌人","敌对","抵抗"],"a":"A","e":"“敌”意为“匹敌、相当”，指势力相当。“敌国外患”指势力相当的外国侵犯的忧患。","tag":"字词释义"},{"s":"对“所以动心忍性”中加点词的用法，解说得当的一项是？","o":["动：动词，震动；忍：忍耐，无活用","动：使动，使……震撼；忍：使动，使……坚忍","动：名词，活动；忍：形容词，坚韧","动、忍均为意动用法"],"a":"B","e":"“动”“忍”都是使动用法：“使……震撼”“使……坚忍”。","tag":"字词释义"},{"s":"下列对“故天将降大任于是人也”的翻译，正确的一项是？","o":["所以上天将要降临重大使命给这样的人。","因此上天将要下达重要任务于是这个人。","所以上天降低重任给这个人。","因此上天将要托付大任认同这个人。"],"a":"A","e":"“故”为所以，“大任”为重大使命，“于是人”为“给这样的人”。A 项翻译准确。","tag":"内容理解"},{"s":"下列语句停顿划分正确的一项是？","o":["舜发于畎 / 亩之中","故天将降大任 / 于是人也","困于心衡 / 于虑而后作","入则无 / 法家拂士"],"a":"D","e":"A 拆散“畎亩”；B 应在“故”后稍顿；C 应为“困于心/衡于虑”；D“入则无/法家拂士”停顿正确。","tag":"断句"},{"s":"文章开篇列举舜、傅说等六人的事例，作用是？","o":["证明出身底层的人更容易成功","作为事实论据，论证磨难能使人担当大任","说明古代君王都来自民间","对比安逸环境使人堕落"],"a":"B","e":"六人都是出身微贱而终担大任，作为事实论据论证“磨难能使人担当大任”。","tag":"论证方法"},{"s":"下列对文章内容的理解，不符合文意的一项是？","o":["人才想要成才，需要经受肉体、精神多方面磨难","人犯错之后，只要自我反省，就一定能够成功","国家长久安定，既需要国内贤臣，也需要外部对手的警醒","文章从个人成才推及国家治理，由小到大论证观点"],"a":"B","e":"“人恒过，然后能改”强调犯错后能改正，但“只要反省就一定成功”说法过于绝对，不符合文意。","tag":"内容理解"},{"s":"下列关于本文的说法，不正确的一项是？","o":["“曾、衡、拂”都是本文出现的通假字","本文先举例，再说理，最后提炼中心论点","文章仅从正面论证忧患的价值","结尾“生于忧患，死于安乐”统领全篇"],"a":"C","e":"文章既从正面论证忧患使人成才，又从反面论证安乐导致亡国，“仅从正面”说法错误。","tag":"内容理解"},{"s":"下列对文章论证思路的分析，正确的一项是？","o":["先提出中心论点，再举事例证明","先列举事例，提炼人才造就的道理，再引申到治国，最后归纳论点","先谈论国家治理，再谈论个人成长","先反面论证安乐亡国，再正面论证忧患成才"],"a":"B","e":"文章先列举六人事例，提炼出“生于忧患”的道理，再引申到国家治理（入无法家拂士、出无敌国外患），最后归纳中心论点。","tag":"论证思路"}],"jd":[{"o":"舜发于畎亩之中，傅说举于版筑之间，胶鬲举于鱼盐之中，管夷吾举于士，孙叔敖举于海，百里奚举于市。","t":"舜从田野之中兴起，傅说从筑墙工匠中被举荐，胶鬲从鱼盐商贩中被选拔，管夷吾从狱官手里获释被任用，孙叔敖从海滨隐居处被征召，百里奚从集市上被赎买任用。","notes":[["发","兴起，被任用"],["举","被举用，被选拔"],["畎亩","田地"],["版筑","筑墙"]]},{"o":"故天将降大任于是人也，必先苦其心志，劳其筋骨，饿其体肤，空乏其身，行拂乱其所为，","t":"所以上天要把重大使命赋予某人时，必定先使他心志痛苦，筋骨劳累，体肤饥饿，身心困乏，行事受挫扰乱，","notes":[["故","所以"],["是人","这样的人"],["苦","使……痛苦"],["劳","使……劳累"],["饿","使……饥饿"],["空乏","使……穷困"],["拂","违背，不顺"]]},{"o":"所以动心忍性，曾益其所不能。","t":"以此来惊动他的心志，坚韧他的性格，增加他所不具备的能力。","notes":[["动","使……震撼"],["忍","使……坚忍"],["曾","同“增”，增加"]]},{"o":"人恒过，然后能改；困于心，衡于虑，而后作；征于色，发于声，而后喻。","t":"人常犯错，然后才能改正；内心困窘，思虑阻塞，而后才能振作；表现在脸色，抒发于言语，而后才能被人理解。","notes":[["恒","常常"],["过","犯过错"],["然后","这样以后"],["衡","同“横”，梗塞，不顺"],["作","奋起，有所作为"],["征","征验，表现"],["喻","了解，明白"]]},{"o":"入则无法家拂士，出则无敌国外患者，国恒亡。","t":"在内无坚守法度的大臣和辅佐之士，在外无敌对国家的忧患，国家常会灭亡。","notes":[["入","在国内"],["法家","守法度的大臣"],["拂士","辅佐君主的贤士"],["出","在国外"],["敌","匹敌，相当"],["恒","常常"]]},{"o":"然后知生于忧患而死于安乐也。","t":"由此可知，人在忧患中生存，在安乐中灭亡。","notes":[["于","在"]]}]},{"no":45,"t":"答谢中书书","src":"部编版八年级上册·[南朝齐梁]陶弘景","tag":"八年级上册","html":true,"p":["山川之美，古来共谈。高峰入云，清流见底。两岸石壁，五色交辉。青林翠竹，<u>四时</u><u>俱</u>备。晓雾将<u>歇</u>，猿鸟乱鸣；夕日<u>欲</u><u>颓</u>，<u>沉鳞</u><u>竞</u>跃。实是<u>欲界</u>之仙都。自康乐以来，未复有能<u>与</u>其<u>奇</u>者。<br>"],"common":"","q":[{"s":"“青林翠竹，<em class='k'>四时</em><em class='k'>俱</em>备”中“<em class='k'>四时</em>”的意思是？","o":["四季","四个时辰","时候","时辰"],"a":"A","e":"“四时”意为“四季”。青葱的林木与翠绿的竹林，四季常备。","tag":"字词释义"},{"s":"“四时<em class='k'>俱</em>备”中“<em class='k'>俱</em>”的意思是？","o":["全，都","一起","工具","具备"],"a":"A","e":"“俱”意为“全、都”。“俱备”即全都具备。","tag":"字词释义"},{"s":"“晓雾将<em class='k'>歇</em>”中“<em class='k'>歇</em>”的意思是？","o":["消散","休息","停止","睡觉"],"a":"A","e":"“歇”此处意为“消散”。清晨的薄雾将要消散。","tag":"字词释义"},{"s":"“夕日<em class='k'>欲</em>颓”中“<em class='k'>欲</em>”的意思是？","o":["将要","想要","欲望","如果"],"a":"A","e":"“欲”此处意为“将要”。夕阳将要落山。","tag":"字词释义"},{"s":"“夕日欲<em class='k'>颓</em>”中“<em class='k'>颓</em>”的意思是？","o":["坠落（太阳落山）","颓废","倒塌","衰败"],"a":"A","e":"“颓”此处意为“坠落”，指太阳落山。","tag":"字词释义"},{"s":"“<em class='k'>沉鳞</em>竞跃”中“<em class='k'>沉鳞</em>”指的是？","o":["潜游在水中的鱼","沉在水底的鳞片","落水的鱼","深水中的生物"],"a":"A","e":"“沉鳞”以“鳞”代指鱼，是借代，指潜游在水中的鱼。","tag":"字词释义"},{"s":"“沉鳞<em class='k'>竞</em>跃”中“<em class='k'>竞</em>”的意思是？","o":["争相","竟然","比赛","竞争"],"a":"A","e":"“竞”意为“争相”。鱼儿争相跃出水面。","tag":"字词释义"},{"s":"“实是<em class='k'>欲界</em>之仙都”中“<em class='k'>欲界</em>”的意思是？","o":["人间","欲望的境界","天界","世俗"],"a":"A","e":"“欲界”本为佛家语，此指人间。“仙都”即仙境。","tag":"字词释义"},{"s":"“未复有能<em class='k'>与</em>其奇者”中“<em class='k'>与</em>”的读音和意思是？","o":["yù，参与，这里有“欣赏、领悟”之意","yǔ，和","yú，语气词","yǔ，给予"],"a":"A","e":"“与”读 yù，意为“参与”，这里引申为“欣赏、领悟”。","tag":"字词释义"},{"s":"“未复有能与其<em class='k'>奇</em>者”中“<em class='k'>奇</em>”的活用和意思是？","o":["形容词作名词，奇景","形容词，奇特","形容词，奇怪","动词，惊奇"],"a":"A","e":"“奇”形容词作名词，指奇美的山水景色。","tag":"字词释义"},{"s":"下列对“晓雾将歇，猿鸟乱鸣；夕日欲颓，沉鳞竞跃”的翻译，正确的一项是？","o":["清晨的薄雾将要消散，猿、鸟此起彼伏地鸣叫；夕阳快要落山，水中的鱼争相跃出水面。","清晨的薄雾将要休息，猿鸟慌乱地鸣叫；夕阳将要坠落，鱼鳞竞相跳跃。","清晨的薄雾将要停止，猿鸟乱叫；夕阳想要颓废，沉鱼争相跳跃。","清晨的薄雾快要散尽，猿鸟大声鸣叫；夕阳快要落下，鱼儿争先恐后地跳出水面。"],"a":"A","e":"“歇”意为消散，“乱鸣”为此起彼伏地鸣叫，“颓”意为坠落，“沉鳞”以鳞代鱼。A 项翻译准确。","tag":"内容理解"},{"s":"“沉鳞竞跃”运用的修辞手法是？","o":["借代+拟人","拟人+夸张","夸张+比喻","比喻+借代"],"a":"A","e":"“鳞”代指鱼，是借代；“竞跃”赋予鱼争先恐后的情态，是拟人。","tag":"修辞手法"},{"s":"文中总领全文、概括山川之美的句子是？","o":["山川之美，古来共谈","高峰入云，清流见底","实是欲界之仙都","自康乐以来，未复有能与其奇者"],"a":"A","e":"首句“山川之美，古来共谈”总领全文，点明山川之美自古以来被人共同赞叹。","tag":"内容理解"},{"s":"下列关于结尾“自康乐以来，未复有能与其奇者”的深层含义，理解不正确的一项是？","o":["赞美谢灵运善于发现山水之美","惋惜世人大多不懂欣赏山水奇景","表达作者自己能领略山水美景的自得、庆幸之情","批评谢灵运之后的文人都无所作为"],"a":"D","e":"深层含义有三点：①赞美谢灵运善于发现山水之美；②惋惜世人大多不懂欣赏山水奇景；③表达自己能领略山水美景的自得、庆幸之情。D 项“批评文人无所作为”于文无据。","tag":"内容理解"},{"s":"下列加点词解释有误的一项是？","o":["四时俱备——全，都","晓雾将歇——消散","夕日欲颓——颓废","未复有能与其奇者——欣赏、领悟"],"a":"C","e":"“夕日欲颓”的“颓”意为“坠落”（太阳落山），不是“颓废”。","tag":"字词释义"}],"jd":[{"o":"山川之美，古来共谈。","t":"山川的美丽，自古以来就是文人雅士共同赞叹的。","notes":[["共","共同"]]},{"o":"高峰入云，清流见底。","t":"高耸的山峰直入云霄，清澈的溪流能看见水底。","notes":[["入","耸入"],["见","看见"]]},{"o":"两岸石壁，五色交辉。","t":"两岸的石壁色彩斑斓，交相辉映。","notes":[["交辉","交相辉映"]]},{"o":"青林翠竹，四时俱备。","t":"青葱的林木与翠绿的竹林，四季长存。","notes":[["四时","四季"],["俱","全，都"]]},{"o":"晓雾将歇，猿鸟乱鸣；","t":"清晨的薄雾即将消散时，猿猴与鸟儿此起彼伏地鸣叫；","notes":[["歇","消散"],["乱鸣","此起彼伏地鸣叫"]]},{"o":"夕日欲颓，沉鳞竞跃。","t":"夕阳快要落山时，水中的鱼儿争相跃出水面。","notes":[["欲","将要"],["颓","坠落，太阳落山"],["沉鳞","潜游的鱼（以鳞代鱼）"],["竞","争相"]]},{"o":"实是欲界之仙都。","t":"这里实在是人间的仙境。","notes":[["欲界","人间"],["仙都","仙境"]]},{"o":"自康乐以来，未复有能与其奇者。","t":"自从谢灵运之后，再也没有人能欣赏这奇美的山水了。","notes":[["与(yù)","参与，引申为欣赏、领悟"],["奇","奇景（形作名）"]]}]},{"no":46,"t":"记承天寺夜游","src":"部编版八年级上册·[北宋]苏轼","tag":"八年级上册","html":true,"p":["元丰六年十月十二日夜，解衣欲睡，月色入<u>户</u>，欣<u>然</u>起行。<u>念</u>无与为乐者，<u>遂</u>至承天寺寻张怀民。怀民亦未寝，<u>相与</u>步于中庭。庭下如积水空明，水中藻、荇<small>〔荇〕xìng，水生植物</small><u>交横</u>，<u>盖</u>竹柏影也。何夜无月何处无竹柏<u>但</u>少闲人如吾两人者<u>耳</u>。<br>"],"common":"","q":[{"s":"“月色入<em class='k'>户</em>”中“<em class='k'>户</em>”的意思是？","o":["门","窗户","户口","住户"],"a":"A","e":"“户”此处指“门”。“月色入户”即月光从门照进来。","tag":"字词释义"},{"s":"“欣<em class='k'>然</em>起行”中“<em class='k'>然</em>”的意思是？","o":["……的样子","然后","然而","竟然"],"a":"A","e":"“然”是形容词词尾，意为“……的样子”。“欣然”即高兴的样子。","tag":"字词释义"},{"s":"“<em class='k'>念</em>无与为乐者”中“<em class='k'>念</em>”的意思是？","o":["想到","思念","念叨","念头"],"a":"A","e":"“念”意为“考虑、想到”。想到没有人与我共同赏乐。","tag":"字词释义"},{"s":"“<em class='k'>遂</em>至承天寺”中“<em class='k'>遂</em>”的意思是？","o":["于是，就","成功","即使","顺利"],"a":"A","e":"“遂”意为“于是、就”。于是到承天寺寻找张怀民。","tag":"字词释义"},{"s":"“<em class='k'>相与</em>步于中庭”中“<em class='k'>相与</em>”的意思是？","o":["共同，一起","互相给与","相随","交往"],"a":"A","e":"“相与”意为“共同、一起”。我们一起在庭院中散步。","tag":"字词释义"},{"s":"“水中藻、荇<em class='k'>交横</em>”中“<em class='k'>交横</em>”的意思是？","o":["交错纵横","交叉横放","相互横着","交通横行"],"a":"A","e":"“交横”意为“交错纵横”。","tag":"字词释义"},{"s":"“<em class='k'>盖</em>竹柏影也”中“<em class='k'>盖</em>”的意思是？","o":["大概是","盖子","遮盖","因为"],"a":"A","e":"“盖”表推测语气，意为“大概是”。大概是竹柏的影子。","tag":"字词释义"},{"s":"“<em class='k'>但</em>少闲人如吾两人者耳”中“<em class='k'>但</em>”的意思是？","o":["只是","但是","况且","竟然"],"a":"A","e":"“但”意为“只是”（古今异义，今义为“但是”）。","tag":"字词释义"},{"s":"“如吾两人者<em class='k'>耳</em>”中“<em class='k'>耳</em>”的意思是？","o":["罢了","耳朵","感叹语气词","听到"],"a":"A","e":"“耳”是句末语气词，意为“罢了”。","tag":"字词释义"},{"s":"“何夜无月何处无竹柏但少闲人如吾两人者耳”断句正确的一项是？","o":["何夜无月？何处无竹柏？但少闲人如吾两人者耳。","何夜无月何处？无竹柏但少闲人？如吾两人者耳。","何夜无月？何处无竹柏但？少闲人如吾两人者耳。","何夜无月何处？无竹柏？但少闲人如吾两人者耳。"],"a":"A","e":"应为两个反问句加一个感叹句：“何夜无月？何处无竹柏？但少闲人如吾两人者耳。”","tag":"断句"},{"s":"“水中藻、荇交横，盖竹柏影也”的特殊句式是？","o":["判断句","省略句","倒装句","被动句"],"a":"A","e":"“盖竹柏影也”用“也”表判断，是判断句。","tag":"特殊句式"},{"s":"下列关于本文主旨情感的理解，不正确的一项是？","o":["描绘承天寺月夜美景，抒发赏月的欣喜、漫步的悠闲","暗含作者被贬黄州的落寞苦闷","体现苏轼乐观旷达的人生态度","表达作者对官场生活的向往与留恋"],"a":"D","e":"本文主旨：①描绘月夜美景，抒发赏月的欣喜、漫步的悠闲；②暗含被贬黄州的落寞苦闷；③体现乐观旷达的人生态度。D 项“向往官场”于文无据。","tag":"内容理解"},{"s":"下列对“闲人”内涵的理解，不正确的一项是？","o":["指具有闲情逸致、能够欣赏月色美景的人","暗含作者被贬黄州、仕途失意不得重用的苦闷","表现作者在逆境中乐观旷达、随缘自适的心境","指清闲无事、无所事事的人"],"a":"D","e":"“闲人”包含三层内涵：①闲情逸致、能欣赏月色美景；②暗含被贬黄州、仕途失意的苦闷；③逆境中乐观旷达、随缘自适。D 项“无所事事”是贬义理解，不符。","tag":"内容理解"},{"s":"下列加点词解释有误的一项是？","o":["月色入户——门","念无与为乐者——思念","怀民亦未寝——睡觉","但少闲人如吾两人者耳——只是"],"a":"B","e":"“念”意为“考虑、想到”，不是“思念”。","tag":"字词释义"},{"s":"“相与步于中庭”的特殊句式与下列哪句相同？","o":["蒙辞以军中多务","何陋之有","莲，花之君子者也","其印为余群从所得"],"a":"A","e":"“相与步于中庭”即“（于中庭）步”，状语后置，与“蒙辞以军中多务”（以军中多务辞）相同。","tag":"特殊句式"}],"jd":[{"o":"元丰六年十月十二日夜，解衣欲睡，月色入户，欣然起行。","t":"元丰六年十月十二日夜晚，（我）解开衣服准备睡觉，月光从门照进来，高兴地起身出行。","notes":[["户","门"],["然","……的样子"]]},{"o":"念无与为乐者，遂至承天寺寻张怀民。","t":"想到没有人与我共同赏乐，于是到承天寺找张怀民。","notes":[["念","考虑，想到"],["遂","于是，就"]]},{"o":"怀民亦未寝，相与步于中庭。","t":"怀民也未睡，我们一起在庭院中散步。","notes":[["相与","共同，一起"],["步","散步"]]},{"o":"庭下如积水空明，水中藻、荇交横，盖竹柏影也。","t":"庭院中的月光如积水般澄澈，“水中”藻荇交错纵横，大概是竹柏的影子。","notes":[["空明","澄澈"],["交横","交错纵横"],["盖","大概是"]]},{"o":"何夜无月何处无竹柏但少闲人如吾两人者耳。","t":"哪一夜没有月光？哪里没有竹柏？只是缺少像我们这样的闲人罢了。","notes":[["但","只是"],["耳","罢了"]]}]},{"no":47,"t":"北冥有鱼","src":"部编版八年级下册·（先秦）《庄子》","tag":"八年级下册","html":true,"p":["北冥<small>〔北冥〕北海。庄子想象中的北海，应该在北方的不毛之地。冥，同“溟”，海。下文的“南冥”指南海。</small>有鱼，其名为<small>〔鲲〕大鱼名。</small>。鲲之大，不知其几千里也；化而为鸟，其名为鹏。鹏之背，不知其几千里也；<u>怒</u>而飞，其翼若垂天之云<small>〔垂天之云〕悬挂在天空的云。</small>。<u>是</u>鸟也，<u>海运</u>则将徙<u>于</u>南冥。南冥者，<u>天池</u>也。《齐谐》者，<u>志</u>怪者也。","《谐》之言曰：“鹏之徙于南冥也，水击三千里，<u>抟</u><u>扶摇</u>而上者九万里，去<u>以</u>六月<u>息</u>者也。”<u>野马</u>也，尘埃也，生物<u>之</u>以息相吹也。天之苍<u>苍</u>，其正色邪？<u>其</u>远而无所至极邪？<u>其</u>视下也，亦若是则已矣。"],"common":"","q":[{"s":"“<em class='k'>怒</em>而飞”中“<em class='k'>怒</em>”的意思是？","o":["生气","愤怒","振奋","沉静"],"a":"C","e":"“怒”意为“振奋”，这里指用力鼓动翅膀。“怒而飞”即奋力飞翔。","tag":"字词释义"},{"s":"“<em class='k'>是</em>鸟也”中“<em class='k'>是</em>”的意思是？","o":["表判断","这","正确","这样"],"a":"B","e":"“是”是指示代词，意为“这”。“是鸟也”即这只鸟。","tag":"字词释义"},{"s":"“<em class='k'>海运</em>则将徙于南冥”中“<em class='k'>海运</em>”的意思是？","o":["海上运输","海水运动","海上航行","海上运行"],"a":"B","e":"“海运”意为“海水运动”，这里指海水运动引发的大风。","tag":"字词释义"},{"s":"“海运则将徙<em class='k'>于</em>南冥”中“<em class='k'>于</em>”的意思是？","o":["在","到","对于","从"],"a":"B","e":"“于”意为“到”。“徙于南冥”即迁徙到南海。","tag":"字词释义"},{"s":"“南冥者，<em class='k'>天池</em>也”中“<em class='k'>天池</em>”的意思是？","o":["天上的池","天然形成的大水池","天边的池水","天然湖泊"],"a":"B","e":"“天池”意为“天然形成的大水池”。","tag":"字词释义"},{"s":"“《齐谐》者，<em class='k'>志</em>怪者也”中“<em class='k'>志</em>”的意思是？","o":["志向","记载","标志","记住"],"a":"B","e":"“志”意为“记载”。“志怪者”即记载怪异之事的（书）。","tag":"字词释义"},{"s":"“<em class='k'>抟</em>扶摇而上者九万里”中“<em class='k'>抟</em>”的意思是？","o":["盘旋而上","紧紧握住","环绕四周","直线飞行"],"a":"A","e":"“抟”意为“盘旋着往上飞”。“抟扶摇”即乘着旋风盘旋而上。","tag":"字词释义"},{"s":"“抟<em class='k'>扶摇</em>而上者九万里”中“<em class='k'>扶摇</em>”的意思是？","o":["旋风","大风","微风","狂风"],"a":"A","e":"“扶摇”意为“旋风”，指盘旋而上的风。","tag":"字词释义"},{"s":"“去<em class='k'>以</em>六月息者也”中“<em class='k'>以</em>”的意思是？","o":["用","凭借","因为","按照"],"a":"B","e":"“以”意为“凭借”。“去以六月息”即凭借六月的大风离开。","tag":"字词释义"},{"s":"“去以六月<em class='k'>息</em>者也”中“<em class='k'>息</em>”的意思是？","o":["气息","风","休息","停止"],"a":"B","e":"“息”意为“气息”，这里指风。","tag":"字词释义"},{"s":"“<em class='k'>野马</em>也，尘埃也”中“<em class='k'>野马</em>”的意思是？","o":["野生的马","山野中的雾气","奔驰的马","田野"],"a":"B","e":"“野马”指山野中游动的雾气（远看如奔马）。","tag":"字词释义"},{"s":"“生物<em class='k'>之</em>以息相吹也”中“<em class='k'>之</em>”的用法是？","o":["结构助词，的","主谓之间取消句子独立性","代词，它","动词，去"],"a":"B","e":"“之”是助词，用在主谓之间，取消句子独立性。\"生物之以息相吹\"即生物用气息吹拂。","tag":"字词释义"},{"s":"“天之苍<em class='k'>苍</em>”中“<em class='k'>苍</em>”的意思是？","o":["苍老","湛蓝","苍白","苍茫"],"a":"B","e":"“苍”意为“湛蓝”。“苍苍”即深蓝色。","tag":"字词释义"},{"s":"“<em class='k'>其</em>远而无所至极邪”中“<em class='k'>其</em>”的用法是？","o":["代词，它的","语气词，难道","指示代词，那个","副词，竟然"],"a":"B","e":"“其”是语气词，表推测、反问，难道。“其远而无所至极邪”即还是因为天空高远而看不到尽头呢？","tag":"字词释义"},{"s":"“<em class='k'>其</em>视下也”中“<em class='k'>其</em>”的意思是？","o":["难道","它","那个","大概"],"a":"B","e":"“其”是代词，代大鹏，它。“其视下也”即大鹏从天空往下看。","tag":"字词释义"},{"s":"“南冥者，天池也”属于哪种文言句式？","o":["倒装句","判断句","省略句","被动句"],"a":"B","e":"“……者，……也”是典型的判断句标志，“南冥者，天池也”即南海是天然形成的大水池。","tag":"内容理解"},{"s":"“去以六月息者也”句式判断正确的一项是？","o":["宾语前置，正常语序：以六月息去","状语后置，正常语序：以六月息去","判断句，表肯定判断","省略句，省略主语“鹏”"],"a":"B","e":"“去以六月息”是状语后置句，介词短语“以六月息”（凭借六月的大风）后置，正常语序为“以六月息去”。","tag":"内容理解"},{"s":"下列对“抟扶摇而上者九万里”翻译准确的一项是？","o":["盘旋着乘着旋风飞上九万里高空","抓起旋风向上飞了九万里","依靠大风盘旋飞到九万里之外","拍打水面，借着风力飞到九万里"],"a":"A","e":"“抟扶摇而上者九万里”意为“乘着旋风盘旋飞至九万里的高空”。“抟”是盘旋着往上飞，“扶摇”是旋风。","tag":"内容理解"},{"s":"对“其远而无所至极邪”翻译最准确的一项是？","o":["难道是因为天空高远而看不到尽头吗","它距离太远，没有到达的地方吗","天空辽阔，没有可以停留的地方吗","远方没有尽头，所以不必到达吗"],"a":"A","e":"“其远而无所至极邪”意为“还是因为天空高远而看不到尽头呢”，以推测语气发问。","tag":"内容理解"},{"s":"下列朗读停顿划分正确的一项是？","o":["鲲之大 / 不知其几千里也","抟扶摇 / 而上者九万里","天之 / 苍苍，其正色邪","生物之以息 / 相吹也"],"a":"A","e":"A 正确，“鲲之大”是主语，后停顿。B 应为“抟扶摇而上者 / 九万里”（“抟扶摇而上者”作主语）；C 应为“天之苍苍 / 其正色邪”；D 应为“生物之以息相吹 / 也”。","tag":"断句"},{"s":"文章先写鲲化为鹏、鹏高飞九万里，再写山野雾气、尘埃，这样安排的作用是？","o":["单纯描写天地间各类景物，丰富文章画面","以鲲鹏、尘埃大小对比，说明世间万物都要依靠外力，没有真正的自由","突出鲲鹏体型巨大，尘埃渺小，批判微小事物不值一提","证明只有巨型生物才能乘风远行，小生物无法远行"],"a":"B","e":"写大鹏高飞要凭借六月大风，写雾气尘埃要凭借气息吹拂，大小不同却都“有所待”，从正反两面论证万物皆有所待、没有绝对自由的观点。","tag":"内容理解"},{"s":"作者发出“天之苍苍，其正色邪？其远而无所至极邪？”的疑问，深层用意是？","o":["单纯好奇天空原本的颜色","借对天空的思考，说明人的认知有限，万物都受自身局限","感叹天空广阔，人类十分渺小","表达想要飞上高空看清天空本色的愿望"],"a":"B","e":"作者借“天色湛蓝是本色还是因为高远”的疑问，说明人的认知受到自身条件限制，万物都受自身局限，进一步论证“有所待”的道理。","tag":"内容理解"},{"s":"下列对“去以六月息者也”理解，不符合文章内涵的一项是？","o":["大鹏高飞必须依靠六月大风，有所凭借","大鹏看似自由，实则不能脱离外物的支撑","只要风力足够，万物都能实现绝对的逍遥自由","这句话印证了世间万物皆有所待的道理"],"a":"C","e":"C 不符合。文中强调大鹏“去以六月息”是“有所待”，并未说“只要风力足够就能绝对自由”；庄子认为万物皆有所待，只有“无所待”才能达到逍遥游的境界。","tag":"内容理解"},{"s":"关于本文写作手法与主旨，说法正确的一项是？","o":["文章写实记录远古大鱼大鸟，真实存在鲲鹏这种生物","运用夸张、想象塑造鲲鹏形象，阐明万物皆有所待的道家观点","全文主要赞美大鹏志存高远、不受任何束缚","文中写尘埃雾气是多余内容，仅用来填充篇幅"],"a":"B","e":"本文以极度夸张的笔法和丰富的想象塑造鲲鹏形象，又写雾气尘埃，共同阐明“万物皆有所待”的道家观点。","tag":"内容理解"},{"s":"文中“野马也，尘埃也，生物之以息相吹也”一句，与大鹏形象的关联分析最准确的是？","o":["二者毫无关联，只是顺带描写地面景物","一宏大一微小，无论大小事物，都需要依靠气息、风力才能活动，论证“万物有所待”","用微小尘埃反衬大鹏的强大自由","说明尘埃比大鹏更轻盈，不需要依靠大风"],"a":"B","e":"大鹏翱翔九天靠六月大风，雾气尘埃飘动靠气息吹拂，形体虽有大小，但都“有所待”，共同论证万物皆有所待的观点。","tag":"内容理解"}],"jd":[{"o":"北冥有鱼，其名为鲲。鲲之大，不知其几千里也；化而为鸟，其名为鹏。鹏之背，不知其几千里也；怒而飞，其翼若垂天之云。是鸟也，海运则将徙于南冥。南冥者，天池也。《齐谐》者，志怪者也。","t":"北海有一条鱼，它的名字叫做鲲。鲲的体积巨大，不知道有几千里；鲲变化成为鸟，它的名字就叫作鹏。鹏的脊背，不知道有几千里长；当它奋起而飞的时候，它展开的双翅就像悬挂在天空的云。这只鸟，在海水运动（引发大风）的时候，就会迁徙到南海去。南海，是天然形成的大水池。《齐谐》，是一部记载怪异事物的书。","notes":[["北冥","北海。冥，同“溟”，海"],["鲲","大鱼名"],["怒","振奋，这里指用力鼓动翅膀"],["是","代词，这"],["海运","海水运动，这里指引发的大风"],["于","到"],["天池","天然形成的大水池"],["志","记载"]]},{"o":"《谐》之言曰：“鹏之徙于南冥也，水击三千里，抟扶摇而上者九万里，去以六月息者也。”野马也，尘埃也，生物之以息相吹也。天之苍苍，其正色邪？其远而无所至极邪？其视下也，亦若是则已矣。","t":"《齐谐》这本书上记载说：“鹏鸟迁徙到南海的时候，翅膀拍打水面，能激起三千里的浪涛，它乘着旋风盘旋飞至九万里的高空，它是凭借着六月的大风离开（北海）的。”山野中的雾气，空气中的尘埃，都是生物用气息吹拂而形成的。天色湛蓝，这是它真正的颜色吗？还是因为天空高远而看不到尽头（才呈现出这样的颜色）呢？大鹏从天空往下看，也不过像人在地面上看天一样罢了。","notes":[["抟","盘旋着往上飞"],["扶摇","旋风"],["以","凭借"],["息","气息，这里指风"],["野马","山野中游动的雾气"],["之","助词，主谓之间取消句子独立性"],["苍","湛蓝"],["其","语气词，难道"],["其","代词，代大鹏"]]}]},{"no":48,"t":"大道之行也","src":"部编版八年级下册·（西汉）《礼记》","tag":"八年级下册","html":true,"p":["<span class=\"jz\" title=\"大道：指儒家推崇的上古时代的政治制度\">大道之行也，天下<u>为</u>公。选贤<u>与</u><u>能</u>，讲信<u>修</u>睦。","<u>故人</u>不独<u>亲</u>其<u>亲</u>，不独<u>子</u>其子，使<u>老</u>有所<u>终</u>，壮有所<u>用</u>，幼有所<u>长</u>，<u>矜(guān)</u>、寡、<u>孤</u>、独、废疾者皆有所养，男有<u>分</u>，女有<u>归</u>。","货<u>恶</u>其弃于地也，不必藏于己；力恶其不出于<u>身</u>也，不必为己。<u>是故</u>谋<u>闭</u>而不<u>兴</u>，盗窃乱贼而不作，故<u>外户</u>而不闭。<u>是</u>谓大同。"],"common":"","q":[{"s":"“天下<em class='k'>为</em>公”中“<em class='k'>为</em>”的意思是？","o":["是","做","被","替"],"a":"A","e":"“为”意为“是”。“天下为公”即天下是公共的。","tag":"字词释义"},{"s":"“选贤<em class='k'>与</em>能”中“<em class='k'>与</em>”的意思是？","o":["同“举”，推举","和，同","参与","给予"],"a":"A","e":"“与”同“举”，意为“推举”。“选贤与能”即选拔推举品德高尚、有才干的人。","tag":"字词释义"},{"s":"“讲信<em class='k'>修</em>睦”中“<em class='k'>修</em>”的意思是？","o":["培养","修理","修建","撰写"],"a":"A","e":"“修”意为“培养”。“讲信修睦”即讲求诚信，培养和睦气氛。","tag":"字词释义"},{"s":"“不独<em class='k'>亲</em>其亲”中第一个“<em class='k'>亲</em>”的意思是？","o":["以……为亲","亲人","亲近","父母"],"a":"A","e":"第一个“亲”是名词的意动用法，“以……为亲”。“不独亲其亲”即不只是敬爱自己的父母。","tag":"字词释义"},{"s":"“不独亲其<em class='k'>亲</em>”中第二个“<em class='k'>亲</em>”的意思是？","o":["父母","亲戚","亲爱","家属"],"a":"A","e":"第二个“亲”指“父母”。“亲其亲”即敬爱自己的父母。","tag":"字词释义"},{"s":"“不独<em class='k'>子</em>其子”中第一个“<em class='k'>子</em>”的意思是？","o":["以……为子","子女","儿子","疼爱"],"a":"A","e":"第一个“子”是名词的意动用法，“以……为子”。“不独子其子”即不只是疼爱自己的子女。","tag":"字词释义"},{"s":"“<em class='k'>老</em>有所终”中“<em class='k'>老</em>”的意思是？","o":["老年人","衰老","年长","年迈"],"a":"A","e":"“老”是形容词作名词，指“老年人”。“老有所终”即老年人能有终老的保障。","tag":"词类活用"},{"s":"“老有所<em class='k'>终</em>”中“<em class='k'>终</em>”的意思是？","o":["善终","结束","终于","始终"],"a":"A","e":"“终”意为“终老，善终”。“老有所终”即老年人能有终老的保障。","tag":"字词释义"},{"s":"“壮有所<em class='k'>用</em>”中“<em class='k'>用</em>”的意思是？","o":["效力","使用","费用","任用"],"a":"A","e":"“用”意为“施展才能、为社会效力”。“壮有所用”即壮年人能发挥才能。","tag":"字词释义"},{"s":"“幼有所<em class='k'>长</em>”中“<em class='k'>长</em>”的意思是？","o":["成长","长久","长辈","增长"],"a":"A","e":"“长”读 zhǎng，意为“成长”。“幼有所长”即幼童能顺利成长。","tag":"字词释义"},{"s":"“<em class='k'>矜</em>、寡、孤、独、废疾者”中“<em class='k'>矜</em>”的意思是？","o":["同“鳏”，老而无妻的人","怜悯","庄重","自夸"],"a":"A","e":"“矜”同“鳏”，指老而无妻的人。“矜、寡、孤、独”分别指老而无妻、老而无夫、幼而无父、老而无子的人。","tag":"字词释义"},{"s":"“男有<em class='k'>分</em>”中“<em class='k'>分</em>”的意思是？","o":["职分","分开","部分","分寸"],"a":"A","e":"“分”意为“职分，职业”。“男有分”即男子有职业。","tag":"字词释义"},{"s":"“女有<em class='k'>归</em>”中“<em class='k'>归</em>”的意思是？","o":["出嫁","归来","归属","归还"],"a":"A","e":"“归”意为“女子出嫁”。“女有归”即女子能适时出嫁。","tag":"字词释义"},{"s":"“货<em class='k'>恶</em>其弃于地也”中“<em class='k'>恶</em>”的意思是？","o":["厌恶","凶恶","恶行","恶劣"],"a":"A","e":"“恶”读 wù，意为“厌恶”。人们厌恶财物被扔在地上的行为。","tag":"字词释义"},{"s":"“力恶其不出于<em class='k'>身</em>也”中“<em class='k'>身</em>”的意思是？","o":["自己","身体","身份","亲身"],"a":"A","e":"“身”意为“自己”。“力恶其不出于身也”即人们厌恶（力气）不出于自己，愿意为公众之事出力。","tag":"字词释义"},{"s":"“<em class='k'>是故</em>谋闭而不兴”中“<em class='k'>是故</em>”的意思是？","o":["因此","因为","然而","于是"],"a":"A","e":"“是故”是固定结构，意为“因此”。“是故谋闭而不兴”即因此图谋之心杜绝而不兴起。","tag":"字词释义"},{"s":"“谋<em class='k'>闭</em>而不兴”中“<em class='k'>闭</em>”的意思是？","o":["杜绝","关闭","结束","封闭"],"a":"A","e":"“闭”意为“杜绝”。“谋闭而不兴”即图谋之心杜绝而不兴起。","tag":"字词释义"},{"s":"“谋闭而不<em class='k'>兴</em>”中“<em class='k'>兴</em>”的意思是？","o":["兴起","发生","兴盛","高兴"],"a":"A","e":"“兴”读 xīng，意为“兴起”。“谋闭而不兴”即图谋之心闭塞而不兴起。","tag":"字词释义"},{"s":"“故<em class='k'>外户</em>而不闭”中“<em class='k'>外户</em>”的意思是？","o":["从外面把门带上","外面的门户","推开大门","锁上大门"],"a":"A","e":"“外户”即从外面把门带上。“故外户而不闭”即所以从外面把门带上而不从里面闩上。","tag":"字词释义"},{"s":"“<em class='k'>是</em>谓大同”中“<em class='k'>是</em>”的意思是？","o":["这，此","正确","表判断","于是"],"a":"A","e":"“是”作主语，意为“这，此”。“是谓大同”即这就叫作大同社会。","tag":"字词释义"},{"s":"“<em class='k'>故人</em>不独亲其亲”中“<em class='k'>故人</em>”的意思是？","o":["所以人们","老朋友","原来的人们","古人"],"a":"A","e":"“故”意为“所以”，“人”意为“人们”。“故人”古义为“所以人们”，今义为“老朋友”，是古今异义词。","tag":"古今异义"},{"s":"对“故人不独亲其亲，不独子其子”翻译理解正确的一项是？","o":["所以人们不只敬爱自己的父母，不只疼爱自己的子女","所以人们不把亲人当作亲人，不把子女当作子女","因此人们唯独亲近亲人，唯独疼爱子女","因此人们不偏爱亲人，不溺爱自家孩子"],"a":"A","e":"“亲其亲”即敬爱自己的父母（意动），“子其子”即疼爱自己的子女。A 翻译准确。B 曲解意动用法；C 误把“不独”译为“唯独”；D 改变原意。","tag":"翻译"},{"s":"下列对文章内容理解分析有误的一项是？","o":["“选贤与能，讲信修睦”写大同社会选拔人才、社会风气和睦","“矜、寡、孤、独、废疾者皆有所养”体现大同社会人人得到关爱","“货恶其弃于地也，不必藏于己”是说人们把财物丢弃在地上，不私自占有","“外户而不闭”侧面表现大同社会安定，没有盗窃作乱现象"],"a":"C","e":"C 有误。“货恶其弃于地也，不必藏于己”是说人们厌恶财物被扔在地上的行为，（之所以厌恶）不一定是因为想据为己有，而不是“把财物丢弃在地上”。","tag":"内容理解"},{"s":"下列对“大同”社会理解，表述错误的一项是？","o":["大同社会是儒家构想的理想社会，并非当时现实","大同社会兼顾弱势群体，老人孩子都得到妥善安置","大同社会中所有人无私心，完全没有个人财物","“谋闭而不兴，盗窃乱贼而不作”体现社会安定"],"a":"C","e":"C 表述错误。大同社会并非“完全没有个人财物”，而是人们不把财物据为己有——“货恶其弃于地也，不必藏于己”，并非没有财物。","tag":"内容理解"},{"s":"本文《大道之行也》选自哪一部著作？","o":["《礼记》","《论语》","《孟子》","《庄子》"],"a":"A","e":"本文节选自《礼记·礼运》。《礼记》是儒家经典之一，相传由西汉戴圣编纂。","tag":"文学常识"},{"s":"下列朗读停顿划分正确的一项是？","o":["故 / 人不独亲其亲","矜寡孤 / 独废疾者","是故谋闭 / 而不兴","是谓 / 大同"],"a":"A","e":"A 正确，句首“故”后停顿。B 应为“矜、寡、孤、独 / 废疾者”（矜寡孤独指四种人）；C 应为“是故 / 谋闭而不兴”（“是故”是固定结构，意为“因此”）；D 应为“是 / 谓大同”（“是”作主语，意为“这”）。","tag":"断句"},{"s":"下列句子属于判断句的一项是？","o":["天下为公","故外户而不闭","货恶其弃于地也","力恶其不出于身也"],"a":"A","e":"“天下为公”中“为”表判断，意为“天下是公共的”，属于判断句。其余三项都不是判断句。","tag":"句式"}],"jd":[{"o":"大道之行也，天下为公。选贤与能，讲信修睦。","t":"在大道施行的时候，天下是公共的。选拔推举品德高尚、有才干的人，讲求诚信，培养和睦气氛。","notes":[["大道","指儒家推崇的上古时代的政治制度"],["为","是"],["与","同“举”，推举"],["能","有才干的人"],["修","培养"]]},{"o":"故人不独亲其亲，不独子其子，使老有所终，壮有所用，幼有所长，矜、寡、孤、独、废疾者皆有所养，男有分，女有归。","t":"因此人们不只是敬爱自己的父母，不只是疼爱自己的子女。要使老年人能有终老的保障，中年人能为社会效力，幼童能顺利成长。老而无妻的人、老而无夫的人、幼而无父的人、老而无子的人、有残疾而不能做事的人，都能得到供养。男子要有职业，女子要适时出嫁。","notes":[["故人","所以人们（古今异义）"],["亲","第一个：以……为亲；第二个：父母"],["子","第一个：以……为子"],["终","终老，善终"],["用","施展才能"],["长","成长"],["矜","同“鳏”，老而无妻的人"],["分","职分，职业"],["归","女子出嫁"]]},{"o":"货恶其弃于地也，不必藏于己；力恶其不出于身也，不必为己。是故谋闭而不兴，盗窃乱贼而不作，故外户而不闭。是谓大同。","t":"对于财物，人们厌恶把它扔在地上的行为，但不一定想据为己有；人们都愿意为公众之事竭尽全力，厌恶力气不出于自己，但不一定是为了自己的私利。因此图谋之心杜绝而不会兴起，盗窃、造反和害人的事情不会发生，所以从外面把门带上而不从里面闩上。这就叫作大同社会。","notes":[["恶","厌恶"],["身","自己"],["是故","因此"],["闭","杜绝"],["兴","兴起"],["外户","从外面把门带上"],["是","这，此"]]}]},{"no":49,"t":"小石潭记","src":"部编版八年级下册·（唐）柳宗元","tag":"八年级下册","html":true,"p":["从小丘<u>西</u>行百二十步，隔篁竹，闻水声，如鸣珮环<small>〔如鸣珮环〕好像珮环碰撞的声音。珮、环，都是玉饰。</small>，心<u>乐</u>之。伐竹取道，<u>下</u>见小潭，水尤清冽。全石<u>以为</u>底，近岸，卷石底以出，为<u>坻</u><small>〔坻(chí)〕</small>，为屿，为<u>嵁</u><small>〔嵁(kān)〕</small>，为岩。青树翠蔓，<u>蒙络</u>摇缀，参差披拂<small>〔蒙络摇缀，参差披拂〕蒙盖缠绕，摇曳牵连，参差不齐，随风飘拂。</small>。","潭中鱼<u>可百许</u>头，皆<u>若</u>空游无所依，日光下<u>澈</u>，影布石上。<u>佁然</u><small>〔佁(yǐ)〕</small>不动，<u>俶尔</u><small>〔俶(chù)〕</small>远逝，往来<u>翕忽</u><small>〔翕(xī)〕</small>，似与游者相乐。","潭<u>西南</u>而望，<u>斗</u>折<u>蛇</u>行，明灭可见。其岸势犬牙<u>差互</u><small>〔差(chā)互〕</small>，不可知其源。","坐潭上，四面竹树<u>环合</u>，寂寥无人，<u>凄</u>神<u>寒</u>骨，<u>悄怆</u><small>〔悄怆(qiǎo chuàng)〕</small>幽<u>邃</u><small>〔邃(suì)〕</small>。<u>以</u>其境过<u>清</u><small>〔清〕凄清。</small>，不可久居，<u>乃</u>记之而<u>去</u>。","同游者：吴武陵<small>〔吴武陵〕作者的朋友，当时也被贬到永州。</small>，龚古<small>〔龚古〕作者的朋友。</small>，余弟宗玄<small>〔宗玄〕作者的堂弟。</small>。<u>隶</u>而从者，崔氏二小生<small>〔二小生〕两个年轻人。</small>，曰恕己，曰奉壹。"],"common":"","q":[{"s":"“从小丘<em class='k'>西</em>行”中“<em class='k'>西</em>”的意思是？","o":["西方","西边","西面","向西"],"a":"D","e":"“西”名词作状语，向西。“西行”即向西走。","tag":"字词释义"},{"s":"“心<em class='k'>乐</em>之”中“<em class='k'>乐</em>”的活用和意思是？","o":["快乐","欢乐","高兴","以……为乐"],"a":"D","e":"“乐”意动用法，以……为乐，对……感到快乐。","tag":"字词释义"},{"s":"“<em class='k'>下</em>见小潭”中“<em class='k'>下</em>”的意思是？","o":["下方","下面","低处","向下"],"a":"D","e":"“下”名词作状语，向下。“下见小潭”即向下看见一个小潭。","tag":"字词释义"},{"s":"“全石<em class='k'>以为</em>底”中“<em class='k'>以为</em>”的意思是？","o":["认为","因为","用来","把……当作"],"a":"D","e":"“以为”意为“把……当作”。“全石以为底”即把整块石头当作潭底。","tag":"字词释义"},{"s":"“为<em class='k'>坻</em>”中“<em class='k'>坻</em>”的意思是？","o":["水中小岛","水中岩石","水中土堆","水中高地"],"a":"D","e":"“坻”指水中高地。与“屿”（小岛）、“嵁”（不平的岩石）、“岩”（山岩）都是石头的不同形态。","tag":"字词释义"},{"s":"“为<em class='k'>嵁</em>”中“<em class='k'>嵁</em>”的意思是？","o":["水中小岛","水中高地","不平的岩石","水中土堆"],"a":"C","e":"“嵁”指不平的岩石。","tag":"字词释义"},{"s":"“青树翠蔓，<em class='k'>蒙络</em>摇缀”中“<em class='k'>蒙络</em>”的意思是？","o":["缠绕摇晃","蒙蔽璎珞","摇动连接","覆盖缠绕"],"a":"D","e":"“蒙络”意为“覆盖缠绕”；“摇缀”为“摇曳牵连”。","tag":"字词释义"},{"s":"“潭中鱼<em class='k'>可百许</em>头”中“<em class='k'>可</em>”的意思是？","o":["可以","可能","可是","大约"],"a":"D","e":"“可”意为“大约”。“可百许头”即大约一百来条（许：表示约数，左右）。","tag":"字词释义"},{"s":"“皆<em class='k'>若</em>空游无所依”中“<em class='k'>若</em>”的意思是？","o":["如果","假若","比得上","好像"],"a":"D","e":"“若”意为“好像”。“皆若空游无所依”即都好像在空中游动，没有什么依傍。","tag":"字词释义"},{"s":"“日光下<em class='k'>澈</em>”中“<em class='k'>澈</em>”的意思是？","o":["清澈","澄澈","透明","穿透"],"a":"D","e":"“澈”意为“穿透”。日光向下穿透（潭水）直到水底。","tag":"字词释义"},{"s":"“<em class='k'>佁然</em>不动”中“<em class='k'>佁然</em>”的意思是？","o":["悠闲地","安然的样子","静止的样子","忽然地"],"a":"C","e":"“佁然”意为“静止不动的样子”。","tag":"字词释义"},{"s":"“<em class='k'>俶尔</em>远逝”中“<em class='k'>俶尔</em>”的意思是？","o":["停止","长久","缓慢","忽然"],"a":"D","e":"“俶尔”意为“忽然”。“俶尔远逝”即忽然间向远处游去。","tag":"字词释义"},{"s":"“往来<em class='k'>翕忽</em>”中“<em class='k'>翕忽</em>”的意思是？","o":["忽然","轻快的样子","笨拙的样子","迟缓的样子"],"a":"B","e":"“翕忽”意为“轻快敏捷的样子”。","tag":"字词释义"},{"s":"“潭<em class='k'>西南</em>而望”中“<em class='k'>西南</em>”的意思是？","o":["西南方","西南边","西南面","向西南"],"a":"D","e":"“西南”名词作状语，向西南。“潭西南而望”即向潭水的西南方向望去。","tag":"字词释义"},{"s":"“<em class='k'>斗</em>折蛇行”中“<em class='k'>斗</em>”的活用和意思是？","o":["弯曲，名词作形容词","北斗星，没有活用","像北斗星一样，名作状","折叠，名作动"],"a":"C","e":"“斗”名词作状语，像北斗星那样。“斗折”即（溪水）像北斗星那样曲折。","tag":"字词释义"},{"s":"“斗折<em class='k'>蛇</em>行”中“<em class='k'>蛇</em>”的活用和意思是？","o":["蛇，名词","蜿蜒，名作状","爬行，名作动","像蛇一样，名作状"],"a":"D","e":"“蛇”名词作状语，像蛇那样。“蛇行”即像蛇那样蜿蜒前行。","tag":"字词释义"},{"s":"“其岸势犬牙<em class='k'>差互</em>”中“<em class='k'>差互</em>”的意思是？","o":["差异","互相","整齐","交错"],"a":"D","e":"“差互”意为“交错”。“犬牙差互”即像狗的牙齿那样交错。","tag":"字词释义"},{"s":"“四面竹树<em class='k'>环合</em>”中“<em class='k'>环合</em>”的意思是？","o":["像圆环一样","环绕合围","环抱合拢","环形合拢"],"a":"B","e":"“环合”意为“环绕合抱”。","tag":"字词释义"},{"s":"“<em class='k'>凄</em>神寒骨”中“<em class='k'>凄</em>”的活用和意思是？","o":["凄凉","凄惨","寒冷","使……凄凉"],"a":"D","e":"“凄”使动用法，使……凄凉。与“寒”（使……寒冷）同为使动。","tag":"字词释义"},{"s":"“凄神<em class='k'>寒</em>骨”中“<em class='k'>寒</em>”的活用和意思是？","o":["寒冷","寒心","寒气","使……寒冷"],"a":"D","e":"“寒”使动用法，使……寒冷。","tag":"字词释义"},{"s":"“<em class='k'>悄怆</em>幽邃”中“<em class='k'>悄怆</em>”的意思是？","o":["寂静","忧伤","深远","凄凉"],"a":"D","e":"“悄怆”意为“凄凉、忧伤”。","tag":"字词释义"},{"s":"“悄怆幽<em class='k'>邃</em>”中“<em class='k'>邃</em>”的意思是？","o":["深邃","浅薄","幽静","幽暗"],"a":"A","e":"“邃”意为“深”。“幽邃”即幽深。","tag":"字词释义"},{"s":"“<em class='k'>以</em>其境过清”中“<em class='k'>以</em>”的意思是？","o":["用","把","认为","因为"],"a":"D","e":"“以”意为“因为”。“以其境过清”即因为这里的环境过于凄清。","tag":"字词释义"},{"s":"“以其境过<em class='k'>清</em>”中“<em class='k'>清</em>”的意思是？","o":["清澈","清静","清楚","凄清"],"a":"D","e":"“清”意为“凄清、冷清”。","tag":"字词释义"},{"s":"“<em class='k'>乃</em>记之而去”中“<em class='k'>乃</em>”的意思是？","o":["才","竟然","却","于是，就"],"a":"D","e":"“乃”意为“于是、就”。“乃记之而去”即于是记下（当时的情景）就离开了。","tag":"字词释义"},{"s":"“乃记之而<em class='k'>去</em>”中“<em class='k'>去</em>”的意思是？","o":["去除","过去","前往","离开"],"a":"D","e":"“去”意为“离开”。","tag":"字词释义"},{"s":"“<em class='k'>隶</em>而从者”中“<em class='k'>隶</em>”的意思是？","o":["隶属","奴仆","服从","跟随"],"a":"D","e":"“隶”意为“跟随”。“隶而从者”即跟着（我）一同去的人。","tag":"字词释义"},{"s":"下列加点字词类活用类型与“从小丘<em class='k'>西</em>行”的“<em class='k'>西</em>”相同的一项是？","o":["斗折蛇行","凄神寒骨","心乐之","俶尔远逝"],"a":"A","e":"“西”名词作状语，向西；“斗”“蛇”名词作状语，像北斗星那样、像蛇那样，活用类型相同。B 使动；C 意动；D 无活用。","tag":"字词释义"},{"s":"对“心<em class='k'>乐</em>之”中“<em class='k'>乐</em>”的用法，分析正确的一项是？","o":["名词，快乐","意动用法，以……为乐","使动用法，使……快乐","形容词，欢乐"],"a":"B","e":"“乐”意动用法，以……为乐，对……感到快乐。","tag":"字词释义"},{"s":"下列翻译有误的一项是？","o":["伐竹取道，下见小潭，水尤清冽：砍倒竹子开辟道路，向下看见一个小潭，潭水格外清凉。","潭中鱼可百许头，皆若空游无所依：潭中的鱼大约有一百来条，都好像在空中游动，没有什么依傍。","其岸势犬牙差互，不可知其源：溪岸的形势像狗的牙齿那样交错，不能知道它的源头。","凄神寒骨，悄怆幽邃：神情凄凉，骨头寒冷，寂静幽深。"],"a":"D","e":"D 应为“（这里）使人感到心情凄凉，寒气透骨，幽静深远，弥漫着忧伤的气息”。“凄”“寒”是使动用法（使……凄凉、使……寒冷），不是简单陈述。","tag":"内容理解"},{"s":"下列朗读停顿划分正确的一项是？","o":["从小丘 / 西行百二十步","日光下 / 澈影布石上","其岸 / 势犬牙差互","乃记 / 之而去"],"a":"A","e":"A“从小丘”介词短语后停顿，正确。B 应为“日光/下澈”（“下澈”是偏正，不可拆）；C“其岸势”是主语，不可拆；D 应为“乃/记之而去”。","tag":"断句"},{"s":"文中写潭中游鱼（“俶尔远逝，往来翕忽”）的作用是？","o":["侧面衬托潭水的清澈","直接描写鱼的种类","表现作者喜爱养鱼","与文章主旨无关"],"a":"A","e":"写鱼“皆若空游无所依”、日光下澈影布石上，从侧面衬托潭水之清；“佁然”“俶尔远逝”动静结合，写出游鱼之乐，也暗含作者暂时的愉悦。","tag":"内容理解"},{"s":"下列对本文情感变化的理解，正确的一项是？","o":["由乐到忧","由忧到乐","始终快乐","始终忧伤"],"a":"A","e":"作者初闻水声“心乐之”，见鱼“似与游者相乐”；但“以其境过清”而“凄神寒骨”，流露出贬谪后孤寂悲凉的心境，情感由乐转忧。","tag":"内容理解"},{"s":"“凄神寒骨，悄怆幽邃”在文中的作用是？","o":["渲染凄清的氛围，表达作者贬谪后孤寂悲凉的心境","说明潭水寒冷，环境恶劣","表现作者害怕孤独","与游鱼的快乐形成对比，突出鱼的自由"],"a":"A","e":"这两句融情于景，渲染凄清幽冷的氛围，含蓄地表达了作者被贬后无法排遣的孤寂悲凉之情。","tag":"内容理解"}],"jd":[{"o":"从小丘西行百二十步，隔篁竹，闻水声，如鸣珮环，心乐之。伐竹取道，下见小潭，水尤清冽。全石以为底，近岸，卷石底以出，为坻，为屿，为嵁，为岩。青树翠蔓，蒙络摇缀，参差披拂。","t":"从小土丘往西走约一百二十步，隔着竹林，听到了水流的声音，好像身上佩戴的玉佩、玉环相碰发出的清脆声音，心里对此感到十分高兴。砍伐竹子开辟出一条小路，往下走就看见一个小潭，潭水格外清凉。小潭以整块石头为底，靠近岸边的地方，石底周边部分翻卷过来，露出水面，形成水中高地、小岛、不平的岩石和石岩等各种不同的形状。青葱的树木，翠绿的藤蔓，蒙盖缠绕，摇曳牵连，参差不齐，随风飘拂。","notes":[["西","名词作状语，向西"],["乐","意动用法，以……为乐"],["下","名词作状语，向下"],["以为","把……当作"],["坻","水中高地"],["嵁","不平的岩石"],["蒙络","覆盖缠绕"]]},{"o":"潭中鱼可百许头，皆若空游无所依，日光下澈，影布石上。佁然不动，俶尔远逝，往来翕忽，似与游者相乐。","t":"潭中的鱼大约有一百来条，都好像在空中游动，什么依靠也没有。阳光照到水底，鱼的影子映在水底的石头上。（鱼儿）呆呆地一动不动，忽然间又向远处游去，来来往往轻快敏捷，好像在和游玩的人逗乐。","notes":[["可","大约"],["许","表示约数，左右"],["若","好像"],["澈","穿透"],["佁然","静止不动的样子"],["俶尔","忽然"],["翕忽","轻快敏捷的样子"]]},{"o":"潭西南而望，斗折蛇行，明灭可见。其岸势犬牙差互，不可知其源。","t":"向潭水的西南方向望去，（溪水）像北斗星那样曲折，像蛇那样蜿蜒前行，时隐时现。溪岸的形状像狗的牙齿那样交错不齐，不能够知道它的源头在哪里。","notes":[["西南","名词作状语，向西南"],["斗","名词作状语，像北斗星那样"],["蛇","名词作状语，像蛇那样"],["差互","交错"]]},{"o":"坐潭上，四面竹树环合，寂寥无人，凄神寒骨，悄怆幽邃。以其境过清，不可久居，乃记之而去。","t":"坐在小石潭边上，四面被竹子和树木围绕着，寂静寥落，空无一人，感到心情凄凉，寒气透骨，幽静深远，弥漫着忧伤的气息。因为这里的环境过于凄清，不能长时间停留，于是就把当时的情景记下来便离开了。","notes":[["环合","环绕合抱"],["凄","使动用法，使……凄凉"],["寒","使动用法，使……寒冷"],["悄怆","凄凉，忧伤"],["邃","深"],["以","因为"],["清","凄清"],["乃","于是，就"],["去","离开"]]},{"o":"同游者：吴武陵，龚古，余弟宗玄。隶而从者，崔氏二小生，曰恕己，曰奉壹。","t":"一同去游览的人有：吴武陵、龚古、我的弟弟宗玄。跟着我一同去的，有姓崔的两个年轻人，一个叫恕己，一个叫奉壹。","notes":[["隶","跟随"]]}]},{"no":50,"t":"庄子与惠子游于濠梁","src":"部编版八年级下册·（先秦）《庄子》","tag":"八年级下册","html":true,"p":["庄子与惠子<small>〔惠子〕即惠施，战国时期哲学家，庄子的好友。</small>游于濠梁<small>〔濠梁〕濠水上的桥。濠，水名，在今安徽凤阳。</small>之上。庄子曰：“鲦鱼出游<u>从容</u>，<u>是</u>鱼之乐也。”惠子曰：“子非鱼，<u>安</u>知鱼<u>之</u>乐？”庄子曰：“子非我，安知我不知鱼之乐？”惠子曰：“我非子，<u>固</u>不知子矣；子固非鱼也，子<u>之</u>不知鱼之乐，<u>全</u>矣！”","庄子曰：“请<u>循</u>其<u>本</u>。子曰‘汝<u>安</u>知鱼乐’云者，<u>既</u>已知吾知<u>之</u>而问我，我知之濠上也。”"],"common":"","q":[{"s":"“鲦鱼出游<em class='k'>从容</em>”中“<em class='k'>从容</em>”的意思是？","o":["悠闲自得","从容不迫","急急忙忙","焦躁不安"],"a":"A","e":"“从容”意为“悠闲自得”。“出游从容”即在水里悠闲自在地游动。","tag":"字词释义"},{"s":"“<em class='k'>是</em>鱼之乐也”中“<em class='k'>是</em>”的意思是？","o":["表判断","这","正确","这样"],"a":"B","e":"“是”是指示代词，这。“是鱼之乐也”即这就是鱼的快乐。","tag":"字词释义"},{"s":"“子非鱼，<em class='k'>安</em>知鱼之乐”中“<em class='k'>安</em>”的意思是？","o":["哪里","怎么","安全","为何"],"a":"B","e":"“安”意为“怎么”。“安知鱼之乐”即怎么知道鱼的快乐。","tag":"字词释义"},{"s":"“安知鱼<em class='k'>之</em>乐”中“<em class='k'>之</em>”的用法是？","o":["结构助词，的","代词，它","取消句子独立性","动词，去"],"a":"A","e":"“之”是结构助词，的。“鱼之乐”即鱼的快乐。","tag":"字词释义"},{"s":"“我非子，<em class='k'>固</em>不知子矣”中“<em class='k'>固</em>”的意思是？","o":["坚固","本来","一定","坚持"],"a":"B","e":"“固”意为“本来、固然”。“固不知子矣”即本来不知道你的（想法）。","tag":"字词释义"},{"s":"“子<em class='k'>之</em>不知鱼之乐”中“<em class='k'>之</em>”的用法是？","o":["结构助词，的","取消句子独立性","代词，它","动词，去"],"a":"B","e":"“之”是助词，用在主谓之间，取消句子独立性。\"子之不知鱼之乐\"即你不知道鱼的快乐。","tag":"字词释义"},{"s":"“子之不知鱼之乐，<em class='k'>全</em>矣”中“<em class='k'>全</em>”的意思是？","o":["全部","完全","周全","保全"],"a":"B","e":"“全”意为“完全、完备”。“全矣”即（这说法）完全确定了。","tag":"字词释义"},{"s":"“请<em class='k'>循</em>其本”中“<em class='k'>循</em>”的意思是？","o":["遵循","追溯","循环","按照"],"a":"B","e":"“循”意为“沿循、追溯”。“循其本”即追溯话题的本源。","tag":"字词释义"},{"s":"“请循其<em class='k'>本</em>”中“<em class='k'>本</em>”的意思是？","o":["本来","本源","基础","书籍"],"a":"B","e":"“本”意为“本源、根本”。“循其本”即追溯到话题的本源。","tag":"字词释义"},{"s":"“子曰‘汝<em class='k'>安</em>知鱼乐’云者”中“<em class='k'>安</em>”的意思是？","o":["哪里","怎么","安全","为何"],"a":"A","e":"庄子在辩论中已把“安”的词义由“怎么”偷换为“哪里”，故此处“汝安知鱼乐”的“安”意为“在哪里”。","tag":"字词释义"},{"s":"“<em class='k'>既</em>已知吾知之而问我”中“<em class='k'>既</em>”的意思是？","o":["既然","已经","即使","不久"],"a":"B","e":"“既”意为“已经”。“既已知吾知之”即已经知道我知道（鱼快乐）这件事。","tag":"字词释义"},{"s":"“已知吾知<em class='k'>之</em>而问我”中“<em class='k'>之</em>”的意思是？","o":["结构助词，的","代词，它","取消句子独立性","动词，去"],"a":"B","e":"“之”是代词，代“鱼之乐”（鱼快乐这件事）。","tag":"字词释义"},{"s":"“庄子与惠子游于濠梁之上”属于哪种文言句式？","o":["判断句","状语后置","宾语前置","被动句"],"a":"B","e":"“于濠梁之上”是后置的介词短语（状语），正常语序为“庄子与惠子于濠梁之上游”，属状语后置句。","tag":"内容理解"},{"s":"“是鱼之乐也”句式判断正确的一项是？","o":["省略句","判断句","状语后置","反问句"],"a":"B","e":"“是”作主语（这），“……也”表判断，是判断句。","tag":"内容理解"},{"s":"下列对倒装句“庄子与惠子游于濠梁之上”调整语序正确的一项是？","o":["濠梁之上庄子与惠子游","庄子与惠子于濠梁之上游","庄子于濠梁之上与惠子游","于濠梁之上游庄子与惠子"],"a":"B","e":"“于濠梁之上”是后置状语，提前到谓语“游”前，正常语序为“庄子与惠子于濠梁之上游”。","tag":"内容理解"},{"s":"下列不属于判断句的一项是？","o":["子固非鱼也","菊，花之隐逸者也","我知之濠上也","是鱼之乐也"],"a":"C","e":"C“我知之濠上也”是陈述句（“之”代“鱼之乐”，“濠上”为处所补语），虽有“也”但不是判断句。A“子固非鱼也”、B“菊，花之隐逸者也”（《爱莲说》）、D“是鱼之乐也”均为判断句。","tag":"内容理解"},{"s":"对“鲦鱼出游从容，是鱼之乐也”翻译最准确的一项是？","o":["白鲦鱼游出去十分从容，这是鱼的快乐。","鲦鱼悠闲自在地游动，这就是鱼的快乐啊。","鲦鱼出门游玩不慌不忙，是鱼儿快乐的地方。","鲦鱼游动从容，所以鱼很快乐。"],"a":"B","e":"“出游从容”即悠闲自在地游动，“是鱼之乐也”即这就是鱼的快乐。B 最准确。","tag":"内容理解"},{"s":"下列翻译有误的一项是？","o":["子非鱼，安知鱼之乐：你不是鱼，怎么知道鱼的快乐？","我非子，固不知子矣：我不是你，固然不知道你。","子固非鱼也，子之不知鱼之乐，全矣：你本来就不是鱼，你不知道鱼的快乐，是完全肯定的。","请循其本：请遵循书本上的道理。"],"a":"D","e":"D 误译。“请循其本”意为“请追溯话题的本源”，不是“遵循书本上的道理”。","tag":"内容理解"},{"s":"对“既已知吾知之而问我，我知之濠上也”翻译理解正确的一项是？","o":["你已经知道我懂鱼，却还质问我，我在濠水桥上知晓这件事。","你早就知道鱼很快乐，跑来问我，我在桥上看见鱼。","你已经认定我不懂鱼，所以追问我，我在濠梁观察鱼。","你明明知道鱼的快乐，还来试探我，我在桥上得知。"],"a":"A","e":"“既已知吾知之”即你已经知道我知道（鱼快乐）这件事；“我知之濠上也”即我是在濠水的桥上知道的。A 最准确。","tag":"内容理解"},{"s":"下列朗读停顿划分正确的一项是？","o":["庄子与惠子 / 游于濠梁之上","鲦鱼出游 / 从容，是鱼 / 之乐也","子之不知 / 鱼之乐全矣","既已知吾 / 知之而问我"],"a":"A","e":"A 正确，主语后停顿。B 应为“鲦鱼出游从容 / 是鱼之乐也”；C 应为“子之不知鱼之乐 / 全矣”；D 应为“既已知吾知之 / 而问我”。","tag":"断句"},{"s":"下列断句划分有误的一项是？","o":["子 / 非鱼，安知 / 鱼之乐","请 / 循其本","我非子 / 固不知子矣","我知之 / 濠上也"],"a":"D","e":"D 有误。“我知之濠上也”意为“我是在濠水的桥上知道的”，“濠上”是“知”的处所补语（省略介词“于”），正确停顿为“我知之濠上 / 也”，不应在“之”后断开。","tag":"断句"},{"s":"惠子说“子非鱼，安知鱼之乐”，句中“安”的本意与追问角度是？","o":["哪里，询问知晓鱼之乐的地点","怎么，询问知晓鱼之乐的方式、依据","难道，反问庄子不该揣测鱼","平安，质疑庄子心态浮躁"],"a":"B","e":"“安”本意为“怎么”，惠子是追问庄子凭什么（依据什么）知道鱼快乐，从逻辑推理的角度发问。","tag":"内容理解"},{"s":"庄子结尾“请循其本”偷换“安”的词义，将“安知”理解为？","o":["怎么知道","凭什么知道","在哪里知道","为何知道"],"a":"C","e":"庄子将惠子“安知”的“怎么（凭什么）”偷换为“在哪里”，从而回答“我知之濠上也”（我在濠水桥上知道的），巧妙地化解了惠子的诘难。","tag":"内容理解"},{"s":"庄子看见鱼“出游从容”便判定“是鱼之乐”，体现他怎样的思想？","o":["凡事必须依靠逻辑推理才能得出结论","物我相融，以自身心境投射外物，直观感受自然之美","只有亲身变成鱼，才能知晓鱼的感受","世间万物都拥有与人相同的喜怒哀乐"],"a":"B","e":"庄子从自身悠闲愉悦的心境出发，移情于鱼，认为鱼也快乐，体现了物我相融、以心观物的审美视角。","tag":"内容理解"},{"s":"文章以二人辩论收尾，没有给出统一结论，写作用意是？","o":["说明二人辩论无果，没有意义","对比两种认知世界的方式：惠子理性逻辑，庄子感性审美","暗示庄子的观点才是唯一正确答案","批判惠子死板，不懂欣赏自然"],"a":"B","e":"辩论无定论，正是要展现两种认知方式的差异：惠子以逻辑理性追问，庄子以审美直觉感受，二者各有价值，无需分出对错。","tag":"内容理解"},{"s":"下列对全文主旨理解最深刻的一项是？","o":["本文只是记录庄子与惠子一场无聊的口舌之争","通过濠梁观鱼的辩论，展现惠子强大的逻辑思辨能力","借辩论区分两种人生视角：惠子重客观认知，庄子重精神与自然相融的审美体验","证明人可以不用亲身经历，就能感知万物的情绪"],"a":"C","e":"本文借濠梁之辩，展现惠子重客观逻辑的认知方式与庄子重精神体验、物我相融的审美方式的对立与互补，蕴含深刻的哲学意味。","tag":"内容理解"}],"jd":[{"o":"庄子与惠子游于濠梁之上。庄子曰：“鲦鱼出游从容，是鱼之乐也。”惠子曰：“子非鱼，安知鱼之乐？”庄子曰：“子非我，安知我不知鱼之乐？”惠子曰：“我非子，固不知子矣；子固非鱼也，子之不知鱼之乐，全矣！”","t":"庄子和惠子在濠水的桥上游玩。庄子说：“鲦鱼在河水中游得多么悠闲自得，这就是鱼儿的快乐呀。”惠子说：“你又不是鱼，怎么知道鱼是快乐的呢？”庄子说：“你不是我，怎么知道我不知道鱼儿的快乐呢？”惠子说：“我不是你，固然不知道你（的想法）；你本来就不是鱼，你不知道鱼的快乐，这是可以完全确定的！”","notes":[["从容","悠闲自得"],["是","代词，这"],["安","怎么"],["之","结构助词，的"],["固","固然，本来"],["之","助词，取消句子独立性"],["全","完全，完备"]]},{"o":"庄子曰：“请循其本。子曰‘汝安知鱼乐’云者，既已知吾知之而问我，我知之濠上也。”","t":"庄子说：“请追溯话题本源。你说‘你怎么知道鱼快乐’这样的话，说明你已经知道我知道鱼快乐才来问我。我是在濠水的桥上知道的啊。”","notes":[["循","沿循，追溯"],["本","本源，根本"],["安","怎么"],["既","已经"],["之","代词，代“鱼之乐”"]]}]},{"no":51,"t":"核舟记","src":"部编版八年级下册·（明）魏学洢","tag":"八年级下册","html":true,"p":["明有奇巧人<u>曰</u>王叔远，能以径寸之木，<u>为</u>宫室、器皿、人物，以至鸟兽、木石，<u>罔不</u><u>因</u>势<u>象</u>形，各具情态。尝<u>贻</u>余核舟一，<u>盖</u>大苏<u>泛</u>赤壁云。","舟首尾长约八分有<u>奇</u>，高可二黍<u>许</u>。中<u>轩敞</u>者为舱，箬篷覆之。旁开小窗，左右各四，共八扇。启窗而观，雕栏<u>相望</u>焉。闭之，则右刻“山高月小，水落石出”，左刻“清风徐来，水波不兴”，石青<u>糁</u>之。","船头坐三人，中峨冠而多髯者为东坡，佛印<small>〔佛印（1032—1098）〕宋代名僧，苏轼的朋友。</small>居右，鲁直<small>〔鲁直〕宋代文学家黄庭坚（1045—1105），字鲁直，苏轼的朋友。</small>居左。苏、黄共阅一手卷。东坡右手执卷端，左手抚鲁直背。鲁直左手执卷末，右手指卷，如有所语。东坡现右足，鲁直现左足，各微侧，其两膝相<u>比</u>者，各隐卷底衣褶中。佛印<u>绝类</u>弥勒，袒胸露乳，<u>矫</u>首昂视，神情与苏、黄不<u>属</u>。卧右膝，<u>诎</u>右臂支船，而竖其左膝，左臂挂念珠倚之——珠可<u>历历</u>数也。","舟尾横卧一楫。楫左右<u>舟子</u>各一人。居右者椎髻仰面，左手倚一<u>衡</u>木，右手攀右趾，<u>若</u>啸呼状。居左者右手执蒲葵扇，左手抚炉，炉上有壶，其人视<u>端</u>容寂，若听茶声<u>然</u>。","其船背稍<u>夷</u>，则题名其上，文曰“天启壬戌秋日，虞山王毅叔远甫<small>〔虞山王毅叔远甫〕常熟人王毅字叔远。虞山，山名，在今江苏常熟西北，这里用来代指常熟。甫，男子美称，多附于字之后。</small>刻”，细若蚊足，钩画<u>了了</u>，其色墨。又用篆章一，文曰“初平山人”，其色丹。","通计一舟，为人五；为窗八；为箬篷，为楫，为炉，为壶，为手卷，为念珠各一；对联、题名并篆文，为字共三十有四。而计其长<u>曾</u>不<u>盈寸</u>。盖<u>简</u>桃核<u>修狭</u>者为之。嘻，技亦灵怪矣哉！"],"common":"","q":[{"s":"“明有奇巧人<em class='k'>曰</em>王叔远”中“<em class='k'>曰</em>”的意思是？","o":["说","叫作","是","认为"],"a":"B","e":"“曰”意为“叫作、叫做”。\"明有奇巧人曰王叔远\"即明朝有个手艺奇妙精巧的人叫王叔远。","tag":"字词释义"},{"s":"“能以径寸之木，<em class='k'>为</em>宫室”中“<em class='k'>为</em>”的意思是？","o":["作为","雕刻","成为","因为"],"a":"B","e":"“为”意为“做”，这里指雕刻。","tag":"字词释义"},{"s":"“<em class='k'>罔不</em>因势象形”中“<em class='k'>罔不</em>”的意思是？","o":["没有","全都","不是","不必"],"a":"B","e":"“罔不”意为“无不、全都”。\"罔不因势象形\"即全都是就着材料原来的样子刻成各种事物的形象。","tag":"字词释义"},{"s":"“罔不<em class='k'>因</em>势象形”中“<em class='k'>因</em>”的意思是？","o":["因为","于是","顺着","根据"],"a":"C","e":"“因”意为“顺着、就着”。“因势象形”即就着材料原来的样子雕刻形象。","tag":"字词释义"},{"s":"“罔不因势<em class='k'>象</em>形”中“<em class='k'>象</em>”的意思是？","o":["形象","模仿","想象","象征"],"a":"B","e":"“象”意为“模拟、模仿”。“象形”即刻成事物的形象。","tag":"字词释义"},{"s":"“尝<em class='k'>贻</em>余核舟一”中“<em class='k'>贻</em>”的意思是？","o":["遗留","赠送","带来","给予"],"a":"B","e":"“贻”意为“赠送”。","tag":"字词释义"},{"s":"“<em class='k'>盖</em>大苏泛赤壁云”中“<em class='k'>盖</em>”的意思是？","o":["盖子","大概","因为","原来"],"a":"B","e":"“盖”是句首语气词，表示推测，大概。","tag":"字词释义"},{"s":"“盖大苏<em class='k'>泛</em>赤壁云”中“<em class='k'>泛</em>”的意思是？","o":["漂浮","广泛","泛舟","泛滥"],"a":"C","e":"“泛”意为“泛舟、乘船游览”。“泛赤壁”即乘船游览赤壁。","tag":"字词释义"},{"s":"“舟首尾长约八分有<em class='k'>奇</em>”中“<em class='k'>奇</em>”的意思是？","o":["奇怪","零数","奇数","特别"],"a":"B","e":"“奇”读 jī，意为“零数、余数”。“八分有奇”即八分多一点。","tag":"字词释义"},{"s":"“高可二黍<em class='k'>许</em>”中“<em class='k'>许</em>”的意思是？","o":["允许","也许","左右","许多"],"a":"C","e":"“许”表示约数，上下、左右。“二黍许”即两个黄米粒上下。","tag":"字词释义"},{"s":"“中<em class='k'>轩敞</em>者为舱”中“<em class='k'>轩敞</em>”的意思是？","o":["高大","宽敞","高敞","明亮"],"a":"C","e":"“轩敞”意为“高起而宽敞”。","tag":"字词释义"},{"s":"“雕栏<em class='k'>相望</em>焉”中“<em class='k'>相望</em>”的意思是？","o":["互相看望","左右相对","彼此遥望","相互期待"],"a":"B","e":"“相望”意为“左右相对”。","tag":"字词释义"},{"s":"“石青<em class='k'>糁</em>之”中“<em class='k'>糁</em>”的意思是？","o":["饭粒","涂抹","点缀","混入"],"a":"B","e":"“糁”意为“涂”。“石青糁之”即用石青涂在刻字的凹处。","tag":"字词释义"},{"s":"“其两膝相<em class='k'>比</em>者”中“<em class='k'>比</em>”的意思是？","o":["比较","靠近","并列","相比"],"a":"B","e":"“比”意为“靠近”。“其两膝相比者”即他们互相靠近的两膝。","tag":"字词释义"},{"s":"“佛印<em class='k'>绝类</em>弥勒”中“<em class='k'>绝类</em>”的意思是？","o":["极像","断绝","完全不同","绝无"],"a":"A","e":"“绝类”意为“极像”。","tag":"字词释义"},{"s":"“<em class='k'>矫</em>首昂视”中“<em class='k'>矫</em>”的意思是？","o":["矫正","举起","骄傲","挺直"],"a":"B","e":"“矫”意为“举”。“矫首昂视”即抬头仰望。","tag":"字词释义"},{"s":"“神情与苏、黄不<em class='k'>属</em>”中“<em class='k'>属</em>”的意思是？","o":["属于","类似","连接","嘱咐"],"a":"B","e":"“属”意为“类似”。“不属”即不相类似。","tag":"字词释义"},{"s":"“<em class='k'>诎</em>右臂支船”中“<em class='k'>诎</em>”的意思是？","o":["弯曲","屈服","伸直","委屈"],"a":"A","e":"“诎”同“屈”，意为“弯曲”。","tag":"字词释义"},{"s":"“珠可<em class='k'>历历</em>数也”中“<em class='k'>历历</em>”的意思是？","o":["历史","清楚","经历","历次"],"a":"B","e":"“历历”意为“分明可数、清清楚楚”。","tag":"字词释义"},{"s":"“楫左右<em class='k'>舟子</em>各一人”中“<em class='k'>舟子</em>”的意思是？","o":["小船","撑船的人","船桨","船员"],"a":"B","e":"“舟子”意为“撑船的人”。","tag":"字词释义"},{"s":"“左手倚一<em class='k'>衡</em>木”中“<em class='k'>衡</em>”的意思是？","o":["衡量","平衡","横","称量"],"a":"C","e":"“衡”是通假字，通“横”。“左手倚一衡木”即左手靠着一根横木。","tag":"字词释义"},{"s":"“<em class='k'>若</em>啸呼状”中“<em class='k'>若</em>”的意思是？","o":["如果","好像","假若","倘若"],"a":"B","e":"“若”意为“好像”。“若啸呼状”即好像在大声呼喊的样子。","tag":"字词释义"},{"s":"“其人视<em class='k'>端</em>容寂”中“<em class='k'>端</em>”的意思是？","o":["端正","一端","端详","端庄"],"a":"A","e":"“端”意为“正”。“视端容寂”即眼睛正视（茶炉），神色平静。","tag":"字词释义"},{"s":"“若听茶声<em class='k'>然</em>”中“<em class='k'>然</em>”的意思是？","o":["然后","然而","……的样子","对"],"a":"C","e":"“然”意为“……的样子”。“若听茶声然”即好像在听茶水烧开了没有的样子。","tag":"字词释义"},{"s":"“其船背稍<em class='k'>夷</em>”中“<em class='k'>夷</em>”的意思是？","o":["平坦","平安","铲平","蛮夷"],"a":"A","e":"“夷”意为“平”。","tag":"字词释义"},{"s":"“钩画<em class='k'>了了</em>”中“<em class='k'>了了</em>”的意思是？","o":["结束","清楚","了解","了结"],"a":"B","e":"“了了”意为“清清楚楚”。","tag":"字词释义"},{"s":"“而计其长<em class='k'>曾</em>不盈寸”中“<em class='k'>曾</em>”的意思是？","o":["曾经","竟然","才","曾经，副词"],"a":"B","e":"“曾”意为“竟然”。“曾不盈寸”即竟然不满一寸。","tag":"字词释义"},{"s":"“而计其长曾不<em class='k'>盈寸</em>”中“<em class='k'>盈寸</em>”的意思是？","o":["满一寸","一寸多","不足一寸","一寸左右"],"a":"A","e":"“盈寸”意为“满一寸”。","tag":"字词释义"},{"s":"“盖<em class='k'>简</em>桃核修狭者为之”中“<em class='k'>简</em>”的意思是？","o":["简单","挑选","简略","简明"],"a":"B","e":"“简”意为“挑选”。","tag":"字词释义"},{"s":"“盖简桃核<em class='k'>修狭</em>者为之”中“<em class='k'>修狭</em>”的意思是？","o":["修长的","狭窄的","宽阔的","修长狭窄的"],"a":"D","e":"“修狭”意为“长而窄、修长狭窄”。","tag":"字词释义"},{"s":"下列加点字词类活用类型与“石青糁之”中“石青”相同的一项是？","o":["中峨冠而多髯者为东坡","斗折蛇行（《小石潭记》）","凄神寒骨（《小石潭记》）","心乐之（《小石潭记》）"],"a":"B","e":"“石青”名词作状语，用石青；“斗”“蛇”名词作状语，像北斗星那样、像蛇那样，活用类型相同。A 峨冠名词作动词；C 使动；D 意动。","tag":"字词释义"},{"s":"对“中峨冠而多髯者为东坡”中加点词“峨冠”用法分析正确的一项是？","o":["峨冠，名词，高高的帽子","峨冠，名词作动词，戴着高高的帽子","峨冠，形容词，高大的","峨冠，无词类活用"],"a":"B","e":"“峨冠”名词作动词，意为“戴着高高的帽子”。","tag":"字词释义"},{"s":"下列对“罔不因势象形，各具情态”翻译准确的一项是？","o":["全部顺着材料原来的样子雕刻形象，各有各的神情姿态","没有根据材料形状随便雕刻，神情各不相同","全都不依据木头形状，凭空雕刻人物神态","顺着局势塑造形象，每个人姿态不同"],"a":"A","e":"“罔不因势象形，各具情态”意为“全都是就着材料原来的样子刻成各种事物的形象，各有各的神情姿态”。B 曲解“罔不”；C 曲解“因势”；D 误译“势”。","tag":"内容理解"},{"s":"下列翻译有误的一项是？","o":["尝贻余核舟一：（他）曾经赠给我一只用桃核雕刻成的小船。","启窗而观，雕栏相望焉：推开窗户来看，雕刻着花纹的栏杆左右相对。","其两膝相比者：他们互相比较两条膝盖。","盖简桃核修狭者为之：原来是挑选长而窄的桃核雕刻而成的。"],"a":"C","e":"C 误译。“比”意为“靠近”，“其两膝相比者”应为“他们互相靠近的两膝”。","tag":"内容理解"},{"s":"下列朗读停顿划分正确的一项是？","o":["明有奇巧人 / 曰王叔远","中峨冠 / 而多髯者为东坡","盖简桃核 / 修狭者为之","虞山王毅叔远 / 甫刻"],"a":"A","e":"A 正确。B 应为“中 / 峨冠而多髯者 / 为东坡”（“中”是状语，表位置）；C 应为“盖 / 简桃核修狭者 / 为之”；D 中“甫”是男子美称，应附于“叔远”后，作“虞山王毅叔远甫 / 刻”。","tag":"断句"},{"s":"文章开篇写“能以径寸之木，为宫室、器皿、人物……”，作用是？","o":["说明王叔远雕刻材料十分丰富","总起全文，概括雕刻家技艺高超，为下文核舟细节描写做铺垫","交代作者收集了许多雕刻作品","对比突出桃核是最难雕刻的材料"],"a":"B","e":"开篇总起，以“径寸之木”与“宫室、器皿、人物”的巨大反差突出王叔远技艺高超，为下文核舟的精细描写做铺垫。","tag":"内容理解"},{"s":"文中刻画苏轼、黄鲁直、佛印三人神态动作，下列理解错误的一项是？","o":["苏、黄共阅一手卷，凸显二人文人雅士闲适相交的氛围","佛印袒胸露乳、矫首昂视，表现他洒脱不羁、超脱世俗的气质","三人形象对比鲜明，丰富雕刻画面，侧面体现雕刻技艺精巧","佛印嫌弃书卷乏味，独自抬头观景，与苏黄二人产生隔阂"],"a":"D","e":"D 错误。佛印“矫首昂视”是表现他超脱世俗的僧人形象，并非“嫌弃书卷”“产生隔阂”，文中无此意。","tag":"内容理解"},{"s":"文末统计核舟上人、物、字数量，又感叹“技亦灵怪矣哉”，分析不正确的一项是？","o":["用具体数字直观体现桃核上雕刻内容繁多，形成强烈反差","结尾抒情，直接抒发对微雕技艺的赞叹，收束全文","与开头“奇巧”一词前后呼应，结构完整","意在说明桃核材质特殊，天然适合雕刻大量文字人物"],"a":"D","e":"D 错误。文末统计不是说明“桃核材质特殊”，而是以数量之多与体积之小形成反差，突出雕刻技艺的精湛。","tag":"内容理解"},{"s":"下列对文章写法与主旨理解深度分析，最准确的一项是？","o":["本文只客观介绍核舟外形，没有蕴含作者主观情感","作者借一枚小小的核舟，赞美古代民间手工艺人高超的雕刻技艺","文章主要表达作者对苏轼泛舟赤壁这一历史故事的喜爱","文中舟子的刻画多余，只是为了填充核舟空白位置"],"a":"B","e":"本文通过对核舟上人物、器物细致传神的描写，赞美雕刻者高超的技艺和古代劳动人民的聪明才智。","tag":"内容理解"},{"s":"文中左右窗刻有“山高月小，水落石出”“清风徐来，水波不兴”，安排这两处文字的作用是？","o":["只是装饰窗户，让核舟外观更好看","引用苏轼《赤壁赋》《后赤壁赋》名句，贴合“大苏泛赤壁”主题，丰富文化意境","证明雕刻者擅长书法，雕刻字迹工整清晰","区分左右两扇窗户，方便辨识"],"a":"B","e":"这两句分别出自苏轼《后赤壁赋》《赤壁赋》，与核舟“大苏泛赤壁”的主题相呼应，丰富了文化内涵，也体现雕刻之精细。","tag":"内容理解"}],"jd":[{"o":"明有奇巧人曰王叔远，能以径寸之木，为宫室、器皿、人物，以至鸟兽、木石，罔不因势象形，各具情态。尝贻余核舟一，盖大苏泛赤壁云。","t":"明朝有个手艺奇妙精巧的人叫王叔远，他能够用直径一寸的木头，雕刻出宫殿、器具、人物，甚至飞鸟、走兽、树木、石头，全都是就着材料原来的样子刻成各种事物的形象，各有各的神情姿态。（他）曾经送给我一个用桃核雕刻成的小船，刻的是苏轼乘船游赤壁的情景。","notes":[["曰","叫作，叫做"],["为","做，这里指雕刻"],["罔不","无不，全都"],["因","顺着，就着"],["象","模拟，模仿"],["贻","赠送"],["盖","句首语气词，大概"],["泛","泛舟，乘船游览"]]},{"o":"舟首尾长约八分有奇，高可二黍许。中轩敞者为舱，箬篷覆之。旁开小窗，左右各四，共八扇。启窗而观，雕栏相望焉。闭之，则右刻“山高月小，水落石出”，左刻“清风徐来，水波不兴”，石青糁之。","t":"小船从船头到船尾长度大约八分多一点，高度大约有两个黄米粒。中间高起而宽敞的部分是船舱，用箬竹叶做的船篷覆盖着它。船舱旁边开有小窗，左右两边各有四扇，一共八扇。打开窗户来看，雕刻着花纹的栏杆左右相对。关上窗户，就看到右边刻着“山高月小，水落石出”，左边刻着“清风徐来，水波不兴”，用石青涂在刻字的凹处。","notes":[["奇","零数，余数"],["许","表示约数，上下，左右"],["轩敞","高起而宽敞"],["相望","左右相对"],["糁","涂"]]},{"o":"船头坐三人，中峨冠而多髯者为东坡，佛印居右，鲁直居左。苏、黄共阅一手卷。东坡右手执卷端，左手抚鲁直背。鲁直左手执卷末，右手指卷，如有所语。东坡现右足，鲁直现左足，各微侧，其两膝相比者，各隐卷底衣褶中。佛印绝类弥勒，袒胸露乳，矫首昂视，神情与苏、黄不属。卧右膝，诎右臂支船，而竖其左膝，左臂挂念珠倚之——珠可历历数也。","t":"船头坐着三个人，中间戴着高高的帽子且胡须浓密的是苏东坡，佛印在右边，鲁直在左边。苏东坡和黄鲁直共同看着一幅书画长卷。东坡右手拿着画卷的右端，左手轻按在鲁直的背上。鲁直左手拿着画卷的左端，右手指着画卷，好像在说着什么。东坡露出右脚，鲁直露出左脚，身子都略微侧斜，他们互相靠近的两膝，各自隐藏在手卷下边的衣褶里。佛印极像弥勒佛，袒露着胸脯，露出乳头，抬头仰望，神情和苏东坡、黄鲁直不相类似。（佛印）平放着右膝，弯曲右臂支撑在船上，竖起他的左膝，左臂挂着念珠靠在左膝上——念珠可以清清楚楚地数出来。","notes":[["比","靠近"],["绝类","极像"],["矫","举"],["属","类似"],["诎","同“屈”，弯曲"],["历历","分明可数，清清楚楚"]]},{"o":"舟尾横卧一楫。楫左右舟子各一人。居右者椎髻仰面，左手倚一衡木，右手攀右趾，若啸呼状。居左者右手执蒲葵扇，左手抚炉，炉上有壶，其人视端容寂，若听茶声然。","t":"船尾横放着一支船桨。船桨的左右两边各有一个撑船的人。在右边的撑船人梳着椎形发髻，仰着脸，左手靠着一根横木，右手扳着右脚趾头，好像在大声呼喊的样子。在左边的撑船人右手拿着一把蒲葵扇，左手抚摸着炉子，炉子上有一把水壶，那个人眼睛正视着（茶炉），神色平静，好像在听茶水烧开了没有的样子。","notes":[["舟子","撑船的人"],["衡","同“横”"],["若","好像"],["端","正"],["然","……的样子"]]},{"o":"其船背稍夷，则题名其上，文曰“天启壬戌秋日，虞山王毅叔远甫刻”，细若蚊足，钩画了了，其色墨。又用篆章一，文曰“初平山人”，其色丹。","t":"船的顶部比较平坦，就在上面刻上名字，文字是“天启壬戌秋日，虞山王毅叔远甫刻”，笔画细得像蚊子的腿，一笔一画清清楚楚，字的颜色是黑色。又使用了一枚篆字图章，文字是“初平山人”，字的颜色是红色。","notes":[["夷","平"],["了了","清清楚楚"]]},{"o":"通计一舟，为人五；为窗八；为箬篷，为楫，为炉，为壶，为手卷，为念珠各一；对联、题名并篆文，为字共三十有四。而计其长曾不盈寸。盖简桃核修狭者为之。嘻，技亦灵怪矣哉！","t":"总计这一条船上，刻了五个人；刻了八扇窗户；刻了箬竹叶做的船篷、船桨、炉子、茶壶、手卷、念珠各一件；对联、题名和篆文，刻的字总共三十四个。可是计算它的长度竟然不满一寸。原来是挑选长而窄的桃核雕刻成的。啊，技艺也真是奇妙神奇啊！","notes":[["曾","竟然"],["盈寸","满一寸"],["简","挑选"],["修狭","长而窄"]]}]},{"no":52,"t":"桃花源记","src":"部编版八年级下册·（晋）陶渊明","tag":"八年级下册","html":true,"p":["晋太元<small>〔太元〕东晋孝武帝年号（376—396）。</small>中，武陵人捕鱼为业。<u>缘</u>溪行，忘路之远近。忽逢桃花林，<u>夹岸</u>数百步，中无杂树，芳草<u>鲜美</u>，<u>落英</u><u>缤纷</u>。渔人甚异之，复<u>前</u>行，欲<u>穷</u>其林。","<u>林尽水源</u>，便得一山，山有小口，<u>仿佛</u>若有光。便舍船，从口入。初极狭，才通人。复行数十步，豁然开朗。土地平旷，屋舍<u>俨然</u>，有良田、美池、桑竹之<u>属</u>。","阡陌<small>〔阡陌〕田间小路。</small><u>交通</u>，鸡犬相闻。其中往来种作，男女衣着，<u>悉</u>如外人。黄发垂髫<small>〔黄发垂髫〕指老人和小孩。黄发，旧说是长寿的特征，用来指老人。垂髫，垂下来的头发，用来指小孩。</small>，<u>并</u>怡然自乐。","见渔人，<u>乃</u>大惊，问所从来。<u>具</u>答之。便<u>要</u>还家，设酒杀鸡作食。村中闻有此人，<u>咸</u>来问讯。自云先世避秦时乱，率<u>妻子</u>邑人来此<u>绝境</u>，不复出<u>焉</u>，遂与外人<u>间隔</u>。","问今是何世，<u>乃</u>不知有汉，<u>无论</u>魏晋。此人一一为<u>具</u>言所闻，皆叹惋。余人各复<u>延</u>至其家，皆出酒食。停数日，辞去。此中人语云：“<u>不足</u>为外人道也。”","<u>既</u>出，得其船，便<u>扶</u>向路，处处<u>志</u>之。及郡下<small>〔及郡下〕到了郡城。及，到。郡，指武陵郡。</small>，<u>诣</u>太守，说如此。太守即遣人随其往，寻<u>向</u>所志，遂迷，不复得路。","南阳<small>〔南阳〕郡名，在今河南南阳一带。</small>刘子骥<small>〔刘子骥〕名驎之，字子骥，《晋书·隐逸传》里说他“好游山泽”。</small>，高尚士也，闻之，欣然<u>规</u>往。<u>未果</u>，<u>寻</u>病终。后<u>遂</u>无问<u>津</u>者。"],"common":"","q":[{"s":"“<em class='k'>缘</em>溪行”中“<em class='k'>缘</em>”的意思是？","o":["沿着","缘由","因为","缘分"],"a":"A","e":"“缘”意为“沿着、顺着”。“缘溪行”即顺着溪水划行。","tag":"字词释义"},{"s":"“<em class='k'>夹岸</em>数百步”中“<em class='k'>夹岸</em>”的意思是？","o":["两岸","夹着岸","岸边","两岸之间"],"a":"A","e":"“夹岸”即两岸。","tag":"字词释义"},{"s":"“芳草<em class='k'>鲜美</em>”中“<em class='k'>鲜美</em>”的意思是？","o":["鲜艳","新鲜美味","味道鲜美","鲜嫩美丽"],"a":"D","e":"“鲜美”意为“鲜嫩美丽”，是古今异义词（今义指味道鲜美）。","tag":"字词释义"},{"s":"“<em class='k'>落英</em>缤纷”中“<em class='k'>落英</em>”的意思是？","o":["落花","花","花瓣","落叶"],"a":"A","e":"“落英”指落花。“英”指花。","tag":"字词释义"},{"s":"“落英<em class='k'>缤纷</em>”中“<em class='k'>缤纷</em>”的意思是？","o":["繁多而错杂的样子","缤纷（今义）","纷纷","繁多"],"a":"A","e":"“缤纷”形容落花繁多而错杂的样子。","tag":"字词释义"},{"s":"“复<em class='k'>前</em>行”中“<em class='k'>前</em>”的活用和意思是？","o":["名词作状语，向前","前面","前进","先前"],"a":"A","e":"“前”名词作状语，意为“向前”。“复前行”即又向前划行。","tag":"字词释义"},{"s":"“欲<em class='k'>穷</em>其林”中“<em class='k'>穷</em>”的意思是？","o":["走到尽头","贫穷","穷尽","困窘"],"a":"A","e":"“穷”意为“走到尽头”。“欲穷其林”即想要走到林子尽头。","tag":"字词释义"},{"s":"“林尽水源”的特殊句式是？","o":["判断句","宾语前置","状语后置","被动句"],"a":"C","e":"“林尽水源”即“林尽（于）水源”，桃花林在溪水发源处就到头了，是状语后置，省略介词“于”。","tag":"特殊句式"},{"s":"“<em class='k'>仿佛</em>若有光”中“<em class='k'>仿佛</em>”的意思是？","o":["仿佛（今义）","隐隐约约","好像","相似"],"a":"B","e":"“仿佛”意为“隐隐约约，好像”。","tag":"字词释义"},{"s":"“屋舍<em class='k'>俨然</em>”中“<em class='k'>俨然</em>”的意思是？","o":["整齐的样子","俨然（今义）","严肃","整齐"],"a":"A","e":"“俨然”意为“整齐的样子”。“屋舍俨然”即房屋整整齐齐。","tag":"字词释义"},{"s":"“桑竹之<em class='k'>属</em>”中“<em class='k'>属</em>”的意思是？","o":["类","属于","归属","嘱咐"],"a":"A","e":"“属”意为“类”。“桑竹之属”即桑树竹林之类。","tag":"字词释义"},{"s":"“阡陌<em class='k'>交通</em>”中“<em class='k'>交通</em>”的意思是？","o":["相通","交通运输","交通（今义）","交错相通"],"a":"D","e":"“交通”意为“交错相通”，是古今异义词（今义指交通运输）。","tag":"字词释义"},{"s":"“男女衣着，<em class='k'>悉</em>如外人”中“<em class='k'>悉</em>”的意思是？","o":["全，都","熟悉","详细","知道"],"a":"A","e":"“悉”意为“全、都”。“悉如外人”即全都和外面的人一样。","tag":"字词释义"},{"s":"“<em class='k'>并</em>怡然自乐”中“<em class='k'>并</em>”的意思是？","o":["都，一起","并且","并列","合并"],"a":"A","e":"“并”意为“都、一起”。“并怡然自乐”即都安闲快乐。","tag":"字词释义"},{"s":"“见渔人，<em class='k'>乃</em>大惊”中“<em class='k'>乃</em>”的意思是？","o":["于是，就","才","竟然","却"],"a":"A","e":"“乃”意为“于是、就”。看见渔人，于是十分惊奇。","tag":"字词释义"},{"s":"“<em class='k'>具</em>答之”中“<em class='k'>具</em>”的意思是？","o":["工具","详尽","具备","具有"],"a":"B","e":"“具”意为“详尽、详细”。“具答之”即详尽地回答。","tag":"字词释义"},{"s":"“便<em class='k'>要</em>还家”中“<em class='k'>要</em>”的意思是？","o":["同“邀”，邀请","重要","要求","需要"],"a":"A","e":"“要”同“邀”，邀请。“便要还家”即就邀请（渔人）到自己家。","tag":"字词释义"},{"s":"“<em class='k'>咸</em>来问讯”中“<em class='k'>咸</em>”的意思是？","o":["全，都","咸味","咸（今义）","皆"],"a":"A","e":"“咸”意为“全、都”。“咸来问讯”即都来打听消息。","tag":"字词释义"},{"s":"“率<em class='k'>妻子</em>邑人”中“<em class='k'>妻子</em>”的意思是？","o":["妻子儿女","妻子和儿子","妻子（今义）","家人"],"a":"A","e":"“妻子”意为“妻子儿女”，是古今异义词（今义只指妻子）。","tag":"字词释义"},{"s":"“来此<em class='k'>绝境</em>”中“<em class='k'>绝境</em>”的意思是？","o":["险境","绝境（今义）","与人世隔绝的地方","走投无路"],"a":"C","e":"“绝境”意为“与人世隔绝的地方”，是古今异义词（今义指走投无路的境地）。","tag":"字词释义"},{"s":"“不复出<em class='k'>焉</em>”中“<em class='k'>焉</em>”的意思是？","o":["从这里（兼词，于此）","语气词","哪里","怎么"],"a":"A","e":"“焉”是兼词，意为“于此、从这里”。“不复出焉”即不再从这里出去。","tag":"字词释义"},{"s":"“遂与外人<em class='k'>间隔</em>”中“<em class='k'>间隔</em>”的意思是？","o":["断绝","间隔（今义）","隔开","隔绝"],"a":"D","e":"“间隔”意为“隔绝”，是古今异义词（今义指事物之间距离）。","tag":"字词释义"},{"s":"“<em class='k'>乃</em>不知有汉”中“<em class='k'>乃</em>”的意思是？","o":["竟然","于是","才","就"],"a":"A","e":"“乃”意为“竟然”。“乃不知有汉”即竟然不知道有汉朝。","tag":"字词释义"},{"s":"“<em class='k'>无论</em>魏晋”中“<em class='k'>无论</em>”的意思是？","o":["无论（今义）","不论","不管","更不必说"],"a":"D","e":"“无论”意为“更不必说”，是古今异义词（今义指不管）。","tag":"字词释义"},{"s":"“此人一一为<em class='k'>具</em>言所闻”中“<em class='k'>具</em>”的意思是？","o":["详尽","具备","工具","全"],"a":"A","e":"“具”意为“详尽”。“具言所闻”即详尽地说出所听到的事。","tag":"字词释义"},{"s":"“余人各复<em class='k'>延</em>至其家”中“<em class='k'>延</em>”的意思是？","o":["邀请","延长","延续","拖延"],"a":"A","e":"“延”意为“邀请”。“余人各复延至其家”即其余的人又各自邀请（他）到自己家。","tag":"字词释义"},{"s":"“<em class='k'>不足</em>为外人道也”中“<em class='k'>不足</em>”的意思是？","o":["不值得","不足（今义）","不够","不满"],"a":"A","e":"“不足”意为“不值得”。“不足为外人道也”即不值得对外面的人说。","tag":"字词释义"},{"s":"“<em class='k'>既</em>出”中“<em class='k'>既</em>”的意思是？","o":["已经，……之后","既然","即使","立即"],"a":"A","e":"“既”意为“已经”。“既出”即出来以后。","tag":"字词释义"},{"s":"“便<em class='k'>扶</em>向路”中“<em class='k'>扶</em>”的意思是？","o":["沿着","帮助","扶持","扶着"],"a":"A","e":"“扶”意为“沿着、顺着”。“便扶向路”即就顺着旧路（回去）。","tag":"字词释义"},{"s":"“处处<em class='k'>志</em>之”中“<em class='k'>志</em>”的活用和意思是？","o":["名词作动词，做记号","志向","标记（名词）","标志"],"a":"A","e":"“志”名词作动词，意为“做记号”。“处处志之”即处处做记号。","tag":"字词释义"},{"s":"“<em class='k'>诣</em>太守”中“<em class='k'>诣</em>”的意思是？","o":["拜访，到……去","造诣","指","告诉"],"a":"A","e":"“诣”意为“拜访、到……去”。“诣太守”即去拜见太守。","tag":"字词释义"},{"s":"“寻<em class='k'>向</em>所志”中“<em class='k'>向</em>”的意思是？","o":["先前","方向","朝向","向来"],"a":"A","e":"“向”意为“先前”。“寻向所志”即寻找先前做的标记。","tag":"字词释义"},{"s":"“欣然<em class='k'>规</em>往”中“<em class='k'>规</em>”的意思是？","o":["规则","规矩","计划","规定"],"a":"C","e":"“规”意为“计划、打算”。“欣然规往”即高兴地计划前往。","tag":"字词释义"},{"s":"“<em class='k'>未果</em>”中“<em class='k'>未果</em>”的意思是？","o":["没有实现","没有结果","果实","未成功"],"a":"A","e":"“未果”意为“没有实现”。","tag":"字词释义"},{"s":"“<em class='k'>寻</em>病终”中“<em class='k'>寻</em>”的意思是？","o":["不久","寻找","寻常","寻找（今义）"],"a":"A","e":"“寻”意为“不久”。“寻病终”即不久因病去世。","tag":"字词释义"},{"s":"“后<em class='k'>遂</em>无问津者”中“<em class='k'>遂</em>”的意思是？","o":["于是，就","顺遂","成功","完成"],"a":"A","e":"“遂”意为“就”。“后遂无问津者”即此后就没有探访的人了。","tag":"字词释义"},{"s":"“无问<em class='k'>津</em>者”中“<em class='k'>津</em>”的意思是？","o":["天津","唾液","渡河","渡口"],"a":"D","e":"“津”意为“渡口”。“问津”本义打听渡口，这里引申为探访。","tag":"字词释义"},{"s":"下列加点字词类活用类型与“处处<em class='k'>志</em>之”相同的一项是？","o":["渔人甚异之","欲穷其林","山有小口","一狼洞其中"],"a":"D","e":"“志”名词作动词，做记号；“洞”名词作动词，打洞，活用类型相同。A“异”意动；B“穷”形作动；C 无活用。","tag":"字词释义"},{"s":"对“渔人甚<em class='k'>异</em>之”中“<em class='k'>异</em>”的用法，分析正确的一项是？","o":["异：形容词，奇异","异：意动用法，对……感到惊异","异：使动用法，使……奇异","异：名词，奇异景象"],"a":"B","e":"“异”是意动用法，“对……感到惊异”。“渔人甚异之”即渔人对这件事感到很惊异。","tag":"字词释义"},{"s":"下列句子翻译正确的一项是？","o":["落英缤纷：落花繁多的样子。","阡陌交通：田间小路四通八达，可以通行车辆。","率妻子邑人来此绝境：带领妻子和同乡来到这个走投无路的地方。","不足为外人道也：不值得对外人讲道理。"],"a":"A","e":"B“交通”为交错相通，“通行车辆”误；C“妻子”应译“妻子儿女”，“绝境”为“与世隔绝的地方”；D“道”为“说”。A 正确。","tag":"内容理解"},{"s":"下列翻译有误的一项是？","o":["黄发垂髫，并怡然自乐：老人和小孩，都安适愉快。","乃不知有汉，无论魏晋：竟然不知道有汉朝，更不必说魏晋了。","便扶向路，处处志之：顺着先前的路回去，到处做记号。","寻病终：寻找机会，最终生病去世。"],"a":"D","e":"“寻病终”意为“不久因病去世”，“寻”是“不久”，不是“寻找机会”。","tag":"内容理解"},{"s":"文中桃花源中人“叹惋”的原因是？","o":["渔人路途艰辛，令人同情","外界朝代更迭，战乱不断，世人饱受苦难","担心渔人泄露桃花源的位置","羡慕渔人可以自由外出游历"],"a":"B","e":"桃花源中人听渔人说起外界战乱不断、百姓受苦，因而感叹惋惜。","tag":"内容理解"},{"s":"对文章结尾写“南阳刘子骥欣然规往，未果，寻病终。后遂无问津者”的作用，分析最准确的一项是？","o":["交代真实历史人物寻访桃花源未果，说明桃花源确实存在，只是难以寻找","借助名士寻访失败的情节，增添神秘色彩，暗示桃花源是虚构的理想社会","表达作者惋惜之情，遗憾刘子骥没能找到世外桃源","意在批判世人追求隐逸生活，却缺少坚持寻访的毅力"],"a":"B","e":"借名士寻访失败增添神秘色彩，暗示桃花源是虚构的理想社会，可望而不可即。","tag":"内容理解"},{"s":"桃花源中人叮嘱渔人“不足为外人道也”，下列理解不正确的一项是？","o":["桃花源人害怕外界战乱侵扰，破坏这里安宁平和的生活","他们不愿世俗之人闯入，打破与世隔绝、自给自足的美好家园","桃花源人心存私心，想独自占有这片世外桃源，不愿分享美景","为下文渔人再寻桃花源却迷路埋下伏笔，推动情节发展"],"a":"C","e":"桃花源人叮嘱不外传是出于避乱、守护安宁，并非“心存私心、独自占有”。","tag":"内容理解"}],"jd":[{"o":"晋太元中，武陵人捕鱼为业。缘溪行，忘路之远近。忽逢桃花林，夹岸数百步，中无杂树，芳草鲜美，落英缤纷。渔人甚异之，复前行，欲穷其林。","t":"东晋太元年间，武陵郡有个人以打鱼作为谋生手段。（他）顺着溪水划船前行，忘记了路程的远近。忽然遇到一片桃花林，生长在溪水两岸，长达几百步，中间没有别的树木，花草鲜嫩美丽，落花纷纷地散落在地上。渔人对此感到十分诧异，又继续向前划行，想要走到那片林子的尽头。","notes":[["缘","沿着，顺着"],["夹岸","两岸"],["鲜美","鲜嫩美丽（古今异义）"],["落英","落花"],["缤纷","繁多而错杂的样子"],["前","名词作状语，向前"],["穷","走到尽头"]]},{"o":"林尽水源，便得一山，山有小口，仿佛若有光。便舍船，从口入。初极狭，才通人。复行数十步，豁然开朗。土地平旷，屋舍俨然，有良田、美池、桑竹之属。","t":"桃花林在溪水发源的地方就到头了，便出现一座山，山上有个小洞口，隐隐约约好像有点光亮。（渔人）于是舍弃船只，从洞口进去。起初洞口非常狭窄，仅能容一个人通过。又走了几十步，突然变得开阔明亮了。眼前一片平坦宽广的土地，一排排整齐的房舍，还有肥沃的田地、美丽的池沼，桑树竹林之类的。","notes":[["林尽水源","状语后置（林尽（于）水源）"],["仿佛","隐隐约约，好像"],["俨然","整齐的样子"],["属","类"]]},{"o":"阡陌交通，鸡犬相闻。其中往来种作，男女衣着，悉如外人。黄发垂髫，并怡然自乐。","t":"田间小路交错相通，鸡鸣狗叫的声音此起彼伏，相互都能听见。在田野里来来往往耕种劳作的人们，男女的穿戴全都跟桃花源以外的世人一样。老人和小孩，都安闲快乐。","notes":[["交通","交错相通（古今异义）"],["悉","全，都"],["并","都，一起"]]},{"o":"见渔人，乃大惊，问所从来。具答之。便要还家，设酒杀鸡作食。村中闻有此人，咸来问讯。自云先世避秦时乱，率妻子邑人来此绝境，不复出焉，遂与外人间隔。","t":"（桃花源里的人）看见渔人，于是十分惊奇，问（他）是从哪里来的。（渔人）详尽地回答了他们。（有人）就邀请（渔人）到自己家里去，摆酒杀鸡做饭来款待他。村里的人听说来了这么一个人，都来打听消息。（他们）自己说他们的祖先为了躲避秦朝的战乱，率领妻子儿女和同乡人来到这个与人世隔绝的地方，不再出去，于是就同外界的人隔绝了。","notes":[["乃","于是，就"],["具","详尽，详细"],["要","同“邀”，邀请"],["咸","全，都"],["妻子","妻子儿女（古今异义）"],["绝境","与人世隔绝的地方（古今异义）"],["焉","兼词，于此"],["间隔","隔绝（古今异义）"]]},{"o":"问今是何世，乃不知有汉，无论魏晋。此人一一为具言所闻，皆叹惋。余人各复延至其家，皆出酒食。停数日，辞去。此中人语云：“不足为外人道也。”","t":"（他们）问现在是什么朝代，竟然不知道有过汉朝，更不必说魏朝和晋朝了。渔人把自己知道的事一件一件详尽地说给他们听，（他们）听后都感叹惋惜。其余的人各自又把渔人邀请到自己家中，都拿出酒饭来款待他。（渔人）停留了几天，就告辞离开了。村里的人告诉他说：“（这里的情况）不值得对外面的人说啊。”","notes":[["乃","竟然"],["无论","更不必说（古今异义）"],["延","邀请"],["不足","不值得"]]},{"o":"既出，得其船，便扶向路，处处志之。及郡下，诣太守，说如此。太守即遣人随其往，寻向所志，遂迷，不复得路。","t":"（渔人）出来以后，找到了他的船，就顺着旧路回去，处处都做了标记。到了郡城，（渔人）去拜见太守，报告了这番经历。太守立即派人跟着他去，寻找以前所做的标记，终于迷失了方向，再也找不到通往桃花源的路了。","notes":[["既","已经，……之后"],["扶","沿着，顺着"],["志","名词作动词，做记号"],["诣","拜访，到……去"],["向","先前"]]},{"o":"南阳刘子骥，高尚士也，闻之，欣然规往。未果，寻病终。后遂无问津者。","t":"南阳人刘子骥，是个志向高洁的隐士，听到这件事后，高兴地计划前往。但没有实现，不久就因病去世了。此后就再也没有探寻桃花源的人了。","notes":[["规","计划，打算"],["未果","没有实现"],["寻","不久"],["遂","就"],["津","渡口（引申为探访）"]]}]},{"no":53,"t":"虽有嘉肴","src":"部编版八年级下册·（西汉）《礼记》","tag":"八年级下册","html":true,"p":["虽有<u>嘉</u>肴，弗食，不知其<u>旨</u>也；虽有<u>至</u>道，弗学，不知其善也。<u>是故</u>学然后知不足，教<u>然后</u>知<u>困</u>。","知不足，然后能自<u>反</u>也；知困，然后能自强也。<u>故</u>曰：教学相<u>长</u>也。《兑命<small>〔《兑命》〕即《说命》，《尚书》中的一篇。</small><small>〔兑(yuè)〕同“说”。</small>》曰“<u>学</u>学半”，<u>其</u>此<u>之</u>谓乎！"],"common":"","q":[{"s":"“虽有<em class='k'>嘉</em>肴”中“<em class='k'>嘉</em>”的意思是？","o":["美好","夸奖","善良","嘉奖"],"a":"A","e":"“嘉”意为“美好”。“嘉肴”即美味的菜肴。","tag":"字词释义"},{"s":"“不知其<em class='k'>旨</em>也”中“<em class='k'>旨</em>”的意思是？","o":["主旨","味美","旨意","目的"],"a":"B","e":"“旨”意为“味美”。“不知其旨”即不知道它味道甘美。","tag":"字词释义"},{"s":"“虽有<em class='k'>至</em>道”中“<em class='k'>至</em>”的意思是？","o":["到达","最好的","至于","终点"],"a":"B","e":"“至”意为“极、最好的”。“至道”即最好的道理。","tag":"字词释义"},{"s":"“<em class='k'>是故</em>学然后知不足”中“<em class='k'>是故</em>”的意思是？","o":["因为","因此","虽然","然而"],"a":"B","e":"“是故”意为“因此”。“是故学然后知不足”即因此学习之后才知道自己的不足。","tag":"字词释义"},{"s":"“教<em class='k'>然后</em>知困”中“<em class='k'>然后</em>”的意思是？","o":["这样以后","然而","接着","于是"],"a":"A","e":"“然后”意为“这样以后”。“教然后知困”即教导别人之后才知道自己有困惑。","tag":"字词释义"},{"s":"“教然后知<em class='k'>困</em>”中“<em class='k'>困</em>”的意思是？","o":["困难","困惑","困乏","困境"],"a":"B","e":"“困”意为“困惑”。“知困”即知道自己有困惑的地方。","tag":"字词释义"},{"s":"“然后能自<em class='k'>反</em>也”中“<em class='k'>反</em>”的意思是？","o":["反对","反省","返回","反复"],"a":"B","e":"“反”意为“反省”。“自反”即自我反思。","tag":"字词释义"},{"s":"“<em class='k'>故</em>曰”中“<em class='k'>故</em>”的意思是？","o":["原因","所以","过去","故意"],"a":"B","e":"“故”意为“所以”。“故曰”即所以说。","tag":"字词释义"},{"s":"“教学相<em class='k'>长</em>也”中“<em class='k'>长</em>”的意思是？","o":["长久","增长","生长","延长"],"a":"B","e":"“长”读 zhǎng，意为“增长”。“教学相长”即教与学相互促进、相互增长。","tag":"字词释义"},{"s":"“<em class='k'>学</em>学半”中第一个“<em class='k'>学</em>”的读音和意思是？","o":["xué，学习","xiào，教导","xiào，学习","xué，教导"],"a":"B","e":"第一个“学”读 xiào，同“敩”，意为“教导”。“学（xiào）学半”即教导别人，占自己学习的一半。","tag":"字词释义"},{"s":"“<em class='k'>其</em>此之谓乎”中“<em class='k'>其</em>”的用法是？","o":["代词，它","语气词，大概","代词，他的","副词，其中"],"a":"B","e":"“其”是语气词，表推测，大概。“其此之谓乎”即大概说的就是这个道理吧。","tag":"字词释义"},{"s":"“其此<em class='k'>之</em>谓乎”中“<em class='k'>之</em>”的用法是？","o":["结构助词，的","宾语前置的标志","代词，它","动词，去"],"a":"B","e":"“之”是助词，宾语前置的标志。“此之谓”即“谓此”，宾语“此”前置，意为“说的就是这个”。","tag":"字词释义"},{"s":"对省略句“弗食，不知其旨也”补全省略成分正确的一项是？","o":["（吾）弗食，（吾）不知其旨也","（嘉肴）弗食，（嘉肴）不知其旨也","（道）弗食，（人）不知其旨也","（人）弗食，（嘉肴）不知其旨也"],"a":"A","e":"“弗食”“不知”都省略了主语“人”（吾），即（人）不吃，（人）不知道它的味美。A 补充正确。","tag":"内容理解"},{"s":"对“虽有嘉肴，弗食，不知其旨也”翻译最准确的一项是？","o":["虽然有美味的肉食，不吃它，就不知道它味道甘美。","即使有好菜，没人品尝，就没有美味。","就算有佳肴，不去做饭，就体会不到美味。","即使有美味菜肴，不吃，就不知道它的旨意。"],"a":"A","e":"“虽有”即虽然（即使）有；“弗食”即不吃；“不知其旨”即不知道它味道甘美。A 最准确。D 误将“旨”译为“旨意”。","tag":"内容理解"},{"s":"下列翻译有误的一项是？","o":["虽有至道，弗学，不知其善也：即使有最好的道理，不去学习，就不知道它的好处。","是故学然后知不足，教然后知困：所以学习之后才知道自己的不足，教人之后才知道自己有困惑。","知不足，然后能自反也：知道自己的不足，然后才能自我反思。","学学半：学习是一半的乐趣。"],"a":"D","e":"D 误译。“学（xiào）学半”意为“教导别人，占自己学习的一半”，不是“学习是一半的乐趣”。","tag":"内容理解"},{"s":"下列朗读停顿划分正确的一项是？","o":["虽有 / 嘉肴，弗食，不知 / 其旨也","是故学 / 然后知不足","教然后 / 知困","《兑命》曰：学 / 学半"],"a":"A","e":"A 正确，“虽有”表让步，后停顿；“不知/其旨也”动宾间停顿。B 应为“是故 / 学 / 然后知不足”（“是故”是连接词）；C 应为“教 / 然后知困”（“然后”是顺承连词，在“教”后停顿）；D 中“学学半”应连读（第一个“学”读 xiào，通“敩”，教导）。","tag":"断句"},{"s":"文章开篇用“虽有嘉肴”设喻，作用是？","o":["单纯介绍美食，丰富文章内容","以品尝佳肴类比学习道理，通俗易懂，引出下文教与学的论述","说明美食和学习一样，都需要别人分享","表达作者十分喜爱美味肉食"],"a":"B","e":"以“吃美味的菜才知道味道”类比“学习才知道道理的好处”，设喻说理，通俗易懂，自然引出下文对教与学的论述。","tag":"内容理解"},{"s":"文中“自反”“自强”两种收获，来源是？","o":["只靠独自读书思考","学习与教导他人的实践","阅读古籍《兑命》","和他人辩论道理"],"a":"B","e":"“知不足”源于学习，“知困”源于教导他人，二者都来自学习与教导的实践，进而能“自反”“自强”。","tag":"内容理解"},{"s":"关于本文论证思路，说法正确的一项是？","o":["先讲道理，再举美食事例，最后引用古文总结","先类比设喻，再分析学与教的收获，最后引用典籍印证中心论点","全程引用古书，没有举例说理","先写教学的难处，再写学习的好处"],"a":"B","e":"本文先以“嘉肴”设喻类比，再分析“学”“教”的收获（知不足、知困），推导出“教学相长”的中心论点，最后引用《兑命》印证。","tag":"内容理解"},{"s":"下列对全文主旨概括无误的一项是？","o":["本文借美食告诉人们，生活要懂得品尝美味","教与学相辅相成，实践才能发现自身不足","文章主要劝诫人们多多教导他人，不用自学","本文批判不学习、不教人、不懂反思的人"],"a":"B","e":"本文论述“教学相长”的道理：学习与实践（教人）才能发现不足与困惑，教与学相互促进、相辅相成。","tag":"内容理解"}],"jd":[{"o":"虽有嘉肴，弗食，不知其旨也；虽有至道，弗学，不知其善也。是故学然后知不足，教然后知困。","t":"虽然有美味可口的菜肴，不吃，就不知道它的味美。虽然有最好的道理，不学，就不知道它的好处。因此学习之后才知道自己的不足，教导别人之后才知道自己有困惑的地方。","notes":[["嘉","美好"],["旨","味美"],["至","极，最好的"],["是故","因此"],["然后","这样以后"],["困","困惑"]]},{"o":"知不足，然后能自反也；知困，然后能自强也。故曰：教学相长也。《兑命》曰“学学半”，其此之谓乎！","t":"知道了自己的不足，然后才能自我反思。知道了自己困惑的地方，然后才能自我勉励。所以说：教与学是相互推动、相互促进的。《兑命》说“教别人，占自己学习的一半”，大概说的就是这个道理吧！","notes":[["反","反省"],["故","所以"],["长","增长，促进"],["兑","同“说”，读 yuè"],["学","同“敩”，教导，读 xiào"],["其","语气词，大概"],["之","宾语前置的标志"]]}]},{"no":54,"t":"马说","src":"部编版八年级下册·（唐）韩愈《杂说》","tag":"八年级下册","html":true,"p":["世有伯乐，<u>然后</u>有千里马。千里马常有，<u>而</u>伯乐不常有。<u>故</u><u>虽</u>有名马，<u>祗</u>辱于<span class=\"jz\" title=\"奴隶人：奴仆\">奴隶人之手，<u>骈死</u>于<span class=\"jz\" title=\"槽枥：马槽\">槽枥之间，不<u>以</u>千里称也。","马<u>之</u>千里者，一食<u>或</u>尽粟一石。<u>食</u>马者不知其能千里而食也。<u>是</u>马也，虽有千里之能，食不饱，力不足，才美不外<u>见</u>，<u>且</u>欲与常马等不可得，<u>安</u>求其能千里也？","<u>策</u>之不<u>以</u>其<span class=\"jz\" title=\"道：正确的方法\">道，食之不能尽其<u>材</u>，鸣之而不能<u>通</u>其意，执策而<u>临</u>之，曰：“天下无马！”呜呼！<u>其</u>真无马邪？其真不知马也！"],"common":"","q":[{"s":"“<em class='k'>然后</em>有千里马”中“<em class='k'>然后</em>”的意思是？","o":["这样以后","于是","接着","然而"],"a":"A","e":"“然后”意为这样以后。“然后有千里马”即这样以后才有千里马。","tag":"字词释义"},{"s":"“千里马常有，<em class='k'>而</em>伯乐不常有”中“<em class='k'>而</em>”的意思是？","o":["却，表转折","并且","然后","如果"],"a":"A","e":"“而”表转折，却。“而伯乐不常有”即可是伯乐不常有。","tag":"字词释义"},{"s":"“<em class='k'>故</em>虽有名马”中“<em class='k'>故</em>”的意思是？","o":["所以","原因","过去","故意"],"a":"A","e":"“故”意为所以。“故虽有名马”即因此即使有名马。","tag":"字词释义"},{"s":"“故<em class='k'>虽</em>有名马”中“<em class='k'>虽</em>”的意思是？","o":["即使","虽然","竟然","唯独"],"a":"A","e":"“虽”意为即使（表让步）。“虽有名马”即即使有名贵的马。","tag":"字词释义"},{"s":"“<em class='k'>祗</em>辱于奴隶人之手”中“<em class='k'>祗</em>”的意思是？","o":["只是","恭敬","到达","原本"],"a":"A","e":"“祗”同“只”，只是。“祗辱于奴隶人之手”即只是受辱于奴仆之手。","tag":"字词释义"},{"s":"“<em class='k'>骈死</em>于槽枥之间”中“<em class='k'>骈死</em>”的意思是？","o":["并列而死","先后而死","安然死去","迅速死去"],"a":"A","e":"“骈死”意为并列而死（和普通马一起死）。“骈死于槽枥之间”即一同死在马槽之间。","tag":"字词释义"},{"s":"“不<em class='k'>以</em>千里称也”中“<em class='k'>以</em>”的意思是？","o":["凭借","因为","按照","认为"],"a":"A","e":"“以”意为凭借。“不以千里称”即不凭千里（的才能）著称。","tag":"字词释义"},{"s":"“马<em class='k'>之</em>千里者”中“<em class='k'>之</em>”的用法是？","o":["定语后置的标志","结构助词，的","代词，它","动词，去"],"a":"A","e":"“之”是定语后置的标志，“马之千里者”即日行千里的马。","tag":"句式"},{"s":"“一食<em class='k'>或</em>尽粟一石”中“<em class='k'>或</em>”的意思是？","o":["有时","或者","有人","突然"],"a":"A","e":"“或”意为有时。“一食或尽粟一石”即一顿有时能吃下一石粮食。","tag":"字词释义"},{"s":"“<em class='k'>食</em>马者不知其能千里而食也”中“<em class='k'>食</em>”的意思是？","o":["喂养","食物","吃","粮食"],"a":"A","e":"“食”读 sì，意为喂养、饲养。“食马者”即喂马的人。","tag":"字词释义"},{"s":"“<em class='k'>是</em>马也”中“<em class='k'>是</em>”的意思是？","o":["这","表判断","正确","于是"],"a":"A","e":"“是”作代词，这。“是马也”即这样的马。","tag":"字词释义"},{"s":"“才美不外<em class='k'>见</em>”中“<em class='k'>见</em>”的意思是？","o":["表现","看见","出现","拜见"],"a":"A","e":"“见”同“现”，表现。“才美不外见”即才能和美好的素质不能表现出来。","tag":"字词释义"},{"s":"“<em class='k'>且</em>欲与常马等不可得”中“<em class='k'>且</em>”的意思是？","o":["尚且","并且","反而","暂且"],"a":"A","e":"“且”意为尚且。“且欲与常马等不可得”即想要跟普通马一样尚且办不到。","tag":"字词释义"},{"s":"“<em class='k'>安</em>求其能千里也”中“<em class='k'>安</em>”的意思是？","o":["怎么","安全","安放","哪里"],"a":"A","e":"“安”意为怎么（表反问）。“安求其能千里也”即怎么能要求它日行千里呢？","tag":"字词释义"},{"s":"“<em class='k'>策</em>之不以其道”中“<em class='k'>策</em>”的意思是？","o":["驱赶","马鞭","策略","督促"],"a":"A","e":"“策”是名词作动词，用马鞭驱赶。“策之”即鞭打它。","tag":"词类活用"},{"s":"“不<em class='k'>以</em>其道”中“<em class='k'>以</em>”的意思是？","o":["按照","用","因为","认为"],"a":"A","e":"“以”意为按照。“不以其道”即不按照（驱使千里马的）正确方法。","tag":"字词释义"},{"s":"“食之不能尽其<em class='k'>材</em>”中“<em class='k'>材</em>”的意思是？","o":["才能","材料","木材","资质"],"a":"A","e":"“材”同“才”，才能。“尽其材”即竭尽它的才能。","tag":"字词释义"},{"s":"“鸣之而不能<em class='k'>通</em>其意”中“<em class='k'>通</em>”的意思是？","o":["通晓","通过","通畅","沟通"],"a":"A","e":"“通”意为通晓。“通其意”即通晓它的意思。","tag":"字词释义"},{"s":"“执策而<em class='k'>临</em>之”中“<em class='k'>临</em>”的意思是？","o":["面对","临近","降临","俯视"],"a":"A","e":"“临”意为面对。“执策而临之”即拿着马鞭面对着它。","tag":"字词释义"},{"s":"“<em class='k'>其</em>真无马邪”中“<em class='k'>其</em>”的意思是？","o":["难道","代词，它","其中","大概"],"a":"A","e":"“其”表反问语气，难道。“其真无马邪”即难道真的没有千里马吗？（“其真不知马也”的“其”表推测，大概。）","tag":"字词释义"},{"s":"下列朗读停顿划分正确的一项是？","o":["祗辱于 / 奴隶人之手","食马者 / 不知其能千里而食也","才美不外 / 见","其真无马 / 邪其真不知马也"],"a":"B","e":"B 正确，“食马者”后停顿。A 应为“祗辱 / 于奴隶人之手”；C 应为“才美 / 不外见”；D 应为“其真无马邪？/ 其真不知马也”。","tag":"断句"},{"s":"下面句式判断错误的一项是？","o":["“马之千里者”是定语后置，译为日行千里的马","“祗辱于奴隶人之手”属于状语后置句","“食马者不知其能千里而食也”是被动句","“其真不知马也”为表推测语气的陈述句"],"a":"C","e":"C 判断错误。“食马者不知其能千里而食也”是陈述句，不是被动句。其余三项判断均正确。","tag":"句式"},{"s":"对词类活用分析正确的一项是？","o":["“策之不以其道”中“策”，名词，马鞭","“策之不以其道”中“策”，名词作动词，用马鞭驱赶","“食之不能尽其材”中“尽”，形容词，尽头","“食之不能尽其材”中“尽”，名词作状语，尽力"],"a":"B","e":"B 分析正确。“策”名词作动词，用马鞭驱赶。A 未看出活用；C、D 对“尽”分析错误，“尽”是形容词作动词，竭尽。","tag":"词类活用"},{"s":"对“其真无马邪？其真不知马也”翻译正确的一项是？","o":["难道真的没有千里马吗？大概是（他们）真的不认识千里马吧！","难道真的没有马吗？其实是真的不认识马啊！","它真的没有马吗？是真的不知道马吧！","难道真的没有千里马吗？确实是他们不认识千里马啊！"],"a":"A","e":"前一个“其”表反问（难道），后一个“其”表推测（大概）。A 翻译准确。D 把后一句译成肯定语气，与前文推测语气不符。","tag":"翻译"},{"s":"下列对文章内容理解分析有误的一项是？","o":["“千里马常有，而伯乐不常有”开篇点明核心，伯乐对千里马命运起决定作用","“才美不外见”写出千里马的才能被埋没，无法展现","文中“食马者”指善于发掘人才的贤明君主","全文托物言志，借千里马的遭遇写有才之士怀才不遇"],"a":"C","e":"C 有误。“食马者”指喂马的人，比喻愚昧、不识人才的统治者，并非贤明君主。","tag":"内容理解"},{"s":"下面对本文艺术手法与主旨理解，说法错误的一项是？","o":["以千里马比喻有才之士，伯乐比喻识才的明君","“其真无马邪？其真不知马也”设问，抒发作者的感慨与批判","作者认为千里马本身能力不足，所以才会被埋没","文章层层蓄势，结尾点出问题根源在于统治者不识人才"],"a":"C","e":"C 错误。作者认为千里马被埋没的根源是“食马者”不识马、不善养，并非千里马本身能力不足。","tag":"内容理解"}],"jd":[{"o":"世有伯乐，然后有千里马。千里马常有，而伯乐不常有。故虽有名马，祗辱于奴隶人之手，骈死于槽枥之间，不以千里称也。","t":"世上先有伯乐，然后才有千里马。千里马经常有，可是伯乐不会经常有。因此，即使是很名贵的马，也只能在奴仆的手下受到屈辱，（和普通马）一同死在马槽里，不以千里马而著称。","notes":[["然后","这样以后"],["而","却，表转折"],["故","所以"],["虽","即使"],["祗","同“只”，只是"],["骈死","并列而死"],["以","凭借"]]},{"o":"马之千里者，一食或尽粟一石。食马者不知其能千里而食也。是马也，虽有千里之能，食不饱，力不足，才美不外见，且欲与常马等不可得，安求其能千里也？","t":"日行千里的马，一顿有时能吃下一石粮食。喂马的人不懂得要根据它日行千里的本领来喂养它。这样的马，虽然有日行千里的才能，（但是）吃不饱，力气不足，它的才能和美好的素质也就不能表现在外面，想要跟普通的马一样尚且办不到，又怎么能要求它日行千里呢？","notes":[["之","定语后置的标志"],["或","有时"],["食","喂养，读 sì"],["是","这"],["见","同“现”，表现"],["且","尚且"],["安","怎么"]]},{"o":"策之不以其道，食之不能尽其材，鸣之而不能通其意，执策而临之，曰：“天下无马！”呜呼！其真无马邪？其真不知马也！","t":"用马鞭赶它，不按照（驱使千里马的）正确方法，喂它，却不能让它竭尽才能，它鸣叫，却不能通晓它的意思。拿着马鞭面对着它，说：“天下没有千里马！”唉！难道真的没有千里马吗？其实是他们真的不认识千里马啊！","notes":[["策","用马鞭驱赶"],["以","按照"],["材","同“才”，才能"],["通","通晓"],["临","面对"],["其","难道（表反问）"]]}]},{"no":55,"t":"岳阳楼记","src":"部编版九年级上册·（宋）范仲淹","tag":"九年级上册","html":true,"p":["<span class=\"jz\" title=\"庆历四年：1044 年。庆历，宋仁宗赵祯的年号；本文写于庆历六年（1046）\">庆历四年春，滕子京<u>谪</u>守巴陵郡。<u>越明年</u>，<span class=\"jz\" title=\"政通人和：政事顺利，百姓和乐\">政通人和，百废<u>具</u>兴，<u>乃</u>重修岳阳楼，增其旧制，刻唐贤今人诗赋于其上，<u>属</u>予<u>作文</u><u>以</u>记之。","予观<u>夫</u>巴陵<u>胜</u>状，在洞庭一湖。<u>衔</u>远山，吞长江，浩浩<u>汤汤</u>，横无际涯，朝晖夕阴，气象万千，此则岳阳楼之<u>大观</u>也，前人之述<u>备</u>矣。然则北通巫峡，南极<span class=\"jz\" title=\"潇湘：潇水、湘水。潇水是湘水的支流，湘水流入洞庭湖\">潇湘，迁客<span class=\"jz\" title=\"骚人：战国时屈原作《离骚》，故称屈原或《楚辞》作者为“骚人”，后泛指文人\">骚人，多会于此，览物之情，<u>得无</u>异乎？","<u>若夫</u><u>淫</u>雨<span class=\"jz\" title=\"霏霏：雨雪纷纷而下的样子\">霏霏，连月不开，阴风怒号，浊浪<u>排</u>空，日星隐曜，山岳潜形，商旅<u>不行</u>，<span class=\"jz\" title=\"樯倾楫摧：桅杆倒下，船桨折断。倾，倒下；摧，折断\">樯倾楫摧，薄暮<span class=\"jz\" title=\"冥冥：昏暗\">冥冥，虎啸猿啼。登斯楼也，则有<u>去国</u>怀乡，<span class=\"jz\" title=\"忧谗畏讥：担心被说坏话，惧怕被批评指责\">忧谗畏讥，满目<u>萧然</u>，感极而悲者矣。","<u>至若</u>春和<u>景</u>明，波澜不惊，上下天光，一碧万顷，沙鸥翔<u>集</u>，锦鳞<u>游泳</u>，<span class=\"jz\" title=\"岸芷汀兰：岸上与小洲上的花草。芷，白芷；汀，小洲\">岸芷汀兰，郁郁青青。而或长烟<u>一</u>空，皓月千里，浮光跃金，静影沉璧，渔歌互答，此乐何<u>极</u>！登斯楼也，则有心旷神怡，宠辱偕忘，把酒临风，其喜洋洋者矣。","嗟夫！予<u>尝</u>求<span class=\"jz\" title=\"古仁人：古代品德高尚的人\">古仁人之心，或<u>异</u>二者之为，何哉？不<u>以</u>物喜，不以己悲，居<u>庙堂</u>之高则忧其民，处江湖之远则忧其君。是进亦忧，退亦忧。然则何时而乐耶？其必曰“先天下之忧而忧，后天下之乐而乐”乎！噫！<u>微</u>斯人，吾谁与<u>归</u>？时六年九月十五日。"],"common":"","q":[{"s":"“滕子京<em class='k'>谪</em>守巴陵郡”中“<em class='k'>谪</em>”的意思是？","o":["贬官","流放","责备","指责"],"a":"A","e":"“谪”意为贬官。“滕子京谪守巴陵郡”即滕子京被贬官到巴陵郡做太守。","tag":"字词释义"},{"s":"“<em class='k'>越明年</em>”中“<em class='k'>明年</em>”在文中的意思是？","o":["第二年","今年的下一年","来年","以后"],"a":"A","e":"“明年”古义为第二年，今义为今年的下一年。“越明年”即到了第二年。","tag":"古今异义"},{"s":"“百废<em class='k'>具</em>兴”中“<em class='k'>具</em>”的意思是？","o":["全，都","具体","具备","准备"],"a":"A","e":"“具”同“俱”，全、都。“百废具兴”即各种荒废的事业都兴办起来。","tag":"字词释义"},{"s":"“<em class='k'>乃</em>重修岳阳楼”中“<em class='k'>乃</em>”的意思是？","o":["于是","竟然","才","却"],"a":"A","e":"“乃”意为于是。“乃重修岳阳楼”即于是重新修建岳阳楼。","tag":"字词释义"},{"s":"“<em class='k'>属</em>予作文以记之”中“<em class='k'>属</em>”的意思是？","o":["嘱托","属于","归属","连接"],"a":"A","e":"“属”同“嘱”，嘱托。“属予作文以记之”即嘱托我写一篇文章来记述这件事。","tag":"字词释义"},{"s":"“属予<em class='k'>作文</em>以记之”中“<em class='k'>作文</em>”在文中的意思是？","o":["写文章","习作","文章","作品"],"a":"A","e":"“作文”古义为写文章，今义为学生习作。“属予作文”即嘱托我写文章。","tag":"古今异义"},{"s":"“作文<em class='k'>以</em>记之”中“<em class='k'>以</em>”的意思是？","o":["来，表目的","用","因为","按照"],"a":"A","e":"“以”表目的，来。“以记之”即用来记述这件事。","tag":"字词释义"},{"s":"“予观<em class='k'>夫</em>巴陵胜状”中“<em class='k'>夫</em>”的意思是？","o":["那","大丈夫","语气词","并且"],"a":"A","e":"“夫”是指示代词，那。“观夫巴陵胜状”即看那巴陵的美好景色。","tag":"字词释义"},{"s":"“巴陵<em class='k'>胜</em>状”中“<em class='k'>胜</em>”的意思是？","o":["美好","胜利","超过","名胜"],"a":"A","e":"“胜”意为美好。“胜状”即美好的景色。","tag":"字词释义"},{"s":"“<em class='k'>衔</em>远山”中“<em class='k'>衔</em>”的意思是？","o":["连接","用嘴叼","包含","仰望"],"a":"A","e":"“衔”意为连接（拟人）。 “衔远山”即（洞庭湖）连接着远处的山。","tag":"字词释义"},{"s":"“浩浩<em class='k'>汤汤</em>”中“<em class='k'>汤汤</em>”的意思是？","o":["水势大","热水","汤水","翻腾"],"a":"A","e":"“汤汤”读 shāng shāng，意为水势浩大。","tag":"字词释义"},{"s":"“此则岳阳楼之<em class='k'>大观</em>也”中“<em class='k'>大观</em>”的意思是？","o":["雄伟景象","伟大观点","大规模","观赏"],"a":"A","e":"“大观”意为雄伟景象。“岳阳楼之大观”即岳阳楼的雄伟景象。","tag":"字词释义"},{"s":"“前人之述<em class='k'>备</em>矣”中“<em class='k'>备</em>”的意思是？","o":["详尽","准备","具备","防备"],"a":"A","e":"“备”意为详尽、完备。“前人之述备矣”即前人的记述已经很详尽了。","tag":"字词释义"},{"s":"“览物之情，<em class='k'>得无</em>异乎”中“<em class='k'>得无</em>”的意思是？","o":["恐怕，表推测","得到","没有","难道"],"a":"A","e":"“得无”表推测，恐怕、莫非。“得无异乎”即恐怕会有所不同吧。","tag":"字词释义"},{"s":"“<em class='k'>若夫</em>淫雨霏霏”中“<em class='k'>若夫</em>”的意思是？","o":["像那","如果","假若","丈夫"],"a":"A","e":"“若夫”是发语词，像那，用来引起下文。“若夫淫雨霏霏”即像那连绵的雨纷纷而下。","tag":"字词释义"},{"s":"“<em class='k'>淫</em>雨霏霏”中“<em class='k'>淫</em>”的意思是？","o":["连绵","淫荡","暴雨","狂风"],"a":"A","e":"“淫”意为连绵不断。“淫雨”即连绵不断的雨。","tag":"字词释义"},{"s":"“浊浪<em class='k'>排</em>空”中“<em class='k'>排</em>”的意思是？","o":["冲击","排列","排除","推开"],"a":"A","e":"“排”意为冲击。“浊浪排空”即浑浊的波浪冲向天空。","tag":"字词释义"},{"s":"“商旅<em class='k'>不行</em>”中“<em class='k'>不行</em>”在文中的意思是？","o":["不能通行","不走路","不可以","不执行"],"a":"A","e":"“不行”古义为不能通行，今义为不可以。“商旅不行”即商人和旅客无法通行。","tag":"古今异义"},{"s":"“则有<em class='k'>去国</em>怀乡”中“<em class='k'>去国</em>”的意思是？","o":["离开国都","离开国家","去国外","前往国都"],"a":"A","e":"“去”意为离开，“国”意为国都（京城）。“去国”即离开国都。","tag":"字词释义"},{"s":"“满目<em class='k'>萧然</em>”中“<em class='k'>萧然</em>”的意思是？","o":["萧条","肃然","欢快","静谧"],"a":"A","e":"“萧然”意为萧条冷落的样子。“满目萧然”即眼前尽是萧条的景象。","tag":"字词释义"},{"s":"“<em class='k'>至若</em>春和景明”中“<em class='k'>至若</em>”的意思是？","o":["至于","如果","甚至","到了"],"a":"A","e":"“至若”意为至于，用来转换话题。“至若春和景明”即至于春风和煦、阳光明媚时。","tag":"字词释义"},{"s":"“春和<em class='k'>景</em>明”中“<em class='k'>景</em>”的意思是？","o":["日光","景色","景物","风景"],"a":"A","e":"“景”古义为日光，今义为景色。“春和景明”即春风和煦、阳光明媚。","tag":"字词释义"},{"s":"“沙鸥翔<em class='k'>集</em>”中“<em class='k'>集</em>”的意思是？","o":["停息","集合","集中","集市"],"a":"A","e":"“集”意为停息。“沙鸥翔集”即沙洲上的鸥鸟时而飞翔时而停歇。","tag":"字词释义"},{"s":"“锦鳞<em class='k'>游泳</em>”中“<em class='k'>游泳</em>”在文中的意思是？","o":["游动","游泳运动","浮沉","嬉戏"],"a":"A","e":"“游泳”古义为游动，今义为体育运动。“锦鳞游泳”即美丽的鱼儿在水中游来游去。","tag":"古今异义"},{"s":"“长烟<em class='k'>一</em>空”中“<em class='k'>一</em>”的意思是？","o":["全，都","数目一","一旦","统一"],"a":"A","e":"“一”意为全、都。“长烟一空”即大片烟雾完全消散。","tag":"字词释义"},{"s":"“此乐何<em class='k'>极</em>”中“<em class='k'>极</em>”的意思是？","o":["穷尽","极点","极力","达到"],"a":"A","e":"“极”意为穷尽。“此乐何极”即这种乐趣哪有穷尽。","tag":"字词释义"},{"s":"“予<em class='k'>尝</em>求古仁人之心”中“<em class='k'>尝</em>”的意思是？","o":["曾经","品尝","尝试","经历"],"a":"A","e":"“尝”意为曾经。“予尝求”即我曾经探求。","tag":"字词释义"},{"s":"“或<em class='k'>异</em>二者之为”中“<em class='k'>异</em>”的意思是？","o":["不同于","奇异","差异","奇怪"],"a":"A","e":"“异”意为不同于。“或异二者之为”即或许不同于以上两种心情。","tag":"字词释义"},{"s":"“不<em class='k'>以</em>物喜”中“<em class='k'>以</em>”的意思是？","o":["因为","用","凭借","来"],"a":"A","e":"“以”意为因为。“不以物喜”即不因外物好坏而或喜或悲。","tag":"字词释义"},{"s":"“居<em class='k'>庙堂</em>之高”中“<em class='k'>庙堂</em>”的意思是？","o":["朝廷","庙宇","殿堂","祠堂"],"a":"A","e":"“庙堂”古义为朝廷。“居庙堂之高”即在朝廷做官。","tag":"字词释义"},{"s":"“<em class='k'>微</em>斯人”中“<em class='k'>微</em>”的意思是？","o":["如果没有","微小","轻微","微妙"],"a":"A","e":"“微”意为如果没有。“微斯人”即如果没有这种人。","tag":"字词释义"},{"s":"“吾谁与<em class='k'>归</em>”中“<em class='k'>归</em>”的意思是？","o":["归依","归来","归还","归属"],"a":"A","e":"“归”意为归依。“吾谁与归”即我同谁一道呢。","tag":"字词释义"},{"s":"下面对文言句式判断错误的一项是？","o":["“此则岳阳楼之大观也”为判断句","“居庙堂之高则忧其民”是定语后置句","“吾谁与归”属于宾语前置句","“不以物喜，不以己悲”是被动句"],"a":"D","e":"D 判断错误。“不以物喜，不以己悲”是互文（不因外物好坏和自己得失而或喜或悲），不是被动句。其余三项判断均正确。","tag":"句式"},{"s":"下面词类活用分析正确的一项是？","o":["“百废具兴”中“废”，动词，废弃","“先天下之忧而忧”中“先”，名词作状语，在……之前","“后天下之乐而乐”中“后”，名词，后面","“长烟一空”中“空”，名词，天空"],"a":"B","e":"B 分析正确。“先”名词作状语，在……之前。A“废”是形容词作名词（荒废的事业）；C“后”名词作状语，在……之后；D“空”形容词作动词（消散）。","tag":"词类活用"},{"s":"下列对迁客骚人的览物之情，理解正确的一项是？","o":["迁客骚人能够做到不以物喜，不以己悲","阴雨萧条之景触发迁客骚人喜悦舒畅的心情","迁客骚人悲喜随景物变化，“以物喜，以己悲”","迁客骚人胸怀远大，心系天下百姓安危"],"a":"C","e":"C 理解正确。迁客骚人的心情随阴晴景色变化而或悲或喜（以物喜，以己悲），这正是古仁人与之不同的地方。","tag":"内容理解"},{"s":"下列对文章内容与艺术分析有误的一项是？","o":["文章以“记”为名，大量议论，借写景抒发政治理想","“微斯人，吾谁与归”既赞美古仁人，也暗含劝勉滕子京","“先天下之忧而忧，后天下之乐而乐”体现古仁人超脱个人得失，心怀天下","古仁人“进亦忧，退亦忧”，是指做官就忧愁，不做官就不再忧愁"],"a":"D","e":"D 有误。“进亦忧，退亦忧”是指无论做官（进）还是退隐（退）都心怀天下而忧虑，并非“不做官就不再忧愁”。","tag":"内容理解"},{"s":"下面对全文理解表述错误的一项是？","o":["文中写阴晴两种景色，用来对比迁客骚人两种不同心境","作者实地游览岳阳楼，目睹洞庭风光写下本篇文章","“衔远山，吞长江”的“衔”“吞”用拟人，写出洞庭湖气势宏大","古仁人的境界高于迁客骚人，是作者推崇的理想人格"],"a":"B","e":"B 错误。范仲淹并未亲临岳阳楼，本文是他应滕子京之请、依据《洞庭晚秋图》等写成的。","tag":"内容理解"},{"s":"对“微斯人，吾谁与归”翻译正确的一项是？","o":["如果没有这样的人，我同谁一道呢？","如果没有这种人，我和谁一起回来？","微小的人，我和谁一起回去？","如果没有这个人，我同谁归还呢？"],"a":"A","e":"“微”意为如果没有，“吾谁与归”是宾语前置（吾与谁归）。A 翻译准确。B 误译“归”为回来；C 误译“微”为微小；D 误译“归”为归还。","tag":"翻译"},{"s":"对“先天下之忧而忧，后天下之乐而乐”翻译正确的一项是？","o":["在天下人忧愁之前先忧愁，在天下人快乐之后才快乐","先为天下人担忧，后为天下人高兴","天下人忧愁之前就忧愁，天下人快乐之后就快乐","在天下之前忧愁，在天下之后快乐"],"a":"A","e":"“先”“后”都是名词作状语（在……之前、在……之后）。A 翻译准确。C 漏掉“先”“后”作状语的含义；B、D 语序不当。","tag":"翻译"},{"s":"【联动七八年级】下列句子中属于状语后置（介宾短语后置）的一项是？","o":["刻唐贤今人诗赋于其上","其印为余群从所得","马之千里者","何陋之有"],"a":"A","e":"A 是状语后置，“于其上”后置（于其上刻诗赋）。B 是被动句（为……所，选自《活板》）；C 是定语后置（选自《马说》）；D 是宾语前置（何陋之有=有何陋，选自《陋室铭》）。","tag":"句式"},{"s":"【联动七八年级】下列句中加点字的用法与其他三项不同的一项是？","o":["北通巫峡中“北”","斗折蛇行中“斗”","其一犬坐于前中“犬”","策之不以其道中“策”"],"a":"D","e":"A“北”（选自本文）名词作状语，向北；B“斗”（选自《小石潭记》）名词作状语，像北斗星那样；C“犬”（选自《狼》）名词作状语，像狗一样；D“策”（选自《马说》）名词作动词，用马鞭驱赶。故选 D。","tag":"词类活用"}],"jd":[{"o":"庆历四年春，滕子京谪守巴陵郡。越明年，政通人和，百废具兴，乃重修岳阳楼，增其旧制，刻唐贤今人诗赋于其上，属予作文以记之。","t":"庆历四年的春天，滕子京被贬官到巴陵郡做太守。到了第二年，政事顺利，百姓和乐，各种荒废的事业都兴办起来了，于是重新修建岳阳楼，扩大它原有的规模，把唐代名家和当代人的诗赋刻在上面，嘱托我写一篇文章来记述这件事。","notes":[["谪","贬官"],["明年","第二年"],["具","同“俱”，全，都"],["乃","于是"],["属","同“嘱”，嘱托"],["作文","写文章"],["以","来，表目的"]]},{"o":"予观夫巴陵胜状，在洞庭一湖。衔远山，吞长江，浩浩汤汤，横无际涯，朝晖夕阴，气象万千，此则岳阳楼之大观也，前人之述备矣。然则北通巫峡，南极潇湘，迁客骚人，多会于此，览物之情，得无异乎？","t":"我看那巴陵郡的美好景色，全在洞庭湖上。它连接着远处的山，吞吐长江的水流，浩浩荡荡，无边无际，早晚阴晴变化，景象千变万化，这就是岳阳楼的壮丽景象，前人的记述已经很详尽了。虽然如此，那么向北通到巫峡，向南直到潇水和湘水，被贬谪的官吏和诗人，大多在这里聚会，他们观赏自然景物而触发的感情，恐怕会有所不同吧？","notes":[["夫","那"],["胜","美好"],["衔","连接"],["汤汤","水势浩大"],["大观","雄伟景象"],["备","详尽"],["得无","恐怕，表推测"]]},{"o":"若夫淫雨霏霏，连月不开，阴风怒号，浊浪排空，日星隐曜，山岳潜形，商旅不行，樯倾楫摧，薄暮冥冥，虎啸猿啼。登斯楼也，则有去国怀乡，忧谗畏讥，满目萧然，感极而悲者矣。","t":"像那连绵细雨纷纷而下、整月不放晴的时候，阴冷的风怒吼着，浑浊的波浪冲向天空，太阳和星星隐藏起光辉，山岳隐没了形体，商人和旅客无法通行，桅杆倒下，船桨折断，傍晚天色昏暗，虎在长啸，猿在悲啼。这时登上这座楼，就会产生被贬离京、怀念家乡，担心人家说坏话、惧怕人家批评指责的情绪，眼前尽是萧条的景象，感慨到了极点而悲伤不已。","notes":[["若夫","像那"],["淫","连绵"],["排","冲击"],["不行","不能通行"],["去国","离开国都"],["萧然","萧条的样子"]]},{"o":"至若春和景明，波澜不惊，上下天光，一碧万顷，沙鸥翔集，锦鳞游泳，岸芷汀兰，郁郁青青。而或长烟一空，皓月千里，浮光跃金，静影沉璧，渔歌互答，此乐何极！登斯楼也，则有心旷神怡，宠辱偕忘，把酒临风，其喜洋洋者矣。","t":"至于春风和煦、阳光明媚时，湖面平静，没有惊涛骇浪，天色湖光相接，一片碧绿，广阔无际，沙洲上的鸥鸟时而飞翔时而停歇，美丽的鱼儿在水中游来游去，岸上的香草和小洲上的兰花，草木茂盛，青翠欲滴。有时大片烟雾完全消散，皎洁的月光一泻千里，波动的光闪着金色，静静的月影像沉入水中的玉璧，渔夫的歌声在互相应答，这种乐趣哪有穷尽！这时登上这座楼，就会感到心胸开阔、心情愉快，荣耀和屈辱一并忘了，端着酒杯，吹着微风，那真是快乐高兴极了。","notes":[["至若","至于"],["景","日光"],["集","停息"],["游泳","游动"],["一","全，都"],["极","穷尽"]]},{"o":"嗟夫！予尝求古仁人之心，或异二者之为，何哉？不以物喜，不以己悲，居庙堂之高则忧其民，处江湖之远则忧其君。是进亦忧，退亦忧。然则何时而乐耶？其必曰“先天下之忧而忧，后天下之乐而乐”乎！噫！微斯人，吾谁与归？时六年九月十五日。","t":"唉！我曾经探求古时品德高尚的人的思想感情，他们或许不同于以上两种心情，这是为什么呢？（是因为他们）不因外物好坏和自己得失而或喜或悲，在朝廷做官就为百姓忧虑，被贬到边远地区就为君主忧虑。这样看来，在朝为官也忧虑，在野为民也忧虑，那么他们什么时候才会快乐呢？他们一定会说“在天下人忧之前先忧，在天下人乐之后才乐”吧！唉！如果没有这种人，我同谁一道呢？写于庆历六年九月十五日。","notes":[["尝","曾经"],["异","不同于"],["以","因为"],["庙堂","朝廷"],["微","如果没有"],["归","归依"]]}]},{"no":56,"t":"醉翁亭记","src":"部编版九年级上册·（宋）欧阳修","tag":"九年级上册","html":true,"p":["<span class=\"jz\" title=\"环滁：环绕着滁州城。滁州在安徽东部\">环滁皆山也。其西南诸峰，林<u>壑</u>尤美，望之<u>蔚然</u>而深<u>秀</u>者，<span class=\"jz\" title=\"琅琊：山名，在滁州西南\">琅琊也。<u>山</u>行六七里，渐闻水声潺潺，而泻出于两峰之间者，<span class=\"jz\" title=\"酿泉：泉水名\">酿泉也。峰<u>回</u>路转，有亭<u>翼然</u><u>临</u>于泉上者，醉翁亭也。作亭者谁？山之僧智仙也。<u>名</u>之者谁？太守自谓也。太守与客来饮于此，饮少<u>辄</u>醉，而年又最高，<u>故</u>自号曰醉翁也。醉翁之意不在酒，<u>在乎</u>山水之间也。山水之乐，得之心而<u>寓</u>之酒也。","<u>若夫</u>日出而林<u>霏</u>开，云归而岩穴<u>暝</u>，晦明变化者，山间之朝暮也。野芳发而幽香，佳木<u>秀</u>而繁阴，风霜<u>高洁</u>，水落而石出者，山间之四时也。朝而往，暮而归，四时之景不同，而乐亦无穷也。","至于<u>负者</u>歌于途，行者休于树，前者呼，后者应，<u>伛偻</u><u>提携</u>，往来而不绝者，滁人游也。<u>临</u>溪而渔，溪深而鱼肥，酿泉为酒，泉香而酒<u>洌</u>，山肴野<u>蔌</u>，杂然而<u>前</u><u>陈</u>者，太守宴也。宴酣之乐，非丝非竹，射者中，弈者胜，<u>觥</u>筹交错，起坐而喧哗者，众宾欢也。苍颜白发，<u>颓然</u>乎其间者，太守醉也。","<u>已而</u>夕阳在山，人影散乱，太守归而宾客从也。树林阴<u>翳</u>，鸣声上下，游人<u>去</u>而禽鸟乐也。然而禽鸟知山林之乐，<u>而</u>不知人之乐；人知从太守游而乐，而不知太守<u>之</u><u>乐</u>其乐也。醉能同其乐，醒能述以文者，太守也。太守<u>谓</u>谁？<span class=\"jz\" title=\"庐陵：今江西吉安，欧阳修的籍贯\">庐陵欧阳修也。"],"common":"","q":[{"s":"“林<em class='k'>壑</em>尤美”中“<em class='k'>壑</em>”的意思是？","o":["山谷","护城河","田垄","山峰"],"a":"A","e":"“壑”意为山谷、山沟。“林壑尤美”即树林和山谷尤其优美。","tag":"字词释义"},{"s":"“望之<em class='k'>蔚然</em>而深秀者”中“<em class='k'>蔚然</em>”的意思是？","o":["茂盛的样子","蔚蓝","高大的样子","整齐的样子"],"a":"A","e":"“蔚然”意为草木茂盛的样子。“望之蔚然”即一眼望去树木茂盛。","tag":"字词释义"},{"s":"“蔚然而深<em class='k'>秀</em>者”中“<em class='k'>秀</em>”的意思是？","o":["秀丽","优秀","出众","茂盛"],"a":"A","e":"“秀”意为秀丽。“深秀”即幽深秀丽。","tag":"字词释义"},{"s":"“<em class='k'>山</em>行六七里”中“<em class='k'>山</em>”的意思是？","o":["沿着山路","大山","山上","山中"],"a":"A","e":"“山”名词作状语，沿着山路。“山行六七里”即沿着山路走六七里。","tag":"字词释义"},{"s":"“峰<em class='k'>回</em>路转”中“<em class='k'>回</em>”的意思是？","o":["回环","回来","回头","回避"],"a":"A","e":"“回”意为回环、曲折。“峰回路转”即山势回环、路也跟着转弯。","tag":"字词释义"},{"s":"“有亭<em class='k'>翼然</em>临于泉上者”中“<em class='k'>翼然</em>”的意思是？","o":["像鸟张开翅膀的样子","翅膀","忽然","俨然"],"a":"A","e":"“翼然”意为像鸟张开翅膀的样子（名词作状语）。“有亭翼然”即有一座亭子像鸟展翅一样。","tag":"字词释义"},{"s":"“翼然<em class='k'>临</em>于泉上者”中“<em class='k'>临</em>”的意思是？","o":["居高下视","面临","靠近","光临"],"a":"A","e":"“临”意为居高下视（从高处往下看）。“翼然临于泉上”即像鸟展翅一样居高临下地踞在泉边。","tag":"字词释义"},{"s":"“<em class='k'>名</em>之者谁”中“<em class='k'>名</em>”的意思是？","o":["命名","名字","名声","有名"],"a":"A","e":"“名”名词作动词，命名。“名之者谁”即给它命名的人是谁。","tag":"字词释义"},{"s":"“饮少<em class='k'>辄</em>醉”中“<em class='k'>辄</em>”的意思是？","o":["就","总是","立即","才"],"a":"A","e":"“辄”意为就。“饮少辄醉”即喝一点就醉了。","tag":"字词释义"},{"s":"“<em class='k'>故</em>自号曰醉翁也”中“<em class='k'>故</em>”的意思是？","o":["所以","原因","过去","故意"],"a":"A","e":"“故”意为所以。“故自号曰醉翁”即所以给自己起别号叫醉翁。","tag":"字词释义"},{"s":"“醉翁之意不在酒，<em class='k'>在乎</em>山水之间也”中“<em class='k'>在乎</em>”的意思是？","o":["在于","在意","存在","关心"],"a":"A","e":"“在乎”意为在于。“在乎山水之间”即在于山水之间的美景。","tag":"字词释义"},{"s":"“得之心而<em class='k'>寓</em>之酒也”中“<em class='k'>寓</em>”的意思是？","o":["寄托","居住","寓言","隐藏"],"a":"A","e":"“寓”意为寄托。“寓之酒”即寄托在酒中。","tag":"字词释义"},{"s":"“<em class='k'>若夫</em>日出而林霏开”中“<em class='k'>若夫</em>”的意思是？","o":["像那","如果","假若","至于"],"a":"A","e":"“若夫”是发语词，像那，用来引出下文。“若夫日出”即像那太阳升起。","tag":"字词释义"},{"s":"“日出而林<em class='k'>霏</em>开”中“<em class='k'>霏</em>”的意思是？","o":["雾气","雨雪","飞散","弥漫"],"a":"A","e":"“霏”意为雾气。“林霏开”即树林里的雾气散开。","tag":"字词释义"},{"s":"“云归而岩穴<em class='k'>暝</em>”中“<em class='k'>暝</em>”的意思是？","o":["昏暗","日落","瞑目","幽深"],"a":"A","e":"“暝”意为昏暗。“岩穴暝”即山洞变得昏暗。","tag":"字词释义"},{"s":"“佳木<em class='k'>秀</em>而繁阴”中“<em class='k'>秀</em>”的意思是？","o":["茂盛","秀丽","优秀","秀美"],"a":"A","e":"“秀”意为茂盛。“佳木秀而繁阴”即好的树木枝叶繁茂、形成浓阴。与第 3 题“秀”（秀丽）义不同。","tag":"字词释义"},{"s":"“风霜<em class='k'>高洁</em>”中“<em class='k'>高洁</em>”的意思是？","o":["秋高气爽","高尚纯洁","高大洁净","清高"],"a":"A","e":"“风霜高洁”即风高霜洁，形容秋高气爽的景色。","tag":"字词释义"},{"s":"“<em class='k'>负者</em>歌于途”中“<em class='k'>负者</em>”的意思是？","o":["背东西的人","失败的人","负担的人","赶路的人"],"a":"A","e":"“负者”意为背东西的人。“负者歌于途”即背东西的人在路上唱歌。","tag":"字词释义"},{"s":"“<em class='k'>伛偻</em>提携”中“<em class='k'>伛偻</em>”的意思是？","o":["老人","弯腰","驼背","搀扶"],"a":"A","e":"“伛偻”意为弯腰曲背的样子，借指老人（借代）。“伛偻提携”即老人和小孩。","tag":"字词释义"},{"s":"“伛偻<em class='k'>提携</em>”中“<em class='k'>提携</em>”的意思是？","o":["小孩","提拔","带领","搀扶"],"a":"A","e":"“提携”意为牵扶、领着走，借指小孩（借代）。“伛偻提携”即老老少少。","tag":"字词释义"},{"s":"“<em class='k'>临</em>溪而渔”中“<em class='k'>临</em>”的意思是？","o":["靠近","面临","居高","临时"],"a":"A","e":"“临”意为靠近。“临溪而渔”即到溪边捕鱼。与第 7 题“临”（居高下视）义不同。","tag":"字词释义"},{"s":"“泉香而酒<em class='k'>洌</em>”中“<em class='k'>洌</em>”的意思是？","o":["清","寒冷","凛冽","透彻"],"a":"A","e":"“洌”读 liè，意为清（清澈）。“泉香而酒洌”即泉水香甜、酒水清澈。注意与“冽”（寒冷）区分。","tag":"字词释义"},{"s":"“山肴野<em class='k'>蔌</em>”中“<em class='k'>蔌</em>”的意思是？","o":["菜蔬","菜肴","葱蒜","调料"],"a":"A","e":"“蔌”意为菜蔬（野菜）。“山肴野蔌”即山中的野味和野菜。","tag":"字词释义"},{"s":"“杂然而<em class='k'>前</em>陈者”中“<em class='k'>前</em>”的意思是？","o":["在前面","前面","向前","之前"],"a":"A","e":"“前”名词作状语，在前面。“杂然而前陈”即杂乱地陈列在面前。","tag":"字词释义"},{"s":"“杂然而前<em class='k'>陈</em>者”中“<em class='k'>陈</em>”的意思是？","o":["陈列","陈述","陈旧","陈设"],"a":"A","e":"“陈”意为陈列。“前陈”即陈列在面前。","tag":"字词释义"},{"s":"“<em class='k'>觥</em>筹交错”中“<em class='k'>觥</em>”的意思是？","o":["酒杯","酒筹","酒器","酒壶"],"a":"A","e":"“觥”意为酒杯。“觥筹交错”即酒杯和酒筹交互错杂。","tag":"字词释义"},{"s":"“<em class='k'>颓然</em>乎其间者”中“<em class='k'>颓然</em>”的意思是？","o":["醉倒的样子","颓废","坍塌","衰败"],"a":"A","e":"“颓然”意为醉倒的样子。“颓然乎其间”即醉倒在众人中间。","tag":"字词释义"},{"s":"“<em class='k'>已而</em>夕阳在山”中“<em class='k'>已而</em>”的意思是？","o":["不久","已经","然后","罢了"],"a":"A","e":"“已而”意为不久。“已而夕阳在山”即不久太阳落山。","tag":"字词释义"},{"s":"“树林阴<em class='k'>翳</em>”中“<em class='k'>翳</em>”的意思是？","o":["遮盖","树荫","阴暗","隐蔽"],"a":"A","e":"“翳”意为遮盖、遮蔽。“树林阴翳”即树林枝叶茂密成荫。","tag":"字词释义"},{"s":"“游人<em class='k'>去</em>而禽鸟乐也”中“<em class='k'>去</em>”的意思是？","o":["离开","去除","前往","过去"],"a":"A","e":"“去”意为离开。“游人去而禽鸟乐”即游人离去而禽鸟快乐。","tag":"字词释义"},{"s":"“然而禽鸟知山林之乐，<em class='k'>而</em>不知人之乐”中“<em class='k'>而</em>”的意思是？","o":["却","并且","然后","如果"],"a":"A","e":"“而”表转折，却。“而不知人之乐”即却不知道人的乐趣。","tag":"字词释义"},{"s":"“而不知太守<em class='k'>之</em>乐其乐也”中“<em class='k'>之</em>”的用法是？","o":["取消句子独立性","结构助词，的","代词，它","动词，去"],"a":"A","e":"“太守之乐其乐”中“之”用于主谓之间，取消句子独立性。","tag":"字词释义"},{"s":"“而不知太守之<em class='k'>乐</em>其乐也”中第一个“<em class='k'>乐</em>”的意思是？","o":["以……为乐","快乐","音乐","乐趣"],"a":"A","e":"“乐”意动用法，以……为乐。“乐其乐”即以百姓的快乐为快乐。","tag":"字词释义"},{"s":"“太守<em class='k'>谓</em>谁”中“<em class='k'>谓</em>”的意思是？","o":["是","说","称呼","叫做"],"a":"A","e":"“谓”意为是。“太守谓谁”即太守是谁。","tag":"字词释义"},{"s":"下列朗读停顿划分正确的一项是？","o":["有亭翼然临于 / 泉上者","望之 / 蔚然而深秀者","人知从太守 / 游而乐","而不知太守之乐其 / 乐也"],"a":"B","e":"B 停顿正确：“望之 / 蔚然而深秀者”。A 应在“翼然”后停顿；C 应在“人知”后停顿；D 应在“太守之乐”后停顿。","tag":"断句"},{"s":"下面对文言句式判断错误的一项是？","o":["“有亭翼然临于泉上者，醉翁亭也”是判断句","“泻出于两峰之间”属于状语后置句","“行者休于树”翻译为走路的人在树下休息","“行者休于树”是被动句"],"a":"D","e":"D 错误。“行者休于树”是状语后置句（于树休），不是被动句。A、B、C 判断均正确。","tag":"句式"},{"s":"对“醉翁之意不在酒，在乎山水之间也”翻译理解正确的一项是？","o":["醉翁的心意不在于喝酒，在于山水之间的美景","醉翁不想喝酒，一心只游走在山水中间","醉翁喝酒的目的，是为了欣赏山间流水","醉翁喝醉，不是因为酒，而是山水让他沉醉"],"a":"A","e":"A 翻译准确。“意”指情趣、心意，“在乎”意为在于。B、C、D 均有偏差。","tag":"翻译"},{"s":"下面词类活用分析正确的一项是？","o":["“名之者谁”中“名”，名词，名字","“有亭翼然临于泉上者”中“翼”，名词作状语，像鸟张开翅膀","“山行六七里”中“山”，名词，大山","“乐其乐”第一个“乐”，形容词，快乐"],"a":"B","e":"B 分析正确。“翼”名词作状语，像鸟张开翅膀。A“名”名词作动词（命名）；C“山”名词作状语（沿着山路）；D“乐”意动用法（以……为乐）。","tag":"词类活用"},{"s":"下列对“伛偻提携”理解正确的一项是？","o":["指弯腰搀扶别人","借代，指老人和小孩","描写人们爬山互相扶持","专指滁州当地的劳动者"],"a":"B","e":"B 正确。“伛偻”指弯腰曲背的老人，“提携”指被牵领的小孩，二者借代老人和小孩。","tag":"内容理解"},{"s":"下面对全文理解表述错误的一项是？","o":["本文写于欧阳修被贬滁州之时，文中有山水之乐，也暗含失意的苦闷","“醉”是外表，“乐”是核心，太守之乐的根本是乐百姓之乐","文章结尾，点明禽鸟之乐、游人之乐、太守之乐，三层乐逐层递进","禽鸟之乐，就是太守追求的“与民同乐”"],"a":"D","e":"D 错误。禽鸟之乐是山林自然之乐，太守之乐是“乐其乐”（以百姓的快乐为快乐），二者不同。A、B、C 表述均正确。","tag":"内容理解"},{"s":"对“醉能同其乐，醒能述以文者，太守也”翻译正确的一项是？","o":["喝醉了能够同大家一同欢乐，醒来能够用文章记述这件乐事的人，是太守","醉了能够和大家一起快乐，醒来能够写文章纪念的人，是太守","喝醉后能和大家同乐，清醒后能把文章写下来的人，是太守","醉了同大家一起欢乐，醒来用文字描述太守的人，是太守"],"a":"A","e":"A 翻译准确。“同其乐”即同大家一同欢乐，“述以文”即用文章记述。B 漏“用文章”；C 语序不当；D 误译“太守也”。","tag":"翻译"},{"s":"【联动七八年级】选出与例句“醒能述<em class='k'>以</em>文者”中“<em class='k'>以</em>”用法相同的选项。","o":["以钱覆其口（《卖油翁》）","自以为大有所益（《孙权劝学》）","以我酌油知之（《卖油翁》）","静以修身（《诫子书》）"],"a":"A","e":"例句“述以文”中“以”意为用（介词）。A“以钱覆其口”（用铜钱盖住油葫芦口），“以”也是用，用法相同。B“以”意为认为；C“以”意为凭借；D“以”表目的，来。","tag":"句式"},{"s":"【联动七八年级】选出与例句“醉翁之<em class='k'>之</em>意不在酒”中“<em class='k'>之</em>”用法相同的选项。","o":["水陆草木之花（《爱莲说》）","何陋之有（《陋室铭》）","予独爱莲之出淤泥而不染（《爱莲说》）","久之，目似瞑（《狼》）"],"a":"A","e":"例句“醉翁之意”中“之”是结构助词，的。A“草木之花”（的花）用法相同。B“之”是宾语前置的标志；C“之”用于主谓之间取消句子独立性；D“之”补足音节。","tag":"句式"}],"jd":[{"o":"环滁皆山也。其西南诸峰，林壑尤美，望之蔚然而深秀者，琅琊也。山行六七里，渐闻水声潺潺，而泻出于两峰之间者，酿泉也。峰回路转，有亭翼然临于泉上者，醉翁亭也。作亭者谁？山之僧智仙也。名之者谁？太守自谓也。太守与客来饮于此，饮少辄醉，而年又最高，故自号曰醉翁也。醉翁之意不在酒，在乎山水之间也。山水之乐，得之心而寓之酒也。","t":"环绕滁州的都是山。那西南方的几座山峰，树林和山谷尤其优美，一眼望去草木茂盛又幽深秀丽的，是琅琊山。沿着山路走六七里，渐渐听到潺潺的水声，从两座山峰之间倾泻而出的，是酿泉。山势回环，路也跟着转弯，有一座亭子像飞鸟展翅般踞在泉边，就是醉翁亭。造亭子的是谁？是山里的和尚智仙。给它取名的是谁？是自称为“醉翁”的太守。太守和宾客来此饮酒，喝一点就醉了，而且年纪最大，所以给自己起了“醉翁”的别号。醉翁的情趣不在酒上，而在山水之间。欣赏山水的乐趣，领会在心里，寄托在酒中。","notes":[["壑","山谷"],["蔚然","茂盛的样子"],["秀","秀丽"],["山","沿着山路"],["回","回环"],["翼然","像鸟张开翅膀的样子"],["临","居高下视"],["名","命名"],["辄","就"],["故","所以"],["在乎","在于"],["寓","寄托"]]},{"o":"若夫日出而林霏开，云归而岩穴暝，晦明变化者，山间之朝暮也。野芳发而幽香，佳木秀而繁阴，风霜高洁，水落而石出者，山间之四时也。朝而往，暮而归，四时之景不同，而乐亦无穷也。","t":"像那太阳升起而树林里的雾气散开，云气聚拢而山洞变得昏暗，明暗交替变化的，是山间的早晨和傍晚。野花开放而散发幽香，好的树木枝叶繁茂而形成浓阴，风高霜洁、秋高气爽，水位下落而石头露出，是山间的四季。早晨前往，傍晚归来，四季的景色不同，而乐趣也没有穷尽。","notes":[["若夫","像那"],["霏","雾气"],["暝","昏暗"],["秀","茂盛"],["高洁","秋高气爽"]]},{"o":"至于负者歌于途，行者休于树，前者呼，后者应，伛偻提携，往来而不绝者，滁人游也。临溪而渔，溪深而鱼肥，酿泉为酒，泉香而酒洌，山肴野蔌，杂然而前陈者，太守宴也。宴酣之乐，非丝非竹，射者中，弈者胜，觥筹交错，起坐而喧哗者，众宾欢也。苍颜白发，颓然乎其间者，太守醉也。","t":"至于背东西的人在路上歌唱，行人在树下休息，前面的呼唤，后面的应答，老老少少往来不断的，是滁州百姓在出游。到溪边捕鱼，溪水深而鱼儿肥，用酿泉造酒，泉水香而酒清冽，山中野味野菜，杂乱地陈列在前的，是太守的宴席。宴饮酣畅的乐趣，不在于音乐，投壶的中了，下棋的赢了，酒杯酒筹交互错杂，起身坐下大声喧哗的，是宾客在欢乐。脸色苍老、头发花白，醉倒在众人中间的，是太守喝醉了。","notes":[["负者","背东西的人"],["伛偻","老人"],["提携","小孩"],["临","靠近"],["洌","清"],["蔌","菜蔬"],["前","在前面"],["陈","陈列"],["觥","酒杯"],["颓然","醉倒的样子"]]},{"o":"已而夕阳在山，人影散乱，太守归而宾客从也。树林阴翳，鸣声上下，游人去而禽鸟乐也。然而禽鸟知山林之乐，而不知人之乐；人知从太守游而乐，而不知太守之乐其乐也。醉能同其乐，醒能述以文者，太守也。太守谓谁？庐陵欧阳修也。","t":"不久夕阳落山，人影散乱，是太守归家而宾客跟随。树林枝叶茂密成荫，鸟声忽上忽下，是游人离去而禽鸟快乐。但禽鸟只知山林的乐趣，却不知人的乐趣；人们知道跟随太守游玩的乐趣，却不知太守以他们的快乐为乐。醉时能与民同乐，醒后能用文章记述这事的，是太守。太守是谁？是庐陵的欧阳修。","notes":[["已而","不久"],["翳","遮盖"],["去","离开"],["而","却"],["之","取消句子独立性"],["乐","以……为乐"],["谓","是"]]}]}];
